/* The local provider is single-instance. Transport owner 0 stays generation
 * zero; this separate epoch survives body/world replacement and is retired
 * only by a committed menu unload or by producer-thread exit. */
static struct server_local* s_achievement_server;
static uint64_t s_achievement_host_epoch;

uint64_t server_local_achievement_epoch(struct server_local* s,
	const struct server_player* actor) {
	if(!s || !actor) return 0;
	if(actor == &s->player)
		return s == s_achievement_server ? s_achievement_host_epoch : 0;
	return actor == s->guest_actor && s->guest_gameplay ? s->guest_generation : 0;
}

static void server_local_achievement_fact(struct server_local* s, unsigned kind) {
	uint64_t epoch = server_local_achievement_epoch(s, &s->player);
	if(epoch) game_event_emit(&(struct game_event){.kind = kind,
		.authority = GE_AUTH_SERVER, .who = {.slot = 0, .generation = epoch}});
	if(s->guest_gameplay) game_event_emit(&(struct game_event){.kind = kind,
		.authority = GE_AUTH_SERVER,
		.who = {.slot = 1, .generation = s->guest_generation}});
	if(kind == GE_SESSION_END && s == s_achievement_server)
		s_achievement_host_epoch = 0;
}
