#define CHUNK_DIST2(x1, x2, z1, z2)                                            \
	(((x1) - (x2)) * ((x1) - (x2)) + ((z1) - (z2)) * ((z1) - (z2)))

// Count of times the chunk-eviction loop bailed because furthest_chunk returned the same
// chunk twice in a row (a save-that-failed-to-evict, which would otherwise spin the loop
// forever = a CPU-hang freeze). Surfaced on the F3; a non-zero value names the eviction
// wedge as the freeze cause. Should stay 0 now that save_chunk_obj force-evicts on failure.
// CR-08 (2026-08-20): plain uint32_t (declaration + rationale in server_local.h).
// SOLE production writer is the server thread (server_local_update only ever runs
// from server_local_thread outside tests); the increment below uses __atomic so the
// main thread (telemetry) and the Wii watchdog thread (hang-report dump) -- both
// cross-thread readers via __atomic_load_n at their own call sites -- observe it
// correctly instead of relying on an unsynchronized plain read/write pair.
uint32_t g_evict_stuck = 0;
uint32_t g_near_evict_deferred = 0;

/* Exactly one publisher: main before start/after join, otherwise server.
 * Atomic process-lifetime storage keeps heartbeat reads safe after teardown.
 * No actor pointers, allocation, IO, lock or unbounded retry. A contended
 * reader sleeps at most three times for 1ms to let the lower-priority writer
 * finish; Wii's equal-priority yield cannot resume a preempted server. */
static uint32_t s_death_seq, s_death_words[SERVER_LOCAL_DEATH_FIELDS];
static uint32_t s_death_next_session, s_death_owner;
/* Written only at the server's final act, read only after stop/join. This
 * terminal interval evidence is separate from the unavailable LIVE snapshot.
 * No reader borrows an actor; a new session or ordinary retirement clears it. */
static struct {
	const struct server_local* owner;
	uint32_t death[SERVER_LOCAL_DEATH_FIELDS];
	uint32_t guard[SERVER_LOCAL_PERF_GUARD_WORDS];
	int health;
} s_completion;
static uint32_t s_guard_seq, s_guard_words[SERVER_LOCAL_PERF_GUARD_WORDS], s_guard_requested;
static void perf_guard_reset(struct server_local*);
static void perf_guard_retire(struct server_local*);
static uint32_t perf_guard_barriers(struct server_local*);
#ifdef CAVEWII_TESTING
static void (*s_telemetry_test_hook)(bool guard, bool writing);
void server_local_test_telemetry_hook(void (*hook)(bool, bool)) {
	s_telemetry_test_hook = hook;
}
#define TELEMETRY_TEST_HOOK(g, w) do { if(s_telemetry_test_hook) s_telemetry_test_hook(g, w); } while(0)
#else
#define TELEMETRY_TEST_HOOK(g, w) ((void)0)
#endif
_Static_assert(sizeof(((struct server_local*)0)->death_telemetry)
	== SERVER_LOCAL_DEATH_FIELDS * sizeof(uint32_t), "death record fields");
_Static_assert(sizeof(((struct server_local*)0)->perf_guard_words)
	== SERVER_LOCAL_PERF_GUARD_WORDS * sizeof(uint32_t), "guard record fields");
_Static_assert(sizeof(((struct hw_telemetry_heartbeat*)0)->perf_guard_words)
	== SERVER_LOCAL_PERF_GUARD_WORDS * sizeof(uint32_t), "guard heartbeat fields");

static void death_telemetry_store(const uint32_t* words) {
	__atomic_add_fetch(&s_death_seq, 1, __ATOMIC_ACQ_REL);
	TELEMETRY_TEST_HOOK(false, true);
	__atomic_thread_fence(__ATOMIC_RELEASE);
	for(unsigned i = 0; i < SERVER_LOCAL_DEATH_FIELDS; i++)
		__atomic_store_n(&s_death_words[i], words[i], __ATOMIC_RELAXED);
	__atomic_add_fetch(&s_death_seq, 1, __ATOMIC_RELEASE);
}

static void death_telemetry_begin(struct server_local* s) {
	s_completion.owner = NULL;
	memset(s->death_telemetry, 0, sizeof(s->death_telemetry));
	/* Exhaustion must never recycle a session identity into apparent survival. */
	s_death_owner = s_death_next_session == UINT32_MAX
		? 0 : ++s_death_next_session;
	s->death_telemetry[SLD_SESSION] = s_death_owner;
	death_telemetry_store(s->death_telemetry);
	perf_guard_reset(s);
}

static void death_telemetry_retire(struct server_local* s) {
	if(s_completion.owner == s) s_completion.owner = NULL;
	if(s->death_telemetry[SLD_SESSION] != 0
	   && s->death_telemetry[SLD_SESSION] == s_death_owner) {
		uint32_t unavailable[SERVER_LOCAL_DEATH_FIELDS] = {0};
		s_death_owner = 0;
		death_telemetry_store(unavailable);
	}
	s->death_telemetry[SLD_SESSION] = 0;
	perf_guard_retire(s);
}

static void death_telemetry_complete(struct server_local* s) {
	bool valid = s_death_owner && s->death_telemetry[SLD_SESSION] == s_death_owner;
	s_completion.owner = NULL;
	if(valid) {
		memcpy(s_completion.death, s->death_telemetry, sizeof s_completion.death);
		memcpy(s_completion.guard, s->perf_guard_words, sizeof s_completion.guard);
		s_completion.health = s->player.health;
	}
	death_telemetry_retire(s);
	if(valid) s_completion.owner = s;
}

static void death_telemetry_note(struct server_local* s, bool host,
	enum server_player_damage_cause cause) {
	if(!s_death_owner || s->death_telemetry[SLD_SESSION] != s_death_owner)
		return;
	unsigned count = host ? SLD_HOST_DEATHS : SLD_GUEST_DEATHS;
	unsigned last = host ? SLD_HOST_CAUSE : SLD_GUEST_CAUSE;
	if(s->death_telemetry[count] == UINT32_MAX) {
		death_telemetry_retire(s);
		return;
	}
	s->death_telemetry[count]++;
	s->death_telemetry[last] = (uint32_t)cause;
	death_telemetry_store(s->death_telemetry);
}

bool server_local_death_snapshot(uint32_t out[SERVER_LOCAL_DEATH_FIELDS]) {
	if(!out) return false;
	for(unsigned attempt = 0; attempt < 4; attempt++) {
		uint32_t before = __atomic_load_n(&s_death_seq, __ATOMIC_ACQUIRE);
		if(!(before & 1u)) {
			for(unsigned i = 0; i < SERVER_LOCAL_DEATH_FIELDS; i++)
				out[i] = __atomic_load_n(&s_death_words[i], __ATOMIC_RELAXED);
			__atomic_thread_fence(__ATOMIC_ACQUIRE);
			if(before == __atomic_load_n(&s_death_seq, __ATOMIC_ACQUIRE))
				return out[SLD_SESSION] != 0;
		}
		if(attempt < 3) {
			TELEMETRY_TEST_HOOK(false, false);
			thread_msleep(1);
		}
	}
	memset(out, 0, SERVER_LOCAL_DEATH_FIELDS * sizeof(*out));
	return false;
}

bool server_local_death_heartbeat(bool local, struct hw_telemetry_heartbeat* hb) {
	if(!hb) return false;
	_Static_assert(sizeof(hb->death_record)
		== SERVER_LOCAL_DEATH_FIELDS * sizeof(uint32_t), "death wire fields");
	hb->death_present = true;
	memset(hb->death_record, 0, sizeof(hb->death_record));
	bool valid = local && server_local_death_snapshot(hb->death_record);
	if(!valid) {
		hb->death_record[SLD_HOST_DEATHS] = UINT32_MAX;
		hb->death_record[SLD_GUEST_DEATHS] = UINT32_MAX;
	}
	/* d1 retains explicit unavailable evidence; presentation fields have no
	 * sentinel count/cause. The formatter emits null for an invalid session. */
	hb->anchor.deaths = valid ? hb->death_record[SLD_HOST_DEATHS] : 0;
	hb->anchor.death_cause = valid
		? server_player_damage_cause_name(hb->death_record[SLD_HOST_CAUSE]) : NULL;
	return valid;
}

bool server_local_completion_heartbeat(const struct server_local* s,
	struct hw_telemetry_heartbeat* hb) {
	if(!s || !hb || s->thread_started
	   || !__atomic_load_n(&s->thread_done, __ATOMIC_ACQUIRE)
	   || !__atomic_load_n(&s->thread_stop, __ATOMIC_ACQUIRE)
	   || s_completion.owner != s) return false;
	hb->death_present = true;
	memcpy(hb->death_record, s_completion.death, sizeof hb->death_record);
	hb->perf_guard_present = true;
	memcpy(hb->perf_guard_words, s_completion.guard, sizeof hb->perf_guard_words);
	hb->player_health = s_completion.health;
	hb->anchor.deaths = hb->death_record[SLD_HOST_DEATHS];
	hb->anchor.death_cause = server_player_damage_cause_name(hb->death_record[SLD_HOST_CAUSE]);
	return true;
}

