/* Server-thread publisher, client-thread reader. Every scalar is accessed
 * atomically; the sequence counter keeps one frame from mixing two ticks. */
static uint32_t s_host_weather_diag_seq;
static uint32_t s_server_diag_stage;
uint32_t server_local_diag_stage(void) {
	return __atomic_load_n(&s_server_diag_stage, __ATOMIC_RELAXED);
}
void server_diag_set(enum server_diag_stage stage) {
	__atomic_store_n(&s_server_diag_stage, (uint32_t)stage, __ATOMIC_RELAXED);
}
/* R4: one server-thread writer, bounded cross-thread reader. The payload is
 * intentionally all 32-bit atomic words; it neither borrows actor pointers
 * nor waits on a lock in the transfer path. */
static uint32_t s_portal_diag_seq;
static uint32_t s_portal_diag_words[SPD_FIELD_COUNT];
static uint32_t s_portal_diag_pos_count[SPD_POS_RESULT_VERTICAL + 1];
static uint32_t s_portal_diag_last_result;
static uint32_t s_portal_diag_last_rx_token;
static uint32_t s_portal_diag_last_expect_token;
static uint32_t s_portal_diag_last_delta;
static int32_t s_portal_diag_frame_x, s_portal_diag_frame_y, s_portal_diag_frame_z;
static bool s_portal_diag_on_lit;

static uint32_t portal_diag_float_bits(float value) {
	uint32_t bits;
	memcpy(&bits, &value, sizeof(bits));
	return bits;
}

bool server_local_portal_diag_get(struct server_portal_diag_snapshot* out) {
	if(!out)
		return false;
	for(unsigned attempt = 0; attempt < 4; attempt++) {
		uint32_t before = __atomic_load_n(&s_portal_diag_seq, __ATOMIC_ACQUIRE);
		if(before & 1u)
			continue;
		for(unsigned i = 0; i < SPD_FIELD_COUNT; i++)
			out->word[i] = __atomic_load_n(&s_portal_diag_words[i],
				__ATOMIC_RELAXED);
		__atomic_thread_fence(__ATOMIC_ACQUIRE);
		uint32_t after = __atomic_load_n(&s_portal_diag_seq, __ATOMIC_ACQUIRE);
		if(before == after)
			return out->word[SPD_VALID] != 0;
	}
	return false;
}

static void portal_diag_txn_words(uint32_t* word, unsigned base,
	const struct server_transfer_txn* t) {
	word[base + 0] = t->id;
	word[base + 1] = t->open;
	word[base + 2] = (uint32_t)t->state;
	word[base + 3] = t->src_slot;
	word[base + 4] = t->dst_slot;
	word[base + 5] = t->actor_slot;
	word[base + 6] = t->last_id;
	word[base + 7] = (uint32_t)t->last_state;
}

void server_local_portal_diag_publish(struct server_local* s) {
	if(!s || !s->portal_demo)
		return;
	uint32_t word[SPD_FIELD_COUNT] = {0};
	word[SPD_VALID] = 1;
	word[SPD_DEMO_SPLIT] = s->portal_demo_split;
	word[SPD_DEMO_DEFER] = (uint32_t)s->portal_demo_defer;
	word[SPD_DEMO_PENDING] = s->portal_demo_host_pending;
	word[SPD_DEMO_LIT] = s->portal_demo_split
		? s->portal_demo_host_lit : s_portal_diag_on_lit;
	word[SPD_DEMO_X] = (uint32_t)s_portal_diag_frame_x;
	word[SPD_DEMO_Y] = (uint32_t)s_portal_diag_frame_y;
	word[SPD_DEMO_Z] = (uint32_t)s_portal_diag_frame_z;
	word[SPD_HOST_X] = portal_diag_float_bits((float)s->player.x);
	word[SPD_HOST_Y] = portal_diag_float_bits((float)s->player.y);
	word[SPD_HOST_Z] = portal_diag_float_bits((float)s->player.z);
	word[SPD_HOST_WORLD] = s->player.world_slot;
	word[SPD_HOST_TOKEN] = s->player.correction_seq;
	const struct server_player* guest = s->guest_actor;
	word[SPD_GUEST_PRESENT] = guest != NULL;
	word[SPD_GUEST_GAMEPLAY] = s->guest_gameplay;
	word[SPD_GUEST_WORLD] = UINT32_MAX;
	if(guest) {
		word[SPD_GUEST_X] = portal_diag_float_bits((float)guest->x);
		word[SPD_GUEST_Y] = portal_diag_float_bits((float)guest->y);
		word[SPD_GUEST_Z] = portal_diag_float_bits((float)guest->z);
		word[SPD_GUEST_WORLD] = guest->world_slot;
		word[SPD_GUEST_TOKEN] = guest->correction_seq;
		word[SPD_GUEST_IN_PORTAL] = guest->in_portal;
		word[SPD_GUEST_DWELL] = portal_diag_float_bits(guest->time_in_portal);
		word[SPD_GUEST_COOLDOWN] = (uint32_t)guest->time_until_portal;
	}
	for(unsigned i = 0; i <= SPD_POS_RESULT_VERTICAL; i++)
		word[SPD_POS_ACCEPT + i] = s_portal_diag_pos_count[i];
	word[SPD_POS_LAST_RESULT] = s_portal_diag_last_result;
	word[SPD_POS_LAST_RX_TOKEN] = s_portal_diag_last_rx_token;
	word[SPD_POS_LAST_EXPECT_TOKEN] = s_portal_diag_last_expect_token;
	word[SPD_POS_LAST_DELTA] = s_portal_diag_last_delta;
	portal_diag_txn_words(word, SPD_HOST_TX_ID, &s->transfer[0]);
	portal_diag_txn_words(word, SPD_GUEST_TX_ID, &s->transfer[1]);
	__atomic_add_fetch(&s_portal_diag_seq, 1, __ATOMIC_ACQ_REL);
	__atomic_thread_fence(__ATOMIC_RELEASE);
	for(unsigned i = 0; i < SPD_FIELD_COUNT; i++)
		__atomic_store_n(&s_portal_diag_words[i], word[i], __ATOMIC_RELAXED);
	__atomic_add_fetch(&s_portal_diag_seq, 1, __ATOMIC_RELEASE);
}

void server_local_portal_diag_guest_pos(struct server_local* s,
	enum server_portal_diag_pos_result result, uint32_t received_token,
	float horizontal_delta_sq) {
	if(!s || !s->portal_demo || (unsigned)result > SPD_POS_RESULT_VERTICAL)
		return;
	s_portal_diag_pos_count[result]++;
	s_portal_diag_last_result = (uint32_t)result;
	s_portal_diag_last_rx_token = received_token;
	s_portal_diag_last_expect_token
		= s->guest_actor ? s->guest_actor->correction_seq : 0;
	s_portal_diag_last_delta = portal_diag_float_bits(horizontal_delta_sq);
	server_local_portal_diag_publish(s);
}
static struct server_local_host_weather_diagnostic s_host_weather_diag;
static bool s_host_weather_diag_valid;
static uint32_t s_host_weather_diag_request_seq;
static uint32_t s_host_weather_diag_seen_request_seq;
static unsigned s_host_weather_diag_fresh_ticks;
#ifdef CAVEWII_SERVER_LOCAL_TEST
static uint32_t s_host_weather_diag_exposure_queries;
#endif

#define HOST_WEATHER_DIAG_FRESH_TICKS 40u

static void server_local_host_weather_diagnostic_clear(void) {
	__atomic_add_fetch(&s_host_weather_diag_seq, 1, __ATOMIC_ACQ_REL);
	__atomic_store_n(&s_host_weather_diag_valid, false, __ATOMIC_RELAXED);
	__atomic_add_fetch(&s_host_weather_diag_seq, 1, __ATOMIC_RELEASE);
	s_host_weather_diag_seen_request_seq = __atomic_load_n(
		&s_host_weather_diag_request_seq, __ATOMIC_ACQUIRE);
	s_host_weather_diag_fresh_ticks = 0;
}

void server_local_host_weather_diagnostic_request(void) {
	__atomic_add_fetch(&s_host_weather_diag_request_seq, 1, __ATOMIC_RELEASE);
}

static void server_local_host_weather_diagnostic_publish(
	struct server_local* s, bool body_in_water) {
	struct server_local_host_weather_diagnostic d = {0};
	d.fx = (w_coord_t)floor(s->player.x);
	d.fy = (w_coord_t)floor(s->player.y - PLAYER_EYE_HEIGHT);
	d.fz = (w_coord_t)floor(s->player.z);
	d.wet = server_entity_is_wet(s, body_in_water, s->player.x,
		s->player.y - PLAYER_EYE_HEIGHT, s->player.z);
#ifdef CAVEWII_SERVER_LOCAL_TEST
	s_host_weather_diag_exposure_queries++;
#endif
	d.rained_on = server_weather_exposure_diagnostic(s, d.fx, d.fy, d.fz,
		&d.sky, &d.height, &d.biome_rains);
	d.fire_ticks = s->player.fire;

	__atomic_add_fetch(&s_host_weather_diag_seq, 1, __ATOMIC_ACQ_REL);
	__atomic_store_n(&s_host_weather_diag.wet, d.wet, __ATOMIC_RELAXED);
	__atomic_store_n(&s_host_weather_diag.fire_ticks, d.fire_ticks,
		__ATOMIC_RELAXED);
	__atomic_store_n(&s_host_weather_diag.rained_on, d.rained_on,
		__ATOMIC_RELAXED);
	__atomic_store_n(&s_host_weather_diag.height, d.height, __ATOMIC_RELAXED);
	__atomic_store_n(&s_host_weather_diag.biome_rains, d.biome_rains,
		__ATOMIC_RELAXED);
	__atomic_store_n(&s_host_weather_diag.sky, d.sky, __ATOMIC_RELAXED);
	__atomic_store_n(&s_host_weather_diag.fx, d.fx, __ATOMIC_RELAXED);
	__atomic_store_n(&s_host_weather_diag.fy, d.fy, __ATOMIC_RELAXED);
	__atomic_store_n(&s_host_weather_diag.fz, d.fz, __ATOMIC_RELAXED);
	__atomic_store_n(&s_host_weather_diag_valid, true, __ATOMIC_RELAXED);
	__atomic_add_fetch(&s_host_weather_diag_seq, 1, __ATOMIC_RELEASE);
}

static void server_local_host_weather_diagnostic_publish_if_requested(
	struct server_local* s, bool body_in_water) {
	uint32_t request_seq = __atomic_load_n(
		&s_host_weather_diag_request_seq, __ATOMIC_ACQUIRE);
	if(request_seq != s_host_weather_diag_seen_request_seq) {
		s_host_weather_diag_seen_request_seq = request_seq;
		s_host_weather_diag_fresh_ticks = HOST_WEATHER_DIAG_FRESH_TICKS;
	}
	if(s_host_weather_diag_fresh_ticks == 0) {
		if(__atomic_load_n(&s_host_weather_diag_valid, __ATOMIC_RELAXED))
			server_local_host_weather_diagnostic_clear();
		return;
	}
	s_host_weather_diag_fresh_ticks--;
	server_local_host_weather_diagnostic_publish(s, body_in_water);
}

bool server_local_host_weather_diagnostic_read(
	struct server_local_host_weather_diagnostic* out) {
	if(!out)
		return false;
	/* Three attempts only (the thread.c stripe-reader idiom). The reader is the
	 * main thread (F3 HUD / state export), which outranks the server writer on
	 * the single Broadway core: if the writer is preempted mid-publish (odd
	 * sequence) and the reader waits for it, the writer is never scheduled
	 * again and the game livelocks in render -- the d085 watchdog HANG
	 * (D085-SEQLOCK-FIX-01). Give up instead; the caller skips one frame. */
	for(unsigned attempt = 0; attempt < 3; attempt++) {
		uint32_t before
			= __atomic_load_n(&s_host_weather_diag_seq, __ATOMIC_ACQUIRE);
		if(before & 1u)
			continue;
		bool valid = __atomic_load_n(
			&s_host_weather_diag_valid, __ATOMIC_RELAXED);
		struct server_local_host_weather_diagnostic d = {
			.wet = __atomic_load_n(&s_host_weather_diag.wet, __ATOMIC_RELAXED),
			.fire_ticks = __atomic_load_n(
				&s_host_weather_diag.fire_ticks, __ATOMIC_RELAXED),
			.rained_on = __atomic_load_n(
				&s_host_weather_diag.rained_on, __ATOMIC_RELAXED),
			.height = __atomic_load_n(
				&s_host_weather_diag.height, __ATOMIC_RELAXED),
			.biome_rains = __atomic_load_n(
				&s_host_weather_diag.biome_rains, __ATOMIC_RELAXED),
			.sky = __atomic_load_n(&s_host_weather_diag.sky, __ATOMIC_RELAXED),
			.fx = __atomic_load_n(&s_host_weather_diag.fx, __ATOMIC_RELAXED),
			.fy = __atomic_load_n(&s_host_weather_diag.fy, __ATOMIC_RELAXED),
			.fz = __atomic_load_n(&s_host_weather_diag.fz, __ATOMIC_RELAXED),
		};
		uint32_t after
			= __atomic_load_n(&s_host_weather_diag_seq, __ATOMIC_ACQUIRE);
		if(before == after) {
			*out = valid ? d
				: (struct server_local_host_weather_diagnostic) {0};
			return valid;
		}
	}
	*out = (struct server_local_host_weather_diagnostic) {0};
	return false;
}

/* The server thread is the sole writer; main's heartbeat is the reader.
 * Every shared scalar is 32-bit atomic so the sequence check is C-race-safe. */
static uint32_t s_tnt_evidence_seq;
static struct server_local_tnt_evidence s_tnt_evidence;

static void server_local_tnt_evidence_publish(uint32_t st, uint32_t bits,
	uint32_t primed_left, uint32_t carved, uint32_t pad, uint32_t tick,
	bool reset) {
	__atomic_add_fetch(&s_tnt_evidence_seq, 1, __ATOMIC_SEQ_CST);
	uint32_t gen = __atomic_load_n(&s_tnt_evidence.gen, __ATOMIC_SEQ_CST);
	if(reset)
		gen++;
	__atomic_store_n(&s_tnt_evidence.valid, 1, __ATOMIC_SEQ_CST);
	__atomic_store_n(&s_tnt_evidence.st, st, __ATOMIC_SEQ_CST);
	__atomic_store_n(&s_tnt_evidence.bits, bits, __ATOMIC_SEQ_CST);
	__atomic_store_n(&s_tnt_evidence.primed_left, primed_left, __ATOMIC_SEQ_CST);
	__atomic_store_n(&s_tnt_evidence.carved, carved, __ATOMIC_SEQ_CST);
	__atomic_store_n(&s_tnt_evidence.pad, pad, __ATOMIC_SEQ_CST);
	__atomic_store_n(&s_tnt_evidence.gen, gen, __ATOMIC_SEQ_CST);
	__atomic_store_n(&s_tnt_evidence.tick, tick, __ATOMIC_SEQ_CST);
	__atomic_add_fetch(&s_tnt_evidence_seq, 1, __ATOMIC_SEQ_CST);
}

static void server_local_tnt_evidence_reset(void) {
	server_local_tnt_evidence_publish(0, 0, 0, 0, 0, 0, true);
}

bool server_local_tnt_evidence_take(struct server_local_tnt_evidence* out) {
	if(!out)
		return false;
	*out = (struct server_local_tnt_evidence) {0};
	for(unsigned attempt = 0; attempt < 4; attempt++) {
		uint32_t before = __atomic_load_n(&s_tnt_evidence_seq, __ATOMIC_SEQ_CST);
		if(before & 1u)
			continue;
		struct server_local_tnt_evidence d = {
			.valid = __atomic_load_n(&s_tnt_evidence.valid, __ATOMIC_SEQ_CST),
			.st = __atomic_load_n(&s_tnt_evidence.st, __ATOMIC_SEQ_CST),
			.bits = __atomic_load_n(&s_tnt_evidence.bits, __ATOMIC_SEQ_CST),
			.primed_left = __atomic_load_n(&s_tnt_evidence.primed_left, __ATOMIC_SEQ_CST),
			.carved = __atomic_load_n(&s_tnt_evidence.carved, __ATOMIC_SEQ_CST),
			.pad = __atomic_load_n(&s_tnt_evidence.pad, __ATOMIC_SEQ_CST),
			.gen = __atomic_load_n(&s_tnt_evidence.gen, __ATOMIC_SEQ_CST),
			.tick = __atomic_load_n(&s_tnt_evidence.tick, __ATOMIC_SEQ_CST),
		};
		uint32_t after = __atomic_load_n(&s_tnt_evidence_seq, __ATOMIC_SEQ_CST);
		if(before == after) {
			*out = d;
			return d.valid != 0;
		}
	}
	return false;
}

