static uint32_t save_migrate_u32(size_t value) {
	return value > UINT32_MAX ? UINT32_MAX : (uint32_t)value;
}

static void save_migrate_metric_store(uint32_t* field, uint32_t value) {
	__atomic_store_n(field, value, __ATOMIC_RELEASE);
}

// `started` is shared across all three migration stages (the caller passes
// the SAME chain-start timestamp captured before the first version check in
// server_local_load_world_impl_ex), so `_ms` always reads as "elapsed since
// the reopen began examining CaveWiiSaveVersion" -- whichever stage publishes
// last (chests, if a version-3 world; spawners, if a version-2 or older one)
// reports the FULL chain's wall time, not just its own slice. That is the
// number the 300000ms PASS gate actually needs: this profile exists because
// the WHOLE synchronous sweep -- not any one stage -- has zero real-hardware
// precedent.
static void save_migrate_publish_stats(
	ptime_t started, const struct wall_sign_metadata_migration_stats* stats,
	enum server_local_save_migrate_state state) {
	save_migrate_metric_store(
		&s_save_migrate_ms,
		save_migrate_u32(time_diff_ms(started, time_get())));
	save_migrate_metric_store(
		&s_save_migrate_regions, save_migrate_u32(stats->regions_scanned));
	save_migrate_metric_store(
		&s_save_migrate_chunks, save_migrate_u32(stats->chunks_scanned));
	save_migrate_metric_store(
		&s_save_migrate_signs, save_migrate_u32(stats->signs_rewritten));
	// Publish the terminal/intermediate state last. An acquire reader that sees
	// it then also sees the complete metric snapshot above.
	save_migrate_metric_store(&s_save_migrate_state, (uint32_t)state);
}

static void save_migrate_publish_chest_stats(
	ptime_t started, const struct iron_chest_migration_stats* stats,
	uint32_t expected, enum server_local_save_migrate_state state) {
	save_migrate_metric_store(
		&s_save_migrate_ms,
		save_migrate_u32(time_diff_ms(started, time_get())));
	save_migrate_metric_store(
		&s_save_migrate_chests, save_migrate_u32(stats->blocks_rewritten));
	save_migrate_metric_store(&s_save_migrate_chests_expected, expected);
	save_migrate_metric_store(&s_save_migrate_state, (uint32_t)state);
}

static void save_migrate_publish_spawner_stats(
	ptime_t started, const struct mob_spawner_te_migration_stats* stats,
	uint32_t expected, enum server_local_save_migrate_state state) {
	save_migrate_metric_store(
		&s_save_migrate_ms,
		save_migrate_u32(time_diff_ms(started, time_get())));
	save_migrate_metric_store(
		&s_save_migrate_spawners,
		save_migrate_u32(stats->spawners_synthesized));
	save_migrate_metric_store(&s_save_migrate_spawners_expected, expected);
	save_migrate_metric_store(&s_save_migrate_state, (uint32_t)state);
}

void server_local_save_migrate_metrics_read(
	struct server_local_save_migrate_metrics* out) {
	if(!out)
		return;
	out->state = __atomic_load_n(&s_save_migrate_state, __ATOMIC_ACQUIRE);
	out->elapsed_ms = __atomic_load_n(&s_save_migrate_ms, __ATOMIC_ACQUIRE);
	out->regions_scanned
		= __atomic_load_n(&s_save_migrate_regions, __ATOMIC_ACQUIRE);
	out->chunks_scanned
		= __atomic_load_n(&s_save_migrate_chunks, __ATOMIC_ACQUIRE);
	out->signs_rewritten
		= __atomic_load_n(&s_save_migrate_signs, __ATOMIC_ACQUIRE);
	out->signs_expected
		= __atomic_load_n(&s_save_migrate_expected, __ATOMIC_ACQUIRE);
	out->signs_verified
		= __atomic_load_n(&s_save_migrate_verified, __ATOMIC_ACQUIRE);
	out->chests_rewritten
		= __atomic_load_n(&s_save_migrate_chests, __ATOMIC_ACQUIRE);
	out->chests_expected
		= __atomic_load_n(&s_save_migrate_chests_expected, __ATOMIC_ACQUIRE);
	out->chests_verified
		= __atomic_load_n(&s_save_migrate_chests_verified, __ATOMIC_ACQUIRE);
	out->spawners_synthesized
		= __atomic_load_n(&s_save_migrate_spawners, __ATOMIC_ACQUIRE);
	out->spawners_expected
		= __atomic_load_n(&s_save_migrate_spawners_expected, __ATOMIC_ACQUIRE);
	out->spawners_verified
		= __atomic_load_n(&s_save_migrate_spawners_verified, __ATOMIC_ACQUIRE);
}

// A4 near-stream pacing. The near send used to push exactly ONE chunk per server
// tick; with the fixed 50ms inter-tick sleep that capped streaming at ~20 chunks/s,
// the visible "very slow chunk generation". CHUNK_SEND_BATCH lets one tick drain up
// to N nearest-unsent chunks, but CHUNK_SEND_BUDGET_MS bounds the batch's wall-clock
// so a run of chunks that each need real generation can't stack N x ~14ms into one
// tick and re-freeze render: a chunk already populated by a neighbour's quadrant
// sends in well under a ms (just a memcpy + RPC), so the batch cheaply clears the
// resident-but-unsent backlog while a single generating chunk still trips the budget
// and stops. Pure scheduling -- byte-identical chunks reach the client, only sooner.
//
// NOTE on why we do NOT also shorten the inter-tick sleep: the server thread runs one
// full game tick (server_world_tick -> current_tick++, daytime, scheduled/fluid ticks,
// random ticks) per loop iteration, so the inter-tick sleep IS the simulation tick rate
// (~20 TPS). Shortening it to "catch up" on streaming would run the whole game faster
// while chunks load (day/night, fluids, mob AI, crop growth) -- a faithfulness break.
// So the batch only spends the EXISTING per-tick compute window more productively
// (shipping the already-populated quadrant neighbours a single ensure_populated() just
// generated, instead of one chunk per tick); the 50ms period is left untouched. Lifting
// the gen-bound frontier rate without speeding the sim needs decoupling the chunk pump
// from the 20 TPS game tick -- a second-wave refactor, called out in the writeup.
#define CHUNK_SEND_BATCH 4
#define CHUNK_SEND_BUDGET_MS 12
// Loading-screen watchdog: enter the world anyway after this many ticks even if the
// near radius never fully streams (a chunk that can't load), so the screen can't hang.
// With the sim suspended during load the server ticks fast (~short sleep), so this is a
// large tick count -- a generous wall-clock backstop well above a normal spawn load; it
// only fires on a pathological world (a chunk that can never send).
#define LOAD_WATCHDOG_TICKS 6000
/* Respawn cannot release input or allocate a replacement ring while unsaved
 * departed chunks remain. Three failed attempts at the existing retry cadence
 * retire the drain as a terminal load failure (estk/wl_failed telemetry). */
#define RESPAWN_DRAIN_SAVE_ATTEMPTS 3

// Harden audit #3: O(1) fresh entity id. Pre-increment the monotonic counter so the
// first id handed out is 1 (id 0 is reserved for the local player), matching the old
// entity_gen_id's first return. Replaces entity_gen_id's O(N) full-dict max-key scan
// at every server spawn site -- the server is the sole producer of fresh ids and they
// are session-local (never saved), so a never-reused running counter is unique, > 0,
// and monotonic in the deterministic spawn order. Consumes no RNG.
uint32_t server_local_gen_id(struct server_local* s) {
	assert(s);
	/* Loaded entities intentionally receive session-local ids. If a test/tool or
	 * future importer seeded the dictionary independently of the counter, skip
	 * occupied keys instead of overwriting and leaking the existing entity. */
	do {
		s->next_entity_id++;
	} while(s->next_entity_id == 0
			// Post-review finding #4 (adversarial review, 2026-08-13):
			// UINT32_MAX is entity_painting_select_art's "no self" sentinel
			// for a not-yet-placed scratch candidate (entity_painting.h) --
			// a live entity actually assigned this id would be silently
			// excluded from every future painting/minecart/boat overlap
			// dict-scan that passes self_id=UINT32_MAX (entity_painting.c's
			// entity_painting_validate_surface: `other->id == self_id`),
			// exactly the same class of problem id 0 already can't be handed
			// out for (0 means "no local player" to other consumers).
			// Astronomically unlikely in practice -- needs the entire 32-bit
			// id space exhausted in one session -- but free to guard, and
			// the whole point of a sentinel is that no live id may ever
			// equal it.
			|| s->next_entity_id == UINT32_MAX
			|| dict_entity_get(s->entities, s->next_entity_id) != NULL);
	return s->next_entity_id;
}

