// Debug-only ("debug.chest_selftest"): exercise the per-chunk chest persistence
// lifecycle end to end on real hardware with no player input. Registers a chest
// with known contents in a throwaway far chunk, forces that chunk through the
// real save+evict (gather -> set_blocks -> region file) and reload (get_blocks
// -> te_store_insert), then checks the contents survived. Writes PASS/FAIL to
// chest_selftest_result.txt on the SD card (and stdout). Runs once at world
// load; leaves a stray generated region far from spawn -- harmless.
static void server_local_chest_selftest(struct server_local* s) {
	assert(s);
	const w_coord_t CX = 100, CZ = 100;
	const w_coord_t BX = CX * CHUNK_SIZE + 3, BY = 70, BZ = CZ * CHUNK_SIZE + 5;
	char detail[256] = "";
	const char* status = "FAIL";

	// 1. Load (generate) the throwaway chunk so it is resident and has a region.
	struct server_chunk* sc = NULL;
	if(!server_world_is_chunk_loaded(&s->world, CX, CZ))
		server_world_load_chunk(&s->world, CX, CZ, &sc);
	(void)sc;

	if(!server_world_is_chunk_loaded(&s->world, CX, CZ)) {
		status = "SKIP";
		snprintf(detail, sizeof(detail),
				 "could not load test chunk (%d,%d) -- world has no generator?",
				 (int)CX, (int)CZ);
	} else {
		int slot = -1;
		for(int i = 0; i < MAX_CHESTS; i++)
			if(s->chest_pos[i].y < 0) {
				slot = i;
				break;
			}

		if(slot < 0) {
			snprintf(detail, sizeof(detail), "no free chest slot for the test");
		} else {
			// 2. Register a chest with known contents (A1b: slot 0's row).
			struct te_store selftest = server_world_tile_store(&s->worlds[0]);
			s->chest_pos[slot] = (struct complex_block_pos) {BX, BY, BZ};
			s->te_owners.chest_slot[slot] = selftest.owner_slot;
			s->te_owners.chest_gen[slot] = selftest.owner_generation;
			memset(s->chest_items[slot], 0, sizeof(s->chest_items[slot]));
			s->chest_items[slot][0]
				= (struct item_data) {.id = 265, .count = 17};
			s->chest_items[slot][26]
				= (struct item_data) {.id = 331, .count = 64};
			s->chest_items[slot][53]
				= (struct item_data) {.id = 351, .count = 1, .durability = 3};

			// 3. Force save + evict: real gather -> set_blocks -> release path.
			server_world_save_chunk(&s->world, true, CX, CZ);
			// 4. Reload from disk: real get_blocks -> te_store_insert path.
			struct server_chunk* sc2 = NULL;
			bool reloaded
				= server_world_load_chunk(&s->world, CX, CZ, &sc2);

			if(!reloaded || !sc2) {
				snprintf(detail, sizeof(detail),
						 "chunk reload failed after evict");
			} else {
				// 5. Find the chest back and compare to the known contents.
				int got = server_local_chest_row_w(&s->worlds[0], BX, BY, BZ);
				if(got < 0) {
					snprintf(detail, sizeof(detail),
							 "chest MISSING from table after evict+reload");
				} else {
					struct item_data a = s->chest_items[got][0];
					struct item_data b = s->chest_items[got][26];
					struct item_data d = s->chest_items[got][53];
					bool ok = a.id == 265 && a.count == 17 && b.id == 331
						&& b.count == 64 && d.id == 351 && d.count == 1
						&& d.durability == 3;
					status = ok ? "PASS" : "FAIL";
					snprintf(detail, sizeof(detail),
							 "slot0=(id %u x%u; want 265x17) "
							 "slot26=(id %u x%u; want 331x64) "
							 "slot53=(id %u x%u dmg%u; want 351x1 dmg3)",
							 (unsigned)a.id, (unsigned)a.count, (unsigned)b.id,
							 (unsigned)b.count, (unsigned)d.id, (unsigned)d.count,
							 (unsigned)d.durability);
				}
			}
		}
	}

	printf("CHEST SELFTEST %s: %s\n", status, detail);
	FILE* f = fopen("chest_selftest_result.txt", "w");
	if(f) {
		fprintf(f, "CHEST SELFTEST %s\n%s\n", status, detail);
		fclose(f);
	}
}

// Shears block-break special drop (item_shears.c); forward-declared here to avoid a header touch.
extern bool item_shears_block_drop(struct block_data blk, struct item_data held,
								   struct item_data* out);

// Ice player-harvest water conversion (block_ice.c); forward-declared here (not
// wired through block->onBreak -- see block_ice.c's block_ice_harvest comment for
// why) to avoid a header touch. Deliberately called ONLY from the SRPC_BLOCK_DIG
// player-dig path below, gated by the same harvest condition as the drop-spawn call.
extern void block_ice_harvest(struct server_local* s, struct block_info* this);

/* TOOL DURABILITY (2026-07-29, handoff P1(b)). Apply `amount` wear to the HELD hotbar slot
   and mirror the result to the client. Both Beta wear sites go through here.

   BY POINTER, not inventory_get_hotbar_item(): that returns a COPY, so damaging it would
   mutate a temporary and the real stack would never wear -- the same by-pointer shape
   SRPC_ENTITY_USE already uses for milking/shearing.

   The CRPC_INVENTORY_SLOT push is not optional. The Wii client keeps its own inventory
   mirror and draws the durability bar from it (gui_util.c gates on
   `has_damage && durability > 0`), so a server-only wear would tick the number up
   invisibly -- which is indistinguishable from the bug this fixes. Beta shows the bar after
   exactly ONE use (RenderItem.java:182 -> ItemStack.isItemDamaged, `itemDamage > 0`).

   Amount 0 is the normal "this item does not wear on this path" case and costs nothing. */
static void server_local_wear_held_item(struct server_local* s,
										struct server_player* player,
										uint16_t amount) {
	if(amount == 0)
		return;
	size_t held_slot
		= INVENTORY_SLOT_HOTBAR + inventory_get_hotbar(&player->inventory);
	struct item_data* held = &player->inventory.items[held_slot];
	struct item_data before = *held;
	item_stack_damage(held, amount);
	if(before.id == held->id && before.durability == held->durability
	   && before.count == held->count)
		return;
	server_local_actor_slot_reply(player, &(struct client_rpc) {
		.type = CRPC_INVENTORY_SLOT,
		.payload.inventory_slot.window = WINDOWC_INVENTORY,
		.payload.inventory_slot.slot = held_slot,
		.payload.inventory_slot.item = *held,
	});
}

/* SADDLE-BY-HIT (saddle-slice, 2026-08-13). ItemSaddle.hitEntity -> saddleEntity
   [740c583]: the SAME "ItemStack.hitEntity, reached whether or not the hit
   actually landed" call site the weapon-wear helper above implements --
   EntityPlayer.attackTargetEntityWithCurrentItem calls
   ItemStack.hitEntity on the held stack UNCONDITIONALLY right after
   attackEntityFrom, so an i-frame-ABSORBED swing still saddles. Only a PIG
   target saddles (saddleEntity's EntityPig type check); any
   other monster hit with a saddle held is a no-op, matching Beta exactly.
   Consumes exactly one saddle (stack size minus one) ONLY when the pig was not
   already saddled (the getSaddled check) -- re-hitting an already-saddled
   pig costs nothing. BY POINTER, not the caller's inventory_get_hotbar_item
   copy: same reason as server_local_wear_held_item above. maxStackSize 1
   (ItemSaddle ctor) means a successful saddle always empties the slot, but the
   decrement is written generically like Beta's stackSize--. */
static void server_local_saddle_pig(struct server_local* s,
									struct server_player* player,
									struct entity* pig) {
	assert(s && pig && pig->type == ENTITY_MONSTER
		   && pig->data.monster.id == MONSTER_PIG);
	/* Adversarial review finding 4 (defense in depth): the call site already
	   gates on MONSTER_PIG, and the assert above documents that contract, but
	   an assert compiles OUT under NDEBUG (the shipping .dol -- see CLAUDE.md's
	   assert-under-NDEBUG trap). Re-check for real here too, so a FUTURE
	   refactor that folds saddle-by-hit into the generic per-monster attack
	   dispatch (the way entity_wolf_interact already runs unconditionally,
	   self-filtering) can't accidentally saddle a non-pig monster if it forgets
	   to re-add the outer gate. Matches Beta's OWN redundancy: ItemSaddle.
	   saddleEntity's `if (var2 instanceof EntityPig)` [740c583] lives INSIDE
	   saddleEntity, not only at its one call site. */
	if(pig->type != ENTITY_MONSTER || pig->data.monster.id != MONSTER_PIG)
		return;
	size_t held_slot
		= INVENTORY_SLOT_HOTBAR + inventory_get_hotbar(&player->inventory);
	struct item_data* held = &player->inventory.items[held_slot];
	if(held->id != ITEM_SADDLE || held->count == 0
	   || pig->data.monster.saddled)
		return;
	pig->data.monster.saddled = true;
	if(--held->count == 0)
		*held = (struct item_data) {0};
	server_local_actor_slot_reply(player, &(struct client_rpc) {
		.type = CRPC_INVENTORY_SLOT,
		.payload.inventory_slot.window = WINDOWC_INVENTORY,
		.payload.inventory_slot.slot = held_slot,
		.payload.inventory_slot.item = *held,
	});
}

/* F4-RNG (ASTRA-RNG2-RULING 1/2/5/6): every block drop draws from the
 * AFFECTED world's own java.util.Random World.rand (struct server_world.rand)
 * -- ordinary harvests, blast drops (Explosion.doEffects:157), support-loss
 * cascades and fluid-planned drops alike. The world is always passed or
 * resolved from the dispatch (block_world), never from the host/view owner.
 * `crop_pos` selects BlockCrops' own FLOAT seed-position arithmetic. */
typedef bool (*server_local_drop_unit_emit)(
	struct server_local* s, struct java_random* rng,
	struct block_info* blk_info, struct item_data item, bool crop_pos,
	void* ctx);

static void server_local_block_drop_position(
	struct java_random* rng, const struct block_info* blk_info,
	bool crop_pos, float pos[3]) {
	assert(rng && blk_info && pos);
	const float spread = 0.7F;
	const int at[3] = {blk_info->x, blk_info->y, blk_info->z};
	for(int k = 0; k < 3; k++) {
		const float draw = jrand_next_float(rng);
		if(crop_pos) {
			/* BlockCrops.dropBlockAsItemWithChance:89-93: offset = nextFloat()
			 * * spread + (1.0F - spread) * 0.5F in FLOAT, then
			 * (double)((float)x + offset) -- all-float addition. */
			const float off = draw * spread + (1.0F - spread) * 0.5F;
			pos[k] = (float)at[k] + off;
		} else {
			/* Block.dropBlockAsItem_do:317-319: (double)(nextFloat() * var6) +
			 * (double)(1.0F - var6) * 0.5D, added to (double)x; narrowed only
			 * because CaveWii stores entity coordinates as floats. */
			const double inset = (double)(1.0F - spread) * 0.5;
			pos[k] = (float)((double)at[k] + (double)(draw * spread) + inset);
		}
	}
}

static bool server_local_spawn_drop_unit(struct server_local* s,
									 struct java_random* rng,
									 struct block_info* blk_info,
									 struct item_data item, bool crop_pos,
									 void* ctx) {
	struct server_world* w = ctx; /* A1a: the world the drop joins */
	assert(w && w->session == s);
	struct server_local_planned_drop drop = {.item = item};
	drop.item.count = 1;
	/* Wii OOM policy: own memory and both no-allocation publish capacities before
	 * the three World.rand offsets or four Math.random constructor draws. A
	 * failed cosmetic drop therefore advances neither stream. */
	drop.reserved_entity = server_entity_malloc();
	if(!drop.reserved_entity)
		return true;
	if(!server_local_reserve_planned_drop_batch(s, 1)) {
		server_local_cancel_planned_drop(&drop);
		return true;
	}
	server_local_block_drop_position(rng, blk_info, crop_pos, drop.pos);
	server_local_commit_planned_drop_batch(w, &drop, 1);
	/* Ordinary block drops treat an entity-cap/OOM failure as a dropped cosmetic
	 * item and continue enumerating later units. */
	return true;
}

// Beta Block.dropBlockAsItemWithChance. The chance is per quantityDropped
// unit, uses <=, and consumes no chance draw when quantityDropped is zero.
// BlockCrops is an override: chance gates only the wheat super-drop; then each
// of the three seed trials runs and a successful trial IMMEDIATELY draws its
// three float positions (interleaved, BlockCrops.java:85-108). Gravel/tall-
// grass choose their random id only after the chance succeeds, matching
// idDropped(meta, rand) order. All draws are on `rng` = the affected world's
// World.rand; vanilla quantity is evaluated once before chance and identity. [decompile 740c583 Block.java:294-326, BlockCrops.java,
// Explosion.java]
static bool server_local_enumerate_block_drops_with_chance(
	struct server_world* w, struct java_random* rng,
	struct block_info* blk_info, float chance,
	server_local_drop_unit_emit emit, void* emit_ctx) {
	struct server_local* s = w->session;
	assert(s && rng && blk_info);
	assert(emit);
	assert(chance >= 0.0F && chance <= 1.0F);

	/* Beta server BlockPistonMoving.dropBlockAsItemWithChance:57-63 calls
	 * the stored block's COMPLETE dropBlockAsItem operation (chance 1), not
	 * just idDropped/quantityDropped. Keep its crop override and chance/id
	 * ordering, at this position and in the affected world's callback scope. */
	struct block_data stored_data;
	struct block_info stored_info;
	if(blk_info->block->type == BLOCK_PISTON_MOVING) {
		struct item_data stored;
		struct server_world* previous = block_world_enter(s, w);
		bool found = piston_moving_stored(s, blk_info->x, blk_info->y,
			blk_info->z, &stored);
		block_world_leave(s, previous);
		if(!found || stored.id >= 256 || stored.id == BLOCK_PISTON_MOVING)
			return true;
		stored_data = (struct block_data) {.type = (uint8_t)stored.id,
			.metadata = (uint8_t)(stored.durability & 0x0F)};
		stored_info = *blk_info;
		stored_info.block = &stored_data;
		blk_info = &stored_info;
		chance = 1.0F;
	}

	const uint8_t type = blk_info->block->type;
	const struct block* block = blocks[type];
	if(!block || !block->getDroppedItem)
		return true;

	/* BlockBed.dropBlockAsItemWithChance:184-188 skips the 0x8 half entirely
	 * (isBlockFootOfBed(meta) = meta&8; PAR-BED-META: Beta's own layout, so
	 * only the half WITHOUT 0x8 drops); unlike a door's id=0, no chance. */
	if(type == BLOCK_BED && bed_meta_is_head(blk_info->block->metadata))
		return true;

	if(type == BLOCK_CROPS) {
		// quantityDropped is one even for immature crops, so the super call
		// always consumes its chance draw; idDropped is wheat only at meta 7
		// (-1 otherwise: no item, so no position draws).
		bool wheat_pass = jrand_next_float(rng) <= chance;
		if((blk_info->block->metadata & 0x0F) == 7 && wheat_pass
		   && !emit(s, rng, blk_info,
				   (struct item_data) {.id = ITEM_WHEAT,
									  .durability = 0,
									  .count = 1},
				   false, emit_ctx))
			return false;
		for(int i = 0; i < 3; i++)
			if(jrand_next_int_bound(rng, 15)
			   <= (blk_info->block->metadata & 0x0F)
			   && !emit(
					s, rng, blk_info,
					(struct item_data) {.id = ITEM_SEED, .durability = 0,
										.count = 1},
					true, emit_ctx))
				return false;
		return true;
	}

	if(type > BLOCK_TRAP_DOOR) {
		struct java_random tmp = *rng;
		size_t count = block->getDroppedItem(blk_info, NULL, &tmp, s);
		if(count == 0) {
			// Preserve the legacy extension callback's RNG behavior even
			// when it returns no items. Vanilla uses quantityDropped below.
			(void)block->getDroppedItem(blk_info, NULL, rng, s);
			return true;
		}

		struct item_data items[count];
		/* Block callbacks write the three vanilla fields individually. Their
		 * freshly created drops have no imported compound (the former padding
		 * byte must not become a random opaque-record handle). */
		for(size_t k = 0; k < count; k++) items[k].nbt_record = 0;
		size_t actual = block->getDroppedItem(blk_info, items, rng, s);
		assert(actual == count);
		if(actual < count)
			count = actual;

		for(size_t k = 0; k < count; k++)
			for(uint8_t unit = 0; unit < items[k].count; unit++)
				if(jrand_next_float(rng) <= chance
				   && !emit(s, rng, blk_info, items[k], false, emit_ctx))
					return false;
		return true;
	}

	/* Block.java:300-309: quantity once, then chance, then id for EACH
	 * successful unit. A zero/negative id does not erase its chance draw.
	 * getDroppedItem supplies identity only; its legacy stack count is not
	 * quantityDropped. No live count/probe call consumes a second roll. */
	const int quantity = block_quantity_dropped(type, rng);
	for(int unit = 0; unit < quantity; unit++) {
		if(jrand_next_float(rng) > chance)
			continue;
		struct item_data item = {0};
		if(block->getDroppedItem(blk_info, &item, rng, s) > 0
		   && item.id != 0) {
			item.count = 1;
			if(!emit(s, rng, blk_info, item, false, emit_ctx))
				return false;
		}
	}
	return true;
}

void server_local_spawn_block_drops_with_chance(
	struct server_world* w, struct block_info* blk_info, float chance) {
	assert(w && w->session);
	(void)server_local_enumerate_block_drops_with_chance(
		w, &w->rand, blk_info, chance, server_local_spawn_drop_unit,
		w);
}

struct server_local_plan_drop_ctx {
	server_local_planned_drop_sink sink;
	void* sink_ctx;
};

static bool server_local_plan_drop_unit(
	struct server_local* s, struct java_random* rng,
	struct block_info* blk_info, struct item_data item, bool crop_pos,
	void* opaque) {
	(void)s;
	struct server_local_plan_drop_ctx* ctx = opaque;
	assert(ctx && ctx->sink);
	struct server_local_planned_drop drop = {.item = item};
	drop.item.count = 1;
	/* Own detached memory before the offset draws. Capacity is preflighted for
	 * the whole batch at transaction commit; Math.random constructor draws are
	 * deferred until that preflight succeeds. No Math consumer can interleave
	 * with synchronous populate, so successful order remains byte-for-byte. */
	drop.reserved_entity = server_entity_malloc();
	if(!drop.reserved_entity)
		return false;
	server_local_block_drop_position(rng, blk_info, crop_pos, drop.pos);
	if(ctx->sink(ctx->sink_ctx, &drop))
		return true;
	free(drop.reserved_entity);
	return false;
}

bool server_local_plan_block_drops_w(
	struct server_world* w, struct block_info* blk_info,
	server_local_planned_drop_sink sink, void* sink_ctx) {
	if(!w || !w->session || !blk_info || !sink
	   || !blocks[blk_info->block->type])
		return false;
	/* Every currently fluid-displaceable block has a side-effect-free onBreak;
	 * tests/test_fluid_lifecycle_env.c pins that registry invariant.  Refuse a
	 * future exception rather than executing an unjournaled callback. */
	if(blocks[blk_info->block->type]->onBreak)
		return false;
	struct server_local_plan_drop_ctx ctx = {
		.sink = sink, .sink_ctx = sink_ctx};
	return server_local_enumerate_block_drops_with_chance(
		w, &w->rand, blk_info, 1.0F, server_local_plan_drop_unit,
		&ctx);
}

bool server_local_plan_block_drops(
	struct server_local* s, struct block_info* blk_info,
	server_local_planned_drop_sink sink, void* sink_ctx) {
	if(!s)
		return false;
	/* The dispatch world (block_world): legacy s-only callers. */
	return server_local_plan_block_drops_w(block_world(s), blk_info, sink,
										   sink_ctx);
}

void server_local_cancel_planned_drop(
	struct server_local_planned_drop* drop) {
	if(!drop || !drop->reserved_entity)
		return;
	free(drop->reserved_entity);
	drop->reserved_entity = NULL;
}

bool server_local_reserve_planned_drop_batch(
	struct server_local* s, size_t count) {
	if(count == 0)
		return true;
	if(!s)
		return false;
	/* Reserve both no-allocation commit surfaces while the caller can still
	 * roll back its world journal. If dictionary reserve fails, the tick-list
	 * reservation is cancelled before reporting failure. */
	if(!server_local_entity_join_reserve(s, count))
		return false;
	if(!server_local_entity_dict_reserve(s, count)) {
		server_local_entity_join_cancel(s, count);
		return false;
	}
	return true;
}

void server_local_commit_planned_drop_batch(
	struct server_world* w, struct server_local_planned_drop* drops,
	size_t count) {
	if(count == 0)
		return;
	assert(w && w->session && (count == 0 || drops));
	struct server_local* s = w->session;
	for(size_t i = 0; i < count; i++) {
		struct server_local_planned_drop* drop = &drops[i];
		struct entity* e = drop->reserved_entity;
		if(!e)
			server_local_reservation_violation(
				"planned item commit without detached entity");
		uint32_t id = server_local_gen_id(s);
		entity_item(id, e, true, w, drop->item);
		e->teleport(e, drop->pos);
		/* The detached entity and dictionary/tick capacities are already owned;
		 * this exact four-draw constructor step has no failure point. */
		server_local_item_velocity(&s->player, false, &s->rand_src, e->vel);
		e->data.item.death_transaction = 0;
		e->data.item.death_sequence = 0;
		// FH-12: this is the ONE choke point every ordinary block-break drop
		// funnels through (server_local_spawn_block_drops(_with_chance/
		// _after_break) -> spawn_drop_unit/plan_drop_unit -> here).
		// [740c583: Block.dropBlockAsItem_do -- `var13.delayBeforeCanPickup
		// = 10;`]
		e->data.item.pickup_delay = 10;

		if(dict_entity_get(s->entities, id) != NULL)
			server_local_reservation_violation(
				"planned item id unexpectedly occupied");
		server_local_entity_dict_consume(s, 1);
		struct entity** slot = dict_entity_safe_get(s->entities, id);
		if(*slot != NULL)
			server_local_reservation_violation(
				"planned item reserved slot unexpectedly occupied");
		*slot = e;
		server_local_entity_join_reserved_batch(s, &id, 1);
		if(server_local_world_publishes(s, w))
			server_local_publish_item(s, e);
		drop->reserved_entity = NULL;
#ifdef CAVEWII_SERVER_LOCAL_TEST
		s_planned_drop_publish_total++;
#endif
	}
}

/* BlockSnow.harvestBlock:50-60 and BlockTNT.onBlockDestroyedByPlayer:44-46
 * call dropBlockAsItem_do directly: three position floats, NO chance draw.
 * Their normal quantityDropped is zero for blasts/support loss/pistons. */
static void server_local_harvest_block_drops(struct server_local* s,
										   struct block_info* info) {
	const uint8_t type = info->block->type;
	if(type == BLOCK_SNOW || type == BLOCK_TNT) {
		struct server_world* w = block_world(s);
		struct item_data item = {.id = type == BLOCK_SNOW ? ITEM_SNOW_BALL : BLOCK_TNT,
								 .count = 1};
		(void)server_local_spawn_drop_unit(s, &w->rand, info, item, false, w);
		return;
	}
	server_local_spawn_block_drops_after_break(s, info);
}

static void server_local_spawn_block_drops_impl(
	struct server_local* s, struct block_info* blk_info, bool run_break) {
	assert(s && blk_info);
	if(!blocks[blk_info->block->type])
		return;
	if(run_break && blocks[blk_info->block->type]->onBreak)
		blocks[blk_info->block->type]->onBreak(s, blk_info);
	/* A1a legacy: block-callback drop paths have only a server_local. */
	server_local_spawn_block_drops_with_chance(block_world(s), blk_info, 1.0F);
}

void server_local_spawn_block_drops(struct server_local* s,
									struct block_info* blk_info) {
	server_local_spawn_block_drops_impl(s, blk_info, true);
}

void server_local_spawn_block_drops_after_break(
	struct server_local* s, struct block_info* blk_info) {
	server_local_spawn_block_drops_impl(s, blk_info, false);
}

#ifdef CAVEWII_SERVER_LOCAL_TEST
static bool s_fail_next_window_alloc = false;
void server_local_test_fail_next_window_alloc(void) {
	s_fail_next_window_alloc = true;
}
#endif

static bool server_local_window_actor_valid(struct server_local* s,
	struct server_player* player) {
	return s && player && (player == &s->player
		|| (player->inventory.owner == player && player->inventory.user == s
			&& player->inventory.reply));
}

/* Process-lifetime generation: a freshly allocated provider cannot reuse a
 * token left in the main-thread pending FIFO by the previous provider. Only
 * the local server thread issues tokens; exhaustion fails instead of wrapping. */
static uint64_t server_guest_generation;
bool server_local_bind_guest(struct server_local* s, struct server_player* actor,
	struct server_rpc_source* source) {
	if(!s || !source || !actor || actor == &s->player || s->guest_actor
	   || !server_local_window_actor_valid(s, actor)
	   || actor->active_inventory != &actor->inventory
	   || inventory_get_picked_item(&actor->inventory, NULL)
	   || server_guest_generation == UINT64_MAX)
		return false;
	s->guest_actor = actor;
	s->guest_generation = ++server_guest_generation;
	/* A new attach is a new physical body. Register its already-authored
	 * offer pose now; a previous occupant's entry is stale. */
	actor->added_to_chunk = false;
	server_local_refresh_guest_membership(s);
	/* A new attach is a new client with its own ticket numbering, so the
	 * previous occupant's retired ticket must not make the newcomer's first
	 * request look stale. The client tears its windows down across the same
	 * boundary (client_session_clear_windows), so no in-flight request from
	 * the old attach can still be waiting for a reply. */
	actor->recipe_craft_ticket = 0;
	actor->recipe_craft_reason = RECIPE_CRAFT_INVALID_REQUEST;
	*source = (struct server_rpc_source){.slot = 1, .generation = s->guest_generation};
	/* S1-d: a new attach is a new BODY with its own (zeroed) tallies, so the
	 * published slot-1 mirror must not keep showing the previous occupant's.
	 * Same reasoning as the ticket reset just above. */
	for(unsigned k = 0; k < SERVER_ACTION_COUNT; k++)
		__atomic_store_n(&s->actor_actions[1][k], 0u, __ATOMIC_RELAXED);
	return true;
}

bool server_local_unbind_guest(struct server_local* s,
	const struct server_rpc_source* source) {
	if(!s || !source || s->guest_owned || source->slot != 1 || !source->generation
	   || source->generation != s->guest_generation || !s->guest_actor)
		return false;
	struct server_player* actor = s->guest_actor;
	if(actor->active_inventory != &actor->inventory
	   || inventory_get_picked_item(&actor->inventory, NULL))
		return false;
	actor->added_to_chunk = false; /* v5: leaves every section list */
	if(s->guest_gameplay) game_event_emit(&(struct game_event){
		.kind = GE_SESSION_END, .authority = GE_AUTH_SERVER,
		.who = {.slot = 1, .generation = s->guest_generation}});
	s->guest_actor = NULL;
	s->a2w_guest_presentation = false;
	s->guest_generation = 0;
	s->guest_respawn_phase = GUEST_RESPAWN_IDLE;
	/* Active tuple retires here; the server-lifetime counter must never reuse
	 * an epoch for a later binding. */
	s->guest_respawn_epoch = 0;
	s->guest_respawn_generation = 0;
	s->guest_respawn_anchor = false;
	s->guest_respawn_ready = false;
	s->guest_gameplay = false;
	s->guest_entity_id = 0;
	/* Same rule as guest_release: the departing body owes nothing, and the
	 * refresh pass will not clear it once two-anchor mode ends. */
	server_local_residency_release_anchor(s, 1);
	/* ...and RECONCILE, exactly as guest_release does (R-A8 A8-L9). This is a
	 * clear of s->guest_gameplay, and since the live switch landed that field
	 * is load-bearing for three things a bare clear does not touch: the
	 * residency block's lifetime (server_local_residency_sync's disjunction),
	 * the transport accept class (svin_set_split_accept) and the split
	 * radius/far-ring policy. Leaving them behind would strand the block for
	 * the rest of the session and leave slot-1 SRPC_PLAYER_POS admitted.
	 *
	 * Today this call cannot change anything, and that is PROVEN rather than
	 * argued: tests/test_split_live_toggle.c A8 drives the production APIs and
	 * shows this function REFUSES while a body is admitted (it requires
	 * !s->guest_owned; admission requires s->guest_owned), so every reachable
	 * arrival here already has guest_gameplay == false. The call is here so the
	 * invariant "every clear of guest_gameplay reconciles" holds by
	 * construction instead of by that reachability argument -- A8's second leg
	 * forces the state anyway and pins the reconcile. It can only ever FREE or
	 * no-op (the wanted set strictly shrinks), never allocate, which is the
	 * same precondition server_local_split_policy_apply already asserts. */
	server_local_split_policy_apply(s);
	return true;
}

/* ===== S1-a2 actor identity resolution (../entity/actor_ident.h) ========
 * The ONE place a stored {slot, generation} role becomes a live actor. Kept
 * here, beside bind/unbind, because the guest generation this validates
 * against is issued by server_local_bind_guest immediately above.
 *
 * The guest leg requires all four of: the slot, a nonzero generation, an
 * EXACT match against the live s->guest_generation, and an admitted gameplay
 * body (s->guest_gameplay + s->guest_actor). guest_release / unbind zero the
 * generation and clear guest_gameplay, and every new admission takes the NEXT
 * value of a process-lifetime counter that never wraps (bind refuses at
 * UINT64_MAX), so a role stamped for a departed session can never resolve --
 * not on leave, not on death-release, not on rejoin. That is the whole
 * lifetime-safety argument; there is no retained actor pointer anywhere. */
struct server_player* server_local_actor_resolve(struct server_local* s,
	struct actor_ident id) {
	if(!s)
		return NULL;
	if(id.slot == ACTOR_SLOT_HOST)
		return id.generation == 0 ? &s->player : NULL;
	if(id.slot != ACTOR_SLOT_GUEST || !id.generation)
		return NULL;
	if(!s->guest_gameplay || !s->guest_actor
	   || id.generation != s->guest_generation)
		return NULL;
	return s->guest_actor;
}

/* S1-a3: enumerate the LOCAL PLAYER BODIES a world hit may damage, in a fixed
 * order so a sweep is deterministic. Index 0 is always the host (Beta's single
 * EntityPlayer, and the only candidate the pre-split sweeps ever tested);
 * index 1 is the admitted guest body or NULL. Deliberately a plain indexed
 * getter rather than a pointer array: entity_arrow.c / entity_egg.c /
 * entity_fish.c must not see struct server_local's layout (they include
 * server_local.h, not server_local_state.h), and a getter keeps the "no
 * retained actor pointer" rule -- callers re-ask every sweep.
 *
 * `guest_gameplay` is the same admission leg server_local_actor_resolve uses,
 * so a guest that is merely ATTACHED (window-only) is not a damage candidate,
 * and with the split switch off index 1 is always NULL -- which is why every
 * sweep below is byte-identical on the OFF path (test_split_off_equiv). */
struct server_player* server_local_damage_candidate(
	struct server_local* s, unsigned index) {
	if(!s)
		return NULL;
	if(index == 0)
		return &s->player;
	if(index != 1)
		return NULL;
	return (s->guest_gameplay && s->guest_actor) ? s->guest_actor : NULL;
}

struct actor_ident server_local_actor_ident(const struct server_local* s,
	const struct server_player* player) {
	if(!s || !player || player == &s->player)
		return ACTOR_IDENT_HOST;
	/* An actor that is not the host can only be the admitted guest body; any
	 * other pointer is a caller bug, and stamping it as the host would be a
	 * silent mis-attribution, so refuse it loudly under the test build's
	 * forced asserts and fall back to the host (no role change) in release. */
	assert(player == s->guest_actor);
	if(player != s->guest_actor)
		return ACTOR_IDENT_HOST;
	return (struct actor_ident) {.slot = ACTOR_SLOT_GUEST,
								 .generation = s->guest_generation};
}

void server_local_window_reply(struct inventory* inv, struct client_rpc* call) {
	if(inv->reply)
		inv->reply(call, inv->reply_user);
	else
		clin_rpc_send(call);
}

bool server_local_has_chest_view(struct server_local* s,
	w_coord_t x, w_coord_t y, w_coord_t z) {
	return inventory_chest_view_at(s, x, y, z) != NULL;
}

bool server_local_open_inventory(struct server_local* s,
	struct inventory_logic* logic, size_t capacity, w_coord_t x, w_coord_t y,
	w_coord_t z, uint8_t window, uint8_t type) {
	return server_local_open_inventory_for(s, s ? &s->player : NULL,
		logic, capacity, x, y, z, window, type);
}

bool server_local_open_linked_inventory(struct server_local* s,
	struct inventory_logic* logic, size_t capacity, w_coord_t x, w_coord_t y,
	w_coord_t z, w_coord_t x2, w_coord_t y2, w_coord_t z2,
	uint8_t window, uint8_t type) {
	return server_local_open_linked_inventory_for(s, s ? &s->player : NULL,
		logic, capacity, x, y, z, x2, y2, z2, window, type);
}

bool server_local_open_entity_inventory(struct server_local* s,
	struct inventory_logic* logic, size_t capacity, uint32_t entity_id,
	uint8_t window, uint8_t type) {
	return server_local_open_entity_inventory_for(s, s ? &s->player : NULL,
		logic, capacity, entity_id, window, type);
}

static bool server_local_open_inventory_impl(
	struct server_local* s, struct server_world* w, struct server_player* player, struct inventory_logic* logic, size_t capacity,
	w_coord_t x, w_coord_t y, w_coord_t z, bool linked, w_coord_t x2,
	w_coord_t y2, w_coord_t z2, uint8_t window, uint8_t type) {
	// The whitelist IS the registry (window_registry.h). It used to be a
	// hand-maintained chain, and D8 shipped because the dispenser's row was
	// never added to it: every server_local_open_inventory call for the
	// dispenser -- including block_dispenser.c's onRightClick -- failed closed
	// on contract_valid alone, so its GUI could not open at all.
	// WINDOW_KEY_BLOCK excludes the player's own inventory (capacity 0) and the
	// entity-keyed storage minecart, which has its own open path below.
	const struct window_desc* desc = window_registry_find(logic);
	bool contract_valid = desc && desc->key == WINDOW_KEY_BLOCK
		&& desc->capacity != 0 && capacity == desc->capacity
		&& window == desc->windowc && type == desc->wire_type
		&& linked == desc->linked;
	if(!server_local_window_actor_valid(s, player) || !logic || capacity == 0 || capacity > UINT8_MAX
	   || !contract_valid
	   || !player->has_pos
	   || player->active_inventory != &player->inventory)
		return false;

	#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(s_fail_next_window_alloc) {
		s_fail_next_window_alloc = false;
		return false;
	}
	#endif
	/* A1b: bind the window to its opening world BEFORE on_create runs, so
	 * the backing lookup inside on_create already resolves through it. */
	if(!w || w->session != s || server_world_handle_of(w).generation == 0)
		return false;
	struct inventory* inv = malloc(sizeof(*inv));
	if(!inv)
		return false;

	struct server_world_handle prior_binding = player->window_world;
	player->window_world = server_world_handle_of(w);
	bool created = linked ?
		inventory_create_linked(inv, logic, s, player, capacity, x, y, z,
								x2, y2, z2) :
		inventory_create(inv, logic, s, player, capacity, x, y, z);
	if(!created) {
		// inventory_create owns and releases its item array on a failed
		// populate; the unpublished outer allocation is still ours.
		player->window_world = prior_binding;
		free(inv);
		return false;
	}

	// Publish only after every fallible allocation and backing-owner lookup has
	// succeeded. OPEN must remain FIFO-ahead of the authoritative snapshot.
	inv->reply = player->inventory.reply;
	inv->reply_user = player->inventory.reply_user;
	player->active_inventory = inv;
	server_local_window_reply(inv, &(struct client_rpc) {
		.type = CRPC_OPEN_WINDOW,
		.payload.window_open.window = window,
		.payload.window_open.type = (enum window_type)type,
		.payload.window_open.slot_count = (uint8_t)capacity,
	});
	for(size_t slot = 0; slot < capacity; slot++)
		server_local_window_reply(inv, &(struct client_rpc) {
			.type = CRPC_INVENTORY_SLOT,
			.payload.inventory_slot.window = window,
			.payload.inventory_slot.slot = (uint8_t)slot,
			.payload.inventory_slot.item = inv->items[slot],
		});
	return true;
}

