// Reset every positional tile-entity table that is keyed only by (x,y,z) with
// no world key and repopulated per-chunk by te_store_insert. ONE helper for
// BOTH callers -- first-boot init (server_local_init: server_local lives on
// main()'s STACK, so an uncovered table reads garbage; a garbage y >= 0 makes
// every free-slot scan see the slot as occupied) and the world-load boundary
// (world A's slots would otherwise keep ticking/leaking into world B, the
// exact class the furnace clear below documented). Hand-rolled per-site kind
// lists are how BOTH holes happened (dispensers missing from init AND the
// boundary; notes/records missing from the boundary) -- the same enumeration
// drift D12's tile_entities_any() closed on the save side.
// ADDING A TE KIND with a positional table? Its arrays go HERE, nowhere else.
// (Chests/signs are deliberately absent: their monolithic archive reader
// memsets them on load. piston_moving has its own store clear/init.)
// Map part 2a: same reasoning as the positional tables below -- id-keyed
// rather than position-keyed (see MAX_MAP_CACHE's doc comment), but the same
// "uncovered == garbage read as a live slot on Wii's stack" and "world-load
// boundary must not leak world A's cached maps into world B" hazards apply
// identically. (A1b split it out so the world-load boundary can release one
// slot's tile rows while keeping this session-level reset.)
static void server_local_reset_map_cache(struct server_local* s) {
	for(size_t i = 0; i < MAX_MAP_CACHE; i++) s->map_cache_id[i] = INT32_MIN;
	memset(s->map_cache_data, 0, sizeof(s->map_cache_data));
	memset(s->map_cache_dirty, 0, sizeof(s->map_cache_dirty));
	memset(s->map_cache_touch, 0, sizeof(s->map_cache_touch));
	s->map_cache_touch_counter = 0;
	memset(s->map_cache_holder_count, 0, sizeof(s->map_cache_holder_count));
	memset(s->map_client_sent_any, 0, sizeof(s->map_client_sent_any));
	memset(s->map_client_generation, 0, sizeof(s->map_client_generation));
}

static void server_local_reset_positional_te_tables(struct server_local* s) {
	/* IMP-TE-CAPS: the tables are slabs of te_rows[kind] rows each. */
	size_t nf = (size_t)s->te_rows[TE_KIND_FURNACE];
	size_t nd = (size_t)s->te_rows[TE_KIND_DISPENSER];
	size_t nn = (size_t)s->te_rows[TE_KIND_NOTE];
	size_t nr = (size_t)s->te_rows[TE_KIND_RECORD_PLAYER];
	size_t ns = (size_t)s->te_rows[TE_KIND_SPAWNER];
	struct te_owner_table* o = &s->te_owners;
	memset(s->furnace_pos, -1, nf * sizeof(*s->furnace_pos)); // .y < 0 == free
	memset(s->furnaces, 0, nf * sizeof(*s->furnaces));
	memset(s->dispenser_pos, -1, nd * sizeof(*s->dispenser_pos));
	memset(s->dispensers, 0, nd * sizeof(*s->dispensers));
	memset(s->note_pos, -1, nn * sizeof(*s->note_pos));
	memset(s->notes, 0, nn * sizeof(*s->notes));
	memset(s->note_prev_powered, 0, nn * sizeof(*s->note_prev_powered));
	memset(s->record_player_pos, -1, nr * sizeof(*s->record_player_pos));
	memset(s->records, 0, nr * sizeof(*s->records));
	// FH-17: same reasoning as furnace/dispenser/note/record_player above --
	// uncovered here means a fresh session's table reads garbage as a live
	// y>=0 slot, and a world-load boundary would otherwise leak world A's
	// spawner TEs into world B.
	memset(s->spawner_te_pos, -1, ns * sizeof(*s->spawner_te_pos));
	memset(s->spawner_tes, 0, ns * sizeof(*s->spawner_tes));
	/* A1b: every row above is free, so every owner key is world-neutral --
	 * all seven kinds, as the old whole-struct memset did. */
	size_t nc = (size_t)s->te_rows[TE_KIND_CHEST];
	size_t ng = (size_t)s->te_rows[TE_KIND_SIGN];
	memset(o->chest_slot, 0, nc);
	memset(o->chest_gen, 0, nc * sizeof(uint32_t));
	memset(o->sign_slot, 0, ng);
	memset(o->sign_gen, 0, ng * sizeof(uint32_t));
	memset(o->furnace_slot, 0, nf);
	memset(o->furnace_gen, 0, nf * sizeof(uint32_t));
	memset(o->dispenser_slot, 0, nd);
	memset(o->dispenser_gen, 0, nd * sizeof(uint32_t));
	memset(o->note_slot, 0, nn);
	memset(o->note_gen, 0, nn * sizeof(uint32_t));
	memset(o->record_slot, 0, nr);
	memset(o->record_gen, 0, nr * sizeof(uint32_t));
	memset(o->spawner_slot, 0, ns);
	memset(o->spawner_gen, 0, ns * sizeof(uint32_t));
	server_local_reset_map_cache(s);
}

static bool mob_spawn_box_blocked(struct server_local* s, struct AABB* box);

/* Beta Entity.preparePlayerToSpawn:96-110 on an EYE-basis pos[] (CaveWii's
 * player y is posY = feet + PLAYER_EYE_HEIGHT): raise by whole blocks while
 * the 0.6 x 1.8 box collides (EntityPlayer.preparePlayerToSpawn:150-156 sets
 * yOffset 1.62F and setSize(0.6F, 1.8F) first). Shared by the first-join
 * push-up and the perf_stress load setup (BUG-SPAWN). */
static void server_local_prepare_player_to_spawn(struct server_local* s,
	float pos[3]) {
	const float half_width = 0.6F / 2.0F;
	while(pos[1] > 0.0F) {
		struct AABB box = {
			.x1 = pos[0] - half_width,
			.y1 = pos[1] - PLAYER_EYE_HEIGHT,
			.z1 = pos[2] - half_width,
			.x2 = pos[0] + half_width,
			.y2 = pos[1] - PLAYER_EYE_HEIGHT + 1.8F,
			.z2 = pos[2] + half_width,
		};
		if(!mob_spawn_box_blocked(s, &box))
			break;
		pos[1] += 1.0F;
	}
}

/* next-gaps-0924/W1A-b -- Beta's FIRST-JOIN push-up.
 *   Minecraft.changeWorld:1284-1287 [retromcp b1.7.3 client]: a world with no
 *   saved player gets createPlayer(world) + thePlayer.preparePlayerToSpawn();
 *   Entity.preparePlayerToSpawn:96-110:
 *       while(posY > 0.0D) { setPosition(posX, posY, posZ);
 *           if(worldObj.getCollidingBoundingBoxes(this, boundingBox).size() == 0)
 *               break;
 *           ++posY; }
 *       motionX = motionY = motionZ = 0; rotationPitch = 0;
 * (EntityPlayer.preparePlayerToSpawn:150-156 first sets yOffset 1.62F and
 * setSize(0.6F, 1.8F)). CaveWii writes the new world's Player tag at CREATION
 * (screen_select_world.c), from a surface probe of UNPOPULATED terrain, so
 * the load path reads a tag Beta would not have and skipped this loop: a
 * tree/pumpkin/cactus populated onto the spawn column buried the player (and
 * now suffocates it). The tag is still that creation placeholder exactly when
 * the level.dat has never been SAVED: the one checkpoint that writes Player
 * also writes LastPlayed (server_local's level checkpoint, Beta
 * WorldInfo.updateTagCompound), and the template carries LastPlayed = 0. So
 * LastPlayed == 0 is Beta's "no saved player"; any saved world -- Beta's SSP
 * load of a saved Player tag, World.spawnPlayerWithLoadedChunks:256-276 -- is
 * never pushed.
 * The collision test is Beta's getCollidingBoundingBoxes on the live world
 * (mob_spawn_box_blocked, World.java:959 cell walk). The chunk is populated
 * first, because decoration is what can bury the spawn. Motion is zero and
 * the tag's pitch is 0 on this path already. Not applied to portal arrivals
 * (their Teleporter search) nor to the world-spawn fallback, which runs
 * server_local_anti_suffocate_column (eafbcedd) -- never both. If population
 * cannot complete, the saved position is kept (the pre-fix behaviour). */
static bool server_local_first_join_populate(struct server_local* s,
	const float pos[3]) {
	w_coord_t bx = (w_coord_t)floorf(pos[0]);
	w_coord_t bz = (w_coord_t)floorf(pos[2]);
	struct server_chunk* sc = NULL;
	bool populated = false;
	for(unsigned n = 0; n < 64 && !populated; n++) {
		server_world_begin_update(&s->world);
		populated = server_world_ensure_populated(&s->world, s,
			WCOORD_CHUNK_OFFSET(bx), WCOORD_CHUNK_OFFSET(bz), &sc)
			&& sc;
	}
	return populated;
}

static void server_local_first_join_push_up(struct server_local* s,
	float pos[3]) {
	if(!server_local_first_join_populate(s, pos))
		return;
	server_local_prepare_player_to_spawn(s, pos);
}

/* REL-03: first join for the create-world placeholder in Beta's double
 * posY: feet SpawnY+1 (EntityPlayer.java:40-48), whole-block push-up while
 * the body collides (Entity.java:96-109), eye built in double at the end.
 * False (eye untouched) if population fails. */
static bool server_local_first_join_beta_eye(struct server_local* s,
	const float pos[3], int32_t feet, double* eye_out) {
	if(!server_local_first_join_populate(s, pos))
		return false;
	const float half_width = 0.6F / 2.0F;
	while((double)feet + (double)PLAYER_EYE_HEIGHT > 0.0) {
		struct AABB box = {
			.x1 = pos[0] - half_width,
			.y1 = (float)feet,
			.z1 = pos[2] - half_width,
			.x2 = pos[0] + half_width,
			.y2 = (float)feet + 1.8F,
			.z2 = pos[2] + half_width,
		};
		if(!mob_spawn_box_blocked(s, &box))
			break;
		feet++;
	}
	*eye_out = (double)feet + (double)PLAYER_EYE_HEIGHT;
	return true;
}

/* R3 (sweep seed 3141592653589793238): Beta's new-world spawn search on a
 * LIVE world, in ChunkProviderServer order.
 *   World.java:215-227 getInitialSpawnLocation walks with World.rand and
 *   probes each candidate through WorldProvider.canCoordinateBeSpawn ->
 *   World.getFirstUncoveredBlock -> World.getBlockId -> getChunkFromChunkCoords
 *   -> ChunkProviderServer.provideChunk/loadChunk (:67-95): the chunk is
 *   generated AND every 2x2 quadrant it completes (current, west, north,
 *   northwest) is populated right there. Population flows WorldGenLiquids
 *   springs immediately; a spring meeting water hardens through
 *   BlockFluid.triggerLavaMixEffects (:217-222), which draws World.rand twice
 *   -- the SAME Random the search walks with -- so the walk after that
 *   candidate differs from a raw-terrain probe. The column read is also
 *   post-population (a lake/tree can change the uncovered block).
 * server_world_load_chunk is this port's loadChunk (install, then populate
 * eligible resident quadrants in the same order; quad_fluid_lava_mix draws
 * w->rand). The search therefore runs on a temporary slot-0 world of the
 * session whose rand IS the caller's World.rand (copied in, copied back).
 * The world persists on teardown with each chunk's own TerrainPopulated
 * flag, so the load path neither re-populates a decorated chunk nor skips
 * one that still owes its population -- the same chunks Beta would hold in
 * memory, with the same decoration state.
 * Precondition: no world is loaded in `s` (create-world happens before the
 * load request). `dir` is the reserved world directory with its region/
 * folder (sworld_finish_create creates it before the search). */
#ifdef CAVEWII_SERVER_LOCAL_TEST
void (*server_local_test_spawn_search_phase)(struct server_world* w,
											 bool begin);
#endif

/* Resident-chunk bound for the search. Beta keeps every probed chunk in
 * memory; an ocean start can walk hundreds of chunks, more than the Wii heap
 * holds. Above SPAWN_SEARCH_RESIDENT_CAP the farthest chunks are saved and
 * leave residency (the streaming unload: TerrainPopulated kept per chunk, so
 * a reload is byte-identical and still owes exactly its own population).
 * What must stay identical to Beta is WHEN each quadrant populates, because
 * population draws World.rand (lava-mix fizz) on the search's own stream and
 * rewrites the columns the walk reads. Beta's ChunkProviderServer.loadChunk
 * populates a quadrant the moment its last member is loaded, and in Beta
 * "loaded" = ever loaded. So the search remembers every chunk it ever loaded
 * (`ever`); before a NEW chunk N loads, every quadrant that N completes
 * against `ever` gets its evicted members reloaded first, so loadChunk's
 * automatic population (current, west, north, northwest) fires exactly where
 * Beta's does. A reload of an already-populated-quadrant member populates
 * nothing (the flag is saved); a quadrant that was complete before N is
 * already populated, a quadrant not complete with N is left alone. */
#define SPAWN_SEARCH_RESIDENT_CAP 32
#ifdef CAVEWII_SERVER_LOCAL_TEST
static size_t s_test_spawn_search_peak_resident;
size_t server_local_test_spawn_search_peak_resident(void) {
	return s_test_spawn_search_peak_resident;
}
#endif

struct spawn_search_ctx {
	struct server_world* w;
	int64_t* ever; /* S_CHUNK_ID of every chunk the search has loaded */
	size_t n_ever, cap_ever;
	bool oom;
};

static bool spawn_search_ever(const struct spawn_search_ctx* c, w_coord_t x,
	w_coord_t z) {
	const int64_t id = S_CHUNK_ID(x, z);
	for(size_t i = 0; i < c->n_ever; i++)
		if(c->ever[i] == id)
			return true;
	return false;
}

/* Telemetry only (hw1030n): chunks the running search has loaded so far
 * ("ssw" heartbeat field, the "Finding a spawn point" screen). Written by the
 * server thread, read by main; never read by the search. */
static uint32_t s_spawn_search_probes;

static bool spawn_search_remember(struct spawn_search_ctx* c, w_coord_t x,
	w_coord_t z) {
	if(spawn_search_ever(c, x, z))
		return true;
	if(c->n_ever == c->cap_ever) {
		size_t ncap = c->cap_ever ? c->cap_ever * 2 : 64;
		int64_t* n = realloc(c->ever, ncap * sizeof(*n));
		if(!n)
			return false;
		c->ever = n;
		c->cap_ever = ncap;
	}
	c->ever[c->n_ever++] = S_CHUNK_ID(x, z);
	__atomic_store_n(&s_spawn_search_probes, (uint32_t)c->n_ever,
		__ATOMIC_RELAXED);
	return true;
}

/* Load (or reload from the search's own saves) one chunk, Beta's loadChunk. */
static bool spawn_search_load(struct spawn_search_ctx* c, w_coord_t x,
	w_coord_t z) {
	struct server_world* w = c->w;
	if(server_world_chunk_resident(w, x, z))
		return true;
	/* Pending light work pins quadrants against population; drain it first so
	 * loadChunk's automatic population is never skipped for a reason Beta's
	 * synchronous provider does not have. */
	for(unsigned n = 0; n < 64 && server_world_light_pending(w); n++)
		server_world_light_drain(w);
	struct server_chunk* sc = NULL;
	if(!server_world_load_chunk(w, x, z, &sc) || !sc)
		return false;
#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(dict_server_chunks_size(w->chunks) > s_test_spawn_search_peak_resident)
		s_test_spawn_search_peak_resident = dict_server_chunks_size(w->chunks);
#endif
	return spawn_search_remember(c, x, z);
}

/* Above the cap: save + unload the chunks farthest from the probe, never the
 * probe's own 3x3 (just (re)loaded for its quadrants), never a light-pinned
 * column. A refused unload leaves that chunk and moves on. */
static void spawn_search_evict(struct spawn_search_ctx* c, w_coord_t cx,
	w_coord_t cz) {
	struct server_world* w = c->w;
	while(dict_server_chunks_size(w->chunks) > SPAWN_SEARCH_RESIDENT_CAP) {
		int64_t best = 0;
		long best_d = -1;
		dict_server_chunks_it_t it;
		dict_server_chunks_it(it, w->chunks);
		while(!dict_server_chunks_end_p(it)) {
			const int64_t id = dict_server_chunks_ref(it)->key;
			const w_coord_t x = S_CHUNK_X(id), z = S_CHUNK_Z(id);
			dict_server_chunks_next(it);
			if(abs((int)(x - cx)) <= 1 && abs((int)(z - cz)) <= 1)
				continue;
			if(server_world_light_pinned(w, x, z))
				continue;
			const long d = (long)(x - cx) * (x - cx) + (long)(z - cz) * (z - cz);
			if(d > best_d) {
				best_d = d;
				best = id;
			}
		}
		if(best_d < 0)
			return;
		if(!server_world_save_chunk(w, true, S_CHUNK_X(best), S_CHUNK_Z(best))) {
			fprintf(stderr, "server_local: spawn search could not unload chunk "
							"(%d,%d); keeping it resident\n",
					(int)S_CHUNK_X(best), (int)S_CHUNK_Z(best));
			return;
		}
	}
}

static int server_local_spawn_search_block_id(void* ctx, int x, int y, int z) {
	struct spawn_search_ctx* c = ctx;
	struct server_world* w = c->w;
	const w_coord_t cx = WCOORD_CHUNK_OFFSET(x), cz = WCOORD_CHUNK_OFFSET(z);
	if(svin_spawn_cancelled())
		return -1; /* the requester gave up: fail the walk, no spawn */
	if(!server_world_chunk_resident(w, cx, cz)) {
		if(!spawn_search_ever(c, cx, cz)) {
			/* A chunk Beta has never seen: first bring back the evicted
			 * members of every quadrant this load completes (see above). */
			static const int origins[4][2] = {{0, 0}, {-1, 0}, {0, -1}, {-1, -1}};
			for(int q = 0; q < 4; q++) {
				const w_coord_t px = cx + origins[q][0], pz = cz + origins[q][1];
				bool complete = true;
				for(int dz = 0; dz < 2 && complete; dz++)
					for(int dx = 0; dx < 2 && complete; dx++) {
						const w_coord_t mx = px + dx, mz = pz + dz;
						if(mx == cx && mz == cz)
							continue;
						complete = spawn_search_ever(c, mx, mz);
					}
				if(!complete)
					continue;
				for(int dz = 0; dz < 2; dz++)
					for(int dx = 0; dx < 2; dx++) {
						const w_coord_t mx = px + dx, mz = pz + dz;
						if((mx == cx && mz == cz)
						   || server_world_chunk_resident(w, mx, mz))
							continue;
						if(!spawn_search_load(c, mx, mz))
							return -1;
					}
			}
		}
		if(!spawn_search_load(c, cx, cz))
			return -1;
		spawn_search_evict(c, cx, cz);
	}
	struct block_data b;
	if(!server_world_get_block(w, x, y, z, &b))
		return -1;
	return b.type;
}

bool server_local_beta_spawn_search(struct server_local* s, const char* dir,
									int64_t seed,
									struct java_random* world_rand, int* out_x,
									int* out_z) {
	assert(s && dir && world_rand && out_x && out_z);
	if(s->player.has_pos) {
		fprintf(stderr, "server_local: spawn search refused -- a world is "
						"loaded\n");
		return false;
	}
	if(!s->world_populate_scratch)
		s->world_populate_scratch = server_local_create_populate_scratch();
	if(!s->world_populate_scratch) {
		fprintf(stderr, "server_local: spawn search FAILED -- populate "
						"scratch unavailable\n");
		return false;
	}
	string_t name;
	string_init_set_str(name, dir);
	struct server_world* w = &s->worlds[0];
	if(!server_world_create_owned_with_populate_scratch(
		   w, name, WORLD_DIM_OVERWORLD, seed, false,
		   s->world_populate_scratch, s, 0)) {
		fprintf(stderr, "server_local: spawn search FAILED -- world "
						"initialization failed\n");
		string_clear(name);
		return false;
	}
	w->local = s;
	w->session = s;
	/* World.rand IS the caller's instance (World.java:169): the search walk
	 * and the fizz draws of any population it triggers share one stream. */
	w->rand = *world_rand;
#ifdef CAVEWII_SERVER_LOCAL_TEST
	s_test_spawn_search_peak_resident = 0;
	if(server_local_test_spawn_search_phase)
		server_local_test_spawn_search_phase(w, true);
#endif
	struct spawn_search_ctx ctx = {.w = w};
	__atomic_store_n(&s_spawn_search_probes, 0u, __ATOMIC_RELAXED);
	const struct worldgen_spawn_world provider
		= {.ctx = &ctx, .block_id = server_local_spawn_search_block_id};
	const bool found
		= worldgen_beta_spawn_search(&provider, &w->rand, out_x, out_z);
	free(ctx.ever);
#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(server_local_test_spawn_search_phase)
		server_local_test_spawn_search_phase(w, false);
#endif
	*world_rand = w->rand;
	/* Found: persist (TerrainPopulated per chunk) -- see the header comment.
	 * Failed: discard, so the create flow's cleanup finds an empty region/
	 * folder and nothing of a spawn-less world survives (REL-03b). */
	if(found)
		server_world_destroy(w);
	else
		server_world_discard(w);
	/* Population's item drops (server_local_commit_planned_drop_batch ->
	 * s->entities) belonged to the temp world; the persisted chunks carry
	 * their own entity records. Same release as the world unload. */
	{
		dict_entity_it_t it;
		dict_entity_it(it, s->entities);
		while(!dict_entity_end_p(it)) {
			free(dict_entity_ref(it)->value);
			dict_entity_next(it);
		}
		dict_entity_reset(s->entities);
		server_local_entity_sections_reset(s);
		s->next_entity_id = 0;
	}
	string_clear(name);
	return found;
}

/* worldgen_set_spawn_search_override adapter: one session per process owns
 * the create-world search. `dir` must name the world being created. */
static struct server_local* s_spawn_search_session;
static char s_spawn_search_dir[512];

static bool server_local_spawn_search_override(int64_t seed,
											   struct java_random* rng,
											   int* out_x, int* out_z) {
	assert(s_spawn_search_session && s_spawn_search_dir[0]);
	return server_local_beta_spawn_search(s_spawn_search_session,
										  s_spawn_search_dir, seed, rng, out_x,
										  out_z);
}

void server_local_install_spawn_search(struct server_local* s,
									   const char* dir) {
	if(!s || !dir) {
		s_spawn_search_session = NULL;
		s_spawn_search_dir[0] = 0;
		worldgen_set_spawn_search_override(NULL);
		return;
	}
	s_spawn_search_session = s;
	snprintf(s_spawn_search_dir, sizeof(s_spawn_search_dir), "%s", dir);
	worldgen_set_spawn_search_override(server_local_spawn_search_override);
}

bool server_local_migrate_bed_metadata_stage(
	struct level_archive* la, string_t level_name,
	struct bed_metadata_migration_stats* stats, bool* ran, bool* converted) {
	assert(la && level_name && stats && ran && converted);
	memset(stats, 0, sizeof(*stats));
	*ran = false;
	*converted = false;
	if(level_archive_get_save_version(la)
	   != CAVEWII_SAVE_VERSION_MOB_SPAWNER_TES)
		return true; /* already 5, or an earlier stage declined: retry later */
	*ran = true;
	/* Provenance: only a world this port CREATED can hold the legacy
	 * encoding by construction. A real Beta import (no CaveWiiGenerator tag)
	 * already holds Beta's layout and must never be converted. */
	if(level_archive_was_created_by_cavewii(la)) {
		if(!region_archive_migrate_bed_metadata(level_name, stats))
			return false;
		*converted = true;
	}
	return level_archive_upgrade_save_version(la, CAVEWII_SAVE_VERSION_BED_META);
}

/* IMP-MIGRATE-FAST: the CaveWiiSaveVersion chain (v2 wall signs, v3 iron
 * chests, v4 spawner TEs, v5 bed metadata), unchanged in order, gating and
 * stamping; extracted from server_local_load_world_impl_ex so the equivalence
 * test can run the production chain. Stages 2-4 are fed by ONE read-only
 * survey (region_archive_migration_survey) taken lazily before the first of
 * them runs; a stage the survey cannot prove to be a no-op runs its staged
 * pass (see region_archive.h). False = load aborted; the caller discards. */
static uint32_t s_import_progress_state; /* 0 idle, 1 percent, 2 working */
static uint32_t s_import_progress_permille;
#ifdef CAVEWII_SERVER_LOCAL_TEST
static bool s_migration_survey_disabled;
void server_local_test_migration_survey_enable(bool enabled) {
	s_migration_survey_disabled = !enabled;
}
#endif

bool server_local_import_progress(uint32_t* percent) {
	uint32_t state
		= __atomic_load_n(&s_import_progress_state, __ATOMIC_ACQUIRE);
	if(percent) {
		uint32_t permille
			= __atomic_load_n(&s_import_progress_permille, __ATOMIC_ACQUIRE);
		*percent = state == 1 ? (permille >= 1000 ? 100u : permille / 10u)
							  : UINT32_MAX;
	}
	return state != 0;
}

static void server_local_import_progress_set(uint32_t permille, void* ctx) {
	(void)ctx;
	__atomic_store_n(&s_import_progress_permille, permille, __ATOMIC_RELEASE);
	__atomic_store_n(&s_import_progress_state, 1u, __ATOMIC_RELEASE);
}

static void server_local_migration_survey_ensure(
	string_t level_name, struct region_migration_survey* survey,
	bool* surveyed) {
	if(*surveyed)
		return;
	*surveyed = true;
#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(s_migration_survey_disabled)
		return; /* survey stays zeroed: valid == false, staged passes run */
#endif
	ptime_t start = time_get();
	region_archive_migration_survey(level_name, survey,
									server_local_import_progress_set, NULL);
	/* Staged passes that may still run afterwards have no percentage. */
	__atomic_store_n(&s_import_progress_state, 2u, __ATOMIC_RELEASE);
	fprintf(stderr,
			"server_local: import survey %s: regions=%zu chunks=%zu ms=%d "
			"signs:%s chests:%s(proven=%zu bare=%zu items=%zu) "
			"spawners:%s(no_te=%zu)\n",
			survey->valid ? "complete" : "inconclusive (staged passes decide)",
			survey->regions_scanned, survey->chunks_scanned,
			(int)time_diff_ms(start, time_get()),
			survey->ws_failed ? "staged" : "ok",
			survey->iron_failed ? "staged" : "ok", survey->iron_proven_blocks,
			survey->iron_bare_blocks, survey->iron_items,
			survey->spawner_failed ? "staged" : "ok",
			survey->spawners_missing_te);
}

/* dropin-1029 review B2: a stage that REWROTE region bytes makes its version
 * stamp durable before the next stage runs (the crash barrier the per-stage
 * saves gave); a no-op stage's stamp stays in the batch, so a drop-in Beta
 * import still writes level.dat once. False = that save failed (load aborts,
 * exactly as a failed immediate stamp did). */
#ifdef CAVEWII_SERVER_LOCAL_TEST
static int32_t s_chain_power_cut_after = -1;
static bool s_chain_power_cut_hit;
void server_local_test_chain_power_cut_after(int32_t version) {
	s_chain_power_cut_after = version;
	s_chain_power_cut_hit = false;
}
#endif
static bool server_local_chain_stage_done(struct level_archive* level,
										  bool wrote_regions,
										  int32_t version) {
	if(wrote_regions && !level_archive_save_batch_flush(level)) {
		fprintf(stderr,
				"server_local: save version %d stamp save failed; load aborted\n",
				version);
		return false;
	}
#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(s_chain_power_cut_after == version) {
		s_chain_power_cut_hit = true; /* simulated power cut: stop here */
		return false;
	}
#endif
	return true;
}

static bool server_local_save_version_chain_impl(
	struct level_archive* level, string_t level_name, bool profile,
	uint32_t profile_regions, ptime_t save_migrate_chain_start) {
	struct region_migration_survey survey;
	memset(&survey, 0, sizeof(survey));
	bool surveyed = false;
	/* PLAYER-HEALTH-NBT: classify a pre-fix Player.Health once (from the
	 * Player compound's own provenance, see
	 * level_archive_normalize_player_health) and record the CaveWiiHealth
	 * marker, which the first stamp below or the next checkpoint persists. */
	{
		bool health_converted = false;
		if(!level_archive_normalize_player_health(level, &health_converted)) {
			fprintf(stderr,
					"server_local: player health normalisation failed; load aborted\n");
			return false;
		}
		if(health_converted)
			fprintf(stderr,
					"server_local: player Health converted from CaveWii units to Beta half-hearts\n");
	}
	/* Save version 2 removes block 68's port-private +2 metadata offset. Inspect
	 * every region before any chunk can become resident, and convert only after
	 * creation-time or block-data provenance proves the old encoding. Per-chunk
	 * markers preserve restart safety before the final level.dat stamp. */
	if(level_archive_get_save_version(level)
	   < CAVEWII_SAVE_VERSION_WALL_SIGNS) {
		ptime_t migration_start = time_get();
		struct wall_sign_metadata_migration_stats migration;
		enum wall_sign_metadata_resolution resolution;
		bool cavewii_created
			= level_archive_was_created_by_cavewii(level);
		bool legacy_intent
			= level_archive_has_wall_sign_legacy_intent(level);
		server_local_migration_survey_ensure(level_name, &survey, &surveyed);
		bool prepared = region_archive_prepare_wall_sign_metadata_surveyed(
			level_name, cavewii_created, legacy_intent, &survey,
			&resolution, &migration);
		if(prepared
		   && resolution == WALL_SIGN_METADATA_NEEDS_LEGACY_INTENT) {
			prepared
				= level_archive_record_wall_sign_legacy_intent(level);
			if(prepared)
				prepared = region_archive_prepare_wall_sign_metadata_surveyed(
					level_name, cavewii_created, true, &survey, &resolution,
					&migration);
		}
		if(!prepared) {
			if(profile) {
				save_migrate_publish_stats(
					migration_start, &migration, SERVER_SAVE_MIGRATE_FAIL);
			}
			fprintf(stderr,
					"server_local: wall-sign metadata provenance scan/migration failed after %zu regions/%zu chunks/%zu signs; load aborted\n",
					migration.regions_scanned, migration.chunks_scanned,
					migration.signs_rewritten);
			return false;
		}
		if(resolution == WALL_SIGN_METADATA_MIGRATED
		   || resolution == WALL_SIGN_METADATA_ALREADY_BETA) {
			if(!level_archive_upgrade_save_version(
				   level, CAVEWII_SAVE_VERSION_WALL_SIGNS)) {
				if(profile)
					save_migrate_publish_stats(
						migration_start, &migration,
						SERVER_SAVE_MIGRATE_FAIL);
				fprintf(stderr,
						"server_local: wall-sign metadata version stamp failed; load aborted\n");
				return false;
			}
			fprintf(stderr,
					"server_local: wall-sign metadata %s: regions=%zu chunks=%zu signs=%zu ms=%d\n",
					resolution == WALL_SIGN_METADATA_MIGRATED
						? "migration complete"
						: "already Beta-format; conversion skipped",
					migration.regions_scanned, migration.chunks_scanned,
					migration.signs_rewritten,
					(int)time_diff_ms(migration_start, time_get()));
			if(profile) {
				save_migrate_publish_stats(
					migration_start, &migration,
					resolution == WALL_SIGN_METADATA_MIGRATED
						? SERVER_SAVE_MIGRATE_RELOAD
						: SERVER_SAVE_MIGRATE_FAIL);
			}
			if(!server_local_chain_stage_done(
				   level, resolution == WALL_SIGN_METADATA_MIGRATED,
				   CAVEWII_SAVE_VERSION_WALL_SIGNS))
				return false;
		} else {
			fprintf(stderr,
					"server_local: wall-sign metadata migration REFUSED (%s); save version %d left unchanged and world data left intact\n",
					resolution == WALL_SIGN_METADATA_REFUSED_MIXED
						? "mixed Beta 2/3 and legacy provenance"
						: "provenance unknown: only ambiguous 4/5 or no signs",
					level_archive_get_save_version(level));
			if(profile) {
				save_migrate_publish_stats(
					migration_start, &migration, SERVER_SAVE_MIGRATE_FAIL);
			}
		}
	}
	/* Save version 3 (FH-07): iron chests move off Beta's id 95 to 200. Runs
	 * only from an exactly-version-2 world so a refused wall-sign migration
	 * above keeps BOTH stages retryable on later loads. Block rewrites are
	 * per-instance provenance-proven (Chest TE at the coordinate); bare-95 and
	 * item-id rewrites need world evidence: creation provenance, or >=1 proven
	 * iron chest found by the first pass (a world that provably contains port
	 * iron chests is a port world). Beta imports therefore stamp version 3
	 * without a single byte of their data changing. */
	if(level_archive_get_save_version(level)
	   == CAVEWII_SAVE_VERSION_WALL_SIGNS) {
		ptime_t iron_start = time_get();
		struct iron_chest_migration_stats iron;
		bool cavewii_created
			= level_archive_was_created_by_cavewii(level);
		server_local_migration_survey_ensure(level_name, &survey, &surveyed);
		bool prepared = region_archive_migrate_iron_chest_ids_surveyed(
			level_name, cavewii_created, cavewii_created, &survey, &iron);
		if(prepared && !cavewii_created && iron.blocks_rewritten > 0) {
			struct iron_chest_migration_stats items_pass;
			prepared = region_archive_migrate_iron_chest_ids_surveyed(
				level_name, false, true, &survey, &items_pass);
			iron.items_rewritten += items_pass.items_rewritten;
		}
		if(prepared)
			prepared = level_archive_upgrade_save_version(
				level, CAVEWII_SAVE_VERSION_IRON_CHEST_IDS);
		if(!prepared) {
			if(profile) {
				save_migrate_publish_chest_stats(
					save_migrate_chain_start, &iron,
					profile_regions,
					SERVER_SAVE_MIGRATE_FAIL);
			}
			fprintf(stderr,
					"server_local: iron-chest id migration failed after %zu regions/%zu chunks (%zu blocks, %zu items rewritten); load aborted\n",
					iron.regions_scanned, iron.chunks_scanned,
					iron.blocks_rewritten, iron.items_rewritten);
			return false;
		}
		fprintf(stderr,
				"server_local: iron-chest id migration complete: regions=%zu chunks=%zu blocks=%zu items=%zu ms=%d\n",
				iron.regions_scanned, iron.chunks_scanned,
				iron.blocks_rewritten, iron.items_rewritten,
				(int)time_diff_ms(iron_start, time_get()));
		if(profile) {
			save_migrate_publish_chest_stats(
				save_migrate_chain_start, &iron,
				profile_regions,
				SERVER_SAVE_MIGRATE_RELOAD);
		}
		if(!server_local_chain_stage_done(
			   level, iron.blocks_rewritten + iron.items_rewritten > 0,
			   CAVEWII_SAVE_VERSION_IRON_CHEST_IDS))
			return false;
	}
	/* Save version 4 (FH-17): dungeon mob spawners move off a metadata-encoded
	 * mob type to a faithful MobSpawner tile entity (Beta TileEntityMobSpawner's
	 * EntityId/Delay). Runs only from an exactly-version-3 world, keeping this
	 * stage retryable if a crash lands between it and the version stamp. Unlike
	 * the iron-chest migration, there is no id-collision ambiguity to resolve
	 * with world provenance: a BLOCK_MOB_SPAWNER that already owns a MobSpawner
	 * TE (a real Beta import, or an already-migrated instance) is untouched;
	 * one with no TE is unambiguously this port's legacy metadata encoding
	 * (Beta's own worldgen/loader always creates the TE), so it is always
	 * synthesized regardless of creation provenance -- see region_archive.c's
	 * migration header for the full argument. */
	if(level_archive_get_save_version(level)
	   == CAVEWII_SAVE_VERSION_IRON_CHEST_IDS) {
		ptime_t spawner_start = time_get();
		struct mob_spawner_te_migration_stats spawner_stats;
		server_local_migration_survey_ensure(level_name, &survey, &surveyed);
		bool prepared = region_archive_migrate_mob_spawner_tes_surveyed(
			level_name, &survey, &spawner_stats);
		if(prepared)
			prepared = level_archive_upgrade_save_version(
				level, CAVEWII_SAVE_VERSION_MOB_SPAWNER_TES);
		if(!prepared) {
			if(profile) {
				save_migrate_publish_spawner_stats(
					save_migrate_chain_start, &spawner_stats,
					profile_regions,
					SERVER_SAVE_MIGRATE_FAIL);
			}
			fprintf(stderr,
					"server_local: mob-spawner TE migration failed after %zu regions/%zu chunks (%zu synthesized); load aborted\n",
					spawner_stats.regions_scanned,
					spawner_stats.chunks_scanned,
					spawner_stats.spawners_synthesized);
			return false;
		}
		fprintf(stderr,
				"server_local: mob-spawner TE migration complete: regions=%zu chunks=%zu synthesized=%zu ms=%d\n",
				spawner_stats.regions_scanned, spawner_stats.chunks_scanned,
				spawner_stats.spawners_synthesized,
				(int)time_diff_ms(spawner_start, time_get()));
		if(profile) {
			save_migrate_publish_spawner_stats(
				save_migrate_chain_start, &spawner_stats,
				profile_regions,
				SERVER_SAVE_MIGRATE_RELOAD);
		}
		if(!server_local_chain_stage_done(
			   level, spawner_stats.spawners_synthesized > 0,
			   CAVEWII_SAVE_VERSION_MOB_SPAWNER_TES))
			return false;
	}
	/* Save version 5 (PAR-BED-META): legacy CaveWii bed metadata -> Beta's
	 * layout, CaveWii-created worlds only, from exactly version 4. */
	{
		ptime_t bed_start = time_get();
		struct bed_metadata_migration_stats bed_stats;
		bool bed_ran = false, bed_converted = false;
		if(!server_local_migrate_bed_metadata_stage(level, level_name,
				&bed_stats, &bed_ran, &bed_converted)) {
			fprintf(stderr,
					"server_local: bed metadata migration failed after %zu regions/%zu chunks (%zu of %zu beds rewritten); load aborted\n",
					bed_stats.regions_scanned, bed_stats.chunks_scanned,
					bed_stats.beds_rewritten, bed_stats.beds_seen);
			return false;
		}
		if(bed_ran)
			fprintf(stderr,
					"server_local: bed metadata %s: regions=%zu chunks=%zu (marked %zu) beds=%zu rewritten=%zu ms=%d\n",
					bed_converted ? "migration complete"
								  : "not CaveWii-created; conversion skipped",
					bed_stats.regions_scanned, bed_stats.chunks_scanned,
					bed_stats.chunks_already_marked, bed_stats.beds_seen,
					bed_stats.beds_rewritten,
					(int)time_diff_ms(bed_start, time_get()));
		if(bed_ran
		   && !server_local_chain_stage_done(level,
				  bed_converted && bed_stats.beds_rewritten > 0,
				  CAVEWII_SAVE_VERSION_BED_META))
			return false;
	}
	return true;
}

bool server_local_save_version_chain(struct level_archive* level,
	string_t level_name, bool profile, uint32_t profile_regions) {
	/* save_migrate hardware-proof profile: one shared start point for ALL
	 * CaveWiiSaveVersion stages, so whichever stage publishes last reports
	 * elapsed time for the WHOLE synchronous chain (not just its own slice)
	 * -- see save_migrate_publish_stats's comment. */
	ptime_t save_migrate_chain_start = time_get();
	/* dropin-1029: every CaveWiiSaveVersion stamp of this chain lands in ONE
	 * level.dat save at the end (previously one save per stage: 4 rotations
	 * on a Beta import, so Beta's level.dat_old was replaced by our own
	 * intermediate stamp). With one save the first and only rotation moves
	 * the world's own level.dat -- byte-exact, as Beta wrote it -- to
	 * level.dat_old. Restart safety is unchanged in kind: every stage is
	 * already re-runnable from an older version (per-chunk markers; proven-
	 * instance rewrites that find nothing the second time; TE presence), and
	 * a crash before the save simply re-runs them. The wall-sign legacy
	 * intent stays an immediate save (a pre-migration barrier; only CaveWii
	 * legacy worlds take that path). A failing stage still persists the
	 * stamps of the stages before it, as the per-stage saves did. */
	level_archive_save_batch_begin(level);
	bool ok = server_local_save_version_chain_impl(level, level_name, profile,
		profile_regions, save_migrate_chain_start);
#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(s_chain_power_cut_hit) { /* nothing after the cut reaches the disk */
		s_chain_power_cut_after = -1;
		s_chain_power_cut_hit = false; /* one-shot: the next load is real */
		level_archive_save_batch_abandon(level);
		__atomic_store_n(&s_import_progress_state, 0u, __ATOMIC_RELEASE);
		return false;
	}
#endif
	if(!level_archive_save_batch_end(level) && ok) {
		fprintf(stderr,
				"server_local: save-version stamp save failed; load aborted\n");
		ok = false;
	}
	__atomic_store_n(&s_import_progress_state, 0u, __ATOMIC_RELEASE);
	return ok;
}

/* R3: the server-thread half of the create-world spawn search mailbox
 * (svin_spawn_*). Idle session only (same rule as convert-only): the search
 * borrows slot 0 for its temporary world. */
void server_local_spawn_search_service(struct server_local* s) {
	uint64_t ticket;
	const char* dir;
	struct svin_spawn_request r;
	bool idle = !s->player.has_pos && !s->guest_actor
		&& s->world_switch_phase == SERVER_WORLD_SWITCH_IDLE;
	for(unsigned i = 0; i < SERVER_LOCAL_WORLD_SLOTS; i++)
		idle = idle && s->world_slot_state[i] == SERVER_WORLD_SLOT_EMPTY;
	/* An unload/switch still finishing: leave the request queued for a
	 * later tick instead of refusing it (the requester's wait is bounded).
	 * A session with a live player never sees a create request. */
	if(!idle || !svin_spawn_take(&ticket, &dir, &r))
		return;
	if(svin_spawn_cancelled()) {
		(void)svin_spawn_finish(ticket, SVIN_SPAWN_FAILED, NULL, NULL);
		return;
	}
	float world_spawn[3], player_spawn[3];
	server_local_install_spawn_search(s, dir);
	worldgen_find_initial_spawns(r.seed, r.superflat, r.start_nether,
								 world_spawn, player_spawn);
	server_local_install_spawn_search(NULL, NULL);
	(void)svin_spawn_finish(ticket, worldgen_last_spawn_search_ok()
								? SVIN_SPAWN_FOUND : SVIN_SPAWN_FAILED,
							world_spawn, player_spawn);
}

#ifdef CAVEWII_SERVER_LOCAL_TEST
void (*server_local_test_spawn_search_wait_hook)(void);
#endif

/* Main-thread wait state for server_local_spawn_search_progress. */
static bool s_spawn_wait_active;
static ptime_t s_spawn_wait_start;

bool server_local_spawn_search_progress(uint32_t* probes, uint32_t* elapsed_ms) {
	if(!s_spawn_wait_active)
		return false;
	if(probes)
		*probes = __atomic_load_n(&s_spawn_search_probes, __ATOMIC_RELAXED);
	if(elapsed_ms) {
		const int32_t ms = time_diff_ms(s_spawn_wait_start, time_get());
		*elapsed_ms = ms > 0 ? (uint32_t)ms : 0u;
	}
	return true;
}

bool server_local_create_spawns(const char* dir, int64_t seed, bool superflat,
								bool start_nether, float world_spawn[3],
								float player_spawn[3],
								void (*idle)(void* user), void* user) {
	assert(dir && world_spawn && player_spawn);
	if(!svin_spawn_provider()) {
		/* No local server (standalone front-end rigs, tools): the in-thread
		 * search, which says on stderr that it reads unpopulated terrain. */
		worldgen_find_initial_spawns(seed, superflat, start_nether, world_spawn,
									 player_spawn);
		return worldgen_last_spawn_search_ok();
	}
	const struct svin_spawn_request r
		= {.seed = seed, .superflat = superflat, .start_nether = start_nether};
	/* One outstanding request; the create flow is the only requester, so a
	 * FINISHED result nobody released is its own leftover. */
	svin_spawn_release_stale();
	const uint64_t ticket = svin_spawn_request(dir, &r);
	if(!ticket) {
		fprintf(stderr, "[world] spawn search request refused (a search is "
						"still running)\n");
		return false;
	}
	/* Beta's create blocks its client in the World constructor too; here the
	 * caller's idle keeps the frame and the watchdog alive. Bound: a Wii walk
	 * of a few hundred chunks is well under a minute; a search still going
	 * after SPAWN_SEARCH_TIMEOUT_MS is stopped (its next probe fails, the
	 * temp world is discarded) and reported, never hung. */
	enum { SPAWN_SEARCH_TIMEOUT_MS = 10 * 60 * 1000,
		   SPAWN_SEARCH_CANCEL_GRACE_MS = 30 * 1000 };
	const ptime_t start = time_get();
	bool cancelled = false;
	struct svin_spawn_result res;
	s_spawn_wait_start = start;
	s_spawn_wait_active = true;
	while(!svin_spawn_read(ticket, &res)) {
		const int32_t waited = time_diff_ms(start, time_get());
		if(!cancelled && waited > SPAWN_SEARCH_TIMEOUT_MS) {
			fprintf(stderr, "[world] spawn search for seed %lld exceeded %d s; "
							"stopping it\n", (long long)seed,
					SPAWN_SEARCH_TIMEOUT_MS / 1000);
			(void)svin_spawn_cancel(ticket);
			cancelled = true;
		}
		if(cancelled
		   && waited > SPAWN_SEARCH_TIMEOUT_MS + SPAWN_SEARCH_CANCEL_GRACE_MS) {
			/* The server half never answered the cancel (stuck provider):
			 * the ticket stays its own and is retired with the provider. */
			fprintf(stderr, "[world] spawn search did not stop; create "
							"abandoned\n");
			s_spawn_wait_active = false;
			return false;
		}
#ifdef CAVEWII_SERVER_LOCAL_TEST
		if(server_local_test_spawn_search_wait_hook)
			server_local_test_spawn_search_wait_hook();
#endif
		if(idle)
			idle(user);
		else
			thread_msleep(1);
	}
	s_spawn_wait_active = false;
	(void)svin_spawn_release(ticket);
	if(res.outcome != SVIN_SPAWN_FOUND) {
		fprintf(stderr, "[world] spawn search outcome %u for seed %lld -- no "
						"Beta spawn%s\n", (unsigned)res.outcome, (long long)seed,
				cancelled ? " (timed out)" : "");
		return false;
	}
	memcpy(world_spawn, res.world_spawn, sizeof(res.world_spawn));
	memcpy(player_spawn, res.player_spawn, sizeof(res.player_spawn));
	return true;
}

void server_local_convert_service(struct server_local* s) {
	uint64_t ticket;
	const char* path;
	bool cancelled;
	if(!svin_convert_take(&ticket, &path, &cancelled))
		return;
	enum svin_convert_outcome outcome = SVIN_CONVERT_CANCELLED;
	bool may_have_changed = false;
	if(!cancelled) {
		outcome = SVIN_CONVERT_WORLD_ACTIVE;
		bool idle = !s->player.has_pos && !s->guest_actor
			&& s->world_switch_phase == SERVER_WORLD_SWITCH_IDLE;
		for(unsigned i = 0; i < SERVER_LOCAL_WORLD_SLOTS; i++)
			idle = idle && s->world_slot_state[i] == SERVER_WORLD_SLOT_EMPTY;
		if(idle) {
			string_t name;
			string_init_set_str(name, path);
			struct checkpoint_journal_verdict verdict;
			outcome = SVIN_CONVERT_JOURNAL_REFUSED;
			if(checkpoint_journal_allows_load(name, &verdict)) {
				struct level_archive level;
				outcome = SVIN_CONVERT_OPEN_FAILED;
				if(level_archive_create(&level, name)) {
					/* Beta SaveConverterMcRegion.converMapToMCRegion, lines
					 * 27-54 (1.7.3-LTS server decompile), converts archives and
					 * stamps WorldInfo without
					 * constructing a World/player. This port's schema/output
					 * authority remains the unchanged load-time chain above. */
					may_have_changed = true;
					outcome = server_local_save_version_chain(&level, name, false, 0)
						? SVIN_CONVERT_SUCCEEDED : SVIN_CONVERT_FAILED;
					/* Ordinary load permits a provenance refusal to remain
					 * retryable. Convert Done must certify the current schema. */
					if(outcome == SVIN_CONVERT_SUCCEEDED
					   && level_archive_get_save_version(&level)
						   != CAVEWII_SAVE_VERSION_CURRENT) {
						fprintf(stderr, "server_local: convert-only migration refused; save version remains %d\n",
							level_archive_get_save_version(&level));
						outcome = SVIN_CONVERT_FAILED;
					}
					/* A current-version archive can still have pre-fix health.
					 * The ordinary chain leaves that normalization dirty for its
					 * next checkpoint. Do not certify discarded changes as Done. */
					if(outcome == SVIN_CONVERT_SUCCEEDED && level.modified) {
						fprintf(stderr, "server_local: convert-only normalization requires a save on Play\n");
						outcome = SVIN_CONVERT_SAVE_PENDING;
					}
					/* The chain owns its durable stamps. No checkpoint, player
					 * save, LastPlayed update or extra archive flush here. */
					level_archive_discard(&level);
				}
			}
			string_clear(name);
		}
	}
	if(outcome != SVIN_CONVERT_SUCCEEDED && outcome != SVIN_CONVERT_CANCELLED)
		fprintf(stderr, "server_local: convert-only ticket=%llu outcome=%u changed=%u\n",
			(unsigned long long)ticket, (unsigned)outcome, may_have_changed);
	(void)svin_convert_finish(ticket, outcome, may_have_changed);
}

// (Re)create the world named `name` from its level.dat. A portal transaction
// supplies an override so the source player tag can remain committed until the
// destination archive has opened successfully.
static void server_local_skylight_init(struct server_local* s); // W2b, defined beside the recompute
static __attribute__((warn_unused_result)) bool
server_local_load_world_impl_ex(
	struct server_local* s, const string_t name,
	const struct world_load_override* override, bool preserve_live_inventory) {
	/* G6 L1 follow-up: every load attempt starts with no refusal reason, so
	 * a reason left by an earlier attempt (one that never reached the
	 * SRPC_LOAD_WORLD failure card) can never label a later, unrelated
	 * failure. */
	s_load_refusal_reason[0] = 0;
	assert(!s->player.has_pos);
	/* A0: fail closed in NDEBUG builds too. Loading over a still-live world
	 * (a refused release the caller did not check) would overwrite the only
	 * copy; every caller now branches on its release status first. */
	if(s->player.has_pos) {
		fprintf(stderr,
				"server_local: world still held; load refused\n");
		return false;
	}
	/* H3: a load binds the host to the routed world; a committed slot left
	 * from a previous session (host in the Nether) would resolve nothing. */
	s->player.world_slot = 0;
	server_local_tnt_evidence_reset();
	server_local_mob_motion_reset();
	/* This allocation normally happened once in server_local_init, before any
	 * chunk/display-list churn. A retry here is still pre-world and fails the load
	 * explicitly instead of entering an unfinishable populate loop. */
	if(!s->world_populate_scratch)
		s->world_populate_scratch = server_local_create_populate_scratch();
	if(!s->world_populate_scratch) {
		fprintf(stderr,
				"server_local: populate rollback scratch unavailable; load aborted\n");
		return false;
	}
	s->load_wait_ticks = 0;
	s->load_failure_terminal = false;
	s->respawn_drain_save_failures = 0;
	/* G9 R3: a new world starts with its publication barrier down. */
	s->light_stop_published = false;
	clin_server_publication_stop(false);
	s->stream_recovery_epoch = 0;
	// Failed or abandoned loads must never leak a previous reason into a later
	// async finalizer. Arm the one-shot only after this load fully succeeds.
	s->preserve_live_inventory_on_finish = false;
	s->inventory_finish_pending = false;
	// FIX #4b: arm (not clear) the pending flag across a world load. A saved
	// chest/furnace table can already hold an orphaned row from BEFORE this
	// load (a save taken mid-retry, or a crash while a row was retained) --
	// the archive reader below repopulates chest_pos/furnace_pos verbatim,
	// so that row would otherwise sit unswept until some unrelated container
	// is next destroyed. Arming here makes one full sweep pass run on the
	// first tick after finished_loading; it self-clears through the
	// existing `= !complete` in server_local_retry_orphaned_container_drops
	// when that pass finds nothing retained, so a healthy load still costs
	// exactly one scan -- the same one every tick used to pay before FIX #4.
	s->orphan_container_retry_pending = true;

	string_set(s->level_name, name);

#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(s_fail_world_loads_remaining > 0) {
		s_fail_world_loads_remaining--;
		string_reset(s->level_name);
		return false;
	}
#endif
	/* G6 separation (astra-journal-0926): this tree writes no checkpoint
	 * journal and has no recovery for one. A save that carries an
	 * UNRESOLVED experimental `checkpoint.journal` (INTENT without
	 * COMPLETE/RECOVERED: its region headers / level.dat may be a
	 * half-published epoch) or a malformed one is REFUSED visibly, files
	 * preserved -- never ignored. A resolved journal is inert. */
	{
		struct checkpoint_journal_verdict jv;
		if(!checkpoint_journal_allows_load(s->level_name, &jv)) {
			fprintf(stderr,
					"[server] refusing to load: %s/%s is %s (epoch %u%s) -- an "
					"experimental checkpoint journal this build cannot resolve; "
					"files preserved\n",
					string_get_cstr(s->level_name), CHECKPOINT_JOURNAL_GUARD_NAME,
					jv.state == CHECKPOINT_JOURNAL_UNRESOLVED ? "UNRESOLVED"
															   : "MALFORMED",
					jv.epoch, jv.torn_tail ? ", torn tail" : "");
			/* L1: the SRPC_LOAD_WORLD handler puts THIS text on the failure
			 * card instead of the generic terrain-memory line. */
			snprintf(s_load_refusal_reason, sizeof(s_load_refusal_reason), "%s",
					 checkpoint_journal_refusal_text(&jv));
			string_reset(s->level_name);
			return false;
		}
	}
	if(!level_archive_create(&s->level, s->level_name)) {
		string_reset(s->level_name);
		return false;
	}
	// PER-WORLD creative (LEVEL_GAME_MODE, 2026-09-01). Set on EVERY load,
	// before anything can act on it, so a creative world cannot leak its mode
	// into the next survival world loaded in the same session. Absent or
	// malformed tag reads survival (level_archive_is_creative fails closed).
	s->creative_mode = level_archive_is_creative(&s->level);
	/* Save versions 2..5 (IMP-MIGRATE-FAST: server_local_save_version_chain
	 * holds the unchanged staged chain, fed by one read-only survey). */
	if(!server_local_save_version_chain(&s->level, s->level_name,
			s->save_migrate_profile, (uint32_t)s->save_migrate_regions)) {
		level_archive_discard(&s->level);
		string_reset(s->level_name);
		return false;
	}
	/* A PREPARED death journal owns its stacks until the source regions and
	 * cleared respawn player agree. Resolve it before reading Player.Dimension
	 * or constructing either world; a failure leaves every durable owner intact
	 * and fails the load closed for a later retry. */
	if(!death_drop_recover_if_needed(s->level_name, &s->level)) {
		level_archive_discard(&s->level);
		string_reset(s->level_name);
		return false;
	}
	{
		vec3 pos;
		vec2 rot;
		enum world_dim dim = WORLD_DIM_OVERWORLD;
		/* Data.SpawnXYZ is a required triple, but imported/corrupt archives can
		 * omit one member or give it the wrong type. Read into locals as one unit;
		 * never retain a partial triple or the automatic server struct's prior
		 * bytes. The deterministic fallback matches the existing degraded-load
		 * policy used when Player itself is unreadable. */
		int32_t world_spawn_x = 0, world_spawn_y = 80, world_spawn_z = 0;
		int32_t parsed_spawn_x, parsed_spawn_y, parsed_spawn_z;
		bool world_spawn_valid
			= level_archive_read(
				&s->level, LEVEL_WORLD_SPAWNX, &parsed_spawn_x, 0)
			&& level_archive_read(
				&s->level, LEVEL_WORLD_SPAWNY, &parsed_spawn_y, 0)
			&& level_archive_read(
				&s->level, LEVEL_WORLD_SPAWNZ, &parsed_spawn_z, 0)
			&& parsed_spawn_y >= 0 && parsed_spawn_y < WORLD_HEIGHT
			&& level_player_position_values_valid(
				parsed_spawn_x, parsed_spawn_y, parsed_spawn_z);
		if(world_spawn_valid) {
			world_spawn_x = parsed_spawn_x;
			world_spawn_y = parsed_spawn_y;
			world_spawn_z = parsed_spawn_z;
		} else
			fprintf(stderr,
					"server_local: malformed world SpawnXYZ; using 0,80,0\n");
		// PARITY GAP (2026-08-26 fork audit): a brand-new world (no Player tag
		// on disk yet) or a corrupt/foreign one hits this exact fallback, and
		// it shares the no-bed respawn's anti-suffocation gap -- Beta's
		// ServerConfigurationManager.playerLoggedIn [740c583:82-84] runs the
		// SAME push-up-while-colliding loop for a player's very first join,
		// after force-loading the destination chunk. `used_world_spawn_fallback`
		// tracks whether THIS load actually used that degraded XZ/Y (never for
		// an `override`-driven arrival -- portal travel already runs its own
		// clearance search, tp_create_volume_clear in portal_teleporter.c).
		bool used_world_spawn_fallback = false;
		enum { SPAWN_PROBE_NONE, SPAWN_PROBE_FALLBACK, SPAWN_PROBE_BETA_EYE,
			   SPAWN_PROBE_PUSH_UP } spawn_probe = SPAWN_PROBE_NONE;
		double first_join_eye = 0.0; /* REL-03 Beta double posY */
		bool first_join_exact = false;
		bool vsp_player_read = level_archive_read_player(&s->level, pos, rot,
														 NULL, &dim);
		float vsp_disk_pos[3] = {pos[0], pos[1], pos[2]};
		if(!vsp_player_read) {
			// Corrupt/foreign Player tag (e.g. an imported world whose
			// Player node our reader rejects): fall back to the saved
			// spawn point. The old path SKIPPED the whole setup --
			// leaving `dim` UNINITIALIZED for the CRPC_WORLD_RESET
			// below and has_pos forever false, soft-locking the
			// loading screen (2026-06-12 persistence audit). A
			// degraded spawn-point load beats a hang.
			pos[0] = world_spawn_x + 0.5f;
			pos[1] = world_spawn_y + PLAYER_EYE_HEIGHT;
			pos[2] = world_spawn_z + 0.5f;
			rot[0] = 0.0f;
			rot[1] = 0.0f;
			dim = WORLD_DIM_OVERWORLD;
			used_world_spawn_fallback = true;
		}
		if(override) {
			memcpy(pos, override->pos, sizeof(pos));
			memcpy(rot, override->rot, sizeof(rot));
			dim = override->dimension;
			used_world_spawn_fallback = false;
		}
		{
			int64_t world_seed = 0;
			level_archive_read(&s->level, LEVEL_RANDOM_SEED, &world_seed, 0);
			if(!server_world_create_owned_with_populate_scratch(
				   &s->world, s->level_name, dim, world_seed, s->superflat,
				   s->world_populate_scratch, s, 0)) {
				fprintf(stderr,
						"server_local: world initialization failed; load aborted\n");
				level_archive_discard(&s->level);
				string_reset(s->level_name);
				return false;
			}
			// Bind the chest/sign tables to the world's chunk lifecycle,
			// so each chunk loads/saves its own TileEntities instead of a
			// global chest store (see server_world.h, docs/chest_store_
			// redesign.md). Must precede chest_archive_read below.
			s->world.local = s;
			s->worlds[0].session = s; /* A1a: create cleared it; this world is slot 0 of this session */
			/* host_vehicle_smoke_8m reload DISK stage: the real reopen and
			 * player read, BEFORE any collision adjustment below. */
			if(vsp_armed())
				vsp_srv_reload_disk(s, vsp_disk_pos, vsp_player_read,
									used_world_spawn_fallback, override != NULL);
			/* hw1029c (data loss): the spawn probes below LOAD chunks (and
			 * their TileEntities/Entities, ChunkLoader.java:176-194), so they
			 * may only run once this load's world-boundary resets are done --
			 * the flat-archive restore commit, server_local_release_slot_te_rows
			 * and dict_entity_reset further down drop every slot-0 row and
			 * entity, and a chunk loaded before them stayed resident with its
			 * chests/signs/furnaces/paintings gone (a Beta map with no Player
			 * tag: Dream Journal's spawn chunks (11,-2)/(10,-2); the checkpoint
			 * then refused the chunk, "tile_entity_preserve"). Decide which
			 * probe applies here; run it after the resets (spawn_probe below). */
			if(used_world_spawn_fallback) {
				spawn_probe = SPAWN_PROBE_FALLBACK;
			} else if(!override) {
				/* W1A-b: a never-saved level.dat has no real Player tag --
				 * Beta's first join (see the helper). */
				int64_t last_played = 0;
				/* REL-03: only the exact create-world placeholder takes
				 * Beta's double-posY push-up. */
				const bool placeholder = dim == WORLD_DIM_OVERWORLD
					&& pos[0] == (float)world_spawn_x + 0.5F
					&& pos[2] == (float)world_spawn_z + 0.5F
					&& pos[1] == (float)(world_spawn_y + 1)
						   + PLAYER_EYE_HEIGHT;
				if(level_archive_read(&s->level, LEVEL_LAST_PLAYED,
									  &last_played, 0)
				   && last_played == 0)
					spawn_probe = placeholder ? SPAWN_PROBE_BETA_EYE
											  : SPAWN_PROBE_PUSH_UP;
			}
			s->player.x = pos[0];
			s->player.y = pos[1]; /* the spawn probe below may still raise it */
			s->player.z = pos[2];
			s->player.rx = rot[0];
			s->player.ry = rot[1];
			s->player.dimension = dim;
			float saved_fall_distance = 0.0F;
			if(!level_archive_read(&s->level, LEVEL_PLAYER_FALL_DISTANCE,
							  &saved_fall_distance, 0)
			   || !isfinite(saved_fall_distance) || saved_fall_distance < 0.0F)
				saved_fall_distance = 0.0F;
			s->player.fall_distance = saved_fall_distance;
			s->player.old_vel_y = 0;
			s->player.vel_y = 0;
			s->player.on_ground = false;
			s->player.sneaking = false;
			if(!preserve_live_inventory) {
				/* Ordinary/menu and death loads construct a fresh EntityPlayer. A
				 * live portal load restores these fields from portal_origin below. */
				s->player.vel_x = 0.0f;
				s->player.vel_z = 0.0f;
				server_local_actor_motion_reset(&s->player);
				s->player.hurt_resist_time = 0;
				s->player.last_damage = 0;
				s->player.damage_remainder = 0;
				s->player.ticks_existed = 0; /* W1F: fresh EntityPlayer */
				s->player.entity_rand.seeded = false; /* F4-RNG */
			}
			s->player.has_pos = true;
		}

		level_archive_read(&s->level, LEVEL_TIME, &s->world_time, 0);

		// Weather (WorldInfo raining/rainTime/thundering/thunderTime). Absent
		// (legacy/imported world) leaves the zero-initialized default -- not
		// raining/thundering, both timers 0 -- which is exactly Beta's own
		// WorldInfo(seed,name) default-construct state for a brand-new world:
		// the very next server_weather_tick rolls a fresh countdown, matching
		// a freshly created Beta world rather than needing a special case.
		int8_t weather_raining_byte = 0, weather_thundering_byte = 0;
		level_archive_read(&s->level, LEVEL_WEATHER_RAINING,
						   &weather_raining_byte, 0);
		s->weather.raining = weather_raining_byte != 0;
		level_archive_read(&s->level, LEVEL_WEATHER_RAIN_TIME,
						   &s->weather.rain_time, 0);
		level_archive_read(&s->level, LEVEL_WEATHER_THUNDERING,
						   &weather_thundering_byte, 0);
		s->weather.thundering = weather_thundering_byte != 0;
		level_archive_read(&s->level, LEVEL_WEATHER_THUNDER_TIME,
						   &s->weather.thunder_time, 0);
		// Strengths are runtime-only (never persisted); a fresh/loaded world
		// starts at 0 and ramps toward the loaded flags over the next ~100
		// ticks (the same ±0.01/tick lerp a live game already applies).
		s->weather.rain_strength = 0.0f;
		s->weather.prev_rain_strength = 0.0f;
		s->weather.thunder_strength = 0.0f;
		s->weather.prev_thunder_strength = 0.0f;
		s->weather.flash_ticks = 0;
		// W2b: World.calculateInitialSkylight -- every World constructor, strengths still 0.
		server_local_skylight_init(s);
		// FIX #5: force the next CRPC_WEATHER_SET to send regardless of
		// whether the freshly loaded values happen to match whatever the
		// PREVIOUS world last published -- a client that just attached to a
		// brand-new world must never rely on a stale snapshot.
		s->weather_last_sent_valid = false;
		// F3 (adversarial review): Beta reseeds field_9437_g/soundCounter at
		// EVERY World construction, never persisting them -- do the same on
		// every load/create, here (see server_weather_seed's own citation).
		server_weather_seed(s);
		// F2 (adversarial review): any in-flight lightning bolts belong to
		// the PREVIOUS world/dimension's block positions -- a dimension
		// switch or fresh load must not let them keep restriking into the
		// new world. This is also the memory-leak fix: without freeing here,
		// every world/dimension switch across a session's lifetime leaks one
		// realloc'd active_bolts array (server_local itself has no general
		// teardown call in production -- this load path is the one place
		// guaranteed to run on every switch).
		server_weather_bolts_destroy(s);

		level_archive_read_player_health(&s->level, &s->player.health);
		if(s->player.health > MAX_PLAYER_HEALTH)
			s->player.health = MAX_PLAYER_HEALTH;
		/* A quit-while-dead save loads dead (health<=0): the client shows the
		 * death screen again once ingame, Beta-faithfully. The death-position
		 * latch does NOT round-trip (Beta persists nothing extra either -- its
		 * drops already happened at death); the respawn transaction falls back
		 * to the saved corpse position as the drop origin. */
		s->player.has_death_pos = false;
		/* D6: mirror the persisted death-transaction counter; an absent tag is
		 * a legacy/imported world whose disk may carry small pre-fix ids --
		 * the floor jumps past all of them. */
		if(!level_archive_read_death_tx_counter(&s->level,
												&s->death_tx_counter))
			s->death_tx_counter = CAVEWII_DEATH_TX_LEGACY_FLOOR;
		s->player.spawn_x = world_spawn_x;
		s->player.spawn_y = world_spawn_y;
		s->player.spawn_z = world_spawn_z;
		s->player.has_bed_spawn = false;
		if(!level_archive_read_player_spawn(
			   &s->level, &s->player.has_bed_spawn,
			   &s->player.bed_spawn_x, &s->player.bed_spawn_y,
			   &s->player.bed_spawn_z))
			fprintf(stderr,
					"server_local: malformed Player.SpawnXYZ ignored\n");

		// WORLD data: keyed by the (re)created world's dimension.
		/* A1b: release slot 0's previous-instance rows, then restore this
		 * dimension's flat archive stamped with the new instance's owner. */
		/* A2-S: BOTH flat archives are decoded into scratch and mapped onto
		 * the shared table BEFORE any slot-0 row is released; only a fully
		 * validated plan commits (the commit releases slot 0's rows and
		 * installs the image; slot 1's rows keep their indices). A refusal
		 * leaves every row exactly as it was. */
		struct te_store legacy = server_world_tile_store(&s->worlds[0]);
		struct tile_restore_plan plan;
		bool restored
			= complex_archive_prepare_w(&legacy, s->level_name, dim, &plan)
				== STORAGE_OK
			&& te_restore_preflight(&legacy, &plan) == STORAGE_OK
			&& te_restore_commit(&plan);
		if(!restored) {
			te_restore_abort(&plan);
			server_world_discard(&s->world);
			s->player.has_pos = false;
			level_archive_discard(&s->level);
			string_reset(s->level_name);
			return false;
		}

		s->player.oxygen = MAX_OXYGEN;
		s->player.fire = -PLAYER_FIRE_RESISTANCE; // fresh entity: not lit
		// Fresh-player portal baseline (Beta EntityPlayer ctor:
		// timeUntilPortal = 20). The LIVE dimension switch re-stamps its
		// own carried fire/oxygen + 10-tick cooldown AFTER this returns.
		s->player.time_until_portal = 20;
		s->player.time_in_portal = 0.0f;
		s->player.in_portal = false;
		s->player.portal_travel_requested = false;
		// S2 splash latch (the four-field init rule above applies): TRUE =
		// the isFirstUpdate guard -- loading INTO water plays no splash.
		s->player.was_in_water = true;

		if(s->entity_dict_reserved != 0)
			server_local_reservation_violation(
				"world load with detached dictionary slots");
		dict_entity_reset(s->entities);
		server_local_entity_sections_reset(s); /* P4b: ids restart at 1 */
		// Harden audit #3 (verdict follow-up): the entity dict is reset on load,
		// so restart the fresh-id counter to restore the documented "first id is 1"
		// per-world invariant. CRPC_WORLD_RESET below clears the client dict too, so
		// the reused ids cannot alias any surviving entity (see the UNLOAD path note).
		s->next_entity_id = 0;
		s->minecart_snapshot_priority_cursor = 0;
		s->minecart_snapshot_background_cursor = 0;
		s->next_minecart_ride_epoch = 0;
		s->next_chunk_list_order = 0;
		s->entity_query_count = 0;
		s->player.added_to_chunk = false;
		/* Player membership is established after the spawn probe below
		 * (hw1029c), once the player's final position is known. */
		// Clear the process-static torch-burnout list for the freshly created world too
		// (the world clock just reset to 0 in server_world_create above) -- symmetric with
		// the UNLOAD path, and covers a load with no prior unload (first boot / dimension
		// change). See the unload-path note for why a stale list strands torches dark.
		redstone_torch_reset_burnout();
		// Same world-boundary clear for the process-resident TILE-ENTITY tables that are
		// keyed only by (x,y,z) with no world key and repopulated per-chunk by te_store_insert
		// (so, unlike chests/signs, they have NO monolithic archive reader to memset them). On
		// UNLOAD, server_world_destroy saves chunks with erase=false, so te_store_release never
		// runs and the slots survive: without this, world A's furnaces keep ticking in world B
		// (leaking the 64-slot table until "Too many furnaces" silently drops new ones), and an
		// in-flight piston move's id-36 slot lingers into the next world. Mirrors the chest/sign
		// reset + the torch-burnout / next_entity_id boundary clears above.
		// The clear is the SHARED helper: this site's hand-rolled list covered
		// only furnaces, so dispenser/note/record slots leaked across worlds
		// (contents contamination at matching coordinates + slot exhaustion).
		/* A1b: the world-load boundary releases only slot 0's rows (the shared
		 * tables may hold another world's), then the session map cache reset
		 * the full helper performs. */
		server_local_release_slot_te_rows(s, 0);
		server_local_reset_map_cache(s);
		server_local_release_slot_pistons(s, 0);
		server_local_release_slot_spawner_tracker(s, 0);

		/* hw1029c: every world-boundary reset above has run, so a chunk the
		 * spawn probe loads keeps its TileEntities and Entities like any later
		 * streamed chunk (Beta ChunkLoader.loadChunkIntoWorldFromCompound
		 * :176-194 attaches both at chunk load; nothing clears them after). */
		/* Slot 0 explicitly: this load boundary owns slot 0 (the release_slot_*
		 * calls above), whatever dimension it is loading. */
		assert(dict_server_chunks_size(s->worlds[0].chunks) == 0
			   && "no chunk may load before the world-boundary TE/entity resets");
		if(spawn_probe == SPAWN_PROBE_FALLBACK) {
			/* `dim` was forced to WORLD_DIM_OVERWORLD with the fallback, so the
			 * world just created IS the destination -- always takes the
			 * live-reader branch inside server_local_anti_suffocate_column,
			 * never the archived one. gen_throttle_armed is false right
			 * after server_world_create_impl (armed only inside the
			 * streaming ensure_populated path), so this first synchronous
			 * chunk load is NOT throttled/deferred. */
			w_coord_t clear_y;
			if(server_local_anti_suffocate_column(
				   s, (w_coord_t)world_spawn_x, (w_coord_t)world_spawn_z,
				   (w_coord_t)world_spawn_y, &clear_y)
			   == BED_RESPAWN_VALID)
				/* int + float = float, same precision as the untouched
				 * `world_spawn_y + PLAYER_EYE_HEIGHT` fallback formula --
				 * bit-identical when clear_y == world_spawn_y (see the
				 * citation on server_local_anti_suffocate_column). */
				pos[1] = clear_y + PLAYER_EYE_HEIGHT;
			// else: chunk generation itself failed on this call (I/O
			// error) -- keep the degraded-but-previously-accepted
			// fallback position rather than fail the whole world load
			// over a cosmetic push-up.
		} else if(spawn_probe == SPAWN_PROBE_BETA_EYE) {
			first_join_exact = server_local_first_join_beta_eye(
				s, pos, world_spawn_y + 1, &first_join_eye);
		} else if(spawn_probe == SPAWN_PROBE_PUSH_UP) {
			server_local_first_join_push_up(s, pos);
		}
		if(spawn_probe != SPAWN_PROBE_NONE) {
			s->player.x = pos[0];
			s->player.y = first_join_exact ? first_join_eye : pos[1];
			s->player.z = pos[2];
		}
		/* Beta playerLoggedIn: the destination chunk (and its entities) is
		 * loaded first, then the player joins it. */
		server_local_refresh_player_membership(s);
		s->player.active_inventory = &s->player.inventory;

		/* B1 stamp: the reset names the world it installs (the A1a identity
		 * of the freshly created slot-0 world); the client binds its world
		 * context to it, and that world's stamped traffic must match. */
		clin_rpc_send(&(struct client_rpc) {
			.type = CRPC_WORLD_RESET,
			.payload.world_reset.dimension = dim,
			.payload.world_reset.local_entity = 0,
			.payload.world_reset.world_index = s->worlds[0].world_index,
			.payload.world_reset.world_generation = s->worlds[0].generation,
		});

		clin_rpc_send(&(struct client_rpc) {
			.type = CRPC_PLAYER_SET_HEALTH,
			.payload.player_set_health.health = s->player.health
		});
	}
	s->preserve_live_inventory_on_finish = preserve_live_inventory;
	s->inventory_finish_pending = true;
	return true;
}

bool server_local_load_world_impl(struct server_local* s,
										 const string_t name) {
	bool loaded = server_local_load_world_impl_ex(s, name, NULL, false);
	if(loaded && !s->death_telemetry[SLD_SESSION])
		death_telemetry_begin(s);
	return loaded;
}

static bool server_local_death_world_reload(struct server_local* s) {
	enum {
		DEATH_RETRY_LIVE_TICKS = 20,
		DEATH_RETRY_POSITIONLESS_TICKS = 500,
	};
	ptime_t reload_start = time_get();
	size_t source_chunks = s->player.has_pos
		? dict_server_chunks_size(s->world.chunks) : 0;
	string_t lvl;
	string_init_set(lvl, s->level_name);
	if(s->player.has_pos && s->death_drop_recover_from_disk) {
		/* The journal was PREPARED before any source mutation and all needed
		 * base chunks were preflighted. Do not save a partially closed live
		 * world; reopening below invokes death_drop_recover_if_needed first. */
		assert(s->death_drop_active && s->death_drop_journal);
		if(!s->death_drop_prepared_durable) {
			/* A successful rename already made PREPARED observable, but the
			 * committed-name sync was inconclusive. Retain every live owner and
			 * the exact heap journal across retries until the forward decision is
			 * durably re-stored; only then may the source be abandoned. */
			s->death_drop_prepared_durable
				= death_drop_journal_store(
					s->level_name, s->death_drop_journal)
				== DEATH_DROP_JOURNAL_STORE_DURABLE;
			if(!s->death_drop_prepared_durable) {
				fprintf(stderr,
						"[world_switch] death stage=journal_resync result=retry retry_ticks=%d\n",
						DEATH_RETRY_LIVE_TICKS);
				s->death_world_evict = true;
				s->death_world_retry_delay = DEATH_RETRY_LIVE_TICKS;
				string_clear(lvl);
				return false;
			}
		}
		if(!server_local_abandon_prepared_death_world(s)) {
			/* A0: the release refused (a partner is attached). Nothing was
			 * torn down and the PREPARED journal is untouched; retry on the
			 * live cadence instead of loading over the still-live source. */
			fprintf(stderr,
					"[world_switch] death stage=source_release result=retry retry_ticks=%d\n",
					DEATH_RETRY_LIVE_TICKS);
			s->death_world_evict = true;
			s->death_world_retry_delay = DEATH_RETRY_LIVE_TICKS;
			string_clear(lvl);
			return false;
		}
		assert(!s->player.has_pos);
		s->death_drop_active = false;
		s->death_drop_prepared_durable = false;
		s->death_drop_recover_from_disk = false;
		server_local_free_death_drop_journal(s);
	}
	if(s->player.has_pos) {
		// Match portal travel's hard commit boundary. The only live Nether copy
		// must remain resident until player/session state and every chunk owner
		// have durably checkpointed.
		ptime_t close_start = time_get();
		if(!server_local_close_active_inventory(s)) {
			fprintf(stderr,
					"[world_switch] death stage=inventory_close result=fail ms=%d chunks=%zu retry_ticks=%d\n",
					(int)time_diff_ms(close_start, time_get()), source_chunks,
					DEATH_RETRY_LIVE_TICKS);
			s->death_world_evict = true;
			s->death_world_retry_delay = DEATH_RETRY_LIVE_TICKS;
			string_clear(lvl);
			return false;
		}
		fprintf(stderr,
				"[world_switch] death stage=inventory_close result=ok ms=%d chunks=%zu\n",
				(int)time_diff_ms(close_start, time_get()), source_chunks);
		bool checkpointed = false;
		if(s->death_drop_active) {
			assert(s->death_drop_journal);
			/* PREPARED is the durable forward-complete decision. Allocation may
			 * have left some runtime EntityItems absent; reconstruct all of them
			 * before a single source-region write. */
			if(!s->death_drop_prepared_durable) {
				s->death_drop_journal->phase = DEATH_DROP_JOURNAL_PREPARED;
				s->death_drop_prepared_durable
					= death_drop_journal_store(
						s->level_name, s->death_drop_journal)
					== DEATH_DROP_JOURNAL_STORE_DURABLE;
			}
			if(s->death_drop_prepared_durable
			   && s->death_drop_transfer_index
				   == s->death_drop_journal->count
			   && server_local_apply_death_container_slots(s)
			   && server_local_materialize_death_drops(s)
			   && server_local_checkpoint_entity_owners(s, "death_journal")
			   && server_world_checkpoint_chunks(&s->world)
			   && server_local_checkpoint_legacy_tile_entities(
				   s, "death_journal")
			   /* Durability barrier BEFORE the two irreversible steps below:
			    * the journal is the ONLY recovery record for these chunks, so
			    * it may not be removed -- and level.dat may not advance --
			    * until every region write above is fsync'd on the card. */
			   && server_local_sync_regions_durable(s, "death_journal")
			   && server_local_write_level_state(s)
			   && level_archive_save(&s->level)
			   && death_drop_journal_remove(s->level_name)) {
				s->death_drop_active = false;
				s->death_drop_prepared_durable = false;
				server_local_free_death_drop_journal(s);
				checkpointed = true;
			}
		} else {
			/* Compatibility for old saves/tests that latch death_world_evict
			 * without entering through the journal-aware lethal path. */
			checkpointed = server_local_checkpoint_live_world(s, "death");
		}
		// The lethal transition is not reversible. Keep the client on the early
		// loading screen across persistence retries instead of revealing a live
		// Nether world paired with an Overworld respawn player.
		if(!checkpointed) {
			fprintf(stderr,
					"[world_switch] death stage=journal_checkpoint result=retry retry_ticks=%d\n",
					DEATH_RETRY_LIVE_TICKS);
			s->death_world_evict = true;
			s->death_world_retry_delay = DEATH_RETRY_LIVE_TICKS;
			string_clear(lvl);
			return false;
		}
		if(!server_local_discard_world_impl(s, false)) {
			/* A0: checkpointed but not released (a partner is attached). The
			 * source stays live; retry exactly like a failed checkpoint. */
			fprintf(stderr,
					"[world_switch] death stage=source_release result=retry retry_ticks=%d\n",
					DEATH_RETRY_LIVE_TICKS);
			s->death_world_evict = true;
			s->death_world_retry_delay = DEATH_RETRY_LIVE_TICKS;
			string_clear(lvl);
			return false;
		}
	}
	ptime_t load_start = time_get();
	bool loaded = server_local_load_world_impl(s, lvl);
	fprintf(stderr,
			"[world_switch] death stage=world_load result=%s ms=%d chunks=%zu total_ms=%d\n",
			loaded ? "ok" : "fail",
			(int)time_diff_ms(load_start, time_get()), source_chunks,
			(int)time_diff_ms(reload_start, time_get()));
	if(!loaded) {
		// load_world resets level_name on every failure. Preserve the owned name
		// as the retry payload; the next no-position attempt must skip unload and
		// reopen this same archive instead of stalling behind the has_pos gate.
		string_set(s->level_name, lvl);
		s->death_world_evict = true;
		s->death_world_retry_delay = DEATH_RETRY_POSITIONLESS_TICKS;
	} else {
		s->death_world_retry_delay = 0;
	}
	string_clear(lvl);
	return loaded;
}

#ifdef CAVEWII_SERVER_LOCAL_TEST
bool server_local_test_death_world_reload(struct server_local* s) {
	assert(s);
	return server_local_death_world_reload(s);
}
#endif

// ===== Transactional, cooperative dimension switch =========================

static void server_local_restore_portal_state(struct server_local* s) {
	s->player.x = s->portal_origin.x;
	s->player.y = s->portal_origin.y;
	s->player.z = s->portal_origin.z;
	s->player.rx = s->portal_origin.rx;
	s->player.ry = s->portal_origin.ry;
	s->player.dimension = s->portal_origin.dimension;
	s->player.fire = s->portal_origin.fire;
	s->player.oxygen = s->portal_origin.oxygen;
	s->player.vel_x = s->portal_origin.vel_x;
	s->player.motion_y = s->portal_origin.motion_y;
	s->player.vel_y = s->portal_origin.vel_y;
	s->player.old_vel_y = s->portal_origin.old_vel_y;
	s->player.vel_z = s->portal_origin.vel_z;
	s->player.fall_distance = s->portal_origin.fall_distance;
	/* Beta changeWorld reuses this EntityPlayer. Keep its persistent pre-call
	 * moveEntity state through rollback; the post-ACK reliable snapshot later
	 * converges sneak to the controller's current held state. */
	s->player.on_ground = s->portal_origin.on_ground;
	s->player.sneaking = s->portal_origin.sneaking;
	s->player.distance_walked = s->portal_origin.distance_walked;
	s->player.next_step_distance = s->portal_origin.next_step_distance;
	server_local_refresh_player_membership(s);
	s->player.time_until_portal = s->portal_origin.time_until_portal;
	s->player.time_in_portal = s->portal_origin.time_in_portal;
	s->player.in_portal = false;
	s->player.portal_travel_requested = false;
}

static void server_local_capture_portal_origin(
	struct server_local* s, const struct world_load_override* origin) {
	s->portal_origin.x = origin->pos[0];
	s->portal_origin.y = origin->pos[1];
	s->portal_origin.z = origin->pos[2];
	s->portal_origin.rx = origin->rot[0];
	s->portal_origin.ry = origin->rot[1];
	s->portal_origin.dimension = origin->dimension;
	s->portal_origin.fire = s->player.fire;
	s->portal_origin.oxygen = s->player.oxygen;
	s->portal_origin.vel_x = s->player.vel_x;
	s->portal_origin.motion_y = s->player.motion_y;
	s->portal_origin.vel_y = s->player.vel_y;
	s->portal_origin.old_vel_y = s->player.old_vel_y;
	s->portal_origin.vel_z = s->player.vel_z;
	s->portal_origin.fall_distance = s->player.fall_distance;
	s->portal_origin.on_ground = s->player.on_ground;
	s->portal_origin.sneaking = s->player.sneaking;
	s->portal_origin.distance_walked = s->player.distance_walked;
	s->portal_origin.next_step_distance = s->player.next_step_distance;
	s->portal_origin.time_until_portal = s->player.time_until_portal;
	s->portal_origin.time_in_portal = s->player.time_in_portal;
	s->portal_origin.rollback_retry_delay = 0;
	s->portal_origin.rollback_retry_count = 0;
	s->portal_origin.valid = true;
}

enum {
	PORTAL_ROLLBACK_RETRY_DELAY_TICKS = 20,
	PORTAL_ROLLBACK_RETRY_MAX = 5,
};

static bool server_local_portal_rollback(struct server_local* s) {
	if(!s->portal_origin.valid || s->load_failure_terminal)
		return false;

	struct world_load_override origin = {
		.pos = {s->portal_origin.x, s->portal_origin.y, s->portal_origin.z},
		.rot = {s->portal_origin.rx, s->portal_origin.ry},
		.dimension = s->portal_origin.dimension,
	};
	string_t lvl;
	string_init_set(lvl, s->level_name);

	if(s->portal_job) {
		portal_teleporter_destroy(s->portal_job);
		s->portal_job = NULL;
	}
	// The destination player was never committed. Drop its live chunks and any
	// modified level tree without another flush. A completed destination chunk
	// checkpoint may remain on disk (so a newly built portal is not orphaned),
	// while the source Player tag remains the sole durable session position.
	if(s->player.has_pos && !server_local_discard_world_impl(s, false)) {
		/* A0: the uncommitted destination could not be released (a partner
		 * attached mid-transaction). Reopening the source over it would
		 * overwrite the live world, and the positionless retry never runs
		 * while a world is held, so fail closed: keep everything live, keep
		 * the transaction record, and publish the terminal load failure. */
		fprintf(stderr,
				"[world_switch] portal stage=destination_release result=terminal; retaining loading barrier\n");
		s->load_failure_terminal = true;
		clin_rpc_send(&(struct client_rpc) {.type = CRPC_LOAD_FAILED});
		string_clear(lvl);
		return false;
	}

	bool loaded = server_local_load_world_impl_ex(s, lvl, &origin, true);
	if(loaded) {
		server_local_restore_portal_state(s);
		level_archive_write_player(&s->level, origin.pos, origin.rot, NULL,
								   origin.dimension);
		level_archive_save(&s->level);
		s->portal_origin.valid = false;
		s->portal_origin.rollback_retry_delay = 0;
		s->portal_origin.rollback_retry_count = 0;
	} else {
		// Preserve both the transaction record and its world name. The load
		// helper clears level_name on failure; without restoring it, the next
		// retry would attempt to open "/level.dat" and could never recover.
		string_set(s->level_name, lvl);
		s->portal_origin.valid = true;
		s->portal_origin.rollback_retry_count++;
		if(s->portal_origin.rollback_retry_count
		   >= PORTAL_ROLLBACK_RETRY_MAX) {
			s->portal_origin.rollback_retry_delay = 0;
			s->load_failure_terminal = true;
			fprintf(stderr,
					"[world_switch] portal stage=source_rollback result=terminal attempts=%u; retaining loading barrier\n",
					s->portal_origin.rollback_retry_count);
			clin_rpc_send(&(struct client_rpc) {.type = CRPC_LOAD_FAILED});
		} else
			s->portal_origin.rollback_retry_delay
				= PORTAL_ROLLBACK_RETRY_DELAY_TICKS;
	}
	string_clear(lvl);
	return loaded;
}

/* A1a (Astra D8): the admitted actor's committed LIVE world, or NULL.
 * Membership: the host body and the currently bound guest body are admitted;
 * both are committed to slot 0 until A2 gives each actor its own binding
 * (PREPARE/ABORT keep the source, only COMMIT moves it). A slot whose world
 * is not live (between a release and the next load) has generation 0 and
 * yields NULL -- callers treat NULL as "this actor has no world: do nothing".
 * Synchronous borrow: never cache the pointer across ticks; delayed work
 * stores server_world_handle_of(w) and resolves it with
 * server_local_world_from_handle at use. */
struct server_world* server_local_world_of(struct server_local* s,
	const struct server_player* actor) {
	if(!s || !actor)
		return NULL;
	if(actor != &s->player && !(s->guest_actor && actor == s->guest_actor))
		return NULL;
	/* A2-T/A2-W: each body is committed to ITS slot (0 until a COMMIT moves
	 * it); a slot other than the routed one must also be bound to this
	 * session (server_local_world_from_handle's rule). */
	uint8_t slot = actor->world_slot;
	if(slot >= SERVER_LOCAL_WORLD_SLOTS)
		return NULL;
	struct server_world* w = &s->worlds[slot];
	if(!server_world_chunks_ready(w) || !w->generation)
		return NULL;
	if(slot != 0 && w->session != s)
		return NULL;
	return w;
}

struct server_world* server_local_world_from_handle(struct server_local* s,
	struct server_world_handle h) {
	if(!s || !h.generation || h.world_index >= SERVER_LOCAL_WORLD_SLOTS)
		return NULL;
	struct server_world* w = &s->worlds[h.world_index];
	if(!server_world_chunks_ready(w) || w->generation != h.generation
	   || w->world_index != h.world_index || w->session != s)
		return NULL;
	return w;
}

/* A0 interim rule (split-dimensions-plan-0924), until per-actor dimensions
 * land: one world context serves both players, and travel releases it. While
 * a partner body is attached the host's travel is refused BEFORE any
 * checkpoint/discard, so both players keep the source world untouched. The
 * dwell resets and the Beta arrival cooldown (setInPortal pins it at 10 while
 * in contact) re-arms the ramp only after the host leaves the portal, so a
 * host parked in the frame gets exactly one notice, not one per tick. */
static void server_local_portal_refuse_for_partner(struct server_local* s) {
	fprintf(stderr,
			"[world_switch] portal stage=partner_attached result=refused\n");
	s->player.portal_travel_requested = false;
	s->player.in_portal = false;
	s->player.time_in_portal = 0.0F;
	s->player.time_until_portal = 10;
	server_local_send_hud_message(s, "Portal: Player 2 must leave first");
}

/* Split dims, the A2-T PRODUCTION CALLER. A host dwell moves the host alone
 * through the actor transfer transaction (both worlds stay live) when
 *  - a partner is attached AND world-bound client payloads are on (lane B's
 *    "split.world_payloads"; clin_world_payloads_enabled is the client's own
 *    answer, set once at boot) -- each view can then show its own world; or
 *  - the host already stands outside the routed slot 0 (only A2-T put it
 *    there; the legacy switch below tears down slot 0 and cannot move it).
 * Otherwise the legacy path runs exactly as before (flag OFF with a partner:
 * the A0 refusal). */
static bool server_local_portal_uses_transfer(struct server_local* s) {
	struct server_world* hw = server_local_world_of(s, &s->player);
	if(hw && hw != &s->worlds[0])
		return true;
	return s->guest_actor && clin_world_payloads_enabled();
}

static void server_local_portal_request_transfer(struct server_local* s) {
	struct server_world* src = server_local_world_of(s, &s->player);
	enum world_dim dst = src && src->dimension == WORLD_DIM_NETHER
		? WORLD_DIM_OVERWORLD : WORLD_DIM_NETHER;
	uint32_t id = 0;
	enum server_transfer_rc rc = server_transfer_request(s, &s->player, dst, &id);
	/* Either way the dwell is consumed and the contact cooldown pinned (Beta
	 * setInPortal holds it at 10 while in contact), so a host parked in the
	 * frame neither re-requests every dwell nor gets one notice per tick. */
	s->player.portal_travel_requested = false;
	s->player.in_portal = false;
	s->player.time_in_portal = 0.0F;
	s->player.time_until_portal = 10;
	if(rc == SERVER_TRANSFER_OK) {
		fprintf(stderr, "[world_switch] portal stage=a2t_request result=ok id=%u "
						"dim=%d\n", (unsigned)id, (int)dst);
		/* S2 portal.travel: the instant the dwell is consumed (Beta
		 * EntityPlayerSP.onLivingUpdate:39-62), host UI route. */
		server_local_emit_sound_ui(
			SOUND_PORTAL_TRAVEL, 1.0F,
			rand_gen_flt(server_local_sound_rng()) * 0.4F + 0.8F);
		return;
	}
	if(rc == SERVER_TRANSFER_DUPLICATE)
		return; /* already travelling: the open transaction keeps its notice */
	fprintf(stderr, "[world_switch] portal stage=a2t_request result=refused "
					"rc=%d\n", (int)rc);
	/* an admission refusal already toasted its reason */
	if(rc != SERVER_TRANSFER_REFUSED_ADMISSION)
		server_local_send_hud_message(s, "Cannot open the other dimension now");
}

/* The host's client side of an A2-T COMMIT (server_transfer.c commit() calls
 * this for the host once world-bound payloads answered the capacity
 * reservation). Lane B's contract (B2-A2T-client.md): BEGIN_WORLD_SWITCH is
 * player 0's barrier -- stamped with the world player 0 is leaving, so the
 * client accepts it -- then a WORLD_RESET stamped with the destination world
 * rebuilds (or, for a host joining the guest's live world at this generation,
 * joins) that slot and binds view 0 to it. Sent claims follow what the client
 * KEEPS: only a host join keeps the slot's payload; every other arrival
 * rebuilds it from empty, so the destination's sent claims are dropped (F3,
 * else the retained world comes back full of holes). */
void server_local_host_transfer_publish(struct server_local* s, uint8_t src_slot) {
	if(!s || src_slot >= SERVER_LOCAL_WORLD_SLOTS)
		return;
	struct server_world* src = &s->worlds[src_slot];
	struct server_world* dst = server_local_world_of(s, &s->player);
	if(!dst || dst == src)
		return;
	/* Only an admitted second body can keep an independent world running while
	 * the host's newly bound context presents. Single-player loads keep their
	 * original global suspension. */
	s->a2w_host_presentation = s->guest_gameplay && s->guest_actor
		&& s->guest_owned && s->guest_confirmed;
	server_diag_set(SERVER_DIAG_HOST_BEGIN);
	server_local_send_w(src, (struct client_rpc) {.type = CRPC_BEGIN_WORLD_SWITCH});
	const bool host_join = s->guest_actor
		&& server_local_world_of(s, s->guest_actor) == dst;
	if(!host_join) {
		dict_server_chunks_it_t it;
		for(dict_server_chunks_it(it, dst->chunks); !dict_server_chunks_end_p(it);
			dict_server_chunks_next(it))
			dict_server_chunks_ref(it)->value.sent = false;
	}
	server_diag_set(SERVER_DIAG_HOST_RESET);
	clin_rpc_send(&(struct client_rpc) {
		.type = CRPC_WORLD_RESET,
		.payload.world_reset.dimension = dst->dimension,
		.payload.world_reset.local_entity = 0,
		.payload.world_reset.world_index = dst->world_index,
		.payload.world_reset.world_generation = dst->generation,
	});
	server_diag_set(SERVER_DIAG_HOST_HEALTH);
	clin_rpc_send(&(struct client_rpc) {
		.type = CRPC_PLAYER_SET_HEALTH,
		.payload.player_set_health.health = s->player.health,
	});
	/* A2-W: the client now holds the destination's context -- its stream
	 * starts (slot 0 streams through its own loop), and the host's marker
	 * waits for the near ring of this world */
	server_diag_set(SERVER_DIAG_HOST_STREAM);
	server_transfer_stream_enable(s, dst->world_index);
	s->a2w_host_marker_pending = true;
	s->a2w_host_marker_wait = 0;
	fprintf(stderr, "[world_switch] a2t host publish: slot %u -> slot %u gen %u "
					"(%s)\n", (unsigned)src_slot, (unsigned)dst->world_index,
			(unsigned)dst->generation, host_join ? "join" : "rebuild");
}

/* A2-W (A2W-CONTRACT 9): the host's load-screen release after an A2-T COMMIT,
 * for the host's CURRENT world -- the same epoch marker a load ends with. */
bool server_local_host_world_marker(struct server_local* s) {
	if(!s || !s->player.has_pos || s->input_ack_pending != 0
	   || s->load_failure_terminal)
		return false;
	struct server_world* hw = server_local_world_of(s, &s->player);
	bool recovering = s->stream_recovery_epoch != 0 && hw && hw != &s->worlds[0];
	/* Transfer already proved its landing center. Recovery emptied it, so
	 * even the outer-ring fallback must wait for this world's collision column. */
	if(recovering && !server_world_is_chunk_sent(hw,
		WCOORD_CHUNK_OFFSET((w_coord_t)floor(s->player.x)),
		WCOORD_CHUNK_OFFSET((w_coord_t)floor(s->player.z))))
		return false;
	server_local_send_w(hw, (struct client_rpc) {
		.type = CRPC_TIME_SET,
		.payload.time_set = s->world_time,
	});
	uint32_t epoch = server_local_arm_input_handoff(s);
	server_local_send_input_handoff(s, epoch, false);
	if(recovering) s->player.finished_loading = true;
	fprintf(stderr, "[a2w] host marker: epoch %u for slot %u\n", (unsigned)epoch,
			hw ? (unsigned)hw->world_index : 0u);
	return true;
}

// Starts the live switch but leaves portal search/build to bounded step calls.
// The source player tag is saved unchanged; after placement, destination chunks
// checkpoint first and only then is the new location committed to level.dat.
void server_local_portal_travel(struct server_local* s) {
	if(!s || !s->player.has_pos || s->portal_job
	   || s->world_switch_phase != SERVER_WORLD_SWITCH_IDLE)
		return;
	if(server_local_portal_uses_transfer(s)) {
		server_local_portal_request_transfer(s);
		return;
	}
	if(s->guest_actor) {
		server_local_portal_refuse_for_partner(s);
		return;
	}
	struct server_world* source_world = server_local_world_of(s, &s->player);
	if(!source_world)
		return; /* D8: no live committed world -> nothing to travel from */
	ptime_t travel_start = time_get();
	size_t source_chunks = dict_server_chunks_size(source_world->chunks);

	struct world_load_override origin = {
		.pos = {s->player.x, s->player.y, s->player.z},
		.rot = {s->player.rx, s->player.ry},
		.dimension = s->player.dimension,
	};
	struct world_load_override destination = origin;
	destination.dimension = (origin.dimension == WORLD_DIM_NETHER)
		? WORLD_DIM_OVERWORLD
		: WORLD_DIM_NETHER;
	if(destination.dimension == WORLD_DIM_NETHER) {
		destination.pos[0] /= 8.0f;
		destination.pos[2] /= 8.0f;
	} else {
		destination.pos[0] *= 8.0f;
		destination.pos[2] *= 8.0f;
	}

	string_t lvl;
	string_init_set(lvl, s->level_name);
	// on_close commits container slots and drops any picked cursor item before
	// entity/chunk persistence gathers the source world. Close before presenting
	// feedback: after success, every early failure can safely return to gameplay
	// rather than resurrecting a client GUI whose server owner was destroyed.
	ptime_t stage_start = time_get();
	if(!server_local_close_active_inventory(s)) {
		fprintf(stderr,
				"[world_switch] portal stage=inventory_close result=fail ms=%d chunks=%zu\n",
				(int)time_diff_ms(stage_start, time_get()), source_chunks);
		string_clear(lvl);
		return;
	}
	fprintf(stderr,
			"[world_switch] portal stage=inventory_close result=ok ms=%d chunks=%zu\n",
			(int)time_diff_ms(stage_start, time_get()), source_chunks);
	// Beta closes any active GUI on portal contact. Do this before the fallible
	// checkpoint so an aborted transaction cannot leave the client clicking a
	// container the server just committed/destroyed.
	clin_rpc_send(&(struct client_rpc) {.type = CRPC_RETURN_INGAME});
	// S2: portal.travel -- Beta plays it via playSoundFX the instant
	// timeInPortal reaches 1.0F, immediately before mc.usePortal(). This is
	// that exact moment server-side (the dwell latch consumed, the switch
	// committing); queued BEFORE BEGIN_WORLD_SWITCH the ui-routed CRPC drains
	// on the still-live client, so the cue plays as the loading screen takes
	// over. Only THIS portal path emits it -- death/menu world resets share
	// the load seam but never pass through here, so they stay silent.
	// [740c583: EntityPlayerSP.onLivingUpdate:39-62]
	server_local_emit_sound_ui(
		SOUND_PORTAL_TRAVEL, 1.0F,
		rand_gen_flt(server_local_sound_rng()) * 0.4F + 0.8F);
	server_local_world_switch_begin(s, SERVER_WORLD_SWITCH_PORTAL);
	fprintf(stderr,
			"[world_switch] portal feedback begin chunks=%zu elapsed_ms=%d\n",
			source_chunks, (int)time_diff_ms(travel_start, time_get()));

	// Preflight after BEGIN + the explicit scheduler handoff. It can touch SD and
	// parse NBT, so doing it before feedback recreated the reported blank delay.
	// The source world is still fully live and a failure is a reversible cancel.
	struct level_archive probe;
	stage_start = time_get();
	if(!level_archive_create(&probe, lvl)) {
		fprintf(stderr,
				"[world_switch] portal stage=archive_preflight result=fail ms=%d chunks=%zu\n",
				(int)time_diff_ms(stage_start, time_get()), source_chunks);
		server_local_world_switch_cancel(s);
		string_clear(lvl);
		return;
	}
	level_archive_destroy(&probe);
	fprintf(stderr,
			"[world_switch] portal stage=archive_preflight result=ok ms=%d chunks=%zu\n",
			(int)time_diff_ms(stage_start, time_get()), source_chunks);

	// Do not tear down the only live copy until both the global player/session
	// state and every resident chunk (including tile and dynamic entities) have
	// durably checkpointed. The following discard teardown
	// deliberately performs no second, unchecked save pass.
	if(!server_local_checkpoint_live_world(s, "portal")) {
		fprintf(stderr,
				"[world_switch] portal stage=checkpoint result=abort total_ms=%d\n",
				(int)time_diff_ms(travel_start, time_get()));
		// The source is still completely live. Cancel only the reversible
		// feedback state; no WORLD_RESET has committed client teardown.
		server_local_world_switch_cancel(s);
		string_clear(lvl);
		return;
	}
	server_local_capture_portal_origin(s, &origin);
	s->portal_origin.transition_started_at = travel_start;
	if(!server_local_discard_world_impl(s, false)) {
		/* A0: the checkpointed source was NOT released, so it is still the
		 * only live copy. Abort like a failed checkpoint: drop the captured
		 * origin (no transaction started) and cancel only the reversible
		 * feedback; no WORLD_RESET was sent. */
		fprintf(stderr,
				"[world_switch] portal stage=source_release result=abort total_ms=%d\n",
				(int)time_diff_ms(travel_start, time_get()));
		s->portal_origin.valid = false;
		s->portal_origin.rollback_retry_delay = 0;
		s->portal_origin.rollback_retry_count = 0;
		server_local_world_switch_cancel(s);
		string_clear(lvl);
		return;
	}
	// unload clears transaction state for ordinary world exits. Re-arm the
	// snapshot now that the source teardown has completed.
	s->portal_origin.valid = true;
	s->portal_origin.rollback_retry_delay = 0;
	s->portal_origin.rollback_retry_count = 0;
	stage_start = time_get();
	if(!server_local_load_world_impl_ex(s, lvl, &destination, true)) {
		fprintf(stderr,
				"[world_switch] portal stage=destination_load result=fail ms=%d total_ms=%d\n",
				(int)time_diff_ms(stage_start, time_get()),
				(int)time_diff_ms(travel_start, time_get()));
		// The source tag was never overwritten, so rollback can reopen it from
		// the durable snapshot. Keep the name available if that reopen itself
		// transiently fails; server_local_portal_travel_step will retry it.
		string_set(s->level_name, lvl);
		server_local_portal_rollback(s);
		string_clear(lvl);
		return;
	}
	fprintf(stderr,
			"[world_switch] portal stage=destination_load result=ok ms=%d total_ms=%d\n",
			(int)time_diff_ms(stage_start, time_get()),
			(int)time_diff_ms(travel_start, time_get()));
	string_clear(lvl);

	s->player.fire = s->portal_origin.fire;
	s->player.oxygen = s->portal_origin.oxygen;
	/* Minecraft.changeWorld retains the same EntityPlayer instance. Loading the
	 * destination reconstructs Cave's world container, but must not turn that
	 * architectural boundary into a movement-state reset. */
	s->player.fall_distance = s->portal_origin.fall_distance;
	s->player.on_ground = s->portal_origin.on_ground;
	s->player.sneaking = s->portal_origin.sneaking;
	s->player.distance_walked = s->portal_origin.distance_walked;
	s->player.next_step_distance = s->portal_origin.next_step_distance;
	s->player.time_until_portal = 10;
	s->player.time_in_portal = 1.0f;

	struct java_random rng;
	// Only Java Random's low 48 bits survive setSeed. Compute that intended
	// wrap in unsigned arithmetic; the old signed multiply overflows for modern
	// epoch timestamps and is undefined behavior (an immediate UBSan abort).
	uint64_t rng_seed
		= ((uint64_t)CLOCK_SEED_TIME() * UINT64_C(25214903917)
		   + (uint64_t)s->world.current_tick)
		& ((UINT64_C(1) << 48) - 1);
	jrand_set_seed(&rng, (int64_t)rng_seed);
	s->portal_job = portal_teleporter_begin(s, &rng);
	if(!s->portal_job) {
		fprintf(stderr,
				"[world_switch] portal stage=teleporter_begin result=fail total_ms=%d\n",
				(int)time_diff_ms(travel_start, time_get()));
		server_local_portal_rollback(s);
	} else
		fprintf(stderr,
				"[world_switch] portal stage=teleporter_begin result=ok total_ms=%d\n",
				(int)time_diff_ms(travel_start, time_get()));
}

bool server_local_portal_travel_step(struct server_local* s) {
	if(!s)
		return true;
	if(s->load_failure_terminal)
		return true;
	if(!s->portal_job) {
		if(!s->portal_origin.valid || s->player.has_pos)
			return true;
		if(s->portal_origin.rollback_retry_delay > 0) {
			s->portal_origin.rollback_retry_delay--;
			return false;
		}
		return server_local_portal_rollback(s);
	}
	enum portal_teleporter_result result
		= portal_teleporter_step(s, s->portal_job);
	if(result == PORTAL_TELEPORTER_WORKING)
		return false;
	portal_teleporter_destroy(s->portal_job);
	s->portal_job = NULL;

	if(result == PORTAL_TELEPORTER_FAILED) {
		fprintf(stderr,
				"[world_switch] portal stage=teleporter result=fail total_ms=%d; rolling back\n",
				(int)time_diff_ms(s->portal_origin.transition_started_at,
								  time_get()));
		return server_local_portal_rollback(s);
	}
	server_local_refresh_player_membership(s);

	// Portal placement determines the final player position. Resolve any container
	// owner whose block was cleared by the fallback, then atomically persist each
	// destination chunk's absent TE + replacement drops under the CaveWii complete
	// marker. Only after those owner records exist may the legacy full image shrink;
	// only after both may level.dat point at the destination.
	ptime_t commit_start = time_get();
	ptime_t stage_start = commit_start;
	size_t destination_chunks = dict_server_chunks_size(s->world.chunks);
	bool orphans_resolved = server_local_retry_orphaned_container_drops(s);
	fprintf(stderr,
			"[world_switch] portal stage=destination_orphan_resolution result=%s ms=%d chunks=%zu\n",
			orphans_resolved ? "ok" : "fail",
			(int)time_diff_ms(stage_start, time_get()), destination_chunks);
	bool destination_prepared = orphans_resolved
		&& server_local_checkpoint_entity_owners(s, "portal_destination");
	if(!destination_prepared) {
		fprintf(stderr,
				"[world_switch] portal stage=destination_commit result=fail total_ms=%d; rolling back\n",
				(int)time_diff_ms(s->portal_origin.transition_started_at,
								  time_get()));
		return server_local_portal_rollback(s);
	}
	stage_start = time_get();
	bool chunks_checkpointed = server_world_checkpoint_chunks(&s->world);
	fprintf(stderr,
			"[world_switch] portal stage=destination_chunk_checkpoint result=%s ms=%d chunks=%zu\n",
			chunks_checkpointed ? "ok" : "fail",
			(int)time_diff_ms(stage_start, time_get()), destination_chunks);
	if(!chunks_checkpointed) {
		fprintf(stderr,
				"[world_switch] portal stage=destination_commit result=fail total_ms=%d; rolling back\n",
				(int)time_diff_ms(s->portal_origin.transition_started_at,
								  time_get()));
		return server_local_portal_rollback(s);
	}
#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(s_fail_next_portal_after_chunk_checkpoint) {
		s_fail_next_portal_after_chunk_checkpoint = false;
		fprintf(stderr,
				"[world_switch] portal stage=destination_commit result=injected_power_loss total_ms=%d; rolling back\n",
				(int)time_diff_ms(s->portal_origin.transition_started_at,
								  time_get()));
		return server_local_portal_rollback(s);
	}
#endif
	if(!server_local_checkpoint_legacy_tile_entities(
		   s, "portal_destination")) {
		fprintf(stderr,
				"[world_switch] portal stage=destination_commit result=fail total_ms=%d; rolling back\n",
				(int)time_diff_ms(s->portal_origin.transition_started_at,
								  time_get()));
		return server_local_portal_rollback(s);
	}
	/* Durability barrier before the Player commit: level.dat must never point
	 * at a dimension/position whose chunks exist only in libfat's cache. On a
	 * cut here the destination chunks are already durable and the player still
	 * restarts at the source -- same contract as the chunks-first boundary the
	 * injected-power-loss scenario above pins. */
	if(!server_local_sync_regions_durable(s, "portal_destination")) {
		fprintf(stderr,
				"[world_switch] portal stage=destination_commit result=fail total_ms=%d; rolling back\n",
				(int)time_diff_ms(s->portal_origin.transition_started_at,
								  time_get()));
		return server_local_portal_rollback(s);
	}
	stage_start = time_get();
#ifdef CAVEWII_SERVER_LOCAL_TEST
	s_portal_player_commit_attempts++;
#endif
	bool committed = level_archive_write_player(
		&s->level, (vec3) {s->player.x, s->player.y, s->player.z},
		(vec2) {s->player.rx, s->player.ry}, NULL, s->player.dimension)
		&& level_archive_save(&s->level);
	if(!committed) {
		fprintf(stderr,
				"[world_switch] portal stage=destination_player_commit result=fail ms=%d total_ms=%d; rolling back\n",
				(int)time_diff_ms(stage_start, time_get()),
				(int)time_diff_ms(s->portal_origin.transition_started_at,
								  time_get()));
		return server_local_portal_rollback(s);
	}
	fprintf(stderr,
			"[world_switch] portal stage=destination_player_commit result=ok player_ms=%d commit_ms=%d total_ms=%d\n",
			(int)time_diff_ms(stage_start, time_get()),
			(int)time_diff_ms(commit_start, time_get()),
			(int)time_diff_ms(s->portal_origin.transition_started_at,
							  time_get()));
	s->portal_origin.valid = false;
	s->portal_origin.rollback_retry_delay = 0;
	s->portal_origin.rollback_retry_count = 0;
	return true;
}

// Map the authoritative active inventory back to the wire id the client used
// to open it. A delayed click from a closed chest can carry a perfectly valid
// player-inventory slot number; capacity validation alone cannot distinguish
// that stale window from the live one.
static int server_local_active_window_id(const struct server_player* player) {
	if(!player || !player->active_inventory)
		return -1;
	if(player->active_inventory == &player->inventory)
		return WINDOWC_INVENTORY;

	/* Registry data (window_registry.h). A logic missing from this map
	 * permanently soft-locks its window: SRPC_WINDOW_CLOSE/SRPC_WINDOW_CLICK
	 * match the client's window id against this function, so every click and
	 * close request is silently rejected. */
	const struct window_desc* desc
		= window_registry_find(player->active_inventory->logic);
	if(!desc || desc->key == WINDOW_KEY_NONE)
		return -1; /* the player row is only reachable via the check above */
	return (int)desc->windowc;
}

/* Every SRPC_RECIPE_CRAFT is answered, always: the client holds exactly one
 * pending request and only a matching reply retires it, so a silently dropped
 * request would leave the guide waiting forever. That is why this verb is NOT
 * added to server_rpc_blocked_while_sleeping()'s list (which returns without
 * replying) -- the sleeping/loading barriers are enforced INSIDE the handler
 * below and come back as an explicit RECIPE_CRAFT_BUSY instead. */
static void server_local_recipe_craft_reply(struct server_player* player,
	const struct server_rpc* call, enum recipe_craft_reason reason) {
	struct inventory* route = player->active_inventory
		? player->active_inventory : &player->inventory;
	server_local_window_reply(route, &(struct client_rpc) {
		.type = CRPC_RECIPE_CRAFT,
		.payload.recipe_craft = {
			.ticket = call->payload.recipe_craft.ticket,
			.player = call->payload.recipe_craft.player,
			.window = call->payload.recipe_craft.window,
			.reason = reason,
		},
	});
}

/* Requirement 3 -- at most once, per owning actor.
 *
 * `player` is the actor the QUEUE ENVELOPE resolved (host slot 0 or the bound
 * guest slot 1), never anything the payload claims; the payload's own
 * player/window fields are then checked AGAINST that actor, so a split-screen
 * client cannot drive the other player's inventory even by forging both. Each
 * actor keeps one retired ticket: an exact retry replays the recorded verdict
 * without touching the inventory a second time, an older ticket is refused as
 * stale, and the ticket is retired at the seam where a retry could otherwise
 * RE-APPLY -- immediately before the one mutating call, never after it.
 *
 * Ordering (hostile review, finding 4): validation below is PURE, so the ticket
 * is no longer stamped ahead of it. That closes the window in which the actor
 * held a NEW ticket paired with the PREVIOUS request's recorded verdict -- the
 * pair an exact retry replays. Ticket and reason are now always written
 * together, and the mutating branch stamps a conservative verdict up front so
 * even a retry racing the mutation replays a refusal rather than a stale OK. */
static void server_local_process_recipe_craft_for(struct server_local* s,
	struct server_player* player, const struct server_rpc* call) {
	if(!s || !player || !call || call->type != SRPC_RECIPE_CRAFT) return;
	uint32_t ticket = call->payload.recipe_craft.ticket;
	if(!ticket) {
		server_local_recipe_craft_reply(player, call, RECIPE_CRAFT_INVALID_REQUEST);
		return;
	}
	if(ticket == player->recipe_craft_ticket) {
		server_local_recipe_craft_reply(player, call, player->recipe_craft_reason);
		return;
	}
	/* Serial comparison, so the counter may wrap without stranding a client. */
	if(player->recipe_craft_ticket
	   && (int32_t)(ticket - player->recipe_craft_ticket) <= 0) {
		server_local_recipe_craft_reply(player, call, RECIPE_CRAFT_STALE_TICKET);
		return;
	}
	enum recipe_craft_reason reason;
	uint8_t owner = player == &s->player ? 0
		: player == s->guest_actor		 ? 1
										 : UINT8_MAX;
	struct inventory* inv = player->active_inventory;
	if(call->payload.recipe_craft.player != owner)
		reason = RECIPE_CRAFT_WRONG_PLAYER;
	else if(!inv || inv->owner != player
		|| server_local_active_window_id(player)
			!= (int)call->payload.recipe_craft.window)
		reason = RECIPE_CRAFT_WRONG_WINDOW;
	else if(inv->logic != &inventory_logic_crafting
		&& inv->logic != &inventory_logic_player)
		reason = RECIPE_CRAFT_WRONG_WINDOW;
	else if(s->world_switch_phase != SERVER_WORLD_SWITCH_IDLE
		|| s->death_world_evict
		|| (player == &s->player && s->a2w_host_presentation)
		|| server_transfer_actor_inert(s, player)
		|| (s->input_ack_pending != 0
			&& !(player == s->guest_actor
				&& server_transfer_guest_continuity(s)))
		|| player->sleeping
		|| (player == &s->player && server_local_host_respawn_active(s))
		|| !player->has_pos || !player->finished_loading || inv->invalidated
		|| inv->transaction_pending)
		reason = RECIPE_CRAFT_BUSY;
	else {
		/* The at-most-once seam. Everything above was a pure check; this is the
		 * only line past which the world can have changed, so the ticket is
		 * retired HERE -- with a conservative verdict, replaced by the real one
		 * the moment the transaction returns. */
		player->recipe_craft_ticket = ticket;
		player->recipe_craft_reason = RECIPE_CRAFT_BUSY;
		set_inv_slot_t changes;
		set_inv_slot_init(changes);
		reason = inventory_crafting_one_batch(inv,
			inv->logic == &inventory_logic_crafting ? WINDOW_TYPE_WORKBENCH
													: WINDOW_TYPE_INVENTORY,
			call->payload.recipe_craft.recipe_index, s, changes);
		/* Slot updates go out BEFORE the reply, so the reply is the client's
		 * authoritative completion edge with the new contents already applied. */
		if(reason == RECIPE_CRAFT_OK)
			server_local_send_inv_changes(changes, inv,
				call->payload.recipe_craft.window);
		set_inv_slot_clear(changes);
	}
	player->recipe_craft_ticket = ticket;
	player->recipe_craft_reason = reason;
	server_local_recipe_craft_reply(player, call, reason);
}

static void server_local_reopen_active_inventory(struct server_player* player) {
	if(!player || !player->active_inventory)
		return;
	struct inventory* inv = player->active_inventory;
	int window = server_local_active_window_id(player);
	/* REOPEN must send the SAME wire type the OPEN path did, so both read the
	 * row's wire_type (window_registry.h). The double chest is the case that
	 * proves it matters: Beta's ONE-GUI rule (handoff P2(f)) reopens it as
	 * WINDOW_TYPE_CHEST, and grouping it with the iron chest here once flipped
	 * a recovered double chest back onto the fork's GUI -- an OPEN/REOPEN
	 * mismatch visible only after a client window-allocation failure. */
	const struct window_desc* desc = window_registry_find(inv->logic);
	if(!desc
	   || (desc->key == WINDOW_KEY_NONE && inv != &player->inventory))
		return;
	enum window_type type = desc->wire_type;
	if(window < 0 || inv->capacity == 0 || inv->capacity > UINT8_MAX)
		return;

	// REOPEN is self-contained: the client may have destroyed its local window
	// after an allocation failure. Metadata lets it reconstruct, and the full
	// snapshot that follows restores the authoritative contents.
	server_local_window_reply(inv, &(struct client_rpc) {
		.type = CRPC_REOPEN_WINDOW,
		.payload.window_reopen.window = (uint8_t)window,
		.payload.window_reopen.type = type,
		.payload.window_reopen.slot_count = (uint8_t)inv->capacity,
	});
	for(size_t slot = 0; slot < inv->capacity; slot++)
		server_local_window_reply(inv, &(struct client_rpc) {
			.type = CRPC_INVENTORY_SLOT,
			.payload.inventory_slot.window = (uint8_t)window,
			.payload.inventory_slot.slot = (uint8_t)slot,
			.payload.inventory_slot.item = inv->items[slot],
		});
	// A reconstructed window has an empty cursor and hotbar index zero. Both are
	// authoritative state outside items[0..capacity), so the full snapshot must
	// carry them explicitly (including an empty cursor to clear stale state).
	server_local_window_reply(inv, &(struct client_rpc) {
		.type = CRPC_INVENTORY_SLOT,
		.payload.inventory_slot.window = (uint8_t)window,
		.payload.inventory_slot.slot = SPECIAL_SLOT_PICKED_ITEM,
		.payload.inventory_slot.item = inv->picked_item,
	});
	if(inv == &player->inventory)
		server_local_window_reply(inv, &(struct client_rpc) {
			.type = CRPC_PLAYER_HOTBAR_SLOT,
			.payload.player_hotbar_slot.slot
				= (uint8_t)inventory_get_hotbar(inv),
		});
}

/* Beta Entity.handleWaterMovement probes
 * boundingBox.expand(0,-0.4000000059604645,0).contract(.001,.001,.001), then
 * World.handleMaterialAcceleration scans every overlapped material cell. The
 * server player position is the eye, so reconstruct the exact 0.6x1.8 body. */
bool server_local_player_body_in_water_for(
	struct server_local* s, const struct server_player* player) {
	assert(s && player);
	/* A1a (D8): the actor's committed live world; none -> no hazard read. */
	struct server_world* w = server_local_world_of(s, player);
	if(!w)
		return false;
	const double shrink_y = 0.4000000059604645;
	const double epsilon = 0.001;
	const double half_width = (double)(0.6F / 2.0F);
	const double feet_y = player->y - PLAYER_EYE_HEIGHT;
	const double min_x = player->x - half_width + epsilon;
	const double max_x = player->x + half_width - epsilon;
	const double min_y = feet_y + shrink_y + epsilon;
	const double max_y = feet_y + PLAYER_BODY_HEIGHT - shrink_y - epsilon;
	const double min_z = player->z - half_width + epsilon;
	const double max_z = player->z + half_width - epsilon;
	const w_coord_t x0 = (w_coord_t)floor(min_x);
	const w_coord_t x1 = (w_coord_t)floor(max_x + 1.0);
	const w_coord_t y0 = (w_coord_t)floor(min_y);
	const w_coord_t y1 = (w_coord_t)floor(max_y + 1.0);
	const w_coord_t z0 = (w_coord_t)floor(min_z);
	const w_coord_t z1 = (w_coord_t)floor(max_z + 1.0);
	if(y1 < 0 || y0 >= WORLD_HEIGHT)
		return false;

	/* World.handleMaterialAcceleration fails closed unless the entire probe is
	 * resident. A finished player normally has this ring; keep the exact boundary
	 * behavior during load/OOM instead of treating a partial probe as wet. */
	for(w_coord_t x = x0; x <= x1; x++)
		for(w_coord_t z = z0; z <= z1; z++)
			if(!server_world_is_chunk_loaded(
				   w,
				   WCOORD_CHUNK_OFFSET(x), WCOORD_CHUNK_OFFSET(z)))
				return false;

	for(w_coord_t x = x0; x < x1; x++)
		for(w_coord_t y = y0; y < y1; y++)
			for(w_coord_t z = z0; z < z1; z++) {
				struct block_data block;
				if(!server_world_get_block(
					   w, x, y, z, &block)
				   || (block.type != BLOCK_WATER_FLOW
					   && block.type != BLOCK_WATER_STILL))
					continue;
				int metadata = block.metadata & 0x0F;
				if(metadata >= 8)
					metadata = 0;
				float percent_air = (float)(metadata + 1) / 9.0F;
				double surface = (double)(y + 1) - (double)percent_air;
				if((double)y1 >= surface)
					return true;
			}
	return false;
}

static bool server_local_player_body_in_water(struct server_local* s) {
	return server_local_player_body_in_water_for(s, &s->player);
}

/* Beta decrements air while the eye is inside water and restores max air
 * otherwise [McBetaCpp srcorigjava Entity.java:586-601 and
 * EntityLiving.java:115-134; corroborated by the modified, decompile-grounded
 * mcp_spout Beta 1.7.3 tree at 790e9eff]. Like the existing host path, this is
 * an eye-cell approximation: fluid surface height/metadata remains deferred. */
static bool server_local_player_head_in_water_for(
	struct server_local* s, const struct server_player* player) {
	assert(s && player);
	/* A1a (D8): the actor's committed live world; none -> no hazard read. */
	struct server_world* w = server_local_world_of(s, player);
	if(!w)
		return false;
	struct block_data eye;
	return server_world_get_block(w,
		(w_coord_t)floor(player->x), (w_coord_t)floor(player->y),
		(w_coord_t)floor(player->z), &eye)
		&& (eye.type == BLOCK_WATER_STILL || eye.type == BLOCK_WATER_FLOW);
}

bool server_local_player_on_ladder_for(
	struct server_local* s, const struct server_player* player) {
	assert(s && player);
	/* A1a (D8): the actor's committed live world; none -> no hazard read. */
	struct server_world* w = server_local_world_of(s, player);
	if(!w)
		return false;
	struct block_data feet;
	return server_world_get_block(w,
		(w_coord_t)floor(player->x),
		(w_coord_t)floor(player->y - PLAYER_EYE_HEIGHT),
		(w_coord_t)floor(player->z), &feet)
		&& feet.type == BLOCK_LADDER;
}

/* Beta Entity.handleLavaMovement probes
 * boundingBox.expand(-0.10000000149011612,-0.4000000059604645,
 * -0.10000000149011612), then World.isMaterialInBB returns true for any lava
 * material cell in the resulting box. Unlike water acceleration, this has no
 * chunk-residency preflight, fluid-surface test, metadata rule, or .001
 * contract. Reconstruct the player's float-sized 0.6x1.8 box from the eye. */
static enum server_world_scan server_local_player_body_lava_scan_for(
	struct server_local* s, const struct server_player* player) {
	assert(s && player);
	/* A1a (D8): the actor's committed live world; none -> no hazard read. */
	struct server_world* w = server_local_world_of(s, player);
	if(!w)
		return SERVER_WORLD_SCAN_UNKNOWN;
	const double inset_xz = (double)0.1F;
	const double inset_y = (double)0.4F;
	const double half_width = (double)(0.6F / 2.0F);
	const double feet_y = player->y - (double)PLAYER_EYE_HEIGHT;
	return server_world_aabb_lava_scan(w,
		player->x - half_width + inset_xz,
		feet_y + inset_y,
		player->z - half_width + inset_xz,
		player->x + half_width - inset_xz,
		feet_y + (double)PLAYER_BODY_HEIGHT - inset_y,
		player->z + half_width - inset_xz);
}

/* The bool view (test hooks, characterization): a missing column reads as
 * no lava -- server_world_aabb_has_lava's answer, unchanged. Production
 * hazard sensing uses the tri-state scan above. */
static bool server_local_player_body_in_lava_for(
	struct server_local* s, const struct server_player* player) {
	return server_local_player_body_lava_scan_for(s, player)
		== SERVER_WORLD_SCAN_PRESENT;
}

/* Beta Entity.moveEntity's post-move BLOCK-CONTACT sweep. After the move
 * resolves, Beta walks every cell the (slightly contracted) entity box
 * overlaps and calls Block.onEntityCollidedWithBlock on it:
 *
 *   int i1 = floor(boundingBox.minX + 0.001D);  int k3 = floor(boundingBox.maxX - 0.001D);
 *   int k1 = floor(boundingBox.minY + 0.001D);  int l3 = floor(boundingBox.maxY - 0.001D);
 *   int i2 = floor(boundingBox.minZ + 0.001D);  int i4 = floor(boundingBox.maxZ - 0.001D);
 *   if(worldObj.checkChunksExist(i1, k1, i2, k3, l3, i4))
 *     for(j4 = i1; j4 <= k3; j4++) for(k4 = k1; k4 <= l3; k4++) for(l4 = i2; l4 <= i4; l4++)
 *       ... onEntityCollidedWithBlock(worldObj, j4, k4, l4, this);
 *
 * [740c583: Entity.moveEntity, the block-contact tail]. The bounds are
 * floor(min + .001) .. floor(max - .001) INCLUSIVE on every axis --
 * deliberately NOT the
 * floor(min)..floor(max + 1) EXCLUSIVE idiom World.isMaterialInBB /
 * isBoundingBoxBurning use (the fluid helpers above), and NOT a point sample.
 *
 * BlockCactus.onEntityCollidedWithBlock is a bare attackEntityFrom(null, 1)
 * [740c583: BlockCactus.onEntityCollidedWithBlock], so SIDE contact hurts: the
 * cactus collision box is inset 1/16 on X/Z, so a body pressed flush against a
 * cactus reaches 0.0625 into the cactus's OWN cell and this contracted sweep
 * still floors into it. The replaced eye-cell/feet-cell point sample could
 * never observe that -- cactus is solid, so the player is never "inside" one --
 * which is why walking into a cactus did nothing (maintainer observation,
 * real Wii far_walk autopilot, 2026-09-07). Standing on top works for the same
 * reason once the collision box carries Beta's top inset (block_cactus.c).
 *
 * The server player position is the EYE, so reconstruct the exact 0.6 x 1.8
 * body box the client collided with, the same way the fluid helpers above do.
 * This is the player-side twin of entity_monster_post_move_cactus_collisions,
 * which already runs this exact sweep for mobs; the two stay in step by
 * mirroring the same six bound expressions rather than by sharing a callee
 * (the entity/player position conventions differ -- feet origin vs eye). */
static bool server_local_player_cactus_contact_for(
	struct server_local* s, const struct server_player* player) {
	assert(s && player);
	/* A1a (D8): the actor's committed live world; none -> no hazard read. */
	struct server_world* w = server_local_world_of(s, player);
	if(!w)
		return false;
	const double epsilon = 0.001;
	const double half_width = (double)(0.6F / 2.0F);
	const double feet_y = player->y - (double)PLAYER_EYE_HEIGHT;
	const w_coord_t x0 = (w_coord_t)floor(player->x - half_width + epsilon);
	const w_coord_t x1 = (w_coord_t)floor(player->x + half_width - epsilon);
	const w_coord_t y0 = (w_coord_t)floor(feet_y + epsilon);
	const w_coord_t y1
		= (w_coord_t)floor(feet_y + (double)PLAYER_BODY_HEIGHT - epsilon);
	const w_coord_t z0 = (w_coord_t)floor(player->z - half_width + epsilon);
	const w_coord_t z1 = (w_coord_t)floor(player->z + half_width - epsilon);
	if(y1 < 0 || y0 >= WORLD_HEIGHT)
		return false;

	/* Beta World.checkChunksExist gates the WHOLE sweep: an unresolved column
	 * skips every cell rather than half-scanning. Fail closed, exactly like
	 * the water helper above -- a hazard is never inferred from a missing read. */
	for(w_coord_t x = x0; x <= x1; x++)
		for(w_coord_t z = z0; z <= z1; z++)
			if(!server_world_is_chunk_loaded(w,
											 WCOORD_CHUNK_OFFSET(x),
											 WCOORD_CHUNK_OFFSET(z)))
				return false;

	for(w_coord_t x = x0; x <= x1; x++)
		for(w_coord_t y = y0; y <= y1; y++)
			for(w_coord_t z = z0; z <= z1; z++) {
				struct block_data block;
				if(server_world_get_block(w, x, y, z, &block)
				   && block.type == BLOCK_CACTUS)
					return true;
			}
	return false;
}

static bool server_local_player_cactus_contact(struct server_local* s) {
	return server_local_player_cactus_contact_for(s, &s->player);
}

static void server_local_apply_actor_cactus(
	struct server_local* s, struct server_player* player) {
	if(server_local_player_cactus_contact_for(s, player))
		(void)server_local_damage_actor_cause(s, player,
			HEALTH_PER_HEART / 2, 0.0f, 0.0f, NULL, PLAYER_DAMAGE_CACTUS);
}

/* Beta fire CONTACT damage is NOT a Block.onEntityCollidedWithBlock hook --
 * BlockFire overrides getCollisionBoundingBoxFromPool (returns null) but never
 * onEntityCollidedWithBlock, so it inherits Block's empty one. The real site is
 * the tail of Entity.moveEntity:
 *
 *   if(worldObj.isBoundingBoxBurning(boundingBox.func_28195_e(0.001D, 0.001D, 0.001D)))
 *   { dealFireDamage(1); if(!isWet()) { fire++; if(fire == 0) fire = 300; } }
 *
 * [740c583: Entity.moveEntity's burning tail; World.isBoundingBoxBurning].
 * func_28195_e is AxisAlignedBB.contract, and isBoundingBoxBurning scans
 * floor(min) .. floor(max + 1.0) EXCLUSIVE -- a genuinely different bound
 * idiom from the cactus sweep above, so the two do NOT share a loop.
 *
 * Beta's burning box includes fire and both lava ids. The separate, earlier
 * handleLavaMovement probe delivers lava's 4-point hit; this contracted box
 * delivers moveEntity's later 1-point hit through the same hurt gate.
 * [mcb173-retromcp: Entity.java:218-237,480-490; World.java:1395-1415]. */
static bool server_local_player_fire_contact_for(
	struct server_local* s, const struct server_player* player) {
	assert(s && player);
	/* A1a (D8): the actor's committed live world; none -> no hazard read. */
	struct server_world* w = server_local_world_of(s, player);
	if(!w)
		return false;
	const double epsilon = 0.001;
	const double half_width = (double)(0.6F / 2.0F);
	const double feet_y = player->y - (double)PLAYER_EYE_HEIGHT;
	const double min_x = player->x - half_width + epsilon;
	const double max_x = player->x + half_width - epsilon;
	const double min_y = feet_y + epsilon;
	const double max_y = feet_y + (double)PLAYER_BODY_HEIGHT - epsilon;
	const double min_z = player->z - half_width + epsilon;
	const double max_z = player->z + half_width - epsilon;
	const w_coord_t x0 = (w_coord_t)floor(min_x);
	const w_coord_t x1 = (w_coord_t)floor(max_x + 1.0);
	const w_coord_t y0 = (w_coord_t)floor(min_y);
	const w_coord_t y1 = (w_coord_t)floor(max_y + 1.0);
	const w_coord_t z0 = (w_coord_t)floor(min_z);
	const w_coord_t z1 = (w_coord_t)floor(max_z + 1.0);
	if(y1 < 0 || y0 >= WORLD_HEIGHT)
		return false;

	/* World.isBoundingBoxBurning's own checkChunksExist preflight -- and it is
	 * NOT the same range as the block scan below. Beta hands checkChunksExist
	 * the very bounds it then uses EXCLUSIVELY for the cells:
	 *
	 *   int j  = floor(maxX + 1.0);  int j1 = floor(maxZ + 1.0);
	 *   if(checkChunksExist(i, k, i1, j, l, j1)) for(k1 = i; k1 < j; k1++) ...
	 *
	 * and checkChunksExist shifts every argument >> 4 and iterates
	 * `for(k1 = i; k1 <= l; k1++) for(l1 = k; l1 <= j1; l1++)` -- INCLUSIVE of
	 * the +1 bound's own chunk [740c583: World.isBoundingBoxBurning:1590-1598;
	 * World.checkChunksExist:335-351]. So a box whose maxX+1 falls in the NEXT
	 * chunk requires that chunk to exist even though no cell in it is ever
	 * read: on a chunk seam Beta bails where a block-range preflight would
	 * happily proceed. Mirror the CHUNK range, not the block range, or the C
	 * under-checks at exactly that seam. (The cactus sweep's own preflight is
	 * block-ranged and correct there, because its bounds are inclusive cell
	 * indices -- floor(max - .001) -- so their chunks already cover Beta's
	 * inclusive chunk span exactly.) */
	const w_coord_t cx0 = WCOORD_CHUNK_OFFSET(x0);
	const w_coord_t cx1 = WCOORD_CHUNK_OFFSET(x1);
	const w_coord_t cz0 = WCOORD_CHUNK_OFFSET(z0);
	const w_coord_t cz1 = WCOORD_CHUNK_OFFSET(z1);
	for(w_coord_t cx = cx0; cx <= cx1; cx++)
		for(w_coord_t cz = cz0; cz <= cz1; cz++)
			if(!server_world_is_chunk_loaded(w, cx, cz))
				return false;

	for(w_coord_t x = x0; x < x1; x++)
		for(w_coord_t y = y0; y < y1; y++)
			for(w_coord_t z = z0; z < z1; z++) {
				struct block_data block;
				if(server_world_get_block(w, x, y, z, &block)
				   && (block.type == BLOCK_FIRE
					   || block.type == BLOCK_LAVA_FLOW
					   || block.type == BLOCK_LAVA_STILL))
					return true;
			}
	return false;
}

#ifdef CAVEWII_SERVER_LOCAL_TEST
void server_local_test_player_block_contact(struct server_local* s,
											bool* in_cactus, bool* in_fire) {
	if(in_cactus)
		*in_cactus = server_local_player_cactus_contact(s);
	if(in_fire)
		*in_fire = server_local_player_fire_contact_for(s, &s->player);
}
#endif

// Consume every client physics sample at RPC time. The server can be several
// frames behind the 50 ms position stream on Wii; waiting until the end of its
// tick observes only the final grounded sample and loses the landing edge.
/* `ev` (v4): the sample's movement event. With one, a damaging landing is
 * DEFERRED into it -- handleFalling's damage runs at the replay, after the
 * packet's physics and the world's entity hits (NetServerHandler.java:154,
 * 173, 211-213; ASTRA-V3-REVIEW P1 damage ordering); the accounting
 * (fallDistance) still runs here, on every sample, so no landing edge is
 * lost. Without one (the direct accounting entry) the landing is billed
 * at once through the same server_local_actor_apply_fall. */
static bool server_local_player_vertical_sample_ev(struct server_local* s,
	struct server_player* player, double previous_y, float new_vel_y,
	bool new_on_ground, struct actor_motion_event* ev) {
	assert(s && player);
	float previous_vel_y = player->vel_y;
	player->old_vel_y = previous_vel_y;
	player->vel_y = new_vel_y;
	double merged_ground_drop = previous_y - player->y;
	/* PLAYER_POS carries the client's resolved collision result. Beta keys
	 * updateFallState to onGround, never a velocity cutoff: lava drag or an
	 * impulse can cross any cutoff while still airborne. The sole reconstruction
	 * exception is two grounded endpoints separated by >3 blocks with no scalar,
	 * which means the bounded transport dropped every airborne sample. */
	bool merged_landing = player->on_ground && new_on_ground
		&& player->fall_distance == 0.0F && merged_ground_drop > 3.0;
	if(!new_on_ground && merged_ground_drop <= 0.0
	   && player->fall_distance == 0.0F)
		return true;

	const w_coord_t bx = (w_coord_t)floor(player->x);
	const w_coord_t bz = (w_coord_t)floor(player->z);
	const w_coord_t fy
		= (w_coord_t)floor(player->y - PLAYER_EYE_HEIGHT);
	/* A1a (D8): the actor's committed live world; none -> no hazard read. */
	struct server_world* w = server_local_world_of(s, player);
	if(!w)
		return true;
	struct block_data feet;
	bool have_feet = server_world_get_block(w, bx, fy, bz, &feet);
	bool in_water = server_local_player_body_in_water_for(s, player);
	bool on_ladder = have_feet && feet.type == BLOCK_LADDER;
	if(in_water || on_ladder) {
		// Beta clears fallDistance every wet/ladder tick.
		player->fall_distance = 0.0F;
		return true;
	}

	/* Beta adds resolved downward displacement only while airborne. On a grounded
	 * collision call it bills the existing scalar before clearing it; the final
	 * clipped movement is not accumulated. Only the explicit merged-packet case
	 * reconstructs a missing scalar from grounded endpoints. */
	if(!new_on_ground && merged_ground_drop > 0.0)
		/* Java evaluates float fallDistance - double resolvedY in double and
		 * casts once on assignment. Rounding the displacement first can cross a
		 * later ceil(fallDistance-3) damage boundary. */
		player->fall_distance = (float)(
			(double)player->fall_distance + merged_ground_drop);
	else if(merged_landing)
		player->fall_distance = (float)merged_ground_drop;

	if(new_on_ground) {
		int fall_dmg
			= player_fall_damage_hp(player->fall_distance, false);
		/* A damaging landing clears the accumulator now (the sample is
		 * accounted); the hit itself is EntityLiving.fall at the replay. */
		player->fall_distance = 0.0F;
		if(ev) {
			if(fall_dmg > 0) {
				ev->fall_damage = (int16_t)fall_dmg;
				ev->land_x = player->x;
				ev->land_y = player->y;
				ev->land_z = player->z;
			}
			return true;
		}
		return server_local_actor_apply_fall(s, player, fall_dmg, player->x,
											 player->y, player->z);
	}
	return true;
}

bool server_local_player_vertical_sample_for(struct server_local* s,
	struct server_player* player, double previous_y, float new_vel_y,
	bool new_on_ground) {
	return server_local_player_vertical_sample_ev(s, player, previous_y,
		new_vel_y, new_on_ground, NULL);
}

bool server_local_player_vertical_sample_actor(struct server_local* s,
	struct server_player* player, double previous_y, float new_vel_y,
	bool new_on_ground) {
	return server_local_player_vertical_sample_ev(s, player, previous_y,
		new_vel_y, new_on_ground, server_local_actor_motion_last(player));
}

static bool server_local_player_vertical_sample(struct server_local* s,
	double previous_y, float new_vel_y, bool new_on_ground) {
	return server_local_player_vertical_sample_ev(s, &s->player, previous_y,
		new_vel_y, new_on_ground, server_local_actor_motion_last(&s->player));
}

// Beta World.onBlockHit offsets the clicked support block by the hit face and
// extinguishes fire there before block-removal progress begins. BlockFire is
// deliberately non-collidable in Beta, so the ray targets the support block;
// making fire itself selectable would be the wrong fix.
static void server_local_extinguish_fire_on_hit(
	struct server_local* s, const struct server_rpc* call) {
	enum side side = call->payload.block_dig.side;
	if(side < 0 || side >= SIDE_MAX)
		return;
	int dx, dy, dz;
	blocks_side_offset(side, &dx, &dy, &dz);
	w_coord_t x = call->payload.block_dig.x + dx;
	w_coord_t y = call->payload.block_dig.y + dy;
	w_coord_t z = call->payload.block_dig.z + dz;
	struct block_data adjacent;
	if(server_world_get_block(block_world(s), x, y, z, &adjacent)
	   && adjacent.type == BLOCK_FIRE) {
		// Beta World.func_28096_a:1210-1213 sends aux 1004 BEFORE removal.
		// RenderGlobal:1379-1380: fizz 0.5, 2.6+(r1-r2)*0.8 at fire center.
		// Sequence the cosmetic draws explicitly; never advance s->rand_src.
		// Routed to the actor's world (integ-1008 merge: keep L217 routing).
		struct random_gen* g = server_local_sound_rng();
		const float first = rand_gen_flt(g);
		const float second = rand_gen_flt(g);
		server_local_emit_sound_w(block_world(s), SOUND_RANDOM_FIZZ,
			(vec3) {x + 0.5F, y + 0.5F, z + 0.5F}, 0.5F,
			2.6F + (first - second) * 0.8F);
		server_world_set_block(
			block_world(s), x, y, z, (struct block_data) {.type = BLOCK_AIR});
	}
}

static bool server_rpc_blocked_while_sleeping(enum server_rpc_type type) {
	switch(type) {
		case SRPC_PLAYER_POS:
		case SRPC_PLAYER_STATE:
		case SRPC_ENTITY_ATTACK:
		case SRPC_ENTITY_USE:
		case SRPC_HOTBAR_SLOT:
		case SRPC_BLOCK_PLACE:
		case SRPC_BLOCK_DIG:
		case SRPC_WINDOW_CLICK:
		case SRPC_SIGN_SET:
		case SRPC_USE_ITEM:
		case SRPC_WINDOW_DROP:
		case SRPC_DROP_ITEM: return true;
		/* Ride intent is NOT blocked while sleeping: the handler validates
		 * the correlation pair and, when sleeping, publishes unchanged
		 * authority with the request's exact epoch/seq without mutating
		 * occupancy. This prevents a queued intent from being silently
		 * dropped during the sleep window, which would leave the client
		 * pending forever. */
		case SRPC_MINECART_RIDE_INTENT: return false;
		default: return false;
	}
}

/* Deviation-#18 death-screen dwell: crosshair-authored actions from the dead
 * body drain without executing. Beta swallows them structurally -- the moment
 * GuiGameOver substitutes in, runTick pushes leftClickCounter/mouseTicksRan
 * 10000 ticks out and routes every input event into the screen [740c583
 * Minecraft.runTick:972-996] -- so an action RPC that raced the death
 * broadcast is the wire-latency image of a click Beta would have eaten.
 * Deliberately NARROWER than the sleep set: PLAYER_POS/STATE stay accepted
 * (the corpse keeps real client physics; position is not "input"), and the
 * WINDOW_* family stays accepted -- Beta's trigger requires currentScreen ==
 * null, so a container/inventory screen open at death STAYS open and its
 * clicks keep working over the dead player (the container-open dwell). Ride
 * intent keeps its publish-unchanged-authority contract like sleep, enforced
 * inside its handler. */
static bool server_rpc_blocked_while_dead(enum server_rpc_type type) {
	switch(type) {
		case SRPC_ENTITY_ATTACK:
		case SRPC_ENTITY_USE:
		case SRPC_HOTBAR_SLOT:
		case SRPC_BLOCK_PLACE:
		case SRPC_BLOCK_DIG:
		case SRPC_USE_ITEM:
		case SRPC_DROP_ITEM: return true;
		default: return false;
	}
}

static bool server_rpc_blocked_while_host_respawning(
	enum server_rpc_type type) {
	switch(type) {
		case SRPC_PLAYER_POS:
		case SRPC_PLAYER_STATE:
		case SRPC_HOTBAR_SLOT:
		case SRPC_BLOCK_PLACE:
		case SRPC_BLOCK_DIG:
		case SRPC_WINDOW_CLICK:
		case SRPC_SIGN_SET:
		case SRPC_WINDOW_CLOSE:
		case SRPC_WINDOW_DROP:
		case SRPC_WINDOW_TRANSACTION:
		case SRPC_WINDOW_SORT_ADMIT:
		case SRPC_ENTITY_ATTACK:
		case SRPC_ENTITY_USE:
		case SRPC_USE_ITEM:
		case SRPC_DROP_ITEM:
		case SRPC_CREATIVE_GIVE:
		case SRPC_TOGGLE_PAUSE: return true;
		default: return false;
	}
}

/* Consume one cumulative minecart-control snapshot. Structural acceptance is
 * intentionally separate from gameplay acceptance: a valid same-epoch tuple
 * advances the server counters even while a GUI/sleep/loading/reach barrier
 * discards its impulse, so it can never replay after the barrier clears. */
static void server_local_process_minecart_control(
	struct server_local* s, const struct server_rpc* call,
	bool gameplay_allowed) {
	assert(s && call && call->type == SRPC_MINECART_CONTROL);
	const uint32_t id = call->payload.minecart_control.entity_id;
	struct entity** pp = dict_entity_get(s->entities, id);
	struct entity* cart = pp ? *pp : NULL;
	if(!cart || cart->type != ENTITY_MINECART)
		return;

	const uint32_t epoch = call->payload.minecart_control.ride_epoch;
	if(epoch == 0 || cart->data.minecart.ride_epoch == 0
	   || epoch != cart->data.minecart.ride_epoch) {
		/* Never rotate toward an untrusted epoch. Echo the current authority so
		 * a delayed old ride or an optimistic pre-mount sender converges. */
		entity_minecart_mark_snapshot_dirty(cart, true);
		return;
	}

	const uint32_t input_seq = call->payload.minecart_control.input_seq;
	const uint32_t positive
		= call->payload.minecart_control.positive_steps;
	const uint32_t negative
		= call->payload.minecart_control.negative_steps;
	const uint32_t dseq = input_seq - cart->data.minecart.control_seq;
	const uint32_t dpos
		= positive - cart->data.minecart.control_positive_steps;
	const uint32_t dneg
		= negative - cart->data.minecart.control_negative_steps;

	if(dseq == 0 && dpos == 0 && dneg == 0)
		return; /* exact retry of an already accepted tuple */
	if(dseq >= UINT32_C(0x80000000)) {
		/* Modularly older (or exactly half-range ambiguous): ignore rather than
		 * allowing delayed state to rewind the accepted counters. */
		entity_minecart_mark_snapshot_dirty(cart, true);
		return;
	}
	if(dseq > MINECART_CONTROL_MAX_GAP || dpos > dseq || dneg > dseq
	   || (uint64_t)dpos + (uint64_t)dneg != (uint64_t)dseq) {
		/* Same-epoch corruption or a forward gap outside the bounded recovery
		 * window. Rotate instead of fabricating an impulse from missing history. */
		server_rotate_minecart_epoch(s, cart);
		return;
	}

	/* Structurally valid: terminally observe it before any gameplay gate. */
	cart->data.minecart.control_seq = input_seq;
	cart->data.minecart.control_positive_steps = positive;
	cart->data.minecart.control_negative_steps = negative;

	bool apply = gameplay_allowed
		&& s->player.active_inventory == &s->player.inventory
		&& cart->data.minecart.occupied
		&& cart->data.minecart.occupant_id
			== SERVER_LOCAL_PLAYER_ENTITY_ID;
	if(apply) {
		float dx = (float)(cart->pos[0] - s->player.x);
		float dy = (float)(cart->pos[1]
						 - (s->player.y - PLAYER_EYE_HEIGHT));
		float dz = (float)(cart->pos[2] - s->player.z);
		apply = dx * dx + dy * dy + dz * dz < 36.0F;
	}
	if(!apply) {
		entity_minecart_mark_snapshot_dirty(cart, true);
		return;
	}

	int64_t accumulated = (int64_t)cart->data.minecart.pending_throttle
		+ (int64_t)(int32_t)dpos - (int64_t)(int32_t)dneg;
	if(accumulated > INT32_MAX)
		accumulated = INT32_MAX;
	else if(accumulated < INT32_MIN)
		accumulated = INT32_MIN;
	cart->data.minecart.pending_throttle = (int32_t)accumulated;
}

// Adversarial-review finding #10: Beta NetServerHandler.func_6006_a gates entity
// interact/attack on `playerEntity.canEntityBeSeen(target) && distSq<36.0`, not
// distance alone [740c583: EntityLiving.canEntityBeSeen]. canEntityBeSeen rays from
// the PLAYER's eye (posY includes it already -- s->player.y is this engine's
// eye-basis player Y, the established convention every reach check here already
// uses) to the TARGET's own position + its getEyeHeight(); neither EntityBoat nor
// EntityMinecart override getEyeHeight() (confirmed via decompile: both fall through
// to Entity's default 0.0F), so the target endpoint is simply its raw pos, no offset.
// Reuses mob AI's identical predicate (entity_monster.c::mob_los_cell_opaque, now
// exported) rather than a second copy of the Beta occlusion rule (CODESTYLE.md §3.2).
// ONE server-side authority gate for every entity-targeted client request --
// SRPC_ENTITY_ATTACK, SRPC_ENTITY_USE, and the ride-intent MOUNT leg (GB-06,
// docs/audit_2026-08-14_game_breakage.md). [740c583: NetServerHandler.java:
// 477-488, func_6006_a]:
//     if (var3 != null && this.playerEntity.canEntityBeSeen(var3)
//         && this.playerEntity.getDistanceSqToEntity(var3) < 36.0D) { ... }
// Beta applies the SAME conjunction to use (isLeftClick==0) and attack (==1);
// a request that fails it is dropped BEFORE any target/inventory mutation, so
// callers may rely on reject == ZERO state change (and no RNG draws).
//
// Distance: strict < 36.0 (6 blocks), FEET-to-feet Y basis -- the engine's
// canonical documented deviation from Beta's raw-posY read (the player's posY
// IS the eye line, EntityPlayer.yOffset=1.62F); see the Y-BASIS DEVIATION
// note in entity_monster.c. s->player.y is the network EYE, so it drops by
// PLAYER_EYE_HEIGHT exactly like every other gate in the engine.
//
// LOS: canEntityBeSeen [740c583: EntityLiving.java:73-75] -- an eye-to-eye
// rayTraceBlocks. Target eye = posY + getEyeHeight(): height*0.85F for
// living targets (EntityLiving.java:89 == mob_eye_height()) and 0.0F for
// everything else (Entity.java:603 -- minecart/boat/fireball). The player
// end uses the network eye pos RAW -- the same engine-wide convention as the
// mob-AI canEntityBeSeen port (entity_monster.c) and the boat gate this
// generalizes; Beta adds EntityPlayer.getEyeHeight()=0.12F on top of the eye
// line (EntityPlayer.java:349), a sub-block delta shared by every LOS port
// in the engine.
//
// Evaluation order: distance FIRST, then LOS. Beta short-circuits
// canEntityBeSeen first, but both legs are pure so the conjunction is
// order-invariant; distance-first honors los.h's caller contract (the DDA
// step cap is only safe on a distance-gated segment) and skips the raycast
// on the common far miss.
static bool server_local_entity_interaction_allowed(struct server_local* s,
															 const struct server_player* player,
													 const struct entity* target) {
	assert(s && target);
	struct server_world* w = server_local_world_of(s, player);
	if(!w || server_local_entity_world(s, target) != w)
		return false;
	float dx = (float)(target->pos[0] - player->x);
	float dy = (float)(target->pos[1] - (player->y - PLAYER_EYE_HEIGHT));
	float dz = (float)(target->pos[2] - player->z);
	if(dx * dx + dy * dy + dz * dz >= 36.0F)
		return false;
	float target_eye = target->type == ENTITY_MONSTER
		? mob_eye_height(target->data.monster.id)
		: 0.0F;
	return !los_segment_blocked(
		(float)player->x, (float)player->y, (float)player->z,
		target->pos[0], target->pos[1] + target_eye, target->pos[2],
		mob_los_cell_opaque, w);
}

/* Server-thread entry point bound by the local provider to its actual actor.
 * No player ID from an RPC payload is used to select ownership. These guards
 * also apply when a provider calls this directly rather than the legacy switch. */
/* [740c583 server NetServerHandler.java:498-526; EntityPlayerMP:323-325]
 * Compare slotClick's return AFTER executing it. Rejection does not roll back:
 * ACK(false), all post-mutation slots, cursor, then wait for matching response. */
static void server_local_correct_window(struct inventory* inv, uint8_t window) {
	struct client_rpc correction = {.type = CRPC_WINDOW_ITEMS,
		.payload.window_items = {.window = window, .count = inv->capacity}};
	assert(inv->capacity <= CRPC_WINDOW_ITEMS_MAX_SLOTS);
	for(size_t k = 0; k < inv->capacity; k++)
		correction.payload.window_items.items[k] = inv->items[k];
	server_local_window_reply(inv, &correction);
	server_local_window_reply(inv, &(struct client_rpc) {
		.type = CRPC_INVENTORY_SLOT,
		.payload.inventory_slot = {.window = window,
			.slot = SPECIAL_SLOT_PICKED_ITEM, .item = inv->picked_item},
	});
}

static void server_local_finish_window_click(struct inventory* inv, uint8_t window,
	uint16_t action, struct item_data returned, struct item_data expected, bool valid) {
	bool accept = valid && returned.id == expected.id
		&& (!returned.id || (returned.count == expected.count
			&& returned.durability == expected.durability));
	if(!accept) {
		inv->transaction_pending = true;
		inv->transaction_action = action;
	}
	server_local_window_reply(inv, &(struct client_rpc) {
		.type = CRPC_WINDOW_TRANSACTION,
		.payload.window_transaction = {.window = window, .action_id = action,
			.accepted = accept},
	});
	if(!accept) server_local_correct_window(inv, window);
}
void server_local_process_window_for(struct server_local* s,
	struct server_player* player, const struct server_rpc* call) {
	if(!server_local_window_actor_valid(s, player) || !call
	   || !player->active_inventory
	   || player->active_inventory->capacity > CRPC_WINDOW_ITEMS_MAX_SLOTS
	   || (player->active_inventory->owner && player->active_inventory->owner != player))
		return;
	bool recovery_close = s->stream_recovery_epoch != 0
		&& call->type == SRPC_WINDOW_CLOSE;
	if(!recovery_close
		   && (s->world_switch_phase != SERVER_WORLD_SWITCH_IDLE
			   || s->death_world_evict
			   || (player == &s->player && s->a2w_host_presentation)
			   || server_transfer_actor_inert(s, player)
			   || (s->input_ack_pending != 0
				   && !(player == s->guest_actor
					&& server_transfer_guest_continuity(s)))
		   || (player->has_pos && !player->finished_loading)))
		return;
	if(!recovery_close
	   && ((player->sleeping && server_rpc_blocked_while_sleeping(call->type))
		   || (player->health <= 0 && server_rpc_blocked_while_dead(call->type))))
		return;
	switch(call->type) {
		case SRPC_WINDOW_TRANSACTION: {
			struct inventory* inv = player->active_inventory;
			if(inv->transaction_pending
			   && server_local_active_window_id(player) == call->payload.window_transaction.window
			   && inv->transaction_action == call->payload.window_transaction.action_id)
				inv->transaction_pending = false;
			break;
		}
		case SRPC_WINDOW_SORT_ADMIT: {
			struct inventory* inv = player->active_inventory;
			bool admitted = player->has_pos && player->finished_loading
				&& inv->owner == player && !inv->invalidated && !inv->transaction_pending
				&& !inventory_get_picked_item(inv, NULL)
				&& server_local_active_window_id(player) == call->payload.window_sort.window
				&& (!call->payload.window_sort.chest || inventory_chest_sort_admitted(inv));
			server_local_window_reply(inv, &(struct client_rpc){.type = CRPC_WINDOW_SORT_ADMIT,
				.payload.window_sort = {.window = call->payload.window_sort.window,
					.ticket = call->payload.window_sort.ticket, .accepted = admitted}});
			break;
		}
		case SRPC_WINDOW_CLICK: {
			struct inventory* inv = player->active_inventory;
			if(!player->has_pos || !player->finished_loading || inv->transaction_pending
			   || server_local_active_window_id(player) != call->payload.window_click.window)
				break;
			set_inv_slot_t changes;
			set_inv_slot_init(changes);
			bool valid = !inv->invalidated && inventory_slot_valid(inv, call->payload.window_click.slot);
			/* Admission is checked again at every local sort click so an opener
			 * queued after the grant cannot race the exclusive-viewer rule. */
			if(call->payload.window_click.sort_chest)
				valid &= inv->owner == player && inventory_chest_sort_admitted(inv);
			/* The port's synthetic sign-character window is not a Beta item
			 * container. Preserve its existing edit ACK/echo contract, shared
			 * with SRPC_SIGN_SET, without installing an item transaction gate. */
			if(inv->logic == &inventory_logic_sign) {
				bool accepted = valid && inventory_action(inv, player,
					call->payload.window_click.slot, call->payload.window_click.right_click, changes);
				server_local_window_reply(inv, &(struct client_rpc) {
					.type = CRPC_WINDOW_TRANSACTION,
					.payload.window_transaction = {.window = call->payload.window_click.window,
						.action_id = call->payload.window_click.action_id, .accepted = accepted},
				});
				server_local_send_inv_changes(changes, inv, call->payload.window_click.window);
				set_inv_slot_clear(changes);
				break;
			}
			/* C2 tiles (Fable A-H1/A-M1): a shared tile window (furnace /
			 * dispenser) is refreshed from its backing TE BEFORE the pre-click
			 * stack is captured and before EITHER branch -- Quick Move never
			 * runs pre_action. The transaction is then judged against the TRUE
			 * pre-click stack, as Beta's NetServerHandler compares against the
			 * server's own slot, and no stale copy can be written back. The
			 * refreshed slots ride the ordinary correction path on a refusal. */
			if(valid) {
				if(inv->logic == &inventory_logic_furnace)
					(void)inventory_furnace_refresh_window(inv, changes);
				else if(inv->logic == &inventory_logic_dispenser)
					(void)inventory_dispenser_refresh_window(inv, changes);
			}
			struct item_data returned = {0};
			if(valid) {
				if(call->payload.window_click.quick_move)
					returned = inventory_quick_move(inv, player,
						call->payload.window_click.slot, changes);
				else {
					returned = inv->items[call->payload.window_click.slot];
					inventory_action(inv, player, call->payload.window_click.slot,
						call->payload.window_click.right_click, changes);
				}
			}
			server_local_finish_window_click(inv, call->payload.window_click.window,
				call->payload.window_click.action_id, returned,
				call->payload.window_click.expected, valid);
			/* [740c583 server NetServerHandler:502-506, EntityPlayerMP:339-342]:
			 * accepted clicks suppress even the cursor packet. Independent map
			 * counters can diverge; the server's identity is the saved authority.
			 * Do not add a map-specific correction to this vanilla wire path. */
			/* Successful ordinary echoes are suppressed for the actor. Backing
			 * writes and other chest viewers were updated by post_action. */
			set_inv_slot_clear(changes);
			break;
		}
		case SRPC_SIGN_SET: {
			if(!player->has_pos || !player->finished_loading)
				break;
			set_inv_slot_t changes;
			set_inv_slot_init(changes);

			bool window_matches = server_local_active_window_id(player)
				== call->payload.sign_set.window;
			bool accept = window_matches
				&& !player->active_inventory->invalidated
				&& player->active_inventory->logic == &inventory_logic_sign
				&& call->payload.sign_set.slot < SIGN_SIZE
				&& call->payload.sign_set.ch >= ' '
				&& call->payload.sign_set.ch <= '~'
				&& inventory_sign_set_char(
					player->active_inventory, call->payload.sign_set.slot,
					call->payload.sign_set.ch, changes);

			server_local_window_reply(player->active_inventory, &(struct client_rpc) {
				.type = CRPC_WINDOW_TRANSACTION,
				.payload.window_transaction.accepted = accept,
				.payload.window_transaction.action_id
				= call->payload.sign_set.action_id,
				.payload.window_transaction.window
				= call->payload.sign_set.window,
			});

			if(window_matches)
				server_local_send_inv_changes(changes, player->active_inventory,
										  call->payload.sign_set.window);
			set_inv_slot_clear(changes);
			break;
		}
		case SRPC_WINDOW_CLOSE: {
			if(!player->has_pos
			   || (!player->finished_loading
				   && s->stream_recovery_epoch == 0)
			   || server_local_active_window_id(player)
				  != call->payload.window_close.window)
				break;
			struct inventory* active = player->active_inventory;
			// Publish the stable alias before on_close: a container callback can
			// destroy/free `active` and may call back into server inventory code.
			player->active_inventory = &player->inventory;
			if(!active->logic || !active->logic->on_close
			   || !active->logic->on_close(active, player)) {
				player->active_inventory = active;
				server_local_reopen_active_inventory(player);
			} else player->active_inventory->transaction_pending = false;
			break;
		}
		case SRPC_WINDOW_DROP: {
			struct inventory* inv = player->active_inventory;
			if(!player->has_pos || !player->finished_loading || inv->transaction_pending
			   || server_local_active_window_id(player) != call->payload.window_drop.window)
				break;
			bool valid = !inv->invalidated;
			struct item_data picked;
			if(valid && inventory_get_picked_item(inv, &picked)) {
				struct item_data dropped = picked;
				if(call->payload.window_drop.right) dropped.count = 1;
				/* Retain the existing OOM ownership guarantee: allocation failure
				 * rejects/resyncs instead of deleting the cursor's items. */
				struct entity* entity
					= server_local_window_drop_spawn(s, player, &dropped);
				valid = entity != NULL;
				if(entity) {
					entity->data.item.pickup_delay = 40;
					inventory_drop_picked(inv, call->payload.window_drop.right, &dropped);
				}
			}
			server_local_finish_window_click(inv, call->payload.window_drop.window,
				call->payload.window_drop.action_id, (struct item_data){0},
				call->payload.window_drop.expected, valid);
			break;
		}
		default: break;
	}
}

static bool server_local_retry_handoff(struct server_local* s) {
	s->input_handoff_clean_ticks = 0;
	if(s->input_handoff_retry_count >= INPUT_HANDOFF_RETRY_MAX) {
		s->input_handoff_retry_count = INPUT_HANDOFF_RETRY_MAX + 1;
		s->stream_recovery_epoch = 0;
		s->load_failure_terminal = true;
		s->a2w_host_presentation = false;
		s->player.finished_loading = false;
		fprintf(stderr, "[server] input/voxel recovery exhausted after %u attempts; retaining loading barrier\n",
			INPUT_HANDOFF_RETRY_MAX);
		clin_rpc_send(&(struct client_rpc) {.type = CRPC_LOAD_FAILED});
		return false;
	}
	s->input_handoff_retry_count++;
	return true;
}

static void server_local_split_set_request(struct server_local* s,
	const struct server_rpc* call);

/* S1 gate 2 predicate. Every guard tagged `S1 gate 2:` below fails CLOSED for
 * a non-host actor, because the path it guards either leaves this file through
 * a hook whose signature carries NO actor (the block/item hooks in
 * source/block and source/item), or needs an actor IDENTITY this engine does
 * not have yet (projectile shooter, mob attacker, tame owner, vehicle rider --
 * S1-a2, Astra item 5). A guarded guest action drops silently: no mutation, no
 * reply. Never a widened semantic, never a narrowed one -- the action simply
 * does not happen for that actor. */
static bool server_local_actor_is_host(const struct server_local* s,
									   const struct server_player* player) {
	return player == &s->player;
}

/* ===== S1-a1: the seven per-actor gameplay verbs =========================
 * Each body is the verbatim switch case it was extracted from, wrapped in a
 * do/while(0) so every `break` keeps the exact statement it bound to inside
 * the switch, with `s->player` replaced by the ACTING actor. The slot-0
 * switch calls each with &s->player, so the host path is unchanged. */

/* S1-a2 (Astra gate-1 item 2): the movement STATE snapshot, per actor. The
 * body is the verbatim former switch case with `s->player` -> `player->`, and
 * the reject latch read off the ACTING actor rather than the one server-wide
 * flag -- that is the whole point of the move (a host respawn must not swallow
 * the guest's sneak edge, and a guest state change must not raise anything the
 * host reads). For &s->player it is byte-identical to the case it replaces.
 *
 * SRPC_PLAYER_STATE is state ONLY (on_ground + sneaking). Unlike
 * SRPC_PLAYER_POS it drives no odometer, fall damage, trample or portal dwell,
 * so it needs none of the host position handler's ~500 actor-specific lines --
 * which is why it can be actor-generic now while the guest POSITION path stays
 * the deliberately narrow server_local_guest_position. */
/* S1-d (mp-split-0912/68): record ONE accepted gameplay action for `player`.
 * Called from the `_for` handlers below at the point each verb has actually
 * been applied to this actor -- never on a request the owner gate, the actor
 * barrier or the handler's own precondition refused. See the
 * enum server_player_action comment in server_local_state.h for the exact
 * per-slot definition.
 *
 * The tally itself lives on the body. The mirror store is what lets the
 * MAIN-thread heartbeat read it: s->guest_actor is freed by THIS thread when
 * the guest leaves, so the emitter must never dereference it. Same publication
 * shape as anchor_near_owed/anchor_oldest -- a plain RELAXED store of a
 * monotonic counter, never control flow on either side.
 *
 * `owner == 2` (an actor that is neither the host body nor the CURRENT guest)
 * is reachable in principle -- a body mid-teardown -- and is deliberately
 * tallied on the body without a mirror store rather than asserted away. */
static void server_local_note_action(struct server_local* s,
	struct server_player* player, enum server_player_action which) {
	assert(s && player);
	assert((unsigned)which < (unsigned)SERVER_ACTION_COUNT);
	if(player->actions[which] != UINT32_MAX)
		player->actions[which]++;
	unsigned owner = player == &s->player
		? 0u
		: (player == s->guest_actor ? 1u : 2u);
	if(owner < 2u)
		__atomic_store_n(&s->actor_actions[owner][which],
						 player->actions[which], __ATOMIC_RELAXED);
}

static void server_local_process_player_state_for(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	assert(s && player && call);
	if(!player->reject_pos_this_update
	   && player->finished_loading
	   && call->payload.player_state.correction_seq
		  == player->correction_seq) {
		player->on_ground = call->payload.player_state.on_ground;
		player->sneaking = call->payload.player_state.sneaking;
	}
}

static void server_local_process_hotbar_slot_for(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	assert(s && player && call);
	do {
			if(player->has_pos
			   && call->payload.hotbar_slot.slot < INVENTORY_SIZE_HOTBAR) {
				inventory_set_hotbar(&player->inventory,
									 call->payload.hotbar_slot.slot);
				server_local_note_action(s, player, SERVER_ACTION_HOTBAR); /* S1-d */
			}
			break;
	} while(0);
}

static void server_local_process_drop_item_for(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	assert(s && player && call);
	do {
			// Beta 'Q': drop the held HOTBAR item in-world (one, or the stack on
			// Ctrl+Q). All the count + spawn + throw logic is in the factored
			// helper so the golden test can drive it directly.
			if(player->finished_loading
			   && player->active_inventory == &player->inventory
			   /* S1-d: an accepted DROP is one that actually spawned the
				* item entity -- the helper returns NULL when the held slot
				* was empty or the spawn failed, which is not an effect. */
			   && server_local_drop_hotbar_item_for(
				   s, player, call->payload.drop_item.all))
				server_local_note_action(s, player, SERVER_ACTION_DROP);
			break;
	} while(0);
}

/* critique-1028 eat: right-click with NO block target eats the held food.
 * Beta Minecraft.clickMouse :834-838 calls sendUseItem for any held stack
 * when no block place consumed the click; PlayerController.sendUseItem :47-60
 * runs ItemStack.useItemRightClick, and ItemFood.onItemRightClick :14-17 is
 * `--stackSize; heal(healAmount)` (instant, no use duration). Online the same
 * click is Packet15Place(-1,-1,-1,255,item) [PlayerControllerMP :148-153] and
 * the server routes direction 255 to item use [NetServerHandler.handlePlace
 * :291-296]. The eat itself is each food's existing onItemPlace (the same
 * hook the at-a-block path runs; none reads its block arguments), so the
 * heal amounts, the full-health refusal (playability carve-out #2) and the
 * stew->bowl return stay in ONE place. Consumption and the creative
 * no-consume restore mirror the SRPC_BLOCK_PLACE path exactly. */
static bool server_local_eat_held_for(struct server_local* s,
	struct server_player* player) {
	size_t slot = INVENTORY_SLOT_HOTBAR + inventory_get_hotbar(&player->inventory);
	struct item_data* held = &player->inventory.items[slot];
	struct item* it = item_get(held);
	if(!it || !it->onItemPlace || !item_is_food(held->id) || held->count == 0)
		return false;
	struct item_data creative_held = *held;
	struct item_data it_data = *held;
	struct item_data input = it_data;
	if(!it->onItemPlace(s, player, &it_data, NULL, NULL, SIDE_TOP))
		return false;
	if(it_data.id != input.id || it_data.durability != input.durability
	   || it_data.count != input.count)
		*held = it_data; /* stew returns the bowl */
	else
		inventory_consume(&player->inventory, slot);
	if(s->creative_mode)
		*held = creative_held;
	server_local_actor_slot_reply(player, &(struct client_rpc) {
		.type = CRPC_INVENTORY_SLOT,
		.payload.inventory_slot.window = WINDOWC_INVENTORY,
		.payload.inventory_slot.slot = slot,
		.payload.inventory_slot.item = *held,
	});
	return true;
}

/* BUCKET-WATER-OFFLINE: a bucket used with NO ordinary block target (the
 * crosshair ray passes through liquids) runs Beta ItemBucket.onItemRightClick's
 * own liquid ray in item_bucket_use_no_target. PlayerControllerSP.sendUseItem
 * writes the returned stack over the held slot when it differs. Creative
 * (net-new) restores the held stack like the SRPC_BLOCK_PLACE path. */
static bool server_local_bucket_use_for(struct server_local* s,
	struct server_player* player) {
	size_t slot = INVENTORY_SLOT_HOTBAR + inventory_get_hotbar(&player->inventory);
	struct item_data* held = &player->inventory.items[slot];
	struct item_data creative_held = *held;
	if(!item_bucket_use_no_target(s, player, held))
		return false;
	if(s->creative_mode)
		*held = creative_held;
	server_local_actor_slot_reply(player, &(struct client_rpc) {
		.type = CRPC_INVENTORY_SLOT,
		.payload.inventory_slot.window = WINDOWC_INVENTORY,
		.payload.inventory_slot.slot = slot,
		.payload.inventory_slot.item = *held,
	});
	return true;
}

static void server_local_process_use_item_for_body(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	assert(s && player && call);
	do {
			// Use the held item into open air: the PLAYER BOW (audit #17c), a
			// thrown EGG (M4 S5), a placed BOAT (boat-slice), or the FISHING
			// ROD cast/reel (fishing-slice). Each helper is internally
			// guarded on its own held item (+ ammo/has_pos), so an unrelated
			// item is a harmless no-op. The client gates the send on
			// item_has_air_use().
			if(player->active_inventory == &player->inventory) {
				struct item_data air_held;
				bool have_air_held = inventory_get_hotbar_item(
					&player->inventory, &air_held);
				if(have_air_held
				   && (air_held.id == ITEM_EGG
					   || air_held.id == ITEM_SNOW_BALL)) {
					/* S1-a2 OPEN: the thrown projectile now carries the
					 * acting actor's identity (entity_egg.thrower_actor), so
					 * the knockback direction, the retaliation target and the
					 * owner-grace exclusion all name the real thrower instead
					 * of hard-coding the host. */
					server_local_throw_thrown_item(s, player, air_held.id);
				} else if(have_air_held && item_is_food(air_held.id))
					(void)server_local_eat_held_for(s, player);
				else if(have_air_held && item_bucket_is_bucket(air_held.id))
					(void)server_local_bucket_use_for(s, player);
				else if(have_air_held && air_held.id == ITEM_BOAT)
					(void)server_local_place_boat_for(s, player);
				else if(have_air_held && air_held.id == ITEM_FISHING_ROD) {
					/* S1-a2 OPEN: entity_fish.angler_actor names the caster;
					 * the hook re-resolves it every tick and removes itself
					 * when the angler leaves/dies/rejoins, and the reel pulls
					 * the ANGLER (server_local_fishing_rod_action already took
					 * the actor at S1-a1). */
					server_local_fishing_rod_action(s, player);
				} else {
					/* S1-a2 OPEN: the arrow carries the shooter identity, so
					 * a guest shot excludes the GUEST (not the host) from its
					 * owner grace and credits its retaliation to the guest.
					 * A guest arrow CAN damage the host -- Beta players damage
					 * players, kept deliberately. */
					server_local_fire_bow(s, player,
										  call->payload.use_item.charge);
				}
				/* S1-d: the air-use verb reached this actor's held-item
				 * dispatch. Counted here rather than per helper because a
				 * block item used into open air is legitimately inert in
				 * Beta -- there is no effect to observe, and the routing
				 * proof is the whole point of the counter. */
				server_local_note_action(s, player, SERVER_ACTION_USE);
			}
			break;
	} while(0);
}

/* A2-T D4: the block/item callbacks this request dispatches act on the
 * ACTOR's committed world (block_world), not slot 0. */
static void server_local_process_use_item_for(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	struct server_world* bw_prev
		= block_world_enter(s, server_local_world_of(s, player));
	server_local_process_use_item_for_body(s, player, call);
	block_world_leave(s, bw_prev);
}

// R1d: Beta's footstep gate includes `ridingEntity == null` [740c583: Entity.java:437]. The host's
// cart/boat rides have single-writer flags; a pig ride lives only on the pig (pig_ridden /
// pig_rider_id / pig_rider_actor), so it is found by a scan. Called only after the cheaper
// flag tests pass, i.e. once per walking SRPC_PLAYER_POS sample.
/* A1d: the former server_local_host_rides_pig scan for EITHER body (the rider
 * identity resolves to the acting actor; for &s->player it is the old test). */
static bool server_local_actor_rides_pig(struct server_local* s,
	const struct server_player* p) {
	dict_entity_it_t it;
	for(dict_entity_it(it, s->entities); !dict_entity_end_p(it); dict_entity_next(it)) {
		const struct entity* e = dict_entity_ref(it)->value;
		if(e && e->type == ENTITY_MONSTER && e->data.monster.id == MONSTER_PIG
		   && e->data.monster.pig_ridden
		   /* R02 F6: lifetime + real wire id + live world, so a validly
		    * mounted GUEST is gated too (Beta Entity.moveEntity's leg is
		    * `ridingEntity == null` only, Entity.java:410). Host unchanged:
		    * its wire id is SERVER_LOCAL_PLAYER_ENTITY_ID. */
		   && server_local_vehicle_rider(s, e, e->data.monster.pig_rider_actor,
				  e->data.monster.pig_rider_id) == p)
			return true;
	}
	return false;
}

/* A1d (split-dimensions-plan-0924 row #16, A1-CONTRACT: "A1d/C invokes it from
 * both movement paths without duplicate effects"): Beta Entity.moveEntity's
 * footstep leg [Entity.java:436-457] for ONE accepted pose sample of EITHER
 * body -- the odometer, the one step sound on the nextStepDistance crossing
 * and Block.onEntityWalking (farmland trample, redstone-ore glow) for THIS
 * walker. Every entity keeps its own odometer (Entity.java:40-42), so the two
 * players never share one. Called with the pre-sample body state (Beta's
 * `isSneaking && onGround` suppression reads it) BEFORE the new position is
 * stored, exactly where the host handler ran it inline. The host call is the
 * former inline block statement for statement; the only change is that the
 * world is the actor's own (D8) instead of the fixed alias.
 *
 * Block callbacks still take the session and act on slot 0 (the D4 bridge,
 * A1b), so onEntityWalking runs only while the mover's world IS slot 0; the
 * odometer and the sound follow the mover's world unconditionally. */
void server_local_actor_movement_step(struct server_local* s,
	struct server_player* p, double nx, double ny, double nz) {
	assert(s && p);
	// Beta's gate is `canTriggerWalking() && !var18 && this.ridingEntity ==
	// null` [740c583: Entity.moveEntity:478] -- see the host SRPC_PLAYER_POS
	// handler for the full history of the riding clause.
	if(!p->has_pos || p->riding_minecart || p->riding_boat
	   || (p->on_ground && p->sneaking)
	   || server_local_actor_rides_pig(s, p)) // R1d: ridingEntity == null
		return;
	double ddx = nx - p->x;
	double ddz = nz - p->z;
	// Ignore teleport-scale jumps (load/respawn/lag): Beta's setPosition does not
	// accumulate distanceWalked. This 2-block HARD CAP is a deliberate deviation from
	// Beta's unconditional per-move accumulation -- safe because legit walk/sprint is
	// << 1 block/tick (sprint ~0.28), so even a 2-tick merged sample (~0.56 b) stays far
	// under it; it only ever rejects a teleport, never real movement.
	if(ddx * ddx + ddz * ddz >= PLAYER_MOVE_TELEPORT_DELTA_SQ)
		return;
	/* D8: the mover's committed live world. NULL (no live world) reads as no
	 * solid block, which is what the failed alias read gave before: the
	 * odometer still accumulates, nothing is heard or trampled. */
	struct server_world* w = server_local_world_of(s, p);
	// Block under the feet: Beta floor(posY - 0.2 - yOffset). player.y is the
	// EYE, yOffset 1.62 -> floor(y - 1.82).
	int bx = (int)floor(nx);
	int by = (int)floor(ny - (1.62 + 0.2));
	int bz = (int)floor(nz);
	struct block_data below, fence_chk;
	bool solid = w && server_world_get_block(w, bx, by, bz, &below)
		&& below.type != BLOCK_AIR;
	// Beta's var28>0 gate uses the FENCE-substituted id: an air
	// foot cell over a fence still fires (and advances
	// nextStepDistance). [740c583: Entity.moveEntity:483-488]
	if(!solid && w
	   && server_world_get_block(w, bx, by - 1, bz, &fence_chk)
	   && audio_footstep_block_id(BLOCK_AIR, fence_chk.type) != BLOCK_AIR)
		solid = true;
	if(!server_player_walk_step(&p->distance_walked, &p->next_step_distance,
								ddx, ddz, solid))
		return;
	// S2: the S0-deferred footstep SOUND, on exactly this return-true edge
	// (Beta plays it BEFORE onEntityWalking): stepSoundDir2() at
	// getVolume()*0.15F/getPitch(), snow-layer-above -> cloth, silent on a
	// liquid foot cell, at the FEET (playSoundAtEntity plays at posY -
	// yOffset). [740c583: Entity.moveEntity:478-499]
	server_local_emit_footstep_world(
		w, bx, by, bz,
		(vec3) {(float)nx, (float)(ny - PLAYER_EYE_HEIGHT), (float)nz});
	// R1: the generic Block.onEntityWalking dispatch (farmland trample,
	// redstone ore glow), after the sound like Beta. [740c583: Entity.java:457]
	server_local_entity_walked_on_block_w(s, w, bx, by, bz, BLOCK_WALKER_PLAYER);
}

// R1 (docs/intent/r1-block-click-walk-callbacks.md): Block.onBlockClicked dispatch for a
// dig-start. `held` is the actor's hotbar item (NULL = empty hand), the value Beta's
// overrides read off the EntityPlayer (BlockTNT's flint & steel test).
static void server_local_block_clicked(struct server_local* s,
									   struct server_player* player, w_coord_t x,
									   w_coord_t y, w_coord_t z) {
	struct block_data blk;
	/* A1d (D8): the clicking actor's world; no live world, no click. */
	struct server_world* w = server_local_world_of(s, player);
	if(!w || !server_world_get_block(w, x, y, z, &blk) || blk.type == BLOCK_AIR
	   || !blocks[blk.type] || !blocks[blk.type]->onBlockClicked)
		return;
	struct item_data held;
	bool has_held = inventory_get_hotbar_item(&player->inventory, &held);
	blocks[blk.type]->onBlockClicked(
		s, player, has_held ? &held : NULL,
		&(struct block_info) {.block = &blk, .neighbours = NULL, .x = x, .y = y, .z = z});
}

// R1: BlockTNT.onBlockDestroyedByPlayer's primed branch for a PLAYER break of TNT whose
// metadata carries the flint & steel stamp (onBlockClicked). ItemInWorldManager.removeBlock
// writes AIR first, then calls onBlockDestroyedByPlayer(meta): (meta & 1) != 0 constructs
// EntityTNTPrimed at the cell centre, joins it and plays "random.fuse" 1.0F/1.0F; BlockTNT
// .quantityDropped is 0, so the harvest that follows drops nothing. Returns true when it
// primed (the caller then skips the TNT item drop). [740c583: BlockTNT.java:44-53;
// server ItemInWorldManager.removeBlock -> func_325_c:92-111]
static bool server_local_dig_primes_tnt(struct server_local* s, struct block_data blk,
										w_coord_t x, w_coord_t y, w_coord_t z) {
	if(blk.type != BLOCK_TNT || (blk.metadata & 1) == 0)
		return false;
	vec3 pos = {(float)x + 0.5F, (float)y + 0.5F, (float)z + 0.5F};
	if(!server_local_spawn_primed_tnt(s, pos, TNT_FUSE_DEFAULT)) {
		// Beta cannot fail here; this port can (entity reservation). Never lose the
		// block silently: fall back to the unprimed branch's single TNT item drop.
		fprintf(stderr,
				"[tnt] punch-prime entity reservation failed at (%d,%d,%d); "
				"dropping the TNT item instead\n",
				(int)x, (int)y, (int)z);
		return false;
	}
	server_local_emit_sound(SOUND_RANDOM_FUSE, pos, 1.0F, 1.0F);
	return true;
}

static void server_local_process_block_dig_for_body(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	assert(s && player && call);
	do {
			if(player->has_pos && player->finished_loading
			   && player->active_inventory == &player->inventory
			   && call->payload.block_dig.y >= 0
			   && call->payload.block_dig.y < WORLD_HEIGHT) {
				if(!call->payload.block_dig.finished) {
					/* R1d: a repeat of this actor's last accepted dig-start (same
					 * start_seq) is the SAME Packet14 status 0 -- drop it whole, so
					 * no client/transport duplicate can click twice. 0 = unsequenced
					 * (scripts/tests), always accepted. A new press gets a new id,
					 * so Beta's re-click on a re-press is kept. */
					uint32_t seq = call->payload.block_dig.start_seq;
					if(seq != 0 && seq == player->last_dig_start_seq)
						break;
					player->last_dig_start_seq = seq;
					server_local_extinguish_fire_on_hit(s, call);
					// R1: Beta ItemInWorldManager.func_324_a:41-47 -- onBlockHit (the
					// fire punch-out above), THEN re-read the cell and, for id > 0, run
					// Block.onBlockClicked for this actor. Every dig-start (this
					// port's Packet14 status 0) is one click, unconditionally, as on
					// the Beta server. [740c583 server: ItemInWorldManager.java:41-47]
					server_local_block_clicked(s, player, call->payload.block_dig.x,
											   call->payload.block_dig.y,
											   call->payload.block_dig.z);
					break;
				}
				struct block_data blk;
				/* A1d (D8): the digging actor's own world (A1a left the slot-0
				 * token here for the signature change); NULL -> no dig. */
				struct server_world* w = server_local_world_of(s, player);
				if(w && server_world_get_block(w, call->payload.block_dig.x,
										  call->payload.block_dig.y,
										  call->payload.block_dig.z, &blk)) {
					// S0 break sound, the aux-2001 rule: the BREAK-name method
					// (stepSoundDir(): glass-type -> random.glass, sand ->
					// step.gravel), (vol+1)/2 @ pitch*0.8, at the block
					// center, played BEFORE the removal like Beta's
					// sendBlockRemoved playAuxSFX-then-setBlock order.
					// [740c583: PlayerController.sendBlockRemoved ->
					//  World.playAuxSFX(2001) -> RenderGlobal.playAuxSFX
					//  case 2001]
					server_local_emit_sound(
						audio_block_break_sound_id(blk.type),
						(vec3) {call->payload.block_dig.x + 0.5F,
								call->payload.block_dig.y + 0.5F,
								call->payload.block_dig.z + 0.5F},
						(audio_block_sound_volume(blk.type) + 1.0F) / 2.0F,
						audio_block_sound_pitch(blk.type) * 0.8F);
					server_world_set_block(w, call->payload.block_dig.x,
										   call->payload.block_dig.y,
										   call->payload.block_dig.z,
										   (struct block_data) {
											   .type = BLOCK_AIR,
											   .metadata = 0,
										   });
					/* S1-d: a FINISHED dig that really removed a block. The
					 * dig-start / extinguish branch above broke out already,
					 * so this is the block-gone edge, not a progress ping. */
					server_local_note_action(s, player, SERVER_ACTION_DIG);

					if(blocks[blk.type] && blocks[blk.type]->onBreak)
						blocks[blk.type]->onBreak(
							s, &(struct block_info) {
								   .block = &blk,
								   .neighbours = NULL,
								   .x = call->payload.block_dig.x,
								   .y = call->payload.block_dig.y,
								   .z = call->payload.block_dig.z,
							   });
					// R1: TNT punched with flint & steel primes on the break.
					bool tnt_primed = server_local_dig_primes_tnt(
						s, blk, call->payload.block_dig.x, call->payload.block_dig.y,
						call->payload.block_dig.z);

					struct item_data it_data;
					bool has_tool = inventory_get_hotbar_item(
						&player->inventory, &it_data);
					struct item* it = has_tool ? item_get(&it_data) : NULL;

					/* TOOL WEAR -- Beta PlayerControllerSP.sendBlockRemoved (740c583):
					     removed = the base sendBlockRemoved result;
					     held = the current equipped stack;
					     harvestable = the canHarvestBlock gate;
					     with a held stack, its onDestroyBlock runs       <- WEAR
					     when removed and harvestable, harvestBlock runs  <- DROP
					   The wear runs on a held stack ALONE, outside BOTH flags, so it sits
					   HERE -- deliberately ABOVE the digging.tool/digging.min drop gate
					   below, not inside it. Digging stone with a wooden pickaxe drops
					   nothing and still costs the pickaxe a point; so does breaking a
					   hardness-0 torch (ItemTool has no hardness guard in 1.7.3 -- that
					   arrived in a later version).
					   docs/briefs/01_durability_combat.md used to claim the opposite
					   ("only a SUCCESSFUL harvest wears"); it is corrected there.
					   Order also matters: `it`/`it_data` are COPIES taken before the wear,
					   so the drop gate still sees the PRE-wear tool -- which is Beta, where
					   the harvest gate is computed before onDestroyBlock. */
					if(has_tool)
						server_local_wear_held_item(
							s, player,
							item_wear_on_block_break(it_data.id, it, blk.type));

					if(!tnt_primed && blocks[blk.type]
					   && ((it
							&& it->tool.type == blocks[blk.type]->digging.tool
							&& it->tool.tier >= blocks[blk.type]->digging.min)
						   || blocks[blk.type]->digging.min == TOOL_TIER_ANY
						   || blocks[blk.type]->digging.tool == TOOL_TYPE_ANY)) {
						// Beta ItemShears/BlockLeaves.harvestBlock: leaves broken while holding
						// shears drop the leaf block itself instead of the normal sapling roll.
						struct item_data shear_drop;
						if(has_tool
						   && item_shears_block_drop(blk, it_data, &shear_drop)) {
							/* RetroMCP b1.7.3 BlockLeaves.java:159-164:
							 * harvestBlock passes its world to dropBlockAsItem_do.
							 * Keep the legacy spawn entry for live slot 0. */
							vec3 drop_pos = {call->payload.block_dig.x + 0.5F,
										call->payload.block_dig.y + 0.5F,
										call->payload.block_dig.z + 0.5F};
							struct entity* leaf_drop = w == &s->worlds[0]
								? server_local_spawn_item(drop_pos, &shear_drop, false, s)
								: server_local_spawn_item_w(w, drop_pos, &shear_drop, false);
							// FH-12: BlockLeaves.harvestBlock's shears branch calls
							// dropBlockAsItem_do DIRECTLY (bypassing harvestBlock's
							// normal quantityDropped/idDropped path) -- same
							// delayBeforeCanPickup = 10 as every other
							// dropBlockAsItem_do site. [740c583: BlockLeaves.java]
							if(leaf_drop)
								leaf_drop->data.item.pickup_delay = 10;
						} else
							server_local_harvest_block_drops(
								s,
								&(struct block_info) {
									.block = &blk,
									.neighbours = NULL,
									.x = call->payload.block_dig.x,
									.y = call->payload.block_dig.y,
									.z = call->payload.block_dig.z,
								});

						// Beta BlockIce.harvestBlock's water-conversion half (see
						// block_ice.c's block_ice_harvest comment): part of the same
						// "if (var7 && var9) harvestBlock(...)" call this branch
						// already models for the drop above, so it belongs behind the
						// SAME harvest gate, not the generic onBreak hook.
						if(blk.type == BLOCK_ICE)
							block_ice_harvest(
								s, &(struct block_info) {
									   .block = &blk,
									   .neighbours = NULL,
									   .x = call->payload.block_dig.x,
									   .y = call->payload.block_dig.y,
									   .z = call->payload.block_dig.z,
								   });
					}
				}
			}
			break;
	} while(0);
}

/* A2-T D4: the block/item callbacks this request dispatches act on the
 * ACTOR's committed world (block_world), not slot 0. */
static void server_local_process_block_dig_for(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	struct server_world* bw_prev
		= block_world_enter(s, server_local_world_of(s, player));
	server_local_process_block_dig_for_body(s, player, call);
	block_world_leave(s, bw_prev);
}

static void server_local_process_block_place_for_body(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	assert(s && player && call);
	do {
		/* S1-a1b: the whole-verb fail-closed guard is GONE -- every place /
		 * activate / item-use hook now takes the acting actor (blocks.h /
		 * item_types.h), so the obstruction sweep, the window opens, the
		 * facing derivations and the inventory consumption all act on
		 * `player`. The per-path fail-closed paths that a parameter move
		 * does NOT authorize stay refused INSIDE their hooks and are listed
		 * there: bed sleep + the Nether bed blast (Astra gate-2 D1,
		 * sleeping/dimension), cake and every food heal (no actor-aware
		 * health transaction yet), and the furnace / iron-chest / dispenser
		 * window opens (their live-window ownership test is still host-only,
		 * R-S1a1 finding 3 -- owner S1-a2). */
			if(player->has_pos && player->finished_loading
			   && player->active_inventory == &player->inventory
			   && call->payload.block_place.y >= 0
			   && call->payload.block_place.y < WORLD_HEIGHT) {
				int x, y, z;
				blocks_side_offset(call->payload.block_place.side, &x, &y, &z);

				struct block_data blk_where, blk_on;
				/* A1d (D8): the placing actor's own world; NULL -> no place. */
				struct server_world* w = server_local_world_of(s, player);
				/* SNOW-002: resolve the clicked block and the held item
				 * FIRST. Beta ItemReed.onItemUse [740c583 ItemReed.java:12-13]:
				 * `if(world.getBlockId(x,y,z) == Block.snow.blockID) side = 0;`
				 * -- for the three ItemReed-class items (Item.reed,
				 * Item.cake, Item.redstoneRepeater) a click on a snow layer
				 * targets the SNOW CELL itself with side 0 (bottom) and the
				 * offset cell is never read, so an unreadable offset cell
				 * must not block it. Every other item keeps the offset
				 * target below. */
				struct item_data it_data;
				inventory_get_hotbar_item(&player->inventory, &it_data);
				bool reed_on_snow = false;
				bool where_ok = false;
				if(w && server_world_get_block(
					   w, call->payload.block_place.x,
					   call->payload.block_place.y, call->payload.block_place.z,
					   &blk_on)) {
					reed_on_snow = blk_on.type == BLOCK_SNOW
						&& (it_data.id == ITEM_REED || it_data.id == ITEM_CAKE
							|| it_data.id == ITEM_REDSTONE_REPEATER);
					if(reed_on_snow) {
						x = y = z = 0;
						blk_where = blk_on;
						where_ok = true;
					} else {
						where_ok = server_world_get_block(
							w, call->payload.block_place.x + x,
							call->payload.block_place.y + y,
							call->payload.block_place.z + z, &blk_where);
					}
				}
				if(where_ok) {
					struct block_info where = (struct block_info) {
						.block = &blk_where,
						.neighbours = NULL,
						.x = call->payload.block_place.x + x,
						.y = call->payload.block_place.y + y,
						.z = call->payload.block_place.z + z,
					};

					struct block_info on = (struct block_info) {
						.block = &blk_on,
						.neighbours = NULL,
						.x = call->payload.block_place.x,
						.y = call->payload.block_place.y,
						.z = call->payload.block_place.z,
					};

					struct item* it = item_get(&it_data);
					size_t slot = INVENTORY_SLOT_HOTBAR
						+ inventory_get_hotbar(&player->inventory);
					struct item_data* held
						= &player->inventory.items[slot];
					/* CREATIVE no-consume: snapshot the held stack; restored
					 * (and the client re-synced) after the WHOLE right-click
					 * dispatch below. Restoring at the end -- instead of
					 * gating each decrement -- also neutralizes items that
					 * mutate their own stack inside onUseOnBlock (dye/hoe/
					 * flint&steel) and blocks that swallow the held item
					 * (jukebox), without touching any item_*.c. */
					struct item_data creative_held = *held;

					const struct block* clicked = blocks[blk_on.type];
					bool block_handled = false;
					if(clicked && (clicked->onRightClickHandled
								   || clicked->onRightClick)) {
						// Beta onBlockActivated first (chest/lever/...): the block
						// gets first refusal. Legacy void callbacks always handle; the
						// bool form can return false and fall through to held-item use.
						struct item_data before = *held;
						if(clicked->onRightClickHandled)
							block_handled = clicked->onRightClickHandled(
								s, player, held, &where, &on,
								call->payload.block_place.side);
						else {
							clicked->onRightClick(
								s, player, held, &where, &on,
								call->payload.block_place.side);
							block_handled = true;
						}
						if(before.id != held->id
						   || before.durability != held->durability
						   || before.count != held->count)
							server_local_actor_slot_reply(player, &(struct client_rpc) {
								.type = CRPC_INVENTORY_SLOT,
								.payload.inventory_slot.window
								= WINDOWC_INVENTORY,
								.payload.inventory_slot.slot = slot,
								.payload.inventory_slot.item = *held,
							});
					}
					if(!block_handled) {
						enum side side = call->payload.block_place.side;
						// Beta order: the ITEM's use ON the clicked block (bonemeal,
						// hoe, flint+steel) first, then placing a block in the adjacent
						// air (onItemPlace). CONSUMPTION DIFFERS by path: onUseOnBlock
						// gets the REAL held stack and mutates it ITSELF (bonemeal -1; a
						// tool damages itself) -- the dispatch must NOT auto-consume it,
						// or a hoe would be deleted. Only onItemPlace (block place / eat)
						// is consumed here, one per success. Either path notifies the
						// client of the new slot contents.
						/* Buckets: ItemBucket has no onItemUse, so Beta reaches
						 * onItemRightClick (sendUseItem) and its OWN eye ray even
						 * with a block under the crosshair -- the clicked block
						 * and face are not used [ItemBucket.java:12-28]. Same
						 * ray as the no-target path; this dispatch already does
						 * the slot sync and the creative restore. */
						bool used = item_bucket_is_bucket(held->id)
							? item_bucket_use_no_target(s, player, held)
							: (it && it->onUseOnBlock
							   && it->onUseOnBlock(s, player, held, &on, side));
						bool placed = false;
						struct item_data place_input = it_data;
						/* SNOW-002: ItemReed-on-snow places with Beta side 0
						 * (SIDE_BOTTOM) into the snow cell, which is
						 * replaceable for these three items only (World
						 * canBlockBePlacedAt [740c583 World.java:2090-2106]
						 * lists Block.snow); snow's global place_ignore stays
						 * false. The items' own support + obstruction checks
						 * still run. */
						enum side place_side
							= reed_on_snow ? SIDE_BOTTOM : side;
						if(!used
						   && (reed_on_snow || !blocks[blk_where.type]
							   || blocks[blk_where.type]->place_ignore)
						   && it && it->onItemPlace)
							placed = it->onItemPlace(s, player, &it_data,
													 &where, &on, place_side);
						if(placed) {
							/* A place hook may return a new stack through its item copy.
							 * Unchanged copies retain the existing one-item consume path. */
							if(it_data.id != place_input.id
							   || it_data.durability != place_input.durability
							   || it_data.count != place_input.count)
								*held = it_data;
							else
								inventory_consume(&player->inventory, slot);
							/* S1-d: an accepted PLACE is one where the held
							 * item's onItemPlace really put a block in the
							 * world -- not a block activation and not an
							 * item used ON the clicked block. */
							server_local_note_action(s, player,
													 SERVER_ACTION_PLACE);
							// S0 place sound: the STEP-name method
							// (stepSoundDir2(), NOT the break name --
							// placing glass plays step.stone), same
							// (vol+1)/2 @ pitch*0.8 formula, at the placed
							// cell. Beta ItemBlock and ItemReed play this;
							// door/sign/bed/redstone dust placers stay silent.
							// [ItemBlock.onItemUse:50; server ItemReed:58-63]
							uint8_t place_sound_block = BLOCK_AIR;
							if(it_data.id < 256)
								place_sound_block = (uint8_t)it_data.id;
							else if(it_data.id == ITEM_REED)
								place_sound_block = BLOCK_REED;
							else if(it_data.id == ITEM_CAKE)
								place_sound_block = BLOCK_CAKE;
							else if(it_data.id == ITEM_REDSTONE_REPEATER)
								place_sound_block = BLOCK_REDSTONE_REPEATER;
							if(place_sound_block != BLOCK_AIR)
								server_local_emit_sound(
									audio_block_step_sound_id(place_sound_block),
									(vec3) {where.x + 0.5F, where.y + 0.5F,
											where.z + 0.5F},
									(audio_block_sound_volume(
										 place_sound_block)
									 + 1.0F)
										/ 2.0F,
									audio_block_sound_pitch(
										place_sound_block)
										* 0.8F);
						}

						// Sign-slice: Beta ItemSign.onItemUse's tail --
						// `player.displayGUIEditSign(te)` -- runs immediately
						// after a successful placement, no extra right-click
						// needed [740c583: ItemSign.onItemUse,
						// EntityPlayerSP.displayGUIEditSign]. Reuses the
						// EXISTING sign-OSK hook (block_sign.c's onRightClick
						// already opens WINDOWC_SIGN/WINDOW_TYPE_SIGN via this
						// same server_local_open_inventory call for an
						// EXISTING sign) at the JUST-PLACED cell -- no new RPC
						// plumbing. Gated on `placed` (never `used`): signs
						// only ever place, they never act on the clicked
						// block. A failed open (e.g. malloc, or the player's
						// active_inventory already isn't the plain inventory)
						// leaves the sign placed but unopened -- it can still
						// be opened later by right-clicking it, same as any
						// other sign.
						if(placed && it_data.id == ITEM_SIGN)
							server_local_open_inventory_for(
								s, player, &inventory_logic_sign, SIGN_SIZE,
								where.x, where.y, where.z, WINDOWC_SIGN,
								WINDOW_TYPE_SIGN);

						if(used || placed)
							server_local_actor_slot_reply(player, &(struct client_rpc) {
								.type = CRPC_INVENTORY_SLOT,
								.payload.inventory_slot.window
								= WINDOWC_INVENTORY,
								.payload.inventory_slot.slot = slot,
								.payload.inventory_slot.item
								= player->inventory.items[slot],
							});

						// M4 S5: Beta Minecraft.clickMouse -- when NEITHER the
						// block activation NOR the held item's use/place
						// consumed the click (sendPlaceBlock returned false),
						// the trailing sendUseItem still runs and reaches
						// Item.onItemRightClick. So an EGG or SNOWBALL
						// right-clicked AT a block (that did nothing with it)
						// still THROWS, exactly like Beta. Gated to the
						// air-verb throwers (the bow keeps its deliberate
						// open-air-only Wii mapping). [740c583:
						// Minecraft.clickMouse trailing
						// `if(var2 && var1 == 1) sendUseItem`]
						// R-S1a1b F1 (closed by the S1-a1b + S1-a2 integration):
						// this is the SAME helper the air-use verb calls, and
						// since S1-a2 it stamps the ACTING actor's identity on
						// the projectile (entity_egg.thrower_actor, via
						// server_local_actor_ident) instead of hard-coding the
						// host -- so a guest throw reached through BLOCK_PLACE
						// is attributed to the guest exactly like one reached
						// through USE_ITEM. There is no second implementation
						// and no separate gate: whatever use_item_for admits or
						// refuses for an actor, this branch does too.
						if(!used && !placed
						   && (held->id == ITEM_EGG
							   || held->id == ITEM_SNOW_BALL))
							server_local_throw_thrown_item(s, player, held->id);
						// Adversarial-review finding #1: a BOAT needs this
						// exact same trailing-sendUseItem fallback, for a
						// reason specific to water. ItemBoat.onItemRightClick
						// runs its OWN 5.0-block liquid-stopping raycast
						// regardless of any block the ordinary reach-raycast
						// already found -- and Beta water is non-collidable
						// (getBoundingBox()==0, block_water.c), so the
						// client's normal 4.5-block camera_hit ray sails
						// through any shallow/small pond (the common
						// worldgen case) to the lakebed or far shore behind
						// it. That makes camera_hit.hit TRUE and routes the
						// click here (SRPC_BLOCK_PLACE), not to the open-air
						// SRPC_USE_ITEM path -- so without this branch a
						// boat is silently unplaceable on most Beta water.
						// it->onUseOnBlock/onItemPlace are both NULL for
						// item_boat (Beta's ItemBoat overrides neither), so
						// `used`/`placed` are already false here exactly
						// like egg/snowball; server_local_place_boat() does
						// its own independent raycast off player->rx/ry,
						// ignoring this call's where/on entirely, matching
						// "regardless of any normal block target".
						else if(!used && !placed && held->id == ITEM_BOAT)
							(void)server_local_place_boat_for(s, player);
						// fishing-slice: the SAME trailing-sendUseItem path
						// reaches ItemFishingRod.onItemRightClick, so aiming
						// at an unhandled block (the common shoreline case)
						// still casts/reels. Unlike the bow, there is no
						// controller-ambiguity reason to withhold this --
						// see item_has_air_use's citation in items.h.
						// R-S1a1b F2 (closed by the integration + the A2 fix):
						// the cast records the ANGLER identity on the hook
						// (entity_fish.angler_actor) and installs the bobber id
						// on the ACTING body (player->fish_entity_id), and every
						// clearing site in entity_fish.c now resolves that
						// identity -- including the stuck-in-ground despawn,
						// which used to zero the host's id and leave a guest's
						// set forever, wedging server_local_guest_checkpoint and
						// with it every later world save.
						else if(!used && !placed
								&& held->id == ITEM_FISHING_ROD)
							server_local_fishing_rod_action(s, player);
					}
					/* CREATIVE no-consume restore (see snapshot above). */
					if(s->creative_mode
					   && (creative_held.id != held->id
						   || creative_held.durability != held->durability
						   || creative_held.count != held->count)) {
						*held = creative_held;
						server_local_actor_slot_reply(player, &(struct client_rpc) {
							.type = CRPC_INVENTORY_SLOT,
							.payload.inventory_slot.window
							= WINDOWC_INVENTORY,
							.payload.inventory_slot.slot = slot,
							.payload.inventory_slot.item = *held,
						});
					}
				}
			}
			break;
	} while(0);
}

/* A2-T D4: the block/item callbacks this request dispatches act on the
 * ACTOR's committed world (block_world), not slot 0. */
static void server_local_process_block_place_for(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	struct server_world* bw_prev
		= block_world_enter(s, server_local_world_of(s, player));
	server_local_process_block_place_for_body(s, player, call);
	block_world_leave(s, bw_prev);
}

/* The Beta EntityMinecart.attackEntityFrom `> 40` break, everything except
 * the entity removal itself: dismount the rider, drop the cart item, then the
 * type-specific cargo/block drops. Shared by the melee attack handler (which
 * then frees + erases the cart) and the cart tick's explosion-latched break
 * (which returns "remove" so the entity loop frees it).
 * [740c583 EntityMinecart.attackEntityFrom:73-116] */
/* I03: one chest-cart slot of EntityMinecart's break spill, on the cart's
 * own Random (see the caller). Each chunk is allocate-before-RNG like every
 * item spawn; a refused chunk restores the cart stream and stops. */
static void server_local_spill_cart_slot(struct server_local* s,
	struct entity* cart, const struct item_data* stack) {
	struct server_world* w = server_local_entity_world(s, cart);
	if(!w)
		return;
	struct java_random* r = &cart->gameplay_rng;
	const float ox = jrand_next_float(r) * 0.8F + 0.1F;
	const float oy = jrand_next_float(r) * 0.8F + 0.1F;
	const float oz = jrand_next_float(r) * 0.8F + 0.1F;
	int left = stack->count;
	while(left > 0) {
		const struct java_random before = *r;
		int n = jrand_next_int_bound(r, 21) + 10;
		if(n > left)
			n = left;
		struct item_data piece = *stack;
		piece.count = (uint8_t)n;
		vec3 pos = {cart->pos[0] + ox, cart->pos[1] + oy, cart->pos[2] + oz};
		vec3 zero = {0};
		struct entity* e
			= server_local_prepare_item_w(w, pos, &piece, zero, 0, 0, 0, s);
		if(!e) {
			*r = before;
			return;
		}
		/* new EntityItem: constructor motion on the Math stream, then
		 * overwritten by the cart's gaussians. */
		server_local_entity_item_constructor_velocity(e->vel);
		const float gx = (float)jrand_next_gaussian(r);
		const float gy = (float)jrand_next_gaussian(r);
		const float gz = (float)jrand_next_gaussian(r);
		e->vel[0] = gx * 0.05F;
		e->vel[1] = gy * 0.05F + 0.2F;
		e->vel[2] = gz * 0.05F;
		if(!server_local_entity_join(s, e->id)) {
			server_local_rollback_prepared_items(s, &e, 1);
			*r = before;
			return;
		}
		server_local_publish_item(s, e);
		left -= n;
	}
}

void server_local_minecart_break_drops(struct server_local* s,
									   struct entity* cart) {
	assert(s && cart && cart->type == ENTITY_MINECART);
	struct server_world* w = server_local_entity_world(s, cart);
	if(!w)
		return;
	if(cart->data.minecart.occupied)
	    server_set_minecart_occupancy(s, cart, false);
	struct item_data drop
		= {.id = ITEM_MINECART, .durability = 0, .count = 1};
	vec3 dpos = {cart->pos[0], cart->pos[1], cart->pos[2]};
	server_local_spawn_item_batch_w(w, dpos, &drop, 1, false);
	/* Type-specific extra drops, in order. [740c583
	 * EntityMinecart.attackEntityFrom:86-116] cite exactly these two
	 * branches after the unconditional minecartEmpty drop above; the
	 * decompile's redundant SECOND cargo-drain loop inside
	 * attackEntityFrom itself (the one AFTER setEntityDead() already
	 * emptied every stack to 0) is a Beta no-op -- see
	 * MINECART_SLICE_NOTES.md -- so this ports the ONE drop pass that
	 * is actually observable, not the dead second one. */
	if(cart->data.minecart.minecart_type == 1) {
		/* Chest cart: every occupied inventory slot, THEN the chest
		 * block. Beta chunks each stack into rand.nextInt(21)+10-sized
		 * pieces with per-item gaussian scatter (setEntityDead:136-159);
		 * CaveWii drops each occupied slot as ONE item entity preserving
		 * the exact stack -- same total items/ids/counts either way, and
		 * the chunk COUNT is an RNG artefact that cannot be hand-derived
		 * without poisoning the golden (CODESTYLE.md S4.2). Reuses
		 * server_local_spawn_container_item_batch, the same primitive
		 * block_chest.c's own break-drop already applies to a broken
		 * container's contents (its isolated container_drop_rng
		 * stream). */
		/* I03 (board #8): Beta's spill on the CART's own Random [CFR
		 * EntityMinecart.java:119-135]: per occupied slot three nextFloat
		 * offsets (*0.8F+0.1F), then chunks of nextInt(21)+10, each an
		 * EntityItem at pos+offset with motion (float)nextGaussian()*0.05F
		 * (Y +0.2F). The world stream is untouched. */
		for(size_t k = 0; k < MINECART_CHEST_SLOTS; k++)
			if(cart->data.minecart.inventory[k].id != 0)
				server_local_spill_cart_slot(s, cart,
					&cart->data.minecart.inventory[k]);
		struct item_data chest_drop
			= {.id = BLOCK_CHEST, .durability = 0, .count = 1};
		server_local_spawn_item_batch_w(w, dpos, &chest_drop, 1, false);
	} else if(cart->data.minecart.minecart_type == 2) {
		/* Furnace cart: the IDLE furnace block id (Block.stoneOvenIdle),
		 * NEVER the lit one -- regardless of whether it happened to be
		 * actively burning fuel at the moment it broke. */
		struct item_data furnace_drop
			= {.id = BLOCK_FURNACE, .durability = 0, .count = 1};
		server_local_spawn_item_batch_w(w, dpos, &furnace_drop, 1, false);
	}
}

/* Local split bodies are server actors, not entries in s->entities. In
 * particular the host's id is 0, which generic entity lookup rejects.
 * Beta 1.7.3 EntityPlayer.attackTargetEntityWithCurrentItem (RetroMCP
 * b4968f54, EntityPlayer.java:488-505): damage, falling bonus, then weapon
 * wear even when hurt resistance absorbs the hit. Player damage is not
 * difficulty-scaled (attackEntityFrom:366-377 scales only mobs/arrows).
 * Keep the existing six-block / eye-ray interaction policy for both bodies. */
static bool server_local_attack_split_player(struct server_local* s,
	struct server_player* attacker, uint32_t id) {
	struct server_player* target = id == SERVER_LOCAL_PLAYER_ENTITY_ID
		? &s->player
		: (s->guest_gameplay && id == s->guest_entity_id ? s->guest_actor : NULL);
	if(!target)
		return false;
	if(target == attacker || !target->has_pos || !target->finished_loading
	   || target->health <= 0 || server_transfer_actor_inert(s, target))
		return true;
	struct server_world* w = server_local_world_of(s, attacker);
	if(!w || server_local_world_of(s, target) != w)
		return true;
	double dx = target->x - attacker->x;
	double dy = target->y - attacker->y;
	double dz = target->z - attacker->z;
	if(dx * dx + dy * dy + dz * dz >= 36.0
	   || los_segment_blocked((float)attacker->x, (float)attacker->y,
		   (float)attacker->z, (float)target->x, (float)target->y,
		   (float)target->z, mob_los_cell_opaque, w))
		return true;
	struct item_data held;
	struct item* item = inventory_get_hotbar_item(&attacker->inventory, &held)
		? item_get(&held) : NULL;
	int damage = item ? player_melee_damage(item->tool.type, item->tool.tier)
		: player_melee_damage(TOOL_TYPE_ANY, TOOL_TIER_ANY);
	if(attacker->vel_y < 0.0F)
		damage++;
	server_local_note_action(s, attacker, SERVER_ACTION_ATTACK);
	/* v5: EntityPlayer.attackTargetEntityWithCurrentItem ->
	 * attackEntityFrom(this, damage): the attacker's double delta (a
	 * coincident pair takes Beta's Math.random separation). */
	const struct actor_attacker pvp = {
		.present = true, .dx = attacker->x - target->x,
		.dz = attacker->z - target->z};
	(void)server_local_damage_actor_core(s, target, damage, &pvp, NULL,
		PLAYER_DAMAGE_COMBAT, false, false);
	if(item)
		server_local_wear_held_item(s, attacker, item_wear_on_hit_entity(item));
	return true;
}

/* The persistent Entity.boundingBox of a mob: the authoritative doubles once
 * seeded, else the float box built from pos (a hand-built fixture mob that
 * never ran a motion tick). */
static struct mob_aabb_d pig_zombie_pack_box(const struct entity* e) {
	if(e->data.monster.motion_d.valid)
		return e->data.monster.motion_d.bb;
	struct AABB b;
	entity_make_world_bbox(e, &b);
	return (struct mob_aabb_d) {{b.x1, b.y1, b.z1}, {b.x2, b.y2, b.z2}};
}

static void pig_zombie_become_angry_at(struct entity* pz,
									   struct actor_ident attacker) {
	/* becomeAngryAt [server EntityPigZombie.java:67-71]:
	 *   the attacker becomes the target;
	 *   anger level = 400 + own rand nextInt(400);
	 *   sound delay = own rand nextInt(40).  */
	pz->data.monster.aggro_time = MOB_TARGET_RETENTION_TICKS;
	pz->data.monster.target_actor = attacker;
	pz->data.monster.anger_level
		= 400 + jrand_next_int_bound(&pz->gameplay_rng, 400);
	pz->data.monster.anger_sound_delay
		= jrand_next_int_bound(&pz->gameplay_rng, 40);
}

/* PIGZ-PACK (server_local.h contract). Beta [server EntityPigZombie.java:49-64]:
 *   when the attacker is a player:
 *     every other entity in the struck box expanded by 32.0D on each axis
 *         that is a pig zombie becomes angry at the
 *     attacker (becomeAngryAt), then the struck pig zombie does too;
 *     after that, for any attacker,
 *   the
 *   base attackEntityFrom runs and its result is returned.
 * Membership is World.getEntitiesWithinAABBExcludingEntity [World.java:1741]
 * -> Chunk.getEntitiesWithinAABBForEntity [Chunk.java:463]: an entity other than the excluded
 * one whose box intersects the query box -- the strict AxisAlignedBB test
 * against the EXPANDED struck box (not a 32-block centre distance), and no
 * health/deathTime filter: a dying pig zombie is still in its chunk list until
 * setEntityDead, so it is angered too (delay_destroy == 0 = already removed).
 * The query is the struck mob's worldObj, so only pig zombies of the struck
 * mob's own world qualify (actor-world routing: a split guest in the Nether
 * never alerts an Overworld pack at the same coordinates).
 * ORDER: every becomeAngryAt draws only from its OWN pig zombie's Random and
 * writes only that mob's fields, so the chunk-list iteration order is
 * unobservable and the dict walk is equivalent. Per mob the order is fixed:
 * nextInt(400) then nextInt(40); the struck mob's pair precedes its hurt/death
 * pitch, which the callers guarantee by calling this before the damage. */
void server_local_pig_zombie_pack_anger(struct server_local* s,
	struct entity* struck, struct actor_ident attacker) {
	assert(s && struck);
	if(struck->type != ENTITY_MONSTER
	   || struck->data.monster.id != MONSTER_PIG_ZOMBIE)
		return;
	const struct server_world* home = server_local_entity_world(s, struck);
	struct mob_aabb_d query = pig_zombie_pack_box(struck);
	for(int i = 0; i < 3; i++) {
		query.min[i] -= 32.0;
		query.max[i] += 32.0;
	}
	dict_entity_it_t it;
	dict_entity_it(it, s->entities);
	while(!dict_entity_end_p(it)) {
		struct entity* pz = dict_entity_ref(it)->value;
		dict_entity_next(it);
		if(!pz || pz == struck || pz->type != ENTITY_MONSTER
		   || pz->data.monster.id != MONSTER_PIG_ZOMBIE
		   || pz->delay_destroy == 0)
			continue;
		if(!home || server_local_entity_world(s, pz) != home)
			continue;
		struct mob_aabb_d box = pig_zombie_pack_box(pz);
		if(!mob_aabb_intersects(&query, &box))
			continue;
		pig_zombie_become_angry_at(pz, attacker);
	}
	pig_zombie_become_angry_at(struck, attacker);
}

static void server_local_process_entity_attack_for(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	assert(s && player && call);
	struct vsp_use_pre vsp_pre;
	bool vsp_on = vsp_armed()
		&& vsp_srv_use_pre(s, player, call->payload.entity_attack.entity_id, 0,
						   &vsp_pre);
	do {
		  if(!player->has_pos || !player->finished_loading)
		    break;
		  if(player->active_inventory != &player->inventory)
		    break;
		  uint32_t id = call->payload.entity_attack.entity_id;
		  if(server_local_attack_split_player(s, player, id))
		    break;
		  /* A2-E review F2: only a body in this actor's own live world. */
		  struct entity* a2e_target = server_local_actor_entity_ref(s, player, id);
		  struct entity** ptr = a2e_target ? &a2e_target : NULL;
		  /* S1-d: the attack verb passed this actor's barriers and named a
		   * LIVE entity. Counted before the per-branch reach/visibility gates
		   * on purpose: split_actions_6m only REPORTS attack (no mob is
		   * guaranteed to be in range on a scripted run), so the useful
		   * signal is "the guest's attack reached its own body's dispatch",
		   * not "the hit landed". */
		  if(ptr && *ptr)
		    server_local_note_action(s, player, SERVER_ACTION_ATTACK);
		  /* VEHICLE BREAKING [740c583 EntityMinecart.attackEntityFrom:70-85]:
		   * flip the rock direction, arm 10 shake ticks, damage += strength*10
		   * (fist strength 1, same per-tool table as mobs); past 40 the cart
		   * dismounts its rider, dies, and drops the minecart item. Damage
		   * decays 1/tick in the entity tick, so only rapid hits break it.
		   * Same shared func_6006_a authority gate as USE (GB-06). */
		  if(ptr && *ptr && (*ptr)->type == ENTITY_MINECART) {
		    struct entity* cart = *ptr;
		    /* GB-06: the shared gate adds the canEntityBeSeen leg the cart branch
		     * never had -- reach alone let a cart be beaten through a wall. */
		    if(!server_local_entity_interaction_allowed(s, player, cart))
		      break;
		    struct item_data aheld;
		    struct item* ait
			    = inventory_get_hotbar_item(&player->inventory, &aheld)
			    ? item_get(&aheld)
			    : NULL;
		    int astr = ait ? player_melee_damage(ait->tool.type, ait->tool.tier)
					   : player_melee_damage(TOOL_TYPE_ANY, TOOL_TIER_ANY);
		    cart->data.minecart.shake_dir
			    = (int8_t)-cart->data.minecart.shake_dir;
		    cart->data.minecart.shake_ticks = 10;
		    cart->data.minecart.damage_taken = (int16_t)(
			    cart->data.minecart.damage_taken + astr * 10);
		    if(cart->data.minecart.damage_taken > 40) {
		      server_local_minecart_break_drops(s, cart);
		      server_local_send_w(server_local_world_of_id(s, id), (struct client_rpc) {
			      .type = CRPC_ENTITY_DESTROY,
			      .payload.entity_destroy.entity_id = id,
		      });
		      free(cart);
		      dict_entity_erase(s->entities, id);
		    } else {
		      /* Damage/shake is part of the authoritative cart snapshot. Publish
		       * promptly so client prediction cannot invent or erase hit feedback. */
		      entity_minecart_mark_snapshot_dirty(cart, true);
		    }
		    break;
		  }
		  /* VEHICLE BREAKING, boat [740c583: EntityBoat.attackEntityFrom]:
		   * flip the rock direction, arm 10 shake ticks, damage += amount*10
		   * (amount = the same per-tool strength table as the mob/cart
		   * branches); STRICT >40 dismounts the rider, drops 3 planks then
		   * 2 sticks, dies. Damage decays 1/tick in the boat's own tick.
		   * Same 36.0 feet-basis reach gate. */
		  if(ptr && *ptr && (*ptr)->type == ENTITY_BOAT) {
		    struct entity* boat = *ptr;
		    // Adversarial-review finding #10, generalized by GB-06: the shared
		    // func_6006_a reach+canEntityBeSeen gate every entity branch uses.
		    if(!server_local_entity_interaction_allowed(s, player, boat))
		      break;
		    struct item_data bheld;
		    struct item* bit
			    = inventory_get_hotbar_item(&player->inventory, &bheld)
			    ? item_get(&bheld)
			    : NULL;
		    int bstr = bit ? player_melee_damage(bit->tool.type, bit->tool.tier)
						   : player_melee_damage(TOOL_TYPE_ANY, TOOL_TIER_ANY);
		    boat->data.boat.shake_dir = (int8_t)-boat->data.boat.shake_dir;
		    boat->data.boat.shake_ticks = 10;
		    boat->data.boat.damage_taken = (int16_t)(
			    boat->data.boat.damage_taken + bstr * 10);
		    // Adversarial-review finding #8: BOAT_DISPATCH.md's pre-verified
		    // "VERBATIM ORDER" lists step 5 as setBeenAttacked() between the
		    // damage accumulation (step 4, above) and the >40 destroy check
		    // (step 6, below) [740c583: EntityBoat.attackEntityFrom]. Beta's
		    // Entity.beenAttacked is write-only -- confirmed by grepping the
		    // full 1.7.3-LTS client tree: setBeenAttacked() (Entity.java:742,
		    // called by EntityBoat/EntityMinecart's own attackEntityFrom) has
		    // ZERO readers anywhere in that tree, so this is provably inert in
		    // Beta itself, not merely unwired here. Stored anyway (not just
		    // commented away) for verbatim-order fidelity with the dispatch's
		    // citation and in case a future slice adds a reader; kept
		    // boat-scoped (not hoisted onto the shared struct entity) since no
		    // other kind needs it yet.
		    boat->data.boat.been_attacked = true;
		    if(boat->data.boat.damage_taken > BOAT_DESTROY_DAMAGE_THRESHOLD) {
		      // riddenByEntity.mountEntity(this) is Beta's forced-DISMOUNT
		      // idiom (do NOT mistranslate as re-mounting) -- same drop
		      // shape as the land-crash path (boat_spawn_destruction_drops).
		      if(boat->data.boat.occupied)
			    server_local_set_boat_occupancy(s, boat, false);
		      boat_spawn_destruction_drops_w(boat->pos,
		          server_local_entity_world(s, boat));
		      server_local_send_w(server_local_world_of_id(s, id), (struct client_rpc) {
			      .type = CRPC_ENTITY_DESTROY,
			      .payload.entity_destroy.entity_id = id,
		      });
		      free(boat);
		      dict_entity_erase(s->entities, id);
		    } else {
		      // Damage/shake is part of the boat's authoritative correction;
		      // publish promptly so client prediction cannot invent/erase
		      // hit feedback (mirrors the cart's snapshot-dirty precedent).
		      (void)boat_send_correction(boat);
		    }
		    break;
		  }
		  /* FIREBALL PUNCH-DEFLECTION [740c583: EntityFireball.attackEntityFrom]:
		   * any player hit re-aims the fireball along the attacker's look --
		   * motion = look, accel = look * 0.1 -- THE Beta ghast counter-play.
		   * Same shared func_6006_a gate as the cart above (GB-06: adds LOS). */
		  if(ptr && *ptr && (*ptr)->type == ENTITY_FIREBALL) {
		    struct entity* fb = *ptr;
		    if(!server_local_entity_interaction_allowed(s, player, fb))
		      break;
		    float crx = glm_rad(-player->rx);
		    float cry = glm_rad(player->ry + 90.0f);
		    float look[3] = {sinf(crx) * sinf(cry), cosf(cry),
						     cosf(crx) * sinf(cry)};
		    entity_fireball_deflect(fb, look);
		    break;
		  }
		  /* PAINTING single-hit pop [740c583: EntityPainting.attackEntityFrom]:
		   * `if (!this.isDead && !this.worldObj.multiplayerWorld) {
		   * setEntityDead(); setBeenAttacked(); ...drop...}` -- no health/
		   * damage accumulation of any kind, ANY hit kills it. Batch-f landing
		   * note: the draft's own 2026-08-13 base predates the GB-06 shared
		   * func_6006_a gate (server_local_entity_interaction_allowed) that
		   * the cart/boat/fireball branches above now use -- adapted to that
		   * same gate here (reach + LOS) rather than the draft's own inline
		   * 36.0-feet-basis-only check, closing the identical LOS gap for
		   * painting that GB-06 already closed for the other punchable
		   * physical objects. */
		  if(ptr && *ptr && (*ptr)->type == ENTITY_PAINTING) {
		    struct entity* pnt = *ptr;
		    if(!server_local_entity_interaction_allowed(s, player, pnt))
		      break;
		    entity_painting_drop_self(pnt, s);
		    server_local_send_w(server_local_world_of_id(s, id), (struct client_rpc) {
			    .type = CRPC_ENTITY_DESTROY,
			    .payload.entity_destroy.entity_id = id,
		    });
		    free(pnt);
		    dict_entity_erase(s->entities, id);
		    break;
		  }
		  if (ptr && *ptr && (*ptr)->type == ENTITY_MONSTER) {
		    struct entity* m = *ptr;
		    /* S1-a2 OPEN: the retaliation latch now carries the attacker
		     * IDENTITY (m->data.monster.target_actor), the AI resolves it
		     * every tick, and the wolf attack-from path and the pig-zombie
		     * pack anger stamp it too -- so a guest punch sends the mob at
		     * the GUEST, not at P1. */
		    struct actor_ident attacker_ident
		      = server_local_actor_ident(s, player);
		    /* GB-06 (docs/audit_2026-08-14_game_breakage.md): this melee path ran
		     * with NO reach/LOS authority at all -- a stale/forged/duplicated RPC
		     * could damage any monster BY ID through walls, wear the weapon, and
		     * anger pig-zombie packs. Beta rejects at the packet handler BEFORE
		     * attackEntityFrom runs, so the gate must precede the death-flop guard
		     * below (whose entity_age reset is attackEntityFrom's first statement
		     * -- a rejected packet must never reach it).
		     * [740c583: NetServerHandler.func_6006_a] */
		    if(!server_local_entity_interaction_allowed(s, player, m))
		      break;
		    // AUDIT #18 ITEM 3 (correctness): a mob already in its death flop
		    // (death_time > 0) is ALREADY DEAD -- Beta's EntityLiving.attackEntityFrom
		    // resets entityAge first, then returns false at `health <= 0`, so a dying
		    // mob can't be re-damaged, re-knocked, or re-aggroed. Without this guard a player
		    // could re-strike a flopping corpse: m->health would drop further,
		    // hurt_time/aggro_time/knockback_time would all re-arm, the corpse
		    // would re-flash red, and a knockback velocity would be written that the
		    // top-of-tick death block then silently ignores -- all non-Beta. (Loot is
		    // already protected by mob_die_tick's death_time==0 edge, so there was no
		    // double-drop.) Preserve the otherwise harmless first-statement age reset.
		    if (m->data.monster.death_time > 0) {
		      /* PIGZ-PACK: EntityPigZombie's override runs its pack anger
		         BEFORE super.attackEntityFrom reaches the age reset and the
		         `health <= 0` return [server EntityPigZombie.java:49-64,
		         EntityLiving.java:293-299], and EntityPlayer.
		         attackTargetEntityWithCurrentItem has no alive check
		         [EntityPlayer.java:468-475] -- so striking a dying pig zombie
		         still angers its pack and itself (2 draws each). */
		      if(m->data.monster.id == MONSTER_PIG_ZOMBIE)
		        server_local_pig_zombie_pack_anger(s, m, attacker_ident);
		      m->data.monster.entity_age = 0;
		      break;
		    }
		    /* A fuse-complete creeper whose blast was rejected by the Wii
		     * per-update cap is no longer an attackable living target.  Its exact
		     * source state belongs to the pending explosion and is retried before
		     * RPC processing; accepting this stale attack could delete that blast. */
		    if(m->data.monster.explosion_pending)
		      break;
		    // Per-tool attack strength on the MOB's 20-pt health scale (fist = 1,
		    // sword 5-8, tool 2-5). Empty hand / non-weapon / unknown item -> fist.
		    struct item_data held;
		    struct item* it = inventory_get_hotbar_item(&player->inventory, &held)
		                          ? item_get(&held)
		                          : NULL;
		    int dmg = it ? player_melee_damage(it->tool.type, it->tool.tier)
		                 : player_melee_damage(TOOL_TYPE_ANY, TOOL_TIER_ANY);
		    /* PIG ZOMBIE GROUP ANGER [740c583: EntityPigZombie.attackEntityFrom]:
		       when the attacker is a player, every pig zombie within the
		       expand(32,32,32) box becomeAngryAt()s BEFORE super.attackEntityFrom
		       runs -- so anger arms even on an i-frame-ABSORBED hit, which is why
		       this precedes the ABSORBED break. becomeAngryAt = target latch +
		       angerLevel 400+rand(400) + randomSoundDelay rand(40); b1.7.3 never
		       decrements angerLevel (angry until death). Neighbours first, the
		       struck one last (Beta's loop order); membership, world and box
		       rules live in server_local_pig_zombie_pack_anger. LIVING-SOUND-RNG: this runs
		       BEFORE the damage call because super.attackEntityFrom now draws
		       the hurt/death pitch on the struck mob's own Random -- Beta's
		       order is becomeAngryAt's nextInt(400), nextInt(40) THEN that
		       pitch [server EntityPigZombie.java:49-64, EntityLiving.java:340/345]. */
		    server_local_pig_zombie_pack_anger(s, m, attacker_ident);
		    enum monster_damage_result damage_result
		      = entity_is_wolf(m)
		        ? entity_wolf_attack_from(m, s, dmg, 0, true, false, false,
		                                  attacker_ident)
		        : entity_monster_apply_damage(m, dmg, false);
		    /* WEAPON WEAR -- Beta EntityPlayer.attackTargetEntityWithCurrentItem
		       (740c583):
		         the target's attackEntityFrom runs;       its result is DISCARDED
		         then, when a stack is held and the target is living,
		         the held stack's hitEntity runs on that target
		             (with the attacker passed along).
		       hitEntity is reached whether or not the hit actually landed -- the boolean
		       from attackEntityFrom is never consulted -- so an i-frame-ABSORBED hit still
		       wears the weapon. That is why this MUST precede the ABSORBED early-out
		       below; putting it after would silently make rapid clicking free.
		       Amounts are INVERTED vs the dig path: sword 1, tool 2
		       (ItemSword.java:17-19 / ItemTool.java:29-31). */
		    if(it)
		      server_local_wear_held_item(s, player, item_wear_on_hit_entity(it));
		    /* ItemSaddle.hitEntity -- the SAME unconditional hitEntity call site
		       as the weapon-wear line above (see server_local_saddle_pig), so
		       this also precedes the ABSORBED early-out below.
		       Adversarial review finding 5, CLOSED GENERALLY by GB-06: the whole
		       monster branch now sits behind the shared func_6006_a gate at its
		       top (reach + canEntityBeSeen), so this saddle call inherits it and
		       its old inner distSq<36.0 copy is gone. */
		    if(m->data.monster.id == MONSTER_PIG)
		        server_local_saddle_pig(s, player, m);
		    if(damage_result == MONSTER_DAMAGE_ABSORBED)
		      break;
		    // RETALIATION (Beta EntityMob.attackEntityFrom: playerToAttack = attacker on
		    // any damage-dealing hit, audit #14). Latch the player as the target
		    // UNCONDITIONALLY -- bypassing the can_acquire light gate AND the can_see LOS
		    // gate (findPlayerToAttack is never consulted on the revenge path). So a
		    // DAYTIME-passive spider you hit turns hostile and chases, and a mob you hit
		    // from outside its line of sight turns to pursue. Set on the SAME path as the
		    // shared resistance window (real damage only -- an absorbed hit
		    // above already `break`ed out, mirroring EntityLiving's super-gate).
		    // PASSIVE animals (Beta 1.7.3 EntityAnimal) do NOT retaliate -- no
		    // findPlayerToAttack / revenge target (panic + flee is Beta 1.8). A hit pig
		    // still takes the damage + knockback below but never latches or chases.
		    if (!monster_is_passive(m->data.monster.id)) {
		        m->data.monster.aggro_time = MOB_TARGET_RETENTION_TICKS;
		        m->data.monster.target_actor = attacker_ident;
		    }
		    if(damage_result != MONSTER_DAMAGE_FRESH)
		      break; // stronger in-window hit: excess only, no fresh-hit knockback
		    // Beta EntityLiving.knockBack: shove the mob away from the player,
		    // COMPOSED with its existing motion (halve, then add -- a second hit
		    // while a prior shove is still sliding keeps half of it);
		    // server_tick_monster suppresses the steer + speed cap for
		    // MOB_KNOCKBACK_TICKS so the shove carries.
		    // Mob motion units S2 (Q3): EntityLiving.attackEntityFrom ->
		    // knockBack(player.posX - posX, player.posZ - posZ) composed AT
		    // THE HIT on the authoritative doubles (halve, 0.4 away,
		    // motionY += (double)0.4F capped); the steer-suppression window
		    // (carve-out #2) is armed as before.
		    mob_motion_knockback(m, &m->data.monster.motion_d,
		        player->x - m->data.monster.motion_d.pos[0],
		        player->z - m->data.monster.motion_d.pos[2],
		        server_local_sound_rng());
		    m->data.monster.knockback_time = MOB_KNOCKBACK_TICKS;
		    // NOTE: a creeper killed by the player simply DIES (handled by the
		    // health<=0 branch in server_tick_monster) -- it does NOT explode.
		    // Beta detonation is the proximity fuse there, never an on-death trigger.
		  }
		  break;
	} while(0);
	if(vsp_on)
		vsp_srv_use_post(s, player, &vsp_pre, VSP_RPC_ENTITY_ATTACK);
}

static void server_local_process_entity_use_for(struct server_local* s,
	struct server_player* player, struct server_rpc* call) {
	assert(s && player && call);
	struct vsp_use_pre vsp_pre;
	bool vsp_on = vsp_armed()
		&& vsp_srv_use_pre(s, player, call->payload.entity_use.entity_id, 0,
						   &vsp_pre);
	do {
		  // Beta Packet7UseEntity flag 0 -> NetServerHandler.func_6006_a ->
		  // EntityPlayer.useCurrentItemOnEntity: the ENTITY's interact() gets first
		  // refusal; only when it returns false does the held stack's
		  // useItemOnEntity fallback run. [740c583: NetServerHandler:475,
		  // EntityPlayer.useCurrentItemOnEntity]
		  if(!player->has_pos || !player->finished_loading)
		    break;
		  if(player->active_inventory != &player->inventory)
		    break;
		  uint32_t id = call->payload.entity_use.entity_id;
		  /* A2-E review F2: only a body in this actor's own live world. */
		  struct entity* a2e_target = server_local_actor_entity_ref(s, player, id);
		  struct entity** ptr = a2e_target ? &a2e_target : NULL;
		  if(!ptr || !*ptr)
		    break;
		  /* S1-d: ENTITY_USE shares the USE slot with the air-use verb -- both
		   * are this actor's "use" action, and keeping them in one slot means
		   * no gameplay verb except SRPC_PLAYER_STATE goes untallied. */
		  server_local_note_action(s, player, SERVER_ACTION_USE);
		  /* F3 protocol boundary: minecart mount/dismount is handled only by
		   * SRPC_MINECART_RIDE_INTENT. Legacy entity-use traffic may still arrive,
		   * but it can only re-publish the server's unchanged authority. */
		  if((*ptr)->type == ENTITY_MINECART) {
		    struct entity* cart = *ptr;
		    if(cart->data.minecart.minecart_type == 0) {
		      /* F3: minecart mount/dismount is now SRPC_MINECART_RIDE_INTENT
		       * (idempotent desired-state, not a toggle). SRPC_ENTITY_USE must
		       * no longer change cart occupancy. Re-publish unchanged authority
		       * so any stale client toggle prediction is corrected. This is
		       * the ONLY reachable minecart_type==0 path in this branch --
		       * provably unchanged from before the slice. */
		      server_publish_minecart_occupancy(cart);
		      break;
		    }
		    /* Types 1 (chest) / 2 (furnace): Beta's interact() branches here
		     * instead of mounting [740c583: EntityMinecart.interact]. Same
		     * shared func_6006_a gate as the monster branch below and
		     * SRPC_ENTITY_ATTACK's own cart branch (GB-06: adds the LOS
		     * leg). [740c583: NetServerHandler.func_6006_a] */
		    if(!server_local_entity_interaction_allowed(s, player, cart))
		        break;
		    if(cart->data.minecart.minecart_type == 1) {
		      /* The cart itself IS the inventory (27 slots --
		       * getSizeInventory(), cited in entity.h's MINECART_CHEST_SLOTS).
		       * Ignore the open failure exactly like block_chest.c's
		       * onRightClick does: a soft no-op click, no crash, no partial
		       * state.
		       *
		       * R-S1a1 finding 1: this MUST be the `_for` variant with the
		       * ACTING actor. The actor-free wrapper
		       * server_local_open_entity_inventory() hard-codes
		       * `s ? &s->player : NULL` (:6127-6131), so with the guest
		       * SRPC_ENTITY_USE dispatch admitted (S1-a1) a guest's cart
		       * click seized s->player.active_inventory and pushed
		       * CRPC_OPEN_WINDOW + all 27 slots onto the HOST's untagged
		       * route -- P1's screen opening a chest P1 never clicked. The
		       * `_for` function inherits the actor's own reply hook and
		       * writes the actor's active_inventory, so the window lands on
		       * whoever clicked. Pinned by test_guest_action_verbs'
		       * chest-cart case (tests/test_local_guest.c). */
		      (void)server_local_open_entity_inventory_for(
		          s, player, &inventory_logic_minecart_chest, CHEST_SIZE,
		          cart->id, WINDOWC_MINECART_CHEST, WINDOW_TYPE_CHEST);
		      break;
		    }
		    /* minecart_type == 2 (furnace): coal fuels it (consume exactly
		     * one, +1200 fuel -- both cited in MINECART_SLICE_NOTES.md); EVERY
		     * interact -- coal or not -- (re)points the push vector away from
		     * the player, which is how a player "aims" a furnace cart's
		     * self-propulsion. Server-authoritative like the cow/sheep
		     * branches below; held/held_before are computed locally since
		     * this branch returns before that pair is computed for the
		     * monster path. [740c583: EntityMinecart.interact
		     * minecartType==2] */
		    {
		      size_t held_slot = INVENTORY_SLOT_HOTBAR
		          + inventory_get_hotbar(&player->inventory);
		      struct item_data* held = &player->inventory.items[held_slot];
		      struct item_data held_before = *held;
		      if(held->id == ITEM_COAL && held->count > 0) {
		        if(--held->count == 0)
		          *held = (struct item_data) {0};
		        cart->data.minecart.fuel += 1200;
		      }
		      cart->data.minecart.push_x = (float)(cart->pos[0] - player->x);
		      cart->data.minecart.push_z = (float)(cart->pos[2] - player->z);
		      if(held_before.id != held->id
		         || held_before.durability != held->durability
		         || held_before.count != held->count)
		        server_local_actor_slot_reply(player, &(struct client_rpc) {
		            .type = CRPC_INVENTORY_SLOT,
		            .payload.inventory_slot.window = WINDOWC_INVENTORY,
		            .payload.inventory_slot.slot = held_slot,
		            .payload.inventory_slot.item = *held,
		        });
		    }
		    break;
		  }
		  if((*ptr)->type == ENTITY_BOAT) {
		    struct entity* boat = *ptr;
		    /* Beta EntityBoat.interact (RetroMCP EntityBoat.java:336-345):
		     * an occupied boat refuses any player other than its rider.
		     * R2: resolve the complete actor/wire/world/lifetime relation;
		     * the host sentinel alone cannot identify an admitted P2 rider. */
		    if(boat->data.boat.occupied
		       && server_local_vehicle_rider(s, boat,
		              boat->data.boat.rider_actor, boat->data.boat.occupant_id)
		              != player)
		      break;
		    // Same Packet7UseEntity gate as the monster branch below [740c583:
		    // NetServerHandler.func_6006_a] -- the shared validator (GB-06)
		    // carries both the reach and the canEntityBeSeen leg finding #10
		    // added here first.
		    if(!server_local_entity_interaction_allowed(s, player, boat))
		      break;
		    // Adversarial-review finding #6: this used to be an
		    // unconditional toggle (!occupied) sent over a droppable,
		    // unacknowledged local RPC -- exactly the pattern commit
		    // 211dfb5 documented as unsafe and fixed for minecarts via
		    // idempotent desired-state. A double-press arriving before the
		    // first round trip's correction lands would toggle twice and
		    // silently self-cancel the mount. Fixed the same way MINUS the
		    // minecart's epoch/sequence machinery (boats have no per-tick
		    // rider-input stream needing an input-epoch handoff): the
		    // client now sends the state it WANTS (desired_occupied),
		    // computed once from its own not-yet-corrected local view
		    // (screen_ingame.c), so two rapid presses before either round
		    // trip completes both request the SAME state and the second
		    // collapses into a harmless idempotent re-assertion instead of
		    // a flip-back. server_local_set_boat_occupancy is already
		    // safely idempotent (re-applies the same fields, re-sends a
		    // correction).
		    if(call->payload.entity_use.desired_occupied
		       && !boat->data.boat.occupied)
		      server_local_release_actor_mounts(s, player, boat);
		    server_local_set_boat_occupancy_for(
			    s, boat, player,
			    call->payload.entity_use.desired_occupied);
		    break;
		  }
		  if((*ptr)->type != ENTITY_MONSTER)
		    break;
		  struct entity* m = *ptr;
		  // Same liveness guards as SRPC_ENTITY_ATTACK: a death-flop corpse and a
		  // cap-retained pending blast are not interactable targets.
		  if(m->data.monster.death_time > 0 || m->health <= 0
		     || m->data.monster.explosion_pending)
		    break;
		  // The shared func_6006_a authority gate (GB-06): reach AND
		  // canEntityBeSeen, for USE exactly as for ATTACK -- Beta applies one
		  // conjunction to both Packet7UseEntity legs.
		  // [740c583: NetServerHandler.java:477-488]
		  if(!server_local_entity_interaction_allowed(s, player, m))
		      break;
		  size_t held_slot = INVENTORY_SLOT_HOTBAR
		      + inventory_get_hotbar(&player->inventory);
		  struct item_data* held = &player->inventory.items[held_slot];
		  struct item_data held_before = *held;
		  bool interact_handled = false;

		  // === Phase 1: Entity.interact (Beta dispatches this FIRST) ===========
		  enum wolf_interact_result wolf_result
		      = entity_wolf_interact_for(m, s, player, held);
		  if(wolf_result != WOLF_INTERACT_NONE) {
		    interact_handled = true;
		    if(wolf_result == WOLF_INTERACT_SMOKE
		       || wolf_result == WOLF_INTERACT_HEARTS)
		      clin_rpc_send(&(struct client_rpc) {
		          .type = CRPC_WOLF_FX,
		          .payload.wolf_fx = {
		              .pos = {m->pos[0], m->pos[1] + 0.8F, m->pos[2]},
		              .hearts = wolf_result == WOLF_INTERACT_HEARTS,
		          },
		      });
		  } else if(m->data.monster.id == MONSTER_PIG
		            && m->data.monster.saddled
		            && (!m->data.monster.pig_ridden
		                || (actor_ident_equal(m->data.monster.pig_rider_actor,
		                        server_local_actor_ident(s, player))
		                    && m->data.monster.pig_rider_id
		                           == server_local_actor_wire_id(s, player)))) {
		    // EntityPig.interact [740c583]: not saddled, or a multiplayer world, or
		    // ridden by someone other than the interacting player -> refuse. Our
		    // server IS the authoritative (non-multiplayerWorld) side wolf/cow/
		    // sheep already run on, so that clause is dropped; the saddled +
		    // not-ridden-by-someone-else gate above is the rest, re-expressed
		    // positively as the branch condition. On pass, Entity.mountEntity
		    // ALWAYS runs and ALWAYS returns true: riding this entity already
		    // (interacting with the pig you already ride) TOGGLES you off --
		    // that is Beta's own dismount path, there is no separate one.
		    // pig_rider_id and pig_rider_actor name the acting player
		    // only while pig_ridden is true (entity.h).
		    if(m->data.monster.pig_ridden) {
		      server_local_pig_clear_rider(m);
		    } else {
		      // Adversarial review finding 2: Entity.mountEntity's single-rider
		      // invariant [740c583] -- switching mounts auto-releases whatever
		      // the player was ALREADY riding (`if (this.ridingEntity != null)
		      // this.ridingEntity.riddenByEntity = null;`, the general branch of
		      // mountEntity). This engine has no player-side "current mount"
		      // field (mount state lives only on the ridden entity, discovered
		      // by scanning -- entity.h's pig_ridden comment); mirror the
		      // minecart mount path's own release loop (server_local.c, the
		      // SRPC_MINECART_RIDE_INTENT desired=true branch), generalized to
		      // also release a ridden pig, so a player can never end up
		      // simultaneously claimed by two mounts.
		      server_local_release_actor_mounts(s, player, m);
		      m->data.monster.pig_ridden = true;
		      m->data.monster.pig_rider_id = server_local_actor_wire_id(s, player);
		      m->data.monster.pig_seat_correction_pending = false;
		      /* The pig tick resolves the acting actor's full lifetime. */
		      m->data.monster.pig_rider_actor
		          = server_local_actor_ident(s, player);
		    }
		    interact_handled = true;
		  } else if(m->data.monster.id == MONSTER_COW && held->id == ITEM_BUCKET
		     && held->count > 0) {
		    // EntityCow.interact: held empty bucket -> setInventorySlotContents(
		    // currentItem, new ItemStack(Item.bucketMilk)) -- the WHOLE slot is
		    // replaced (stackSize never read; safe only because buckets are
		    // maxStackSize 1, which our registry mirrors, so the in-place swap is
		    // byte-equivalent). Returns true -> no item fallback. NO sound (Beta
		    // has none), no cooldown, no server-side gate beyond the packet
		    // validation above. [740c583: EntityCow.interact]
		    *held = (struct item_data) {
		        .id = ITEM_MILK_BUCKET, .count = 1, .durability = 0};
		    interact_handled = true;
		  } else if(m->data.monster.id == MONSTER_SHEEP
		            && held->id == ITEM_SHEARS && held->count > 0
		            && !m->data.monster.sheared) {
		    // EntitySheep.interact, shears && !getSheared() branch. Server-side
		    // (Beta's !multiplayerWorld gate == this authoritative handler):
		    // setSheared(true) + drop 2 + nextInt(3) wool (2-4 -- the b1.7.3
		    // yield, NOT the modern 1-3) of the fleece colour via entityDropItem
		    // with a 1.0F y-offset. The wool colour rides item durability (the
		    // sheep death-drop convention). damageItem(1) sits OUTSIDE Beta's
		    // world gate (client prediction in MP); in this thin-client model it
		    // is applied ONCE, here, authoritatively (research caveat). interact
		    // ALWAYS returns false in Beta, so the item fallback below still runs
		    // (a no-op for shears -- ItemShears has no useItemOnEntity). A second
		    // shear on an already-sheared sheep never enters this branch: no
		    // drops, no durability. b1.7.3 sheep NEVER regrow wool (EntitySheep
		    // has no onLivingUpdate/grass-eating; regrowth is a later version) --
		    // sheared is permanent, do NOT add a regrow timer.
		    // [740c583: EntitySheep.interact, ItemShears, ItemStack.damageItem]
		    m->data.monster.sheared = true;
		    int wool_count = 2 + jrand_next_int_bound(&m->gameplay_rng, 3);
		    for(int i = 0; i < wool_count; i++) {
		      struct item_data wool = {
		          .id = BLOCK_WOOL,
		          .durability = m->data.monster.fleece_color,
		          .count = 1,
		      };
		      // FH-12: entityDropItem -> delayBeforeCanPickup = 10 (set at
		      // prepare). I02: scatter on the sheep's own Random, not a
		      // player-throw on the world stream [CFR EntitySheep.java:66-68].
		      (void)server_local_spawn_sheared_wool(s, m, &wool);
		    }
		    (void)item_stack_damage(held, 1);
		    // interact_handled stays false: Beta EntitySheep.interact returns false.
		  }

		  // === Phase 2: ItemStack.useItemOnEntity fallback ====================
		  if(!interact_handled && held->id == ITEM_DYE && held->count > 0
		     && m->data.monster.id == MONSTER_SHEEP) {
		    // Beta ItemDye's useItemOnEntity hook (mapped name saddleEntity): wool
		    // meta = BlockCloth.getBlockFromDye(damage) = ~damage & 15; only when
		    // the sheep is NOT sheared AND the colour actually differs:
		    // setFleeceColor + --stackSize. A same-colour or sheared sheep
		    // consumes NOTHING. [740c583: ItemDye.saddleEntity,
		    // BlockCloth.getBlockFromDye]
		    int dye_color = (~(int)held->durability) & 15;
		    if(!m->data.monster.sheared
		       && (int)m->data.monster.fleece_color != dye_color) {
		      m->data.monster.fleece_color = (uint8_t)dye_color;
		      if(--held->count == 0)
		        *held = (struct item_data) {0};
		    }
		  }

		  // Held-slot resync on any change (the onRightClickHandled precedent in
		  // the SRPC_BLOCK_PLACE dispatch above).
		  if(held_before.id != held->id
		     || held_before.durability != held->durability
		     || held_before.count != held->count)
		    server_local_actor_slot_reply(player, &(struct client_rpc) {
		        .type = CRPC_INVENTORY_SLOT,
		        .payload.inventory_slot.window = WINDOWC_INVENTORY,
		        .payload.inventory_slot.slot = held_slot,
		        .payload.inventory_slot.item = *held,
		    });
		  break;
	} while(0);
	if(vsp_on)
		vsp_srv_use_post(s, player, &vsp_pre, VSP_RPC_ENTITY_USE);
}

static void server_local_process(struct server_rpc* call, void* user) {
	assert(call && user);

	struct server_local* s = user;
	/* host_vehicle_smoke_8m: the cart RIDE_INTENT authority result (post-
	 * handler state, around the real case below). Dormant: one load. */
	struct vsp_use_pre vsp_ride_pre;
	bool vsp_ride_on = false;
	if(call->type == SRPC_UNLOAD_WORLD)
		(void)hw_telemetry_emit_portal_quit_server("unload_seen",
			/* A1d: the host's world slot, read even while it is not live
			 * (telemetry only; the host's world is slot 0 until A2). */
			s->worlds[0].current_tick,
			s->world_switch_phase == SERVER_WORLD_SWITCH_IDLE
				? "not_begun" : "begun");
	/* The LIVE experimental-split switch (Astra option A). Answered BEFORE the
	 * world-switch / loading / sleeping / death barriers below, exactly like
	 * SRPC_STREAM_RECOVER and SRPC_RECIPE_CRAFT: this is an owner LIFECYCLE
	 * request, not gameplay input, and the requester holds one pending toggle
	 * that only a correlated ack retires -- a silent drop behind a barrier
	 * would strand the Options row. Its own generation check is what rejects a
	 * request authored against a world that is being torn down, so the barrier
	 * it needs is stricter than the ones below, not weaker. */
	if(call->type == SRPC_SPLIT_SET) {
		server_local_split_set_request(s, call);
		return;
	}
	/* A post-ACK full-column install failure starts a voxel-only restream. The
	 * tagged request is accepted only in the exact stable generation it reports;
	 * stale/duplicate requests therefore cannot tear down a newer world. Set the
	 * simulation/input gate first, invalidate every client-stream claim, then put
	 * RESET in the server->client FIFO before this same update reaches near-send. */
	/* B2 gate 2: a world-addressed resend. Only a live world of exactly the
	 * reported generation that has a client route is re-streamed; its answer
	 * is a CRPC_STREAM_RESET stamped for that world (the client's per-world
	 * confirmation), queued before this update's near/far pass re-sends it.
	 * Anything else (stale generation, discarded world, no route) is ignored:
	 * a stale request can never tear down a newer world's stream. Player 0's
	 * own world is skipped too (Fable F6): the client only asks for worlds
	 * that are NOT its primary, so a request naming the host's current world
	 * was sent before player 0 switched into it; the primary's recovery is
	 * SRPC_STREAM_RECOVER's alone. Unlike STREAM_RECOVER there is no
	 * world_switch_phase / finished_loading gate: the exact-generation check
	 * already binds the request to the one world it named, and this path
	 * never touches the host's load state. */
	if(call->type == SRPC_WORLD_RESEND) {
		unsigned index = call->payload.world_resend.world_index;
		if(index < SERVER_LOCAL_WORLD_SLOTS) {
			struct server_world* w = &s->worlds[index];
			bool routed = a1b_world_has_client_route(w)
				|| (index != 0 && clin_world_payloads_enabled()
					&& s->a2w_stream_on[index]);
			if(server_local_world_live(w)
			   && w->generation == call->payload.world_resend.world_generation
			   && routed
			   && w != server_local_world_of(s, &s->player)) {
				s->a2w_reset_pending[index] = true;
				s->a2w_reset_generation[index] = w->generation;
				server_local_retry_world_resends(s);
			}
		}
		return;
	}
	if(call->type == SRPC_STREAM_RECOVER) {
		uint32_t epoch = call->payload.stream_recover.epoch;
		if(epoch != 0 && epoch == s->input_epoch_counter
		   && s->world_switch_phase == SERVER_WORLD_SWITCH_IDLE
		   && s->player.has_pos && s->player.finished_loading
		   && s->input_ack_pending == 0
		   && !server_transfer_actor_inert(s, &s->player)
		   && !s->load_failure_terminal
		   && !s->death_world_evict && !s->portal_job
		   && !s->portal_origin.valid) {
			if(!server_local_retry_handoff(s)) return;
			s->stream_recovery_epoch = epoch;
			server_local_restart_host_stream(s);
		}
		return;
	}
	/* The tagged client ACK is itself the FIFO ownership boundary, so it must be
	 * consumable while the barrier is armed. A stale/wrong token has no effect. */
	if(call->type == SRPC_INPUT_READY) {
		if(call->payload.input_ready.epoch != 0
		   && call->payload.input_ready.epoch == s->input_ack_pending) {
			/* Once the terminal failure has been published, even a delayed ACK for
			 * this epoch must not expose the client without an installed center. */
			if(s->input_handoff_retry_count > INPUT_HANDOFF_RETRY_MAX)
				return;
			if(call->payload.input_ready.retry) {
				if(!server_local_retry_handoff(s)) return;
				s->input_ack_pending = 0;
				s->load_failure_terminal = false;
				if(s->stream_recovery_epoch != 0) {
					server_local_restart_host_stream(s);
					return;
				}
				if(s->a2w_host_presentation) {
					struct server_world* hw = server_local_world_of(s, &s->player);
					if(hw)
						server_local_invalidate_client_chunk_stream_w(s, hw);
					s->a2w_host_marker_pending = true;
					s->a2w_host_marker_wait = 0;
					return;
				}
				s->player.finished_loading = false;
				s->load_wait_ticks = 0;
				server_local_invalidate_client_chunk_stream(s);
				if(s->stream_recovery_epoch != 0)
					clin_rpc_send(&(struct client_rpc) {.type = CRPC_STREAM_RESET});
				return;
			}
			bool vsp_host_presentation = s->a2w_host_presentation;
			if(s->player.has_pos && s->player.finished_loading
			   && (s_achievement_server != s || !s_achievement_host_epoch)) {
				s_achievement_server = s;
				s_achievement_host_epoch = game_event_next_epoch();
				if(s_achievement_host_epoch) game_event_emit(&(struct game_event){
					.kind = GE_SESSION_BEGIN, .authority = GE_AUTH_SERVER,
					.who = {.slot = 0, .generation = s_achievement_host_epoch}});
			}
			s->input_ack_pending = 0;
			s->a2w_host_presentation = false;
			if(vsp_armed())
				vsp_srv_input_ack(s, call->payload.input_ready.epoch,
								  vsp_host_presentation);
			/* Ordinary load/respawn keeps its existing ACK policy. Only live
			 * voxel recovery carries its episode budget into the clean window. */
			if(s->stream_recovery_epoch == 0)
				s->input_handoff_retry_count = 0;
			s->input_handoff_clean_ticks = 0;
			s->load_failure_terminal = false;
			s->stream_recovery_epoch = 0;
			if(s->world_switch_phase != SERVER_WORLD_SWITCH_IDLE)
				server_local_world_switch_complete(s);
			if(s->furnace_demo_open_pending) {
				s->furnace_demo_open_pending = false;
				if(!server_local_open_inventory(
					   s, &inventory_logic_furnace, FURNACE_SIZE,
					   s->furnace_demo_open_x, s->furnace_demo_open_y,
					   s->furnace_demo_open_z, WINDOWC_FURNACE,
					   WINDOW_TYPE_FURNACE))
					fprintf(stderr,
							"[furnace_demo] automatic furnace window could not be opened\n");
			}
		}
		return;
	}
	/* Minecart counters cross the gameplay barriers below: structurally valid
	 * samples must be acknowledged-and-discarded, not left to replay after a
	 * GUI, sleep, pause, load or world handoff ends. */
	/* Answered BEFORE the world-switch / loading / sleeping / death barriers
	 * below, which return WITHOUT replying. The client holds exactly one
	 * pending selected-recipe request and only a matching reply retires it, so
	 * a silent drop would strand the recipe guide; the handler enforces every
	 * one of those barriers itself and answers RECIPE_CRAFT_BUSY instead. This
	 * is also what makes the host path identical to the guest path in
	 * server_local_process_owned, which likewise dispatches this verb directly. */
	if(call->type == SRPC_RECIPE_CRAFT) {
		server_local_process_recipe_craft_for(s, &s->player, call);
		return;
	}
	if(call->type == SRPC_MINECART_CONTROL) {
		bool gameplay_allowed
			= s->world_switch_phase == SERVER_WORLD_SWITCH_IDLE
			&& !s->death_world_evict && !server_local_rpc_paused(s)
			/* Dead-dwell throttle samples are acknowledged-and-discarded,
			 * exactly this block's stated contract for every other
			 * non-gameplay window (deviation #18: the corpse may still be
			 * seated in a cart until the respawn's dismount sweep). */
			&& s->player.health > 0
			&& s->input_ack_pending == 0
			&& !server_transfer_actor_inert(s, &s->player)
			&& !s->load_failure_terminal
			&& s->player.has_pos && s->player.finished_loading
			&& !s->player.sleeping && !s->portal_job
			&& !s->portal_origin.valid
			&& !server_local_host_respawn_active(s)
			/* residency-1005/4 item 1: a body HELD by its residency
			 * recovery barrier (RECOVERING or FAILED) acknowledges the
			 * tuple and discards its impulse, like every barrier here. */
			&& !s->player.rz.recovering;
		server_local_process_minecart_control(
			s, call, gameplay_allowed);
		return;
	}

	// BEGIN_WORLD_SWITCH is a server ownership barrier, not just presentation.
	// A committed respawn is the same boundary for the remainder of this update:
	// every queued request was authored by the dead body, not the fresh player.
	// Drop all such input throughout portal placement, rollback/death retry,
	// destination loading, and the respawn update; UNLOAD could destroy a live
	// transaction and a stale body action could mutate the replacement's world.
	// LOAD alone owns dynamic data and must release its payload on rejection.
	/* All messages before the exact ACK were authored before the client consumed
	 * the epoch-bearing position and therefore belong to the old/ambiguous epoch.
	 * Messages after it are fresh-body input even when both drain in one update. */
	/* Capacity and landing replies advance an already validated transfer. The
	 * host's source-body HOLD blocks gameplay, not these control replies. */
	bool transfer_reply = call->type == SRPC_CAPACITY_REPLY
		|| call->type == SRPC_LANDING_READY;
	const struct server_transfer_txn* guest_tx = &s->transfer[ACTOR_SLOT_GUEST];
	/* While the host's own A2 loading marker waits, its admitted partner may
	 * complete a separate transfer. Only that live guest transaction's exact
	 * control reply crosses the host ACK here; Join resource replies have their
	 * separate cleanup dispatch in server_local_process_owned. */
	bool guest_transfer_reply = server_transfer_guest_continuity(s)
		&& guest_tx->open && guest_tx->actor_slot == ACTOR_SLOT_GUEST
		&& guest_tx->actor_generation == s->guest_generation
		&& ((call->type == SRPC_CAPACITY_REPLY
			&& guest_tx->state == SERVER_TRANSFER_CAPACITY
			&& call->payload.capacity_reply.request_id == guest_tx->id)
			|| (call->type == SRPC_LANDING_READY
				&& guest_tx->state == SERVER_TRANSFER_LANDING
				&& call->payload.landing_ready.token == guest_tx->id
				&& call->payload.landing_ready.slot == guest_tx->dst_slot
				&& call->payload.landing_ready.generation
					== s->worlds[guest_tx->dst_slot].generation));
	bool rejected_handoff_action = (s->input_ack_pending != 0
			&& !guest_transfer_reply)
		|| (!transfer_reply && server_transfer_actor_inert(s, &s->player));
	bool recovery_window_close = s->stream_recovery_epoch != 0
		&& call->type == SRPC_WINDOW_CLOSE;
	if(s->world_switch_phase != SERVER_WORLD_SWITCH_IDLE
	   || s->death_world_evict
	   || (s->player.has_pos && !s->player.finished_loading)
	   || rejected_handoff_action) {
		if(call->type == SRPC_UNLOAD_WORLD) {
			(void)hw_telemetry_emit_portal_quit_server(
				"unload_dropped_at_barrier", s->worlds[0].current_tick,
				"barrier");
			/* Saving was refused, not committed: preserve the pending menu
			 * owner and let it retry after the authoritative handoff. */
			clin_rpc_send(&(struct client_rpc){.type=CRPC_RETURN_INGAME});
		}
		if(call->type==SRPC_RESPAWN && call->payload.respawn.owner==0
		   && call->payload.respawn.generation==0
		   && call->payload.respawn.respawn_epoch==0 && s->player.health<=0
		   && s->world_switch_phase!=SERVER_WORLD_SWITCH_DEATH
		   && !s->death_world_evict && !server_local_host_respawn_active(s))
			server_local_host_respawn_reply(s,HOST_RESPAWN_RETRY,0);
		if(recovery_window_close)
			goto process_recovery_window_close;
		if(call->type == SRPC_LOAD_WORLD) {
			string_clear(call->payload.load_world.name);
		}
		return;
	}
	/* Beta EntityPlayer.isMovementBlocked returns true while sleeping, and the
	 * sleep GUI prevents world/inventory actions. Enforce that on the authority
	 * too so queued or forged RPCs cannot move or act during the bed sequence.
	 * Lifecycle calls and WINDOW_CLOSE remain allowed. */
	if(s->player.sleeping && server_rpc_blocked_while_sleeping(call->type))
		return;
	/* Deviation-#18 dwell: the dead body's crosshair actions drain inert (see
	 * server_rpc_blocked_while_dead's Beta runTick citation). Corpse physics
	 * (PLAYER_POS/STATE), window ops, RESPAWN and the lifecycle calls all
	 * still flow. */
	if(s->player.health <= 0 && server_rpc_blocked_while_dead(call->type))
		return;
	/* residency-1005/2: a body held by its residency recovery barrier takes
	 * no crosshair action on terrain it cannot read (the dead set). */
	if(s->player.rz.recovering && server_rpc_blocked_while_dead(call->type))
		return;
	if(server_local_host_respawn_active(s)
	   && server_rpc_blocked_while_host_respawning(call->type))
		return;

process_recovery_window_close:
	if(vsp_armed() && call->type == SRPC_MINECART_RIDE_INTENT)
		vsp_ride_on = vsp_srv_use_pre(s, &s->player,
			call->payload.minecart_ride_intent.entity_id,
			call->payload.minecart_ride_intent.request_seq, &vsp_ride_pre);
	switch(call->type) {
		case SRPC_LOCAL_GUEST:
			/* Only the source-aware mailbox dispatcher handles this protocol. */
			break;
		case SRPC_CHAT_SEND:
			/* Beta SP: EntityPlayer.sendChatMessage is an empty method, so a
			 * local world receives nothing; the composer is remote-only and
			 * never opens here (screen_chat.c). Consumed as a no-op. */
			break;
		case SRPC_ARM_SWING:
			/* Beta SP: EntityPlayerSP.swingItem sends nothing; only
			 * EntityClientPlayerMP puts Packet18 on the wire
			 * [EntityClientPlayerMP.java:118-121]. The client never emits
			 * this outside a remote session (screen_ingame.c); consumed as a
			 * no-op if it ever arrives. */
			break;
		case SRPC_CAPACITY_REPLY:
			/* Split-dims A2-T admission (client_admission.h): the client's
			 * answer to a capacity RESERVE/COMMIT/RELEASE -- a guest Join's
			 * (lane C, its own id namespace) or this transfer's. */
			if(!server_local_guest_on_capacity_reply(
				   s, call->payload.capacity_reply.request_id,
				   call->payload.capacity_reply.result,
				   call->payload.capacity_reply.ticket))
				server_transfer_on_capacity_reply(
					s, call->payload.capacity_reply.request_id,
					call->payload.capacity_reply.result,
					call->payload.capacity_reply.ticket);
			break;
		case SRPC_LANDING_READY:
			if(!server_local_guest_on_landing_ready(s,
				call->payload.landing_ready.token,
				call->payload.landing_ready.slot,
				call->payload.landing_ready.generation))
				server_transfer_on_landing_ready(
				s, call->payload.landing_ready.token,
				call->payload.landing_ready.slot,
				call->payload.landing_ready.generation);
			break;
		case SRPC_MINECART_CONTROL:
			/* Structurally consumed before every gameplay barrier above. */
			assert(false && "minecart control reached the ordinary RPC switch");
			break;
		case SRPC_SPLIT_SET:
			/* Answered before every barrier above, like STREAM_RECOVER. */
			assert(false && "split set reached the ordinary RPC switch");
			break;
		case SRPC_MINECART_RIDE_INTENT: {
			/* F3: idempotent desired-state ride request. Replaces the toggle
			 * semantics of SRPC_ENTITY_USE for carts. The input_epoch must match
			 * the current completed input handoff; stale-world requests are
			 * inert. One correlated occupancy event is emitted for every
			 * structurally valid current-epoch request, whether accepted,
			 * gameplay-rejected, or already satisfied. */
			uint32_t req_epoch
				= call->payload.minecart_ride_intent.input_epoch;
			uint32_t req_seq
				= call->payload.minecart_ride_intent.request_seq;
			uint32_t target_id
				= call->payload.minecart_ride_intent.entity_id;
			bool desired
				= call->payload.minecart_ride_intent.desired_occupied;

			/* Zero epoch/seq is reserved for server-authored unsolicited
			 * occupancy only. Require a nonzero correlation pair AND the
			 * completed-body conditions so a pre-handoff or forged zero/zero
			 * request cannot mutate occupancy. */
			if(req_epoch == 0 || req_seq == 0
			   || req_epoch != s->input_epoch_counter
			   || !s->player.has_pos || !s->player.finished_loading
			   || s->input_ack_pending != 0)
				break;

			/* Sleeping gate: a valid current-epoch request while sleeping
			 * must NOT be silently dropped. Publish unchanged
			 * authority with the request's exact epoch/seq so the client
			 * retires its pending intent. No occupancy/epoch mutation.
			 * The deviation-#18 dead dwell takes the same shape: a dead
			 * body cannot mount/dismount (Beta swallows the click), but the
			 * client's pending intent must still retire. */
			/* residency-1005/4 item 1: a body held by its residency
			 * recovery barrier answers the same way (no occupancy or ride
			 * epoch mutation; the client's pending intent retires). */
			if(s->player.sleeping || s->player.health <= 0
			   || server_local_host_respawn_active(s)
			   || s->player.rz.recovering) {
				struct entity* cart_s
					= server_local_actor_entity_ref(s, &s->player, target_id);
				if(cart_s && cart_s->type == ENTITY_MINECART) {
					server_publish_minecart_occupancy_correlated(
						cart_s, req_epoch, req_seq);
				} else {
					/* Destroyed target: correlated empty retires pending.
					 * R02 F4: stamped with the host's world (payloads ON). */
					server_local_send_host_scoped(s, (struct client_rpc) {
						.type = CRPC_MINECART_OCCUPANCY,
						.payload.minecart_occupancy.entity_id = target_id,
						.payload.minecart_occupancy.occupant_id = 0,
						.payload.minecart_occupancy.ride_epoch = 0,
						.payload.minecart_occupancy.occupied = false,
						.payload.minecart_occupancy.input_epoch = req_epoch,
						.payload.minecart_occupancy.request_seq = req_seq,
					});
				}
				break;
			}

			/* A2-E review F2: the host rides only a cart of its own world. */
			struct entity* cart
				= server_local_actor_entity_ref(s, &s->player, target_id);

			/* Destroyed target: correlated empty result retires the
			 * centralized intent even when the client entity is gone. */
			if(!cart || cart->type != ENTITY_MINECART) {
				/* R02 F4: stamped with the host's world (payloads ON). */
				server_local_send_host_scoped(s, (struct client_rpc) {
					.type = CRPC_MINECART_OCCUPANCY,
					.payload.minecart_occupancy.entity_id = target_id,
					.payload.minecart_occupancy.occupant_id = 0,
					.payload.minecart_occupancy.ride_epoch = 0,
					.payload.minecart_occupancy.occupied = false,
					.payload.minecart_occupancy.input_epoch = req_epoch,
					.payload.minecart_occupancy.request_seq = req_seq,
				});
				break;
			}

			/* Type 1 (chest) and type 2 (furnace) carts never mount -- Beta's
			 * interact() branches on minecartType before ever considering a
			 * rider [740c583: EntityMinecart.interact]. The normal client can
			 * never author this request for one (entity_minecart.c's
			 * onRightClick early-returns for non-zero types before touching
			 * gstate.players[0].ride), but this RPC is server-authoritative input and must
			 * reject a forged/stale one on its own, not rely on a well-behaved
			 * client. Republish unchanged authority like every other reject
			 * path here (occupied stays false, matching the type's fixed
			 * Open/Use rightClickText, never Ride/Dismount). */
			if(cart->data.minecart.minecart_type != 0) {
				server_publish_minecart_occupancy_correlated(
					cart, req_epoch, req_seq);
				break;
			}

			if(desired) {
				/* Mount: retain gameplay/inventory + the shared func_6006_a gate
				 * (GB-06: mounting through a wall is as much an authority
				 * bypass as attacking through one). Reject shape unchanged:
				 * republish unchanged authority with the request's
				 * correlation. */
				if(s->player.active_inventory != &s->player.inventory) {
					server_publish_minecart_occupancy_correlated(
						cart, req_epoch, req_seq);
					break;
				}
				if(!server_local_entity_interaction_allowed(s, &s->player, cart)) {
					server_publish_minecart_occupancy_correlated(
						cart, req_epoch, req_seq);
					break;
				}
				if(cart->data.minecart.occupied) {
					/* Idempotent if already us, reject if another occupant.
					 * Either way: emit unchanged authority with correlation. */
					server_publish_minecart_occupancy_correlated(
						cart, req_epoch, req_seq);
					break;
				}
				/* Release any other cart owned by the local player, AND any pig
				 * ridden by the local player [740c583: Entity.mountEntity's
				 * single-rider invariant -- `if (this.ridingEntity != null)
				 * this.ridingEntity.riddenByEntity = null;`]. Adversarial
				 * review finding 2: this loop previously released only other
				 * carts, so mounting a cart while riding a saddled pig left
				 * both mounts claiming the player simultaneously. */
				/* G8-VEHICLE-SEAMS-01: the shared release now also drops a
				 * boat the host rides (was carts + pigs only). */
				server_local_release_actor_mounts(s, &s->player, cart);
				server_set_minecart_occupancy_impl(
					s, cart, true, req_epoch, req_seq);
			} else {
				/* Dismount: if this cart records the local player as its
				 * rider, dismount even when the server's separately reported
				 * player position lags outside the reach gate. */
				if(cart->data.minecart.occupied
				   && actor_ident_is_host(cart->data.minecart.rider_actor)
				   && cart->data.minecart.occupant_id
					  == SERVER_LOCAL_PLAYER_ENTITY_ID) {
					server_set_minecart_occupancy_impl(
						s, cart, false, req_epoch, req_seq);
				} else {
					/* Not our cart: return unchanged authority. */
					server_publish_minecart_occupancy_correlated(
						cart, req_epoch, req_seq);
				}
			}
			break;
		}
		case SRPC_TOGGLE_PAUSE:
			/* The death-screen dwell is unpausable: Beta GuiGameOver swallows
			 * every key (keyTyped {}) and doesGuiPauseGame()==false keeps the
			 * world ticking under it. A HOME toggle queued behind the lethal
			 * hit must not freeze the dwell (the death commit already cleared
			 * pause). [740c583 GuiGameOver] */
			if(s->player.health <= 0)
				break;
			server_local_set_paused(s, !s->paused, 0); /* the host toggled */
			if(vsp_armed())
				vsp_srv_pause_toggled(s);
			server_local_send_w(&s->worlds[0], (struct client_rpc) {
				.type = CRPC_TIME_SET,
				.payload.time_set = s->world_time,
			});
			break;
		case SRPC_RESPAWN:
			/* The owner-aware handler consumes stale identities and active host
			 * transactions. A refused legacy request while still dead has no
			 * later completion: retire the UI request so Respawn/Exit can retry. */
			if(!server_local_host_respawn_request(s, call)
			   && !server_local_respawn_request(s) && s->player.health<=0)
				server_local_host_respawn_reply(s,HOST_RESPAWN_RETRY,0);
			break;
		case SRPC_PLAYER_POS:
			if(!server_transfer_actor_frozen(s, &s->player)
			   && !s->player.reject_pos_this_update
			   && s->player.finished_loading
			   && call->payload.player_pos.correction_seq
				  == s->player.correction_seq) {
				double nx = call->payload.player_pos.x;
				double ny = call->payload.player_pos.y;
				double nz = call->payload.player_pos.z;
				if(!level_player_position_values_valid(nx, ny, nz)
				   || !level_player_rotation_values_valid(
					   call->payload.player_pos.rx,
					   call->payload.player_pos.ry)
				   || !level_player_velocity_values_valid(
					   call->payload.player_pos.vel_x,
					   call->payload.player_pos.vel_y,
					   call->payload.player_pos.vel_z))
					break;
				/* residency-1005: refuse (and correct) a pose whose
				 * footprint is not resident, BEFORE any footstep, fall,
				 * portal or RNG side effect. */
				if(!server_local_actor_admit_pose(s, &s->player, nx, nz))
					break;
				/* v5: room for this packet's server half, before any side
				 * effect -- guaranteed by the admitted drain (ACTOR_MOTION_
				 * QUEUE); never a refusal of a delivered sample. */
				if(!server_local_actor_motion_reserve(s, &s->player))
					break;
				double previous_y = s->player.y;
				// Beta Entity.moveEntity footstep -> BlockFarmland trample, server-authoritative
				// (the client owns movement, like Beta SP's integrated server moving the player
				// entity; the world edit must be server-side). The client streams SRPC_PLAYER_POS
				// ~every tick, so each update's horizontal delta is one tick's move. Accumulate
				// Beta's distanceWalkedModified; when it crosses nextStepDistance with a solid block
				// underfoot, that is one footstep -- if the block is farmland, run its trample.
				// (SRPC_PLAYER_POS is the ONLY dropped client->server message under inbox pressure --
				// server_interface.c -- so a dropped sample merges two ticks into one delta; identical
				// to Beta along a straight line, only marginally under-counting cadence on a turn during
				// the gap. Bounded transport artifact, not a logic drift.)
				// (Mobs run the same step + walk dispatch from their own tick since R1, farmland
				// trample included, as Beta does for any canTriggerWalking entity.) Use the
				// persistent pre-call onGround/isSneaking snapshot for Beta's exact suppression;
				// testing the incoming post-move values would shift the ledge/landing edge.
				// Beta's gate is `canTriggerWalking() && !var18 &&
				// this.ridingEntity == null` -- the RIDING clause was missing
				// here, so a rider produced footsteps. It became blatant once
				// the player's position started following the cart: every
				// position update while riding is a real delta, so the odometer
				// crossed once per few blocks of TRACK and the cart clattered
				// along on footstep sounds, faster the quicker it rolled.
				// (Beta 1.7.3 plays NO minecart sound of its own -- there is no
				// playSound in EntityMinecart and no "minecart.*" sound in the
				// whole decompile -- so silence, not a rolling loop, is the
				// faithful result here.) [740c583: Entity.moveEntity:478]
				// Boat-slice: the SAME `ridingEntity == null` gate applies to a
				// boat rider (Beta EntityBoat has no playSound either).
				// A1d row #16: the step leg, shared with the guest's movement
				// route (server_local_guest_position) so both bodies run the
				// one implementation.
				/* v3: Beta handleFlying's server physics for this accepted
				 * sample (lastPos = the pose still on the body). */
				server_local_actor_motion_enqueue(s, &s->player, nx, ny, nz,
					call->payload.player_pos.vel_x,
					call->payload.player_pos.vel_z,
					call->payload.player_pos.on_ground);
				server_local_actor_movement_step(s, &s->player, nx, ny, nz);
				s->player.x = nx;
				s->player.y = ny;
				s->player.z = nz;
				s->player.rx = call->payload.player_pos.rx;
				s->player.ry = call->payload.player_pos.ry;
				if(!server_local_player_vertical_sample(
					   s, previous_y, call->payload.player_pos.vel_y,
					   call->payload.player_pos.on_ground))
					break; /* landing replaced the body; ignore corpse-owned flags */
				server_local_actor_motion_settle(&s->player);
				s->player.on_ground = call->payload.player_pos.on_ground;
				s->player.sneaking = call->payload.player_pos.sneaking;
				// Boat rider steering SOURCE: store the client-reported
				// input velocity unconditionally (mirrors on_ground/
				// sneaking above) -- entity_boat.c's boat_tick_server reads
				// this ONLY while the boat is occupied, so a nonzero value
				// while not riding is simply never consumed.
				s->player.rider_vel_x = call->payload.player_pos.vel_x;
				s->player.rider_vel_z = call->payload.player_pos.vel_z;
				s->player.has_pos = true;
				server_local_actor_pin_pose(s, &s->player);
				server_local_refresh_player_membership(s);
			}
			break;
		case SRPC_PLAYER_STATE:
			server_local_process_player_state_for(s, &s->player, call);
			break;
		case SRPC_HOTBAR_SLOT:
			server_local_process_hotbar_slot_for(s, &s->player, call);
			break;
		case SRPC_WINDOW_CLICK:
		case SRPC_SIGN_SET:
		case SRPC_WINDOW_CLOSE:
		case SRPC_WINDOW_DROP:
		case SRPC_WINDOW_TRANSACTION:
		case SRPC_WINDOW_SORT_ADMIT:
			server_local_process_window_for(s, &s->player, call);
			break;
		case SRPC_RECIPE_CRAFT:
			/* Unreachable: dispatched above, ahead of the barriers, so that a
			 * blocked request still gets its reply. Listed so -Wswitch keeps
			 * covering this enum exhaustively. */
			break;
		case SRPC_CREATIVE_GIVE:
			server_creative_handle_give(s, call);
			break;
		case SRPC_DROP_ITEM:
			server_local_process_drop_item_for(s, &s->player, call);
			break;
		case SRPC_USE_ITEM:
			server_local_process_use_item_for(s, &s->player, call);
			break;
		case SRPC_BLOCK_DIG:
			server_local_process_block_dig_for(s, &s->player, call);
			break;
		case SRPC_BLOCK_PLACE:
			server_local_process_block_place_for(s, &s->player, call);
			break;
		case SRPC_UNLOAD_WORLD:
			// Body factored into server_local_unload_world_impl (M5 seam) so
			// the live dimension switch can reuse it; the menu path keeps its
			// old-dim client reset.
			/* IMP-QUIT-UNSAVABLE: a "Quit anyway" answer excuses only the
			 * chunks it names, and only for this one request. */
			s_quit_accept_unsaved.on = call->payload.unload_world.accept_unsaved;
			s_quit_accept_unsaved.x = call->payload.unload_world.chunk_x;
			s_quit_accept_unsaved.z = call->payload.unload_world.chunk_z;
			s_quit_accept_unsaved.count = call->payload.unload_world.count;
			server_local_unload_world_impl(s, true);
			s_quit_accept_unsaved.on = false;
			break;

		case SRPC_ENTITY_ATTACK:
			server_local_process_entity_attack_for(s, &s->player, call);
			break;

		case SRPC_ENTITY_USE:
			server_local_process_entity_use_for(s, &s->player, call);
			break;
		case SRPC_LOAD_WORLD:
			// Body factored into server_local_load_world_impl (M5 seam) so the
			// live dimension switch can reuse it. RPC-payload string ownership
			// stays here: the impl COPIES the name; the payload is cleared.
			if(!s->player.has_pos && !s->load_failure_terminal
			   && !server_local_load_world_impl(
				   s, call->payload.load_world.name)) {
				/* Initial/menu loads have no portal/death retry owner. A failed
				 * pre-world reservation or archive open therefore cannot reach the
				 * streaming watchdog: publish the terminal result here instead of
				 * leaving has_pos=false behind an endless Building Terrain screen. */
				s->load_failure_terminal = true;
				s->stream_recovery_epoch = 0;
				death_telemetry_retire(s);
				fprintf(stderr,
						"[server] initial world load failed%s%s; retaining loading barrier\n",
						s_load_refusal_reason[0] ? ": " : "", s_load_refusal_reason);
				struct client_rpc failed = {.type = CRPC_LOAD_FAILED};
				snprintf(failed.payload.load_failed_reason,
						 sizeof(failed.payload.load_failed_reason), "%s",
						 s_load_refusal_reason);
				s_load_refusal_reason[0] = 0; /* one refusal, one card */
				clin_rpc_send(&failed);
			}
			string_clear(call->payload.load_world.name);
			break;
		case SRPC_INPUT_READY:
			/* Handled before the ownership barriers above. */
			break;
		case SRPC_STREAM_RECOVER:
		case SRPC_WORLD_RESEND:
			/* Handled before the ownership barriers above. */
			break;
	}
	if(vsp_ride_on)
		vsp_srv_use_post(s, &s->player, &vsp_ride_pre,
						 VSP_RPC_MINECART_RIDE_INTENT);
}

/* Liveness (hostile review, finding 3). An SRPC_RECIPE_CRAFT whose envelope
 * resolves to NO actor -- a stale guest generation, or a guest slot that is not
 * bound/confirmed -- still came from a client holding exactly one in-flight
 * request, and the contract at server_local_recipe_craft_reply says every
 * request is answered. Dropping it silently is the one way the guide can wait
 * forever. There is no actor and therefore no inventory reply route, so the
 * answer goes out on the untagged client queue echoing the payload's own
 * player/window; client_interface.c routes CRPC_RECIPE_CRAFT by that player
 * field, and client_session_window_reply retires only a request whose
 * ticket+player+window all match, so a mis-addressed answer is inert rather
 * than harmful. Nothing was inspected, let alone mutated: the reason says so. */
static void server_local_recipe_craft_drop_reply(const struct server_rpc* call) {
	clin_rpc_send(&(struct client_rpc) {
		.type = CRPC_RECIPE_CRAFT,
		.payload.recipe_craft = {
			.ticket = call->payload.recipe_craft.ticket,
			.player = call->payload.recipe_craft.player,
			.window = call->payload.recipe_craft.window,
			.reason = RECIPE_CRAFT_STALE_SESSION,
		},
	});
}

/* Dispatch from the queue envelope, never from window/action IDs. Until the
 * rest of guest gameplay is actor-aware, unsupported verbs fail closed. */
/* S1-a1: the barriers a GUEST gameplay action must clear, modelled one for one
 * on the ones server_local_process applies to the host ahead of these same
 * verbs. Two classes, kept apart on purpose:
 *   - SERVER-WIDE (a world switch, a committed respawn eviction, an outstanding
 *     input handoff) -- these drop body input for BOTH actors, so they are read
 *     off `s` exactly as the host path reads them.
 *   - ACTOR-SPECIFIC (mid-load, sleeping, dead) -- re-derived from the ACTING
 *     actor, never from s->player, so the host's state can neither admit nor
 *     block the guest. server_rpc_blocked_while_sleeping / _while_dead are the
 *     same pure classifiers the host path uses.
 * The BODY admission (s->guest_gameplay) is required too: a window-only
 * ATTACHED guest owns no body in the world and may not act on it. */
static bool server_local_guest_action_allowed(struct server_local* s,
	const struct server_player* actor, enum server_rpc_type type) {
	assert(s && actor);
	if(!s->guest_gameplay)
		return false;
	if(s->world_switch_phase != SERVER_WORLD_SWITCH_IDLE
	   || s->death_world_evict
	   || server_transfer_actor_inert(s, actor)
	   || (s->input_ack_pending != 0
		   && !server_transfer_guest_continuity(s)))
		return false;
	if(actor->has_pos && !actor->finished_loading)
		return false;
	if(actor->sleeping && server_rpc_blocked_while_sleeping(type))
		return false;
	if(actor->health <= 0 && server_rpc_blocked_while_dead(type))
		return false;
	if(actor->rz.recovering && server_rpc_blocked_while_dead(type))
		return false; /* residency-1005/2: held by its recovery barrier */
	return true;
}

static void server_local_process_owned(struct server_rpc_source source,
	struct server_rpc* call, void* user) {
	struct server_local* s = user;
	/* G9 R3 (ASTRA-G9-REVIEW-2 item 1): after a light stop (an earlier RPC
	 * of this drain whose write failed its reservation, or any stop) no
	 * further request runs: the session ends behind the terminal. Guest
	 * capacity replies still return their resource tickets. */
	if(server_local_light_stopped(s)
	   && !(call->type == SRPC_CAPACITY_REPLY
			&& svin_source_equal(source, (struct server_rpc_source){0}))) {
		s->light_rpc_dropped++;
		return;
	}
	/* Guest admission replies transfer resource ownership during host
	 * recovery too. Join refuses body creation at the same barriers;
	 * respawn records the ticket so its bounded preflight timeout can
	 * return it. Landing readiness and gameplay keep their barriers. */
	if(svin_source_equal(source, (struct server_rpc_source){0})
	   && call->type == SRPC_CAPACITY_REPLY
	   && ((call->payload.capacity_reply.request_id & GUEST_JOIN_CAP_ID_BIT)
		   || (call->payload.capacity_reply.request_id & 0xc0000000u)
			   == GUEST_RESPAWN_CAP_ID_BIT)) {
		(void)server_local_guest_on_capacity_reply(s,
			call->payload.capacity_reply.request_id,
			call->payload.capacity_reply.result, call->payload.capacity_reply.ticket);
		return;
	}
	if(call->type == SRPC_LOCAL_GUEST) {
		server_local_guest_control(s, source, call);
		return;
	}
	if(call->type == SRPC_RECIPE_CRAFT) {
		if(svin_source_equal(source, (struct server_rpc_source){0}))
			server_local_process_recipe_craft_for(s, &s->player, call);
		else if(source.slot == 1 && source.generation
			&& source.generation == s->guest_generation && s->guest_actor
			&& (!s->guest_ticket || s->guest_confirmed))
			server_local_process_recipe_craft_for(s, s->guest_actor, call);
		else
			server_local_recipe_craft_drop_reply(call);
		return;
	}
	if(svin_source_equal(source, (struct server_rpc_source){0})) {
		server_local_process(call, user);
		return;
	}
	if(source.slot != 1 || !source.generation
	   || source.generation != s->guest_generation || !s->guest_actor
	   || (s->guest_ticket && !s->guest_confirmed))
		return;
	if(call->type == SRPC_RESPAWN) {
		(void)server_local_guest_respawn(s, source, call);
		return;
	}
	/* A1d (split-dimensions-plan-0924 row #5): the respawn-plan barrier, the
	 * guest twin of the host's `server_local_host_respawn_active &&
	 * server_rpc_blocked_while_host_respawning` gate in server_local_process.
	 * Once the guest's plan has recorded its death (PREPARED) or begun
	 * LOADING, every request the old body authored -- window clicks on the
	 * corpse's inventory included -- is dropped, with the SAME classifier the
	 * host uses. Before this, PREPARED still let the corpse's WINDOW_CLICK
	 * land (C2inv row #5, "weaker"); LOADING was already closed by
	 * finished_loading. */
	if(s->guest_respawn_phase != GUEST_RESPAWN_IDLE
	   && server_rpc_blocked_while_host_respawning(call->type))
		return;
	if(call->type == SRPC_WINDOW_CLICK || call->type == SRPC_WINDOW_DROP
	   || call->type == SRPC_WINDOW_CLOSE || call->type == SRPC_WINDOW_TRANSACTION
	   || call->type == SRPC_WINDOW_SORT_ADMIT || call->type == SRPC_SIGN_SET)
		server_local_process_window_for(s, s->guest_actor, call);
	/* Movement for an ADMITTED guest body only (server_local_guest_position
	 * re-checks s->guest_gameplay itself). A window-only ATTACHED guest still
	 * cannot move anything: the flag is false, so this is inert. */
	else if(call->type == SRPC_PLAYER_POS)
		server_local_guest_position(s, call);
	/* S1-a1: the seven per-actor gameplay verbs. The generation / actor /
	 * ticket gate above has already run; this adds the body admission and the
	 * actor barriers the host path applies to the very same verbs. A request
	 * that fails any of them drops SILENTLY -- no mutation, no reply -- which
	 * is the established shape for this class (unlike RECIPE_CRAFT, these
	 * verbs hold no client-side pending token that a reply must retire). */
	else if(call->type == SRPC_HOTBAR_SLOT || call->type == SRPC_DROP_ITEM
			|| call->type == SRPC_USE_ITEM || call->type == SRPC_BLOCK_DIG
			|| call->type == SRPC_BLOCK_PLACE
			|| call->type == SRPC_ENTITY_ATTACK
			|| call->type == SRPC_ENTITY_USE
			/* S1-a2: PLAYER_STATE is the EIGHTH verb (Astra gate-1 item 2 asked
			 * for it to be explicitly included or excluded -- INCLUDED). It
			 * rides the same gate as the seven above, which is correct: it
			 * writes the acting body's on_ground/sneaking, and the host applies
			 * exactly the same barriers to its own state RPC. */
			|| call->type == SRPC_PLAYER_STATE) {
		if(!server_local_guest_action_allowed(s, s->guest_actor, call->type))
			return;
		switch(call->type) {
			case SRPC_PLAYER_STATE:
				server_local_process_player_state_for(s, s->guest_actor, call);
				break;
			case SRPC_HOTBAR_SLOT:
				server_local_process_hotbar_slot_for(s, s->guest_actor, call);
				break;
			case SRPC_DROP_ITEM:
				server_local_process_drop_item_for(s, s->guest_actor, call);
				break;
			case SRPC_USE_ITEM:
				server_local_process_use_item_for(s, s->guest_actor, call);
				break;
			case SRPC_BLOCK_DIG:
				server_local_process_block_dig_for(s, s->guest_actor, call);
				break;
			case SRPC_BLOCK_PLACE:
				server_local_process_block_place_for(s, s->guest_actor, call);
				break;
			case SRPC_ENTITY_ATTACK:
				server_local_process_entity_attack_for(s, s->guest_actor, call);
				break;
			case SRPC_ENTITY_USE:
				server_local_process_entity_use_for(s, s->guest_actor, call);
				break;
			default:
				break;
		}
	}
}

/* v5 (ASTRA-V4-REVIEW (2) queue ruling): the per-message admission of the
 * local drain. Beta NetworkManager.java:191-209 processes at most 101 packets
 * of a connection per tick and DEFERS the rest; a movement sample also waits
 * while its body's server-half queue is full (only a pause-held backlog can
 * fill it). A declined message is held by svin, with every later message of
 * its source, for the next update -- nothing is refused or dropped. */
static enum svin_admit_result server_local_admit_owned(
	struct server_rpc_source source, const struct server_rpc* call, void* user) {
	struct server_local* s = user;
	const unsigned slot = source.slot ? 1u : 0u;
	if(s->rpc_taken[slot] >= BETA_READ_PACKETS_PER_TICK)
		return SVIN_DEFER;
	if(call->type == SRPC_PLAYER_POS) {
		struct server_player* body = slot == 0 ? &s->player
			: (source.generation == s->guest_generation ? s->guest_actor
														: NULL);
		if(body && server_local_actor_motion_len(s, body)
					   >= ACTOR_MOTION_QUEUE)
			return SVIN_DEFER_STORAGE; /* only a later (unpaused) update frees it */
	}
	s->rpc_taken[slot]++;
	return SVIN_ADMIT;
}

/* V6 F1 (ASTRA-V5-REVIEW R2) progress controls: the requests a storage-held
 * source must still be able to make -- the host's pause/resume (the only
 * thing that lets a pause-held motion queue replay) and Save-and-quit
 * unload, the guest's own leave. Their handlers re-validate everything
 * (death-screen pause refusal, leave ticket/generation), so this is only
 * the route, never an authority. */
static bool server_local_control_owned(struct server_rpc_source source,
	const struct server_rpc* call, void* user) {
	(void)user;
	if(source.slot == 0)
		return call->type == SRPC_TOGGLE_PAUSE
			|| call->type == SRPC_UNLOAD_WORLD;
	return source.slot == 1 && call->type == SRPC_LOCAL_GUEST
		&& call->payload.local_guest.action == LOCAL_GUEST_LEAVE;
}
/* The state an overtaken request would have been processed under in FIFO
 * order, read just before the overtaking control runs (see
 * server_local_rpc_paused). */
static uint32_t server_local_context_owned(struct server_rpc_source source,
	void* user) {
	(void)source;
	const struct server_local* s = user;
	return SL_RPC_CTX_VALID | (s->paused ? SL_RPC_CTX_PAUSED : 0u);
}
/* Lifetime identity of a source, compared before/after a control: the host's
 * world presence (an unload clears has_pos) and the guest's admitted
 * generation (a leave that took effect clears it). Unchanged = the control
 * did not end the lifetime, so nothing it overtook is cancelled. */
static uint64_t server_local_lifetime_owned(struct server_rpc_source source,
	void* user) {
	const struct server_local* s = user;
	if(source.slot == 0)
		return s->player.has_pos ? 1u : 0u;
	return (s->guest_actor && source.generation == s->guest_generation)
		? s->guest_generation : 0u;
}
/* Overtaken input of an ended lifetime is never processed: release payload
 * ownership, and still answer the one request class whose client holds an
 * in-flight token that only a reply retires. */
static void server_local_cancel_owned(struct server_rpc_source source,
	struct server_rpc* call, void* user) {
	(void)source;
	(void)user;
	if(call->type == SRPC_LOAD_WORLD)
		string_clear(call->payload.load_world.name);
	else if(call->type == SRPC_RECIPE_CRAFT)
		server_local_recipe_craft_drop_reply(call);
}

#ifdef CAVEWII_SERVER_LOCAL_TEST
void (*server_local_test_rpc_done_hook)(struct server_local* s,
	const struct server_rpc* call);
static void server_local_process_owned_observed(struct server_rpc_source src,
	struct server_rpc* call, void* user) {
	server_local_process_owned(src, call, user);
	if(server_local_test_rpc_done_hook)
		server_local_test_rpc_done_hook(user, call);
}
#define SERVER_LOCAL_DRAIN_PROCESS server_local_process_owned_observed
#else
#define SERVER_LOCAL_DRAIN_PROCESS server_local_process_owned
#endif

static void server_local_drain_rpcs(struct server_local* s) {
	s->rpc_taken[0] = s->rpc_taken[1] = 0;
	static const struct svin_drain_ops ops = {
		.process = SERVER_LOCAL_DRAIN_PROCESS,
		.admit = server_local_admit_owned,
		.control = server_local_control_owned,
		.context = server_local_context_owned,
		.lifetime = server_local_lifetime_owned,
		.cancel = server_local_cancel_owned,
	};
	svin_process_owned_messages_ops(&ops, s);
}

/* ===== V6 F2a (ASTRA-F2-RULING 1-8): the LOCAL network phase =============
 * Beta S/net/minecraft/server/MinecraftServer.java:328-341: every world's
 * tick, light drain and entities, THEN the network
 * (NetworkManager.processReadPackets:191-209: per connection, FIFO, at most
 * 101 packets, the rest left queued), THEN the trackers. One bounded drain
 * per update, after server_local_update_body's world passes, services EVERY
 * message class (gameplay, lifecycle, control) through the same admission,
 * budget and F1 storage-hold progress route as before. Each movement sample
 * finishes its server effects at its own FIFO slot (NetServerHandler.
 * handleFlying runs onUpdateEntity inside the packet): right after its
 * handler, that source's body replays its queued events -- before the next
 * message of that source. A paused local session (s->paused at that slot)
 * or a terminal load failure keeps them queued exactly as before; a resume
 * at its own FIFO slot lets the next message replay them. The context is a
 * stack object: no new storage. */
struct server_local_net_phase {
	struct server_local* s;
	bool replayed[SERVER_LOCAL_MAX_PRESENT_ACTORS];
};
static bool server_local_net_replay_eligible(const struct server_local* s) {
	return !s->paused && !s->load_failure_terminal;
}
static void server_local_net_process(struct server_rpc_source source,
	struct server_rpc* call, void* user) {
	struct server_local_net_phase* np = user;
	struct server_local* s = np->s;
	uint64_t history = G9B_BEGIN(&s->worlds[0], "rpc-dispatch", call->type, source.slot);
	SERVER_LOCAL_DRAIN_PROCESS(source, call, s);
	G9B_END(&s->worlds[0], "rpc-dispatch", history, "ok", call->type, source.slot);
	if(!server_local_net_replay_eligible(s))
		return;
	const unsigned i = source.slot ? 1u : 0u;
	if(i == 1 && source.generation != s->guest_generation)
		return; /* a stale guest source owns no live body */
	if(server_local_replay_actor_motion_one(s, i, false))
		np->replayed[i] = true;
}
static enum svin_admit_result server_local_net_admit(
	struct server_rpc_source source, const struct server_rpc* call, void* user) {
	return server_local_admit_owned(source, call,
		((struct server_local_net_phase*)user)->s);
}
static bool server_local_net_control(struct server_rpc_source source,
	const struct server_rpc* call, void* user) {
	return server_local_control_owned(source, call,
		((struct server_local_net_phase*)user)->s);
}
static uint32_t server_local_net_context(struct server_rpc_source source,
	void* user) {
	return server_local_context_owned(source,
		((struct server_local_net_phase*)user)->s);
}
static uint64_t server_local_net_lifetime(struct server_rpc_source source,
	void* user) {
	return server_local_lifetime_owned(source,
		((struct server_local_net_phase*)user)->s);
}
static void server_local_net_cancel(struct server_rpc_source source,
	struct server_rpc* call, void* user) {
	server_local_cancel_owned(source, call,
		((struct server_local_net_phase*)user)->s);
}
static void server_local_network_phase(struct server_local* s,
	struct server_local_net_phase* np) {
	/* Input latches live from the network phase that drained them through
	 * the next update's world pass (formerly cleared at the update top,
	 * before the drain): the minecart throttle a cart consumes in its world
	 * tick, and the per-actor stale-position latch of a lifetime change. */
	dict_entity_it_t control_it;
	dict_entity_it(control_it, s->entities);
	while(!dict_entity_end_p(control_it)) {
		struct entity* e = dict_entity_ref(control_it)->value;
		if(e && e->type == ENTITY_MINECART)
			e->data.minecart.pending_throttle = 0;
		dict_entity_next(control_it);
	}
	s->player.reject_pos_this_update = false;
	if(s->guest_actor)
		s->guest_actor->reject_pos_this_update = false;
	/* G9 diagnostic survival guard: refill before the drain's damage. */
	server_local_perf_guard_before_damage(s);
	s->rpc_taken[0] = s->rpc_taken[1] = 0;
	static const struct svin_drain_ops ops = {
		.process = server_local_net_process,
		.admit = server_local_net_admit,
		.control = server_local_net_control,
		.context = server_local_net_context,
		.lifetime = server_local_net_lifetime,
		.cancel = server_local_net_cancel,
	};
	watchdog_phase_srv(WDS_RPC);
	server_diag_set(SERVER_DIAG_RPC);
	svin_process_owned_messages_ops(&ops, np);
	server_diag_set(SERVER_DIAG_POST_RPC);
}

#ifdef CAVEWII_SERVER_LOCAL_TEST
void server_local_test_process_messages(struct server_local* s) {
	assert(s);
	server_local_drain_rpcs(s);
}
void server_local_test_process_rpc(struct server_local* s,
								   struct server_rpc* call) {
	assert(s && call);
	server_local_process(call, s);
}
#endif

// ===== Living-world milestone, phase 1: natural mob spawning =====
// Beta 1.7.3-flavoured. Each spawn cycle makes a few attempts at random
// positions in a ring around the player; a candidate succeeds if it is a
// 2-tall air gap on a solid floor and dark enough for a hostile (effective
// light <= 7, where sky light is reduced by the day/night "sky subtract"
// exactly as Beta computes it). Capped, with distance despawn. The creeper
// is the only mob today (phase 2 adds zombie/skeleton/spider) — this proves
// the spawn machinery end to end on the existing entity + lighting + day/
// night systems.
#define MOB_SPAWN_CAP 10         // max live monsters in the loaded area
#define MOB_SPAWN_ATTEMPTS 6     // candidate tries per cycle
#define MOB_SPAWN_CYCLE 10       // run the cycle every N world ticks (~2 Hz)
#define MOB_SPAWN_MIN_DIST 16.0F // don't spawn on top of the player
#define MOB_SPAWN_MAX_DIST 56.0F // stay inside the loaded view (~5 chunks)

/* Existing Cave natural-spawn exclusion: horizontal distance 16, strict at
 * the boundary. Every present body suppresses a candidate, matching Beta's
 * all-player query while preserving Cave's established radius and geometry. */
/* A1c: the player-distance exclusions consider the ELIGIBLE actors of the
 * spawning world only (server_local.h, eligible-actor contract). */
static bool mob_spawn_far_from_players_w(struct server_local* s,
										 struct server_world* w, float x,
										 float z) {
	struct server_player* players[SERVER_LOCAL_MAX_PRESENT_ACTORS];
	size_t count = server_local_eligible_actors_w(
		s, w, players, SERVER_LOCAL_MAX_PRESENT_ACTORS);
	for(size_t i = 0; i < count; i++) {
		float dx = x - (float)players[i]->x;
		float dz = z - (float)players[i]->z;
		if(dx * dx + dz * dz
		   < MOB_SPAWN_MIN_DIST * MOB_SPAWN_MIN_DIST)
			return false;
	}
	return true;
}

/* Anchor gate is separate from the unconditional pack-member gate because
 * the pre-split generator's floor/ring construction was its host exclusion.
 * A1c: "a second body is present" is read per world -- fewer than two
 * eligible actors in `w` and the anchor gate stays off, exactly the
 * pre-split single-body behaviour. */
static bool mob_spawn_anchor_far_from_players_w(struct server_local* s,
												struct server_world* w,
												float x, float z) {
	struct server_player* players[SERVER_LOCAL_MAX_PRESENT_ACTORS];
	if(server_local_eligible_actors_w(s, w, players,
									  SERVER_LOCAL_MAX_PRESENT_ACTORS)
	   < 2)
		return true;
	return mob_spawn_far_from_players_w(s, w, x, z);
}


#ifdef CAVEWII_SERVER_LOCAL_TEST
bool server_local_test_mob_spawn_far_from_players(struct server_local* s,
										   float x, float z) {
	return mob_spawn_far_from_players_w(s, &s->worlds[0], x, z);
}
bool server_local_test_mob_spawn_anchor_far_from_players(
	struct server_local* s, float x, float z) {
	return mob_spawn_anchor_far_from_players_w(s, &s->worlds[0], x, z);
}
#endif
// Ghast channel (2026-09-01, ghast-starvation fix; docs/deviations.md "Nether
// ghast sightings starved by the Wii hostile cap"). [740c583: SpawnerAnimals.
// performSpawning gates each EnumCreatureType category BEFORE its chunk loop
// via `countEntities(category) <= maxNumberOfCreature * eligibleChunks/256`;
// EnumCreatureType.monster's maxNumberOfCreature is 70 -- ONE shared "monster"
// budget across every IMob, same shared-cap SHAPE this file already uses
// (MOB_SPAWN_CAP), just Wii-shrunk from ~70 (chunk-scaled) down to a flat 10.
// BiomeGenHell's list is ghast(10)/pig-zombie(10) -- fair odds per attempt --
// but a pig-zombie PACK places up to 4 (`PACK_SPAWN_MEMBERS`) per successful
// roll while a ghast places at most 1 [EntityGhast.getMaxSpawnedInChunk] AND
// needs its own extra `rand.nextInt(20)==0` [EntityGhast.getCanSpawnHere] to
// even attempt. At Beta's real ~70-slot budget that imbalance barely matters;
// crushed to a flat 10 it means 2-3 successful pig-zombie rolls (early, while
// packs are cheap) saturate MOB_SPAWN_CAP before the ghast lottery statistically
// gets a turn, and the function's own top-of-pass `monster_count >= MOB_SPAWN_CAP`
// early-return then blocks EVERY later cycle too (pig zombies barely despawn --
// neutral, no light gate, only the 1-in-800/32-block aged roll) -- measured
// 2026-09-01: 1/15 fresh populations produced a single ghast (avg 0.067) vs
// 9.933 pig-zombies. FIX: ghasts get their OWN small budget, counted and
// capped independently of the ground-hostile MOB_SPAWN_CAP -- the same
// "separate category so one can't starve another" shape ANIMAL_SPAWN_CAP /
// WATER_SPAWN_CAP already use below for the animal vs. hostile vs. water
// categories. Kept intentionally small (headroom, not parity with the real
// ~70-scaled budget) -- see test_ghast_spawn_env.c for the measured before/
// after and docs/deviations.md for the full equivalence argument (the ground/
// pig-zombie cap path is UNCHANGED whenever it isn't already full; the new
// per-pick channel-routing check only ever fires once MOB_SPAWN_CAP has ALREADY
// been reached, so it can't perturb a normal cycle's RNG draws).
#define GHAST_SPAWN_CAP 2        // independent ghast budget (Nether only)
// Passive-animal natural spawn (Beta SpawnerAnimals creatureType ANIMAL). A SEPARATE cap
// from the hostiles (Beta caps each creatureType independently: animal 15 / monster 70 --
// v2 keeps the existing FLAT cap style) so 8 wandering pigs can't starve hostile spawns or
// vice-versa. Slower cycle than hostiles (Beta's bulk animal spawn is at chunk-gen; v2's
// ongoing player-ring pass is the documented approximation). Reuses the hostile attempt/
// distance/pack constants.
#define ANIMAL_SPAWN_CAP 8       // max live passive animals in the loaded area
#define ANIMAL_SPAWN_CYCLE 20    // run the animal cycle every N world ticks (~1 Hz)
// Water-creature pass (Beta EnumCreatureType.waterCreature: the squid, cap 5,
// peaceful category). The THIRD independent spawn category -- its own cap and
// count filter (monster_is_water_creature) so squid never eat the land-animal
// cap and vice versa. Same player-ring approximation as the other passes.
#define WATER_SPAWN_CAP 5        // Beta waterCreature cap (flat, v2 style)
#define WATER_SPAWN_CYCLE 20     // run the water cycle every N world ticks (~1 Hz)
// HARDEN AUDIT #6: RETIRED. This 72-block 2D far-cull threshold is no longer used --
// the audit-#16 Beta-faithful 3D 128/32 despawn (entity_monster.c) is now the SOLE
// despawn authority. Kept as a documented historical note; the cull it gated was removed
// from server_local_spawn_mobs (it duplicated + conflicted with #16 and broke #18 flops).
#define MOB_DESPAWN_DIST 72.0F   // (unused) former near-view-edge far-cull radius

// Dungeon mob-spawner tile-entity behaviour. The spawner block's metadata holds
// Beta's pickMobSpawner index (0..3); a player within range periodically
// triggers a burst of that mob, faithful to TileEntityMobSpawner. The cadence is
// quantised to SPAWNER_CYCLE -- the exact tick delay is gameplay RNG, not world
// determinism, so it matches Beta's rate without being byte-exact.
#define SPAWNER_CYCLE 20          // run the spawner pass every N ticks (~1 s)
#define SPAWNER_RANGE 16          // player activation radius + scan half-extent
#define SPAWNER_MAX_NEARBY 6      // TileEntityMobSpawner.java:67 var10 >= 6 ends the burst
#define SPAWNER_MIN_UNITS 10      // min refire delay in cycles (~200 ticks)
#define SPAWNER_RAND_UNITS 30     // + rand(30) cycles (Beta 200 + rand(600) ticks)

// A mob can stand on a block only if it's a solid, opaque, non-transparent
// cube (approximation of Beta's isBlockNormalCube).
/* Beta World.isBlockNormalCube = isOpaqueCube() && renderAsNormalBlock(). In this
 * port `can_see_through == false` IS "opaque full cube" (stone/grass/dirt false;
 * snow layer/leaves/glass true), so that is the flag to read.
 *
 * THE BUG (2026-07-31): this used to require `opacity >= 15`. `opacity` is a
 * 4-bit designated-initializer field that the ordinary solid blocks NEVER SET --
 * block_stone.c, block_grass.c and block_dirt.c have no `.opacity` line at all,
 * so it defaults to 0. The predicate therefore returned FALSE FOR STONE, GRASS
 * AND DIRT -- i.e. for essentially every block a mob could ever stand on -- and
 * no cell in the world could pass the floor test. Measured on the maintainer's
 * save: 6162 of 6162 candidate cells rejected, the light gate never reached
 * once, zero hostile/passive/water spawns in a 30-minute session. Only the ~38
 * blocks that explicitly set `.opacity` had a value, and those are the
 * see-through ones setting it to 0 or 1, so nothing anywhere qualified. */
static bool mob_solid_floor(uint8_t type) {
	/* Delegate to THE canonical Beta isBlockNormalCube (blocks.c:47, 20 other
	 * call sites). The first fix for this spelled the predicate out a THIRD
	 * time as `!can_see_through && !transparent`, which was still wrong about
	 * TNT: the canonical helper excludes it, so Beta will not spawn a mob on a
	 * TNT block and the open-coded copy would have. Never re-open-code this. */
	return block_is_normal_cube(type);
}

/* Ghast spawn body clearance (batch 1b): Beta constructs the 4x4x4 ghast at
 * the candidate cell and requires checkIfAABBIsClear(boundingBox) (no solid
 * collision boxes inside) && !getIsAnyLiquid(boundingBox)
 * [740c583: EntityLiving.getCanSpawnHere via EntityGhast]. The box is centered
 * on the cell's X/Z with feet at Y, so scan the 4x4x4 block region it spans.
 * A conservative full-cube test (block_is_normal_cube) mirrors the collision
 * probe; liquids are checked explicitly. Runs only after the 1-in-20 ghast
 * roll, so the ~80-cell probe is rare. */
static bool ghast_spawn_clearance(struct server_world* w, w_coord_t x,
								  w_coord_t y, w_coord_t z) {
	for(int dy = 0; dy < 4; dy++)
		for(int dx = -2; dx < 2; dx++)
			for(int dz = -2; dz < 2; dz++) {
				struct block_data b;
				if(!server_world_get_block(w, x + dx, y + dy, z + dz,
										   &b))
					return false; /* unloaded: refuse rather than clip */
				if(block_is_normal_cube(b.type))
					return false;
				if(b.type == BLOCK_WATER_STILL || b.type == BLOCK_WATER_FLOW
				   || b.type == BLOCK_LAVA_STILL || b.type == BLOCK_LAVA_FLOW)
					return false;
			}
	return true;
}

static bool mob_cell_is_liquid(uint8_t type) {
	return type == BLOCK_WATER_FLOW || type == BLOCK_WATER_STILL
		|| type == BLOCK_LAVA_FLOW || type == BLOCK_LAVA_STILL;
}

/* Beta SpawnerAnimals.canCreatureTypeSpawnAtLocation, land branch [740c583]:
 *     isBlockNormalCube(x, y-1, z)
 *  && !isBlockNormalCube(x, y,   z)
 *  && !getBlockMaterial(x, y, z).isLiquid()
 *  && !isBlockNormalCube(x, y+1, z)
 *
 * The two upper clauses are NOT "must be air" -- they are "must not be a full
 * opaque cube", which admits snow layers, torches, flowers, tall grass, rails,
 * and every other non-cube block. Requiring literal BLOCK_AIR (what this port
 * did) makes SNOW-COVERED GROUND completely unspawnable, because the surface
 * stack there is grass, then a snow LAYER, then air: the snow cell fails
 * "must be air", and the air cell above it has the snow layer as its floor,
 * which fails the solid-floor test. Measured on the maintainer's save
 * (2026-07-31): every one of 6162 candidate cells died on these two clauses,
 * the light gate was never reached once, and 30 minutes of play produced no
 * hostile OR passive mobs -- the whole world surface is snow. */
static bool mob_cell_free(struct block_data* cell) {
	return !mob_solid_floor(cell->type) && !mob_cell_is_liquid(cell->type);
}

static bool mob_head_free(struct block_data* cell) {
	return !mob_solid_floor(cell->type);
}

// Beta overworld sky-light subtraction from the celestial angle:
//   f = clamp(1 - (cos(angle*2pi)*2 + 0.5), 0, 1); subtract = (int)(f*11)
// 0 at noon, 11 at midnight. daytime_celestial_angle is pure math, so it's
// server-safe; daytime_brightness is NOT (it reads client gstate), so the
// formula is inlined here rather than calling it.
int server_local_sky_subtract(uint64_t world_time) {
	// w2: the one Beta curve (daytime.c, MathHelper.cos), clear weather.
	return daytime_skylight_subtracted_at(world_time, 0.0F, 0.0F);
}

/* next-gaps-0924/F1 (docs/intent/f1-block-light-value.md): Beta's World.skylightSubtracted as
 * World.calculateSkylightSubtracted(1.0F) computes it [740c583 World.java:991-1007] -- the day/night
 * curve AND the rain / rain-weighted thunder darkening (5/16 each, func_27162_g / func_27166_f,
 * World.java:2398-2404). At partial 1.0F both strength getters collapse to the CURRENT strength.
 * The clear sun term is computed exactly as server_local_sky_subtract does (daytime_celestial_angle +
 * cosf), then daytime_skylight_subtracted (daytime.h, byte-pinned by test_daylight_curve) folds in
 * the weather with Beta's double promotion; at zero weather this is byte-identical to
 * server_local_sky_subtract for every tick (test_block_light_value_golden proves all 24000).
 * NETHER: WorldProviderHell.calculateCelestialAngle:35-37 returns 0.5F -> subtract 11 and the Hell
 * world's strengths never ramp (unobservable anyway: Nether cells store sky light 0). */
static int sl_skylight_compute_w(const struct server_local* s,
								 const struct server_world* w) {
	if(w->dimension == WORLD_DIM_NETHER)
		return 11;
	// w2: daytime.c's one Beta curve -- Java's float steps, MathHelper.cos, the 1.0F partial --
	// evaluated for the current clock (== calculateSkylightSubtracted(1.0F) at clock - 1).
	return daytime_skylight_subtracted_at(s->world_time, s->weather.rain_strength,
										  s->weather.thunder_strength);
}

static int sl_skylight_compute(const struct server_local* s) {
	return sl_skylight_compute_w(s, &s->worlds[0]);
}

/* w2: World.tick:1757-1759. The per-tick call sits after the natural spawn passes and before the random
 * ticks (server_local_update), with the clock already advanced -- exactly Beta's value for the tick that
 * started at world_time - 1. */
void server_local_skylight_recompute(struct server_local* s) {
	server_local_skylight_recompute_w(s, &s->worlds[0]);
}

/* A1c: the cached value belongs to the routed world (slot 0); another
 * world's value is computed on demand (server_local_skylight_subtracted_w)
 * and never overwrites the cache. */
void server_local_skylight_recompute_w(struct server_local* s,
									   struct server_world* w) {
	assert(s && w);
	if(w != &s->worlds[0])
		return;
	s->skylight_subtracted = sl_skylight_compute_w(s, w);
	s->skylight_cached = true;
}

int server_local_skylight_subtracted_w(const struct server_local* s,
									   const struct server_world* w) {
	assert(s && w);
	if(w == &s->worlds[0])
		return server_local_skylight_subtracted(s);
	return sl_skylight_compute_w(s, w);
}

/* W2b: World.calculateInitialSkylight:1726-1731, run by every World constructor (:99/:141/:206), i.e. on
 * every world load and portal switch here. It evaluates calculateSkylightSubtracted(1.0F) (:991) at the
 * SAVED clock itself -- getCelestialAngle(1.0F) (:1065) = calculateCelestialAngle(worldTime, 1.0F) -- so a
 * freshly loaded world holds the angle of world_time + 1 until its first tick (whose recompute then
 * yields the same value). daytime_skylight_subtracted_at(c) is angle(c - 1, 1.0F), hence the +1.
 * Strengths are 0 here, as in Beta's constructor (weather ramps later). Nether: 11 via the same branch. */
static void server_local_skylight_init(struct server_local* s) {
	assert(s);
	s->skylight_subtracted = (s->worlds[0].dimension == WORLD_DIM_NETHER)
		? sl_skylight_compute(s)
		: daytime_skylight_subtracted_at(s->world_time + 1, s->weather.rain_strength,
										 s->weather.thunder_strength);
	s->skylight_cached = true;
}

int server_local_skylight_subtracted(const struct server_local* s) {
	assert(s);
	return s->skylight_cached ? s->skylight_subtracted : sl_skylight_compute(s);
}

bool server_local_is_daytime(const struct server_local* s) {
	return server_local_skylight_subtracted(s) < 4; // World.isDaytime:692-694
}

// World.getBlockId's +-32000000 horizontal window [World.java:311-313, 538].
static bool sl_light_in_window(w_coord_t x, w_coord_t z) {
	return x >= -32000000 && z >= -32000000 && x < 32000000 && z <= 32000000;
}

// Blocks whose getBlockLightValue is the max of their neighbours [World.java:540]: stairSingle 44,
// tilledField 60, stairCompactCobblestone 67, stairCompactPlanks 53 (Block.java:67/83/90/76). The
// double slab (43) is NOT in Beta's list.
static bool sl_light_uses_neighbour_max(uint8_t type) {
	return type == BLOCK_SLAB || type == BLOCK_FARMLAND
		|| type == BLOCK_STONE_STAIRS || type == BLOCK_WOODEN_STAIRS;
}

// World.getBlockLightValue_do(x,y,z,false) [World.java:537-538, 565-583]: y<0 -> 0, y>=128 clamps to
// 127, a non-resident chunk is Beta's EmptyChunk (getBlockLightValue -> 0, EmptyChunk.java:63-65),
// else Chunk.getBlockLightValue = max(sky - subtract, block) [Chunk.java:337-350].
static int sl_light_cell(struct server_world* w, w_coord_t x, w_coord_t y,
						 w_coord_t z, int subtract) {
	if(!sl_light_in_window(x, z))
		return 15;
	if(y < 0)
		return 0;
	if(y >= WORLD_HEIGHT)
		y = WORLD_HEIGHT - 1;
	struct block_data b;
	if(!server_world_get_block(w, x, y, z, &b))
		return 0;
	int v = (int)b.sky_light - subtract;
	return (int)b.torch_light > v ? (int)b.torch_light : v;
}

#ifdef CAVEWII_SERVER_LOCAL_TEST
/* G9 item 3 (ASTRA-G9-REVIEW-2): every consumer light read (crops, grass,
 * saplings, mushrooms, mobs, natural spawning) passes here; a test traces
 * (world, cell, subtract, value) to compare with the Beta-derived field. */
void (*server_local_test_light_read_hook)(struct server_local* s,
										  struct server_world* w, w_coord_t x,
										  w_coord_t y, w_coord_t z,
										  int subtract, int value) = NULL;
void (*server_local_test_spawn_roll_hook)(struct server_world* w, w_coord_t x,
										  w_coord_t y, w_coord_t z,
										  int raw_sky, uint64_t seed_before,
										  uint64_t seed_after,
										  bool decision) = NULL;
#endif
static int server_local_block_light_value_sub_impl(struct server_local* s,
												   struct server_world* w,
												   w_coord_t x, w_coord_t y,
												   w_coord_t z, int subtract);
int server_local_block_light_value_sub_w(struct server_local* s,
										 struct server_world* w, w_coord_t x,
										 w_coord_t y, w_coord_t z,
										 int subtract) {
	const int v = server_local_block_light_value_sub_impl(s, w, x, y, z,
														  subtract);
#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(server_local_test_light_read_hook)
		server_local_test_light_read_hook(s, w, x, y, z, subtract, v);
#endif
	return v;
}

static int server_local_block_light_value_sub_impl(struct server_local* s,
												   struct server_world* w,
												   w_coord_t x, w_coord_t y,
												   w_coord_t z, int subtract) {
	assert(s && w);
	if(!sl_light_in_window(x, z))
		return 15;
	// World.getBlockId: y outside 0..127 and a non-resident chunk read id 0 (air), which never
	// takes the neighbour branch.
	struct block_data here;
	if(y >= 0 && y < WORLD_HEIGHT
	   && server_world_get_block(w, x, y, z, &here)
	   && sl_light_uses_neighbour_max(here.type)) {
		// Beta's exact read order and max fold [World.java:542-561].
		int v = sl_light_cell(w, x, y + 1, z, subtract);
		int e = sl_light_cell(w, x + 1, y, z, subtract);
		int ww = sl_light_cell(w, x - 1, y, z, subtract);
		int so = sl_light_cell(w, x, y, z + 1, subtract);
		int n = sl_light_cell(w, x, y, z - 1, subtract);
		if(e > v)
			v = e;
		if(ww > v)
			v = ww;
		if(so > v)
			v = so;
		if(n > v)
			v = n;
		return v;
	}
	return sl_light_cell(w, x, y, z, subtract);
}

int server_local_block_light_value_sub(struct server_local* s, w_coord_t x,
									   w_coord_t y, w_coord_t z, int subtract) {
	return server_local_block_light_value_sub_w(s, block_world(s), x, y, z,
												subtract);
}

int server_local_block_light_value_w(struct server_local* s,
									 struct server_world* w, w_coord_t x,
									 w_coord_t y, w_coord_t z) {
	return server_local_block_light_value_sub_w(
		s, w, x, y, z, server_local_skylight_subtracted_w(s, w));
}

int server_local_block_light_value(struct server_local* s, w_coord_t x,
								   w_coord_t y, w_coord_t z) {
	return server_local_block_light_value_w(s, block_world(s), x, y, z);
}

int server_local_hostile_spawn_light_w(struct server_local* s,
									   struct server_world* w, w_coord_t x,
									   w_coord_t y, w_coord_t z) {
	// EntityMob.getCanSpawnHere:76-82 -- during a thunderstorm (func_27160_B) the read runs with
	// skylightSubtracted forced to 10, replacing the whole weather-darkened value for this read.
	// The Nether is its own World in Beta whose strengths never ramp, so it is never thundering
	// there; this engine's weather struct is shared across a portal (see daytime.h), hence the gate.
	int subtract = (w->dimension != WORLD_DIM_NETHER
					&& server_weather_is_thundering(s))
		? 10
		: server_local_skylight_subtracted_w(s, w);
	return server_local_block_light_value_sub_w(s, w, x, y, z, subtract);
}

int server_local_hostile_spawn_light(struct server_local* s, w_coord_t x,
									 w_coord_t y, w_coord_t z) {
	return server_local_hostile_spawn_light_w(s, &s->worlds[0], x, y, z);
}

// AUDIT #18 ITEM 5 (pack-spawn): is (x,y,z) a valid hostile spawn cell? Same checks the
// natural spawn loop runs per spot -- a 2-tall air gap on a solid floor, and the Beta
// getCanSpawnHere TWO-ROLL light gate (spawner_hostile_light_ok -- see spawner.h's
// citation; 2026-08-31 fix: this used to be a flat `eff<=7` cutoff, which is NOT what
// Beta does -- see that citation for the exact two-roll shape). Factored out so each
// pack MEMBER is re-validated identically to the anchor (Beta re-runs
// canCreatureSpawnAtLocation + getCanSpawnHere per member).
/* I03: mob_spawn_spot_ok retired -- its cell part is mob_spawn_cell_ok and its
 * light rolls are spawn_candidate_rolls_ok on the candidate's own Random. */

/* I03 (board #8): a natural-spawn CANDIDATE, built the way Beta's
 * SpawnerAnimals builds one [CFR SpawnerAnimals.java:123-132]: only after the
 * RNG-free cell / player-24 / world-spawn-576 tests pass,
 * `newInstance(world)` takes the next entity id (Entity.java:54) and the
 * entity's own Random (Entity.java:96); EntitySlime's constructor then draws
 * its size `1 << rand.nextInt(3)` and `ticksTillJump = rand.nextInt(20)+10`
 * (EntitySlime.java:38-40). getCanSpawnHere then rolls on THAT Random. A
 * refused candidate keeps its consumed id, as Beta's does. The lifetime stream
 * is entity_lifetime_rng_seed(world seed, dimension, id). */
struct spawn_candidate {
	uint32_t id;
	int mob; /* the actual kind (a slime's rolled size) */
	struct java_random rng;
};

static void spawn_candidate_construct(struct server_local* s,
									  const struct server_world* w, int pick,
									  struct spawn_candidate* c) {
	c->id = server_local_gen_id(s);
	entity_lifetime_rng_seed(&c->rng, w->seed, w->dimension, c->id);
	if(pick == MONSTER_SLIME_SMALL) {
		c->mob = slime_size_from_roll(jrand_next_int_bound(&c->rng, 3));
		/* ticksTillJump: drawn to keep the stream in Beta's position; the
		 * engine's documented first-hop deferral (jump_delay 0) stands. */
		(void)jrand_next_int_bound(&c->rng, 20);
	} else {
		c->mob = pick;
	}
}

/* I04: newInstance + setLocationAndAngles: the candidate, then the WORLD
 * stream's yaw nextFloat()*360 [CFR SpawnerAnimals.java:131 natural,
 * :207 sleep]. The yaw value has no consumer here (this engine derives a
 * mob's facing from its motion); the draw keeps the world stream in Beta's
 * position. */
static void spawn_candidate_place(struct server_local* s,
								  const struct server_world* w, int pick,
								  struct spawn_candidate* c) {
	spawn_candidate_construct(s, w, pick, c);
	(void)rand_gen_flt(&s->rand_src);
}

/* getCanSpawnHere's random parts, on the candidate's own Random. The cell
 * geometry is the caller's (already tested); the EntityLiving box test stays
 * the caller's mob_spawn_bbox_clear_w, after these rolls (Beta: `&& super`). */
static bool spawn_candidate_rolls_ok(struct server_local* s,
									 struct server_world* w,
									 struct spawn_candidate* c, w_coord_t x,
									 w_coord_t y, w_coord_t z) {
	if(monster_is_slime(c->mob)) {
		/* EntitySlime.java:154: own nextInt(10) first, then the chunk
		 * Random, then posY < 16 (the size/difficulty clause is always true
		 * here: the hostile pass returns on Peaceful). */
		if(jrand_next_int_bound(&c->rng, 10) != 0)
			return false;
		if(!slime_chunk_is_slimy(w->seed, (int32_t)(x >> 4), (int32_t)(z >> 4)))
			return false;
		return y < 16;
	}
	if(c->mob == MONSTER_GHAST) {
		/* EntityGhast.java:171: own nextInt(20) first, then the box. */
		if(jrand_next_int_bound(&c->rng, 20) != 0)
			return false;
		return ghast_spawn_clearance(w, x, y, z);
	}
	if(monster_def_get(c->mob)->no_light_gate)
		return true; /* EntityPigZombie: no draw */
	/* EntityMob.java:92-102: sky > rand.nextInt(32) refuses; then
	 * getBlockLightValue <= rand.nextInt(8). */
	struct block_data here;
	if(!server_world_get_block(w, x, y, z, &here))
		return false;
#ifdef CAVEWII_SERVER_LOCAL_TEST
	const uint64_t seed_before = c->rng.seed;
#endif
	bool ok = !((int)here.sky_light > jrand_next_int_bound(&c->rng, 32))
		&& server_local_hostile_spawn_light_w(s, w, x, y, z)
			<= jrand_next_int_bound(&c->rng, 8);
#ifdef CAVEWII_SERVER_LOCAL_TEST
	if(server_local_test_spawn_roll_hook)
		server_local_test_spawn_roll_hook(w, x, y, z, (int)here.sky_light,
										  seed_before, c->rng.seed, ok);
#endif
	return ok;
}

/* The RNG-free cell part of mob_spawn_spot_ok / slime_spawn_spot_ok. */
static bool mob_spawn_cell_ok(struct server_world* w, w_coord_t x, w_coord_t y,
							  w_coord_t z) {
	if(y < 1 || y >= WORLD_HEIGHT - 1)
		return false;
	struct block_data here, above, below;
	if(!server_world_get_block(w, x, y, z, &here)
	   || !server_world_get_block(w, x, y + 1, z, &above)
	   || !server_world_get_block(w, x, y - 1, z, &below))
		return false;
	if(!mob_cell_free(&here) || !mob_head_free(&above))
		return false;
	return mob_solid_floor(below.type);
}

// Beta SpawnerAnimals (creatureType ANIMAL) spawn cell: a 2-tall air gap on a GRASS floor
// (Beta EntityAnimal.getCanSpawnHere requires the block below == grass), and BRIGHT --
// effective light max(sky, torch) > 8 (>= 9) with NO day/night sky_subtract (animals spawn
// day OR night; the subtract is the hostile darkness mechanism). The INVERSE of the hostile
// gate above: grass-not-any-solid, bright-not-dark, no-subtract.
static bool animal_spawn_spot_ok(struct server_world* w, w_coord_t x,
								 w_coord_t y, w_coord_t z) {
	if(y < 1 || y >= WORLD_HEIGHT - 1)
		return false;
	struct block_data here, above, below;
	if(!server_world_get_block(w, x, y, z, &here)
	   || !server_world_get_block(w, x, y + 1, z, &above)
	   || !server_world_get_block(w, x, y - 1, z, &below))
		return false; // chunk not loaded here
	if(!mob_cell_free(&here) || !mob_head_free(&above))
		return false; // Beta: cell/head merely must not be full cubes
	if(below.type != BLOCK_GRASS)
		return false; // animals spawn on GRASS only
	int eff = (here.sky_light > here.torch_light) ? (int)here.sky_light
												  : (int)here.torch_light;
	return eff > 8; // bright (>= 9), no sky_subtract -- day or night
}

// Adapter so the pure pack_spawn_scatter_step (combat.h) can draw from the seeded server
// RNG: next(ctx, n) == rand_gen_int(&s->rand_src, n). ctx is the server_local*. Keeping
// the scatter logic pure (driven through this fn-ptr) lets the test pin the exact 6-draw
// order with a deterministic stub while production stays on the one seeded stream.
static int mob_pack_rand(void* ctx, int n) {
	return rand_gen_int(&((struct server_local*)ctx)->rand_src, n);
}

// Per-cell SLIME spawn gate (Beta EntitySlime.getCanSpawnHere, decompile-
// verified; M2 final units), used for the anchor AND re-run per pack member
// exactly as Beta re-runs getCanSpawnHere per member. Clause order is Beta's:
// the shared air/floor cell test first (canCreatureTypeSpawnAtLocation), then
// `(size==1 || difficulty>0)` -- always TRUE here: the hostile pass returns
// before any draw on Peaceful (W1F, server_local_spawn_mobs), so running it
// implies difficulty > 0 -- then the fresh
// rand.nextInt(10)==0 roll (drawn BEFORE the y test, exactly like Beta's &&
// chain), then the chunk-seeded bit-exact nextInt(10) (slime_chunk_is_slimy,
// same chunks as a real Beta world on this seed), and posY < 16 LAST (the
// b1.7.3 ceiling -- NOT the later-version 40). NO light gate of any kind:
// EntitySlime extends EntityLiving, not EntityMob.
/* I03: slime_spawn_spot_ok retired -- its cell part is mob_spawn_cell_ok
 * and its rolls are spawn_candidate_rolls_ok on the candidate's own Random. */

/* ---- Beta EntityLiving.getCanSpawnHere box tests (natural spawns) ----------
 * [740c583: EntityLiving.java:781]
 *     checkIfAABBIsClear(boundingBox)                              (a)
 *  && getCollidingBoundingBoxes(this, boundingBox).size() == 0     (b)
 *  && !getIsAnyLiquid(boundingBox)                                 (c)
 * (a) no live preventEntitySpawning entity intersecting the box -- the flag is
 *     set by the EntityLiving / EntityMinecart / EntityTNTPrimed / EntityBoat
 *     ctors (the player is an EntityLiving); items/arrows/projectiles are
 *     spawn-transparent [740c583: each ctor].
 * (b) no BLOCK collision box intersecting [World.java:959] (the same walk also
 *     re-adds nearby entity boxes -- folded into (a) here).
 * (c) no liquid-material cell inside the box [World.java:1370].
 * Every natural land spawn runs all three via the EntityMob / EntityAnimal /
 * EntitySlime super chain; EntityPigZombie restates them verbatim
 * [EntityPigZombie.java:27]; the ghast additionally rolled its own 4x4x4
 * normal-cube clearance (ghast_spawn_clearance above -- kept: it also owns the
 * unloaded-refuse policy). EntityWaterMob keeps ONLY clause (a), so the squid
 * pass calls mob_spawn_entity_clear alone.
 *
 * WHY (VID_20260808_085407, the spider frozen on snow beside a tree):
 * mob_spawn_spot_ok tests one CELL COLUMN, but a 1.4-wide spider's physics box
 * pokes 0.2 into all four neighbour columns. Spawned at the cell-centre snap
 * beside a tree trunk it began the game already overlapping the trunk's box,
 * and the (pre-fix) threshold-0 clip in entity_intersection_threshold zeroed
 * its every move forever. Beta never CREATES that state -- getCanSpawnHere
 * probes the whole entity box -- and entity.c now also ESCAPES it if it ever
 * arises another way (block placed into a mob). The probe box here is the
 * mob's own physics box (monster_def box_w/h, the exact MOB_BBOX_THUNKS
 * construction) at the cell-centre spawn snap with y_size 0, so this gate and
 * entity_try_move agree about what overlaps; intersections are STRICT
 * (aabb_intersection_strict = Beta intersectsWith), because the box of a mob
 * standing on its floor cell shares a face with that floor and face-touching
 * must not refuse the spawn.
 *
 * RNG: the tests consume no draws. Refusals discard some spawns the old code
 * placed -- gameplay-RNG here is rate-faithful, not stream-pinned (the
 * documented ghast pack-cap precedent). */
static void mob_spawn_box_at(int mob, w_coord_t x, w_coord_t y, w_coord_t z,
							 struct AABB* out) {
	const struct monster_def* d = monster_def_get(mob);
	aabb_setsize_centered_offset(out, d->box_w, d->box_h, d->box_w, 0.0F,
								 d->box_h * 0.5F, 0.0F);
	aabb_translate(out, (float)x + 0.5F, (float)y, (float)z + 0.5F);
}

static bool mob_spawn_entity_clear(struct server_local* s,
								   struct server_world* w, struct AABB* box) {
	/* Local players are not in s->entities -- probe their boxes explicitly
	 * (player.y is the EYE; the box construction mirrors
	 * pmove_player_box). A1c: only the bodies committed to `w`. */
	struct server_player* players[SERVER_LOCAL_MAX_PRESENT_ACTORS];
	size_t player_count = server_local_eligible_actors_w(
		s, w, players, SERVER_LOCAL_MAX_PRESENT_ACTORS);
	for(size_t i = 0; i < player_count; i++) {
		struct AABB pb;
		aabb_setsize_centered(&pb, 0.6F, PLAYER_BODY_HEIGHT, 0.6F);
		aabb_translate(&pb, 0.0F,
			PLAYER_BODY_HEIGHT * 0.5F - PLAYER_EYE_HEIGHT, 0.0F);
		aabb_translate(&pb, (float)players[i]->x, (float)players[i]->y,
					   (float)players[i]->z);
		if(aabb_intersection_strict(box, &pb))
			return false;
	}

	dict_entity_it_t it;
	dict_entity_it(it, s->entities);
	while(!dict_entity_end_p(it)) {
		struct entity* e = dict_entity_ref(it)->value;
		dict_entity_next(it);
		if(!e || e->delay_destroy == 0)
			continue; // same live filter as the cap counters
		if(server_local_entity_world(s, e) != w)
			continue; // A1c: another world's body never blocks this spawn
		/* Beta preventEntitySpawning ctors: living + minecart + primed TNT +
		 * boat [740c583: EntityBoat.<init> "this.preventEntitySpawning =
		 * true;"] -- boats now exist (boat-slice). */
		if(e->type != ENTITY_MONSTER && e->type != ENTITY_MINECART
		   && e->type != ENTITY_PRIMED_TNT && e->type != ENTITY_LOCAL_PLAYER
		   && e->type != ENTITY_BOAT)
			continue;
		struct AABB eb;
		entity_make_world_bbox(e, &eb);
		if(aabb_intersection_strict(box, &eb))
			return false;
	}
	return true;
}

static bool mob_spawn_box_blocked_w(struct server_world* w, struct AABB* box) {
	/* Beta World.getCollidingBoundingBoxes cell walk [World.java:959]; bounds
	 * mirror entity_intersection (incl. the fence -1 Y rim) so the gate scans
	 * exactly what the physics sweep scans. Unloaded cells contribute no box,
	 * exactly like Beta's blockExists guard -- safe because an entity that
	 * later materialises embedded can now slide out (entity.c). */
	w_coord_t min_x = (w_coord_t)floorf(box->x1);
	w_coord_t min_y = (w_coord_t)floorf(box->y1) - 1;
	if(min_y < 0)
		min_y = 0;
	w_coord_t min_z = (w_coord_t)floorf(box->z1);
	w_coord_t max_x = (w_coord_t)ceilf(box->x2) + 1;
	w_coord_t max_y = (w_coord_t)ceilf(box->y2) + 1;
	if(max_y > WORLD_HEIGHT - 1)
		max_y = WORLD_HEIGHT - 1;
	w_coord_t max_z = (w_coord_t)ceilf(box->z2) + 1;

	for(w_coord_t x = min_x; x < max_x; x++)
		for(w_coord_t z = min_z; z < max_z; z++)
			for(w_coord_t y = min_y; y < max_y; y++) {
				struct block_data blk;
				if(!server_world_get_block(w, x, y, z, &blk)
				   || !blocks[blk.type])
					continue;
				struct block* b = blocks[blk.type];
				struct block_info bi
					= (struct block_info) {.block = &blk,
										   .neighbours = NULL,
										   .x = x,
										   .y = y,
										   .z = z};
				// get_piston_moving stays NULL: an id-36 cell yields no box,
				// exactly Beta's orphan-moving-block behaviour (blocks_data.h).
				size_t count = b->getBoundingBox(&bi, true, NULL);
				if(!count)
					continue;
				struct AABB bbox[count];
				b->getBoundingBox(&bi, true, bbox);
				for(size_t k = 0; k < count; k++) {
					aabb_translate(bbox + k, x, y, z);
					if(aabb_intersection_strict(box, bbox + k))
						return true;
				}
			}
	return false;
}

static bool mob_spawn_box_blocked(struct server_local* s, struct AABB* box) {
	return mob_spawn_box_blocked_w(&s->worlds[0], box);
}

static bool mob_spawn_box_liquid(struct server_world* w, struct AABB* box) {
	/* Beta World.getIsAnyLiquid [World.java:1370]: floor(min)..floor(max+1)
	 * per axis (no -1 rim); any liquid cell refuses. */
	w_coord_t min_x = (w_coord_t)floorf(box->x1);
	w_coord_t min_y = (w_coord_t)floorf(box->y1);
	if(min_y < 0)
		min_y = 0;
	w_coord_t min_z = (w_coord_t)floorf(box->z1);
	w_coord_t max_x = (w_coord_t)floorf(box->x2 + 1.0F);
	w_coord_t max_y = (w_coord_t)floorf(box->y2 + 1.0F);
	if(max_y > WORLD_HEIGHT)
		max_y = WORLD_HEIGHT;
	w_coord_t max_z = (w_coord_t)floorf(box->z2 + 1.0F);

	for(w_coord_t x = min_x; x < max_x; x++)
		for(w_coord_t z = min_z; z < max_z; z++)
			for(w_coord_t y = min_y; y < max_y; y++) {
				struct block_data blk;
				if(server_world_get_block(w, x, y, z, &blk)
				   && mob_cell_is_liquid(blk.type))
					return true;
			}
	return false;
}

static bool mob_spawn_bbox_clear_w(struct server_local* s,
								   struct server_world* w, int mob,
								   w_coord_t x, w_coord_t y, w_coord_t z) {
	struct AABB box;
	mob_spawn_box_at(mob, x, y, z, &box);
	return mob_spawn_entity_clear(s, w, &box)
		&& !mob_spawn_box_blocked_w(w, &box) && !mob_spawn_box_liquid(w, &box);
}

static bool mob_spawn_bbox_clear(struct server_local* s, int mob, w_coord_t x,
								 w_coord_t y, w_coord_t z) {
	return mob_spawn_bbox_clear_w(s, &s->worlds[0], mob, x, y, z);
}

/* Test hook: the gate is static; tests probe it directly (mirrors the other
 * server_local_test_* accessors). */
bool server_local_test_mob_spawn_bbox_clear(struct server_local* s, int mob,
											w_coord_t x, w_coord_t y,
											w_coord_t z) {
	return mob_spawn_bbox_clear(s, mob, x, y, z);
}

// Spider jockey: called once for EVERY spider this pass successfully placed
// (the pack anchor AND each pack member, independently) [740c583:
// SpawnerAnimals.performSpawning calls creatureSpecificInit(var43, ...)
// right after EACH member's own entityJoinedWorld -- not once per pack].
// `spider` is the just-spawned, already-joined entity; a miss (99% of the
// time) is a single consumed RNG draw and nothing else. A hit spawns an
// EntitySkeleton at the spider's own final position [740c583:
// creatureSpecificInit's var2/var3/var4 ARE the spider's own spawn
// coordinates] and mounts it via entity_monster_mount_jockey. The skeleton
// is exempt from this pass's monster_count/MOB_SPAWN_CAP accounting -- Beta
// spawns it OUTSIDE and after the cap-governed spawn list entirely (the
// jockey is not itself a `SpawnListEntry` draw) -- matching the documented
// GHAST-pack-cap precedent's "count only what Beta's own cap counts" rule.
static void server_local_spawn_spider_jockey_w(
	struct server_local* s, struct server_world* w, struct entity* spider) {
	if(!spider || spider->data.monster.id != MONSTER_SPIDER)
		return;
	if(!spider_jockey_roll(&s->rand_src))
		return;
	struct entity* skeleton = server_local_spawn_monster_at_w(
		w, (vec3) {spider->pos[0], spider->pos[1], spider->pos[2]},
		MONSTER_SKELETON);
	if(!skeleton)
		return;
	entity_monster_mount_jockey(spider, skeleton);
}

static void server_local_spawn_spider_jockey(
	struct server_local* s, struct entity* spider) {
	server_local_spawn_spider_jockey_w(s, &s->worlds[0], spider);
}

/* SpawnerAnimals.canCreatureTypeSpawnAtLocation, land branch [740c583 SpawnerAnimals.java:153-155]
 * on EmptyChunk-semantics reads (non-resident = air): the same predicates as the natural pass. */
static bool sl_sleep_monster_can_spawn_at(struct server_local* s, w_coord_t x,
										  w_coord_t y, w_coord_t z) {
	struct block_data below, here, above;
	sl_sleep_block(s, x, y - 1, z, &below);
	sl_sleep_block(s, x, y, z, &here);
	sl_sleep_block(s, x, y + 1, z, &above);
	return mob_solid_floor(below.type) && mob_cell_free(&here)
		&& mob_head_free(&above);
}

/* SpawnerAnimals.performSleepSpawning [740c583 SpawnerAnimals.java:169-246] for the local
 * sleeper (the host; see server_local_all_fully_asleep for the guest). Runs on the ONE tick a
 * sleep completes. RNG: every sim draw on s->rand_src in Beta's order (world.rand AND the
 * entity-rand light rolls -- this engine's one-stream spawn convention); the voice pitch on the
 * sound stream. Returns true iff a monster was spawned (the sleeper is then already awake). */
/* One sleeper's leg of SpawnerAnimals.performSleepSpawning [SpawnerAnimals.java:201-280]:
 * the 20 candidates around THIS sleeper's position; a spawn wakes THIS sleeper
 * (`entityplayer.wakeUpPlayer(true, false, false)`, :274) and returns true. */
static bool server_local_sleep_spawn_leg(struct server_local* s,
										 struct server_player* sleeper) {
	// nightSpawnEntities [SpawnerAnimals.java:10]: {EntitySpider, EntityZombie, EntitySkeleton}.
	static const int night_mobs[3] = {MONSTER_SPIDER, MONSTER_ZOMBIE, MONSTER_SKELETON};
	const double pos_x = sleeper->x, pos_y = sleeper->y, pos_z = sleeper->z;
	const w_coord_t fx = (w_coord_t)floor(pos_x), fy = (w_coord_t)floor(pos_y),
					fz = (w_coord_t)floor(pos_z);
	for(int attempt = 0; attempt < 20; attempt++) {
		// Java evaluates `floor(pos) + nextInt(n) - nextInt(n)` left to right: sequence it.
		int ra = rand_gen_int(&s->rand_src, 32);
		int rb = rand_gen_int(&s->rand_src, 32);
		w_coord_t x = fx + ra - rb;
		ra = rand_gen_int(&s->rand_src, 32);
		rb = rand_gen_int(&s->rand_src, 32);
		w_coord_t z = fz + ra - rb;
		ra = rand_gen_int(&s->rand_src, 16);
		rb = rand_gen_int(&s->rand_src, 16);
		w_coord_t y0 = fy + ra - rb;
		if(y0 < 1)
			y0 = 1;
		else if(y0 > 128)
			y0 = 128;
		int mob = night_mobs[rand_gen_int(&s->rand_src, 3)];

		w_coord_t y = y0;
		while(y > 2 && !sl_sleep_is_normal_cube(s, x, y - 1, z))
			y--;
		while(!sl_sleep_monster_can_spawn_at(s, x, y, z) && y < y0 + 16 && y < 128)
			y++;
		if(!(y < y0 + 16 && y < 128))
			continue;

		/* I03 (board #8): newInstance(world) FIRST [SpawnerAnimals.java:201]: the
		 * candidate takes its id and own Random (kept even if refused). Overworld-
		 * only: sleeping happens in slot 0, where this leg spawns. */
		// I04: newInstance, then setLocationAndAngles(x+0.5, y, z+0.5,
		// rand.nextFloat()*360, 0) [:207]: the WORLD yaw draw is real even though
		// the final placement below resets the yaw to 0 (spawn_candidate_place).
		struct spawn_candidate sc;
		spawn_candidate_place(s, &s->worlds[0], mob, &sc);
		// getCanSpawnHere [:208]: EntityMob's two light rolls (raw sky vs nextInt(32), then
		// var4 vs nextInt(8) -- F1's server_local_hostile_spawn_light) on the CANDIDATE's
		// own Random, then EntityLiving's box test.
		struct block_data here;
		sl_sleep_block(s, x, y, z, &here);
		if((int)here.sky_light > jrand_next_int_bound(&sc.rng, 32)
		   || server_local_hostile_spawn_light(s, x, y, z)
				> jrand_next_int_bound(&sc.rng, 8))
			continue;
		if(!mob_spawn_bbox_clear(s, mob, x, y, z))
			continue;

		// Pathfinder.createEntityPathTo(mob, sleeper, 32.0F): the sleeper's posX/posZ and
		// boundingBox.minY = posY - yOffset, yOffset 0.2 while sleeping (EntityPlayer.sleepInBedAt).
		const struct monster_def* d = monster_def_get(mob);
		struct path_entity path;
		if(!monster_path_to_entity(s, (float)x + 0.5F, (float)y, (float)z + 0.5F,
								   d->box_w, d->box_h, (float)pos_x,
								   (float)(pos_y - 0.2), (float)pos_z, 32.0F, &path)
		   || path.length <= 1)
			continue;
		const struct path_waypoint* end = &path.points[path.length - 1];
		if(!(fabs((double)end->x - pos_x) < 1.5 && fabs((double)end->z - pos_z) < 1.5
			 && fabs((double)end->y - pos_y) < 1.5))
			continue;

		// Placement: BlockBed.getNearestEmptyChunkCoordinates(floor(sleeper pos), 1), else the
		// candidate (x, y+1, z) [SpawnerAnimals.java:229-234].
		w_coord_t cx, cy, cz;
		if(!bed_nearest_empty_cell(s, fx, fy, fz, 1, &cx, &cy, &cz)) {
			cx = x;
			cy = y + 1;
			cz = z;
		}
		struct entity* e = server_local_spawn_monster_at_id_w(&s->worlds[0],
			(vec3) {(float)cx + 0.5F, (float)cy, (float)cz + 0.5F}, mob, sc.id,
			&sc.rng);
		if(!e) {
			/* w4: Beta's entityJoinedWorld cannot fail; this engine's entity pool /
			 * dictionary can. A failed allocation is "no spawn": no wake from this path,
			 * so the caller's skip to dawn proceeds, and no jockey roll is drawn. */
			static bool logged = false;
			if(!logged) {
				logged = true;
				fprintf(stderr, "[server] sleep spawn: monster allocation failed; night "
								"skip proceeds (logged once)\n");
			}
			return false;
		}
		server_local_spawn_spider_jockey(s, e); // creatureSpecificInit
		// the sleeper's wakeUpPlayer(true, false, false) [SpawnerAnimals.java:237]: ONLY the
		// sleeper the monster spawned beside wakes; the others keep sleeping. Setting the
		// spawned and stop flags (:239-240) cancels the skip to dawn and end THIS sleeper's
		// 20 candidates -- the iterator goes on to the next sleeper (:174-183).
		server_local_wake_actor(s, sleeper, true, false);
		{ // playLivingSound [SpawnerAnimals.java:238 var14.playLivingSound()]
			/* LIVING-SOUND-RNG: the pitch floats are the NEW mob's own Random
			 * (its lifetime stream, already advanced by getCanSpawnHere's light
			 * rolls) and are drawn only when getLivingSound() is non-null
			 * [EntityLiving.playLivingSound]. */
			uint16_t idle_sid;
			float vol;
			audio_mob_sounds(mob, &idle_sid, NULL, NULL, &vol);
			if(idle_sid != AUDIO_SOUND_NONE)
				server_local_emit_sound(idle_sid,
					(vec3) {e->pos[0], e->pos[1], e->pos[2]}, vol,
					mob_living_sound_pitch(e));
		}
		return true;
	}
	return false;
}

/* SpawnerAnimals.performSleepSpawning(World, List playerEntities) [decompile
 * ../mcb173-retromcp/minecraft/src_original/net/minecraft/src/SpawnerAnimals.java:169-246]:
 * an iterator over the player list (:172) in an endless loop (:174) walks the WHOLE list --
 * that returns the result once the iterator is exhausted (:179-180), one sleeper per pass (:183)
 * -- and every sleeper gets its 20 candidates (:190, fewer than 20 tries and no stop flag). A spawn sets
 * both the result and stop flags (:239-240): the stop flag ends only THAT sleeper's candidates; the result is
 * the accumulated result returned once the iterator is exhausted. So a spawn beside the
 * host does NOT stop the guest's leg: the guest still draws its candidates (the world RNG
 * stream advances by them) and can be ambushed and woken in the same tick. World.tick
 * (World.java:1739-1751) skips to dawn and wakes everyone only when the accumulated
 * result is false (:1748-1751). playerEntities is the join order (World.java:901): the
 * host, then the admitted guest body. Only actors committed to the Overworld are
 * sleepers of this World (isAllPlayersFullyAsleep, :2379, counted them the same way, so
 * a host parked in the Nether leaves a guest-only Overworld quorum whose leg runs alone).
 * Engine-only divergence, noted: a leg's monster ALLOCATION failure answers false for
 * that leg and the walk continues; Beta's entityJoinedWorld cannot fail there (its
 * constructor-exception path, :218-220, returns the result at once). A1d L1; Opus G6SEP H1. */
static bool server_local_sleep_spawn(struct server_local* s) {
	struct server_player* bodies[2] = {&s->player,
		SERVER_LOCAL_GUEST_CAN_SLEEP ? s->guest_actor : NULL};
	bool any = false; /* var2: accumulated over EVERY sleeper, never an early return */
	for(size_t i = 0; i < 2; i++) {
		struct server_player* p = bodies[i];
		if(!p || !p->sleeping || !server_local_sleep_actor_in_overworld(s, p))
			continue;
		any |= server_local_sleep_spawn_leg(s, p);
	}
	return any;
}
static void server_local_spawn_mobs_w(struct server_local* s,
									  struct server_world* w) {
	/* A1c (eligible-actor contract, server_local.h): the pass runs for the
	 * actors committed to `w` only; with none there is no eligible chunk and
	 * therefore no attempt and no draw [740c583: SpawnerAnimals.performSpawning
	 * builds eligibleChunksForSpawning from worldObj.playerEntities]. */
	struct server_player* actors[SERVER_LOCAL_MAX_PRESENT_ACTORS];
	size_t actor_count = server_local_eligible_actors_w(
		s, w, actors, SERVER_LOCAL_MAX_PRESENT_ACTORS);
	if(actor_count == 0)
		return;
	// W1F: Minecraft.java:1151 setAllowedMobSpawns(difficulty > 0, true); with
	// hostile spawns off SpawnerAnimals.performSpawning:47 skips the monster
	// EnumCreatureType before its cap count or any draw. That makes the
	// EntityGhast.java:152 / EntityPigZombie.java:28 / EntitySlime.java:136
	// `difficulty > 0` clauses true whenever this pass runs at all.
	if(!difficulty_allows_hostile_spawns(server_local_difficulty(s)))
		return;
	// One pass: count live monsters for the spawn cap.
	//
	// HARDEN AUDIT #6: the redundant 72-block 2D far-cull that used to live here (set
	// delay_destroy=0 on any mob past MOB_DESPAWN_DIST) was REMOVED. It DUPLICATED and
	// CONFLICTED with the audit-#16 Beta-faithful 3D 128/32 natural despawn in
	// entity_monster.c (server_tick_monster), which runs for EVERY live mob EVERY tick.
	// Two problems it caused: (1) DETERMINISM -- by reaping mobs on a different schedule
	// (this pass runs only every MOB_SPAWN_CYCLE ticks, on a 2D 72-block test) it changed
	// which mobs reached #16's seeded despawn ROLL, shifting the shared rand_src stream;
	// (2) it set delay_destroy=0 on a mob regardless of state, cutting an audit-#18 death
	// FLOP short for a corpse that died past 72 blocks. #16 now SOLELY owns despawn (it is
	// the Beta-authoritative path: 3D feet-to-feet distance, instant >128, 1/800 roll
	// >600-age inside 32). This loop keeps ONLY the live-monster COUNT for the spawn cap.
	//
	// Ghast channel (see GHAST_SPAWN_CAP above): ghasts are counted into their OWN
	// `ghast_count`, not `monster_count`, so a shelf of pig-zombies sitting at
	// MOB_SPAWN_CAP can never crowd out ghast headroom (and vice versa). This is
	// the SAME single dict pass, just a second counter -- no extra O(N) walk.
	int monster_count = 0;
	int ghast_count = 0;
	dict_entity_it_t it;
	dict_entity_it(it, s->entities);
	while(!dict_entity_end_p(it)) {
		struct entity* e = dict_entity_ref(it)->value;
		// HOSTILES only -- passive animals have their OWN cap (ANIMAL_SPAWN_CAP, counted
		// in server_local_spawn_animals) so a herd of pigs can't fill the hostile cap.
		if(e && server_local_entity_world(s, e) == w
		   && e->type == ENTITY_MONSTER && e->delay_destroy != 0
		   && !monster_is_passive(e->data.monster.id)) {
			if(e->data.monster.id == MONSTER_GHAST)
				ghast_count++;
			else
				monster_count++;
		}
		dict_entity_next(it);
	}

	// Nether-only headroom: only the Nether's spawn table can ever pick a ghast
	// (overworld nether_weight is unset -- see monster_spawn_pick_dim), so gating
	// the "keep trying for ghast" escape on dimension keeps every OTHER dimension's
	// cap check an unconditional `monster_count >= MOB_SPAWN_CAP` -- byte-identical
	// to the pre-fix code, always (proved in test_ghast_spawn_env.c's overworld
	// rand-stream-identity section).
	bool ghast_eligible_dim = (w->dimension == WORLD_DIM_NETHER);

	if(monster_count >= MOB_SPAWN_CAP
	   && !(ghast_eligible_dim && ghast_count < GHAST_SPAWN_CAP))
		return;

	for(int k = 0; k < MOB_SPAWN_ATTEMPTS
		&& (monster_count < MOB_SPAWN_CAP
			|| (ghast_eligible_dim && ghast_count < GHAST_SPAWN_CAP));
		k++) {
		float ang = rand_gen_flt(&s->rand_src) * 2.0F * GLM_PI;
		float r = MOB_SPAWN_MIN_DIST
			+ rand_gen_flt(&s->rand_src)
				* (MOB_SPAWN_MAX_DIST - MOB_SPAWN_MIN_DIST);
		/* Split-screen guest coverage (Astra debate 2026-09-11, D): Beta's
		 * SpawnerAnimals draws from the chunks around EVERY player; with an
		 * admitted guest body the attempts alternate between the two bodies
		 * so spawns happen around the guest too. Single player: unchanged
		 * (the rand stream is consumed identically; only the centre moves). */
		double centre_x = actors[0]->x, centre_z = actors[0]->z;
		static bool s_spawn_guest_turn;
		s_spawn_guest_turn = !s_spawn_guest_turn;
		if(s->guest_gameplay && actor_count > 1 && s_spawn_guest_turn) {
			centre_x = actors[1]->x;
			centre_z = actors[1]->z;
		}
		w_coord_t x = (w_coord_t)floorf((float)centre_x + cosf(ang) * r);
		w_coord_t z = (w_coord_t)floorf((float)centre_z + sinf(ang) * r);
		// Beta SpawnerAnimals.getRandomSpawningPointInChunk draws the spawn Y
		// UNIFORMLY OVER THE WHOLE COLUMN -- `var0.rand.nextInt(128)` -- never
		// relative to the player. Anchoring it to the player (the old
		// `player.y + nextInt(32) - 16`) meant the +/-6 scan below only ever
		// sampled a 44-block slab centred on the player, so:
		//   * standing on high ground, every candidate landed in open SKY above
		//     the surrounding terrain and failed the floor test;
		//   * caves -- where Beta does most hostile spawning -- were NEVER
		//     sampled at all.
		// Measured on the maintainer's own save (player at y=92 on a snowy
		// plateau): 6162 of 6162 candidate cells rejected on air/floor, the
		// light gate never once reached, zero mobs in 30 minutes of play.
		// WORLD_HEIGHT is 128, so this is literally Beta's nextInt(128), and it
		// is the same ONE draw as before -- the RNG draw COUNT per attempt is
		// unchanged, only the distribution.
		int y0 = rand_gen_int(&s->rand_src, WORLD_HEIGHT);

		// Scan a vertical window for the first valid spawn cell.
		for(int yy = y0 - 6; yy <= y0 + 6; yy++) {
			if(yy < 1 || yy >= WORLD_HEIGHT - 1)
				continue;
			w_coord_t y = (w_coord_t)yy;
			struct block_data here, above, below;
			if(!server_world_get_block(w, x, y, z, &here)
			   || !server_world_get_block(w, x, y + 1, z, &above)
			   || !server_world_get_block(w, x, y - 1, z, &below))
				continue; // chunk not loaded here
			if(!mob_cell_free(&here) || !mob_head_free(&above))
				continue; // Beta: cell/head merely must not be full cubes
			if(!mob_solid_floor(below.type))
				continue; // need something to stand on

			// Weighted pick among the hostile types -- drawn BEFORE the
			// per-type gate (M2 final units). This is also Beta's real order:
			// SpawnerAnimals picks the spawn-list entry first, THEN runs the
			// entity's getCanSpawnHere -- and the gates genuinely differ now:
			// the slime has NO light gate (EntitySlime extends EntityLiving)
			// but its own slime-chunk check, while every other hostile keeps
			// the eff<=7 darkness gate (EntityMob). DOCUMENTED RNG-STREAM
			// REORDER: the pick roll now draws on light-failing cells that
			// previously consumed nothing -- a v2-internal stream shift, not
			// a Beta divergence (Beta always drew the pick first too).
			// DIMENSION-AWARE (batch 1b): the Nether walks BiomeGenHell's
			// ghast/pig-zombie 10/10 table; the overworld column and its
			// consumed-roll stream are bit-identical to before.
			int mob = monster_spawn_pick_dim(
				(int)w->dimension,
				rand_gen_int(&s->rand_src, monster_spawn_total_weight_dim(
												(int)w->dimension)));

			// Ghast channel routing (see GHAST_SPAWN_CAP above): decide WHICH
			// cap this pick answers to before spending any more draws on it.
			// This branch is a pure integer compare -- no RNG consumed -- so it
			// cannot perturb the draw stream by itself. It only ever changes
			// control flow (via `continue`) in states the pre-fix code could
			// never reach anyway: a non-ghast pick here is skipped ONLY when
			// `monster_count >= MOB_SPAWN_CAP`, which used to mean the outer
			// loop would never have started this attempt at all -- so ground-
			// hostile placement is unaffected whenever the ground cap has
			// headroom (the ordinary case, unchanged byte-for-byte). A ghast
			// pick is skipped here (BEFORE its 1-in-20 roll/clearance draws)
			// once `ghast_count >= GHAST_SPAWN_CAP` -- new behaviour, the whole
			// point of the fix.
			if(mob == MONSTER_GHAST) {
				if(ghast_count >= GHAST_SPAWN_CAP)
					continue;
			} else if(monster_count >= MOB_SPAWN_CAP) {
				continue;
			}

			/* I03 (board #8): Beta tests the RNG-free player-24 /
			 * world-spawn-576 clauses BEFORE constructing the candidate
			 * [SpawnerAnimals.java:123]; only then newInstance (an id, its
			 * own Random, a slime's size) and getCanSpawnHere on THAT
			 * Random [:125-132]. A too-close anchor constructs nothing and
			 * draws nothing; the pack walk below still runs (Beta validates
			 * each pack position independently). A refused candidate ends
			 * this attempt's anchor as before. */
			const bool anchor_far
				= mob_spawn_anchor_far_from_players_w(
					  s, w, (float)x + 0.5F, (float)z + 0.5F)
				&& mob_spawn_far_from_world_spawn((float)x, (float)y,
												  (float)z, s->player.spawn_x,
												  s->player.spawn_y,
												  s->player.spawn_z);
			struct spawn_candidate anchor_c;
			if(anchor_far) {
				spawn_candidate_place(s, w, mob, &anchor_c);
				if(!spawn_candidate_rolls_ok(s, w, &anchor_c, x, y, z))
					continue;
			}

			// AUDIT #18 ITEM 5: PACK-SPAWN. Beta SpawnerAnimals.performSpawning does not
			// place ONE mob per valid spot -- it spawns a PACK: from the anchor it walks up
			// to 4 members, each random-walking off the PREVIOUS member's position by
			// `+= rand.nextInt(6) - rand.nextInt(6)` on X and Z (Y draws cancel but are
			// still consumed), re-validating + capping each. We spawn the anchor as member
			// 0, then walk the remaining PACK_SPAWN_MEMBERS-1 members off it, keeping the
			// EXACT 6-draw RNG order (pack_spawn_scatter_step) so the seeded stream stays
			// deterministic. Every member re-runs the same spot check (mob_spawn_spot_ok,
			// or the slime gate for a slime pack) and obeys the spawn cap -- so a pack
			// thins out near walls/light, exactly like Beta. The same `mob` type fills
			// the pack (Beta places one creature type per seed); a SLIME pack re-rolls
			// each member's SIZE (1 << nextInt(3)) since every Beta member constructs
			// its own EntitySlime.
			// Beta getCanSpawnHere box tests at the ANCHOR, with the ACTUAL
			// spawned mob's box (a slime pack rolls the member size first --
			// Beta sizes each slime in its constructor, before
			// getCanSpawnHere ever sees the box). A refused anchor spawns
			// nothing, but the pack walk below still runs: Beta validates
			// each pack position independently.
			// AUDIT-DOSSIER fix: Beta's world-spawn 24-block exclusion
			// (SpawnerAnimals var33>=576.0F -- see combat.h's
			// mob_spawn_far_from_world_spawn citation), tested in anchor_far.
			if(anchor_far
			   && mob_spawn_bbox_clear_w(s, w, anchor_c.mob, x, y, z)) {
				struct entity* anchor_spawned = server_local_spawn_monster_at_id_w(
					w, (vec3) {(float)x + 0.5F, (float)y, (float)z + 0.5F},
					anchor_c.mob, anchor_c.id, &anchor_c.rng);
				server_local_spawn_spider_jockey_w(s, w, anchor_spawned);
				// Ghast channel: count against ghast_count/GHAST_SPAWN_CAP, NOT
				// the ground-hostile monster_count/MOB_SPAWN_CAP (see above).
				if(mob == MONSTER_GHAST)
					ghast_count++;
				else
					monster_count++;
			}

			int mx = (int)x, my = (int)y, mz = (int)z; // walking member position
			// GHAST pack cap 1 [740c583: EntityGhast.getMaxSpawnedInChunk]:
			// the anchor is the whole pack; the member walk is skipped
			// (documented gameplay-RNG deviation: Beta still consumes the
			// members' scatter draws before its per-chunk cap refuses them --
			// gameplay RNG here is rate-faithful, not stream-pinned).
			for(int m = 1;
				mob != MONSTER_GHAST && m < PACK_SPAWN_MEMBERS
				&& monster_count < MOB_SPAWN_CAP;
				m++) {
				// Random-walk off the previous member (consumes X:2, Y:2, Z:2 draws in
				// Beta order; the Y draws are no-ops in output but real RNG consumption).
				pack_spawn_scatter_step(mob_pack_rand, s, &mx, &my, &mz);
				w_coord_t px = (w_coord_t)mx, py = (w_coord_t)my,
						  pz = (w_coord_t)mz;
				/* I03: RNG-free cell + distance clauses first, then the
				 * member's own candidate (Beta re-runs :123-132 per member). */
				if(!mob_spawn_cell_ok(w, px, py, pz))
					continue; // member landed in an invalid cell -> skip (Beta does too)
				// Harden audit #4: enforce the SAME min-distance-to-player the anchor
				// gets. The anchor spawns on a ring at >= MOB_SPAWN_MIN_DIST, but a pack
				// member random-walks `+= rand(6)-rand(6)` off the previous member and is
				// re-validated ONLY for air/floor/light -- it can scatter back to ~1 block
				// from the player (a point-blank creeper). A single 2D squared-distance
				// compare to the player (matching the anchor's ring radius) rejects that:
				// both faithful (Beta's spawn checks keep mobs off the player) AND a Wii-
				// playability guard against a no-reaction-window spawn in the player's face.
				if(!mob_spawn_far_from_players_w(
					   s, w, (float)px + 0.5F, (float)pz + 0.5F))
					continue; // too close to the player -> skip this member
				// AUDIT-DOSSIER fix: same world-spawn exclusion as the anchor
				// (Beta re-derives it per pack member, not just once per pack).
				if(!mob_spawn_far_from_world_spawn((float)px, (float)py,
												   (float)pz, s->player.spawn_x,
												   s->player.spawn_y,
												   s->player.spawn_z))
					continue; // too close to the world spawn -> skip this member
				struct spawn_candidate mc;
				spawn_candidate_place(s, w, mob, &mc);
				if(!spawn_candidate_rolls_ok(s, w, &mc, px, py, pz))
					continue; // Beta getCanSpawnHere refuses this member
				if(!mob_spawn_bbox_clear_w(s, w, mc.mob, px, py, pz))
					continue; // Beta getCanSpawnHere refuses this member
				struct entity* member_spawned = server_local_spawn_monster_at_id_w(
					w, (vec3) {(float)px + 0.5F, (float)py, (float)pz + 0.5F},
					mc.mob, mc.id, &mc.rng);
				server_local_spawn_spider_jockey_w(s, w, member_spawned);
				monster_count++;
			}
			break; // one PACK per attempt
		}
	}
}

