// --- Dungeon mob-spawner tile-entity behaviour ----------------------------
// Beta's TileEntityMobSpawner ticks every game tick: with a player within 16
// blocks it counts a delay down and, on zero, bursts up to 4 mobs of its stored
// type into a small radius, gating EACH member on getCanSpawnHere() (2026-08-31
// fix: this comment used to read "valid spots only, ignoring light" and call
// that "faithful to TileEntityMobSpawner" -- it is NOT; the decompile's
// `if (var9.getCanSpawnHere())` runs the SAME light gate natural spawning uses,
// see spawner.h's spawner_hostile_light_ok citation. A member that fails it is
// skipped, not spawned; the delay re-roll cadence below is unchanged), then
// re-rolls the delay (200 + rand(600) ticks). The fork has no per-block tick, so
// a periodic pass scans the blocks near the player for spawners and drives the
// same logic; each spawner's delay lives in s->active_spawners (Beta's
// per-tile-entity timer). The scan -- a +-SPAWNER_RANGE cube of
// server_world_get_block -- is the cost here; cheap at the ~1 Hz cadence and
// easily made chunk-local if needed.

/* TileEntityMobSpawner.updateEntity's crowd count [CFR
 * TileEntityMobSpawner.java:66]: World.getEntitiesWithinAABB(member class,
 * AABB(x, y, z, x + 1, y + 1, z + 1).expand(8.0, 4.0, 8.0)).size() --
 * Chunk.getEntitiesOfTypeWithinAAAB:445-458 keeps an entity when
 * class.isAssignableFrom(entity class) (EntityPigZombie extends EntityZombie,
 * so a Zombie spawner counts pigmen; no other spawner mob class has a Beta
 * subclass) and its boundingBox strictly intersectsWith the box
 * [AxisAlignedBB.intersectsWith]. Every entity still in the world counts,
 * a dying one included (isDead is only set when it is removed). A1c: the
 * spawner's own world. */
static int spawner_class_count(struct server_local* s, struct server_world* w,
							   w_coord_t sx, w_coord_t sy, w_coord_t sz,
							   int mob) {
	const double min_x = (double)sx - 8.0, max_x = (double)sx + 1.0 + 8.0;
	const double min_y = (double)sy - 4.0, max_y = (double)sy + 1.0 + 4.0;
	const double min_z = (double)sz - 8.0, max_z = (double)sz + 1.0 + 8.0;
	int n = 0;
	dict_entity_it_t it;
	dict_entity_it(it, s->entities);
	while(!dict_entity_end_p(it)) {
		struct entity* e = dict_entity_ref(it)->value;
		dict_entity_next(it);
		if(!e || e->type != ENTITY_MONSTER || e->delay_destroy == 0
		   || server_local_entity_world(s, e) != w)
			continue;
		const int id = e->data.monster.id;
		if(!(id == mob
			 || (mob == MONSTER_ZOMBIE && id == MONSTER_PIG_ZOMBIE)))
			continue;
		/* Entity.setPosition box: posX +- width/2F, minY = posY - yOffset +
		 * ySize, maxY = minY + height. */
		const double half = (double)(e->width / 2.0F);
		const double bx0 = (double)e->pos[0] - half;
		const double bx1 = (double)e->pos[0] + half;
		const double bz0 = (double)e->pos[2] - half;
		const double bz1 = (double)e->pos[2] + half;
		const double by0 = (double)e->pos[1] - (double)e->y_offset
			+ (double)e->y_size;
		const double by1 = by0 + (double)e->height;
		if(bx1 > min_x && bx0 < max_x && by1 > min_y && by0 < max_y
		   && bz1 > min_z && bz0 < max_z)
			n++;
	}
	return n;
}

// Harden audit #2: total LIVE monsters in the loaded area (not yet reaped). This is the
// GLOBAL population the MOB_SPAWN_CAP bounds -- the natural-spawn loop already enforces
// it, but the spawner path previously honored ONLY its local crowd cap, so N spawners
// could drive the live count far past the cap (and past what the 16-slot move-RPC inbox /
// 512 tick-snapshot were sized for). Computed ONCE per spawner pass (NOT per emit) and
// threaded into sl_spawn_ctx so the emits stay O(1).
static int monsters_alive_total_w(struct server_local* s,
								  struct server_world* w) {
	int n = 0;
	dict_entity_it_t it;
	dict_entity_it(it, s->entities);
	while(!dict_entity_end_p(it)) {
		struct entity* e = dict_entity_ref(it)->value;
		// HOSTILES only -- the spawner global cap bounds the hostile population, not the
		// separately-capped passive animals. A1c: per world (Beta caps per World).
		if(e && server_local_entity_world(s, e) == w
		   && e->type == ENTITY_MONSTER && e->delay_destroy != 0
		   && !monster_is_passive(e->data.monster.id))
			n++;
		dict_entity_next(it);
	}
	return n;
}

static int monsters_alive_total(struct server_local* s) {
	return monsters_alive_total_w(s, &s->worlds[0]);
}

// Block accessor + emitter that bridge the pure spawner core (spawner.c) to the
// live server: read blocks from the server_world, and emit a mob (crowd-capped)
// through the normal monster-spawn path.
static bool sl_spawner_get(void* ctx, w_coord_t x, w_coord_t y, w_coord_t z,
						   struct block_data* blk) {
	struct server_world* w = ctx; /* A1c: the spawner's own world */
	return server_world_get_block(w, x, y, z, blk);
}

struct sl_spawn_ctx {
	struct server_local* s;
	struct server_world* w; /* A1c: the world the spawner block lives in */
	int mob;
	w_coord_t sx, sy, sz; /* the spawner cell (the crowd box origin) */
	/* I04: the current burst member (createEntityInWorld: id + own Random). */
	struct spawn_candidate member;
	// Harden audit #2: the live GLOBAL monster count, seeded ONCE before the burst and
	// bumped per successful emit, so the spawner honors MOB_SPAWN_CAP without an O(N)
	// rescan on each emit. `live` is the running count; emits stop once it reaches `cap`.
	int live;
	int cap;
};

/* I04 (board #8 follow-up): TileEntityMobSpawner builds each member with
 * EntityList.createEntityInWorld BEFORE any of its position draws [CFR
 * TileEntityMobSpawner.java:62]: an id and the member's own Random, kept even
 * if the member is refused (Entity.java:54/96). */
static void sl_spawner_construct(void* ctx) {
	struct sl_spawn_ctx* e = ctx;
	spawn_candidate_construct(e->s, e->w, e->mob, &e->member);
}

/* TileEntityMobSpawner.java:66-70: `if(var10 >= 6) { updateDelay(); return; }`
 * -- checked per member after createEntityInWorld, before its position draws;
 * true ENDS the burst (the caller re-rolls the delay after every burst). */
static bool sl_spawner_too_many_nearby(void* ctx) {
	struct sl_spawn_ctx* e = ctx;
	return spawner_class_count(e->s, e->w, e->sx, e->sy, e->sz, e->mob)
		>= SPAWNER_MAX_NEARBY;
}

/* getCanSpawnHere on the member's own Random [EntityMob.java:92-102]: raw
 * sky light > nextInt(32) refuses, then the (subtract-adjusted) light value
 * <= nextInt(8). */
static bool sl_spawner_can_spawn(void* ctx, int raw_sky_light,
								 int block_light_value) {
	struct sl_spawn_ctx* e = ctx;
	if(raw_sky_light > jrand_next_int_bound(&e->member.rng, 32))
		return false;
	return block_light_value <= jrand_next_int_bound(&e->member.rng, 8);
}

static void sl_spawner_emit(void* ctx, double x, double y, double z) {
	struct sl_spawn_ctx* e = ctx;
	// Harden audit #2: obey the GLOBAL MOB_SPAWN_CAP, not just the local crowd cap.
	// Without this, 8 spawners x 4-per-burst could push live mobs to ~48 -- past what
	// the 16-slot move-RPC inbox + 512 tick-snapshot were sized for, which backs up the
	// server tick against render and caps the framerate. `live` was seeded from the
	// real count once per pass (spawner_fire) and is incremented per emit below, so this
	// is a single int compare, not a rescan. RNG note: this skip does NOT shift the pure
	// spawner_burst stream (it draws all its rand_gen_flt/int BEFORE calling emit).
	// Newborn creation adds no generic motion draws. The cap bounds population;
	// it does not discard any of the burst's already-consumed draws.
	if(e->live >= e->cap)
		return;
	/* setLocationAndAngles(var11, var13, var15, ...) [CFR
	 * TileEntityMobSpawner.java:72-75]: the exact offset position, not a
	 * block-centred cell (the crowd cap is the too_many_nearby hook, checked
	 * before the draws). */
	server_local_spawn_monster_at_id_w(e->w,
		(vec3) {(float)x, (float)y, (float)z}, e->member.mob,
		e->member.id, &e->member.rng);
	e->live++; // count this fresh mob toward the global cap for the rest of the burst
}

// One spawner burst; the spot selection lives in spawner.c (headless-testable).
static void spawner_fire(struct server_local* s, struct server_world* w,
						 w_coord_t sx, w_coord_t sy, w_coord_t sz, int mob) {
	// Harden audit #2: seed the running global count from the live population ONCE here
	// (O(N) per BURST, not per emit), so the burst stops emitting at MOB_SPAWN_CAP.
	struct sl_spawn_ctx e = {.s = s, .w = w, .mob = mob,
		.sx = sx, .sy = sy, .sz = sz,
		.live = monsters_alive_total_w(s, w), .cap = MOB_SPAWN_CAP};
	// 2026-08-31 fix: getCanSpawnHere's light gate needs a day/night subtract --
	// same thunderstorm override (force 10) as the natural hostile passes above.
	// F1: the weather-darkened skylightSubtracted (rain 5/16), Nether-gated override;
	// spawner_spot_ok requires an AIR cell, so no neighbour-max branch applies here.
	int sky_subtract = (w->dimension != WORLD_DIM_NETHER
						&& server_weather_is_thundering(s))
		? 10
		: server_local_skylight_subtracted_w(s, w);
	static const struct spawner_member_ops ops = {
		.construct = sl_spawner_construct,
		.too_many_nearby = sl_spawner_too_many_nearby,
		.can_spawn = sl_spawner_can_spawn,
		.emit = sl_spawner_emit,
	};
	spawner_burst(&s->rand_src, sx, sy, sz, sky_subtract, sl_spawner_get, w,
				  &ops, &e);
}

static bool spawner_tracker_owned(const struct active_spawner* sp,
								  const struct server_world* w) {
	return sp->used && sp->world_slot == w->world_index
		&& sp->world_generation == w->generation;
}

static int spawner_find(struct server_local* s, struct server_world* w,
						w_coord_t x, w_coord_t y, w_coord_t z) {
	for(int i = 0; i < MAX_ACTIVE_SPAWNERS; i++)
		if(spawner_tracker_owned(&s->active_spawners[i], w)
		   && s->active_spawners[i].x == x
		   && s->active_spawners[i].y == y && s->active_spawners[i].z == z)
			return i;
	return -1;
}

// Tracker slot for the spawner at (x,y,z), allocating one with a fresh delay on
// first sight; -1 if the tracker is full.
static int spawner_track(struct server_local* s, struct server_world* w,
						 w_coord_t x, w_coord_t y, w_coord_t z) {
	int idx = spawner_find(s, w, x, y, z);
	if(idx >= 0)
		return idx;
	for(int i = 0; i < MAX_ACTIVE_SPAWNERS; i++)
		if(!s->active_spawners[i].used) {
			struct active_spawner* sp = &s->active_spawners[i];
			sp->x = x;
			sp->y = y;
			sp->z = z;
			sp->used = true;
			sp->world_slot = w->world_index;
			sp->world_generation = w->generation;
			sp->delay = SPAWNER_MIN_UNITS
				+ rand_gen_int(&s->rand_src, SPAWNER_RAND_UNITS);
			return i;
		}
	return -1;
}

// Debug-only ("debug.perf_stress"): a deterministic, no-input worst-case load for
// the P0 perf instruments, read off the F3 overlay on Dolphin/Wii (where the
// emulated Wiimote can't be scripted, so a "fast-travel crossing" can't be driven).
// Reproduces the two everyday tick costs the roadmap flagged, deterministically:
//   - the mob cap (MOB_SPAWN_CAP) ringed around the idle player so each detects +
//     paths in every tick -> the worst LEGAL per-mob collision sweep + get_block
//     dict-fetch storm (read F3 "getblk/tk"); and
//   - one TNT-power explosion in the loaded spawn chunk, which synchronously breaks
//     a sphere of blocks in a SINGLE tick -- each break running the set_block
//     lighting flood + 6-neighbour notify -> the #1 unbudgeted per-edit spike (read
//     F3 "setblk ... pk"). A couple of ring mobs caught in the blast may die;
//     immaterial to the storm magnitude. Runs once at world load like the other
//     demos; best with debug.superflat for a clean, fully-loaded stage.
static void server_local_perf_stress_demo(struct server_local* s) {
	assert(s);
	vec3 spawn = {
		(float)s->player.x, (float)s->player.y, (float)s->player.z,
	};
	int px = (int)spawn[0], pz = (int)spawn[2];

	// Stand the whole scene ON the surface. The saved/default spawn Y can be high air
	// on a fresh world; mobs spawned at an air Y would free-fall and take landing
	// damage, corrupting the collision-storm reading. Snap to the loaded spawn chunk's
	// heightmap so the player, the mob ring, and the blast all sit on the ground.
	uint8_t gh = 0;
	int gy = (int)spawn[1];
	if(server_world_get_height(&s->world, px, pz, &gh))
		gy = (int)gh;

	/* BUG-SPAWN (2026-10-14): player.y is the EYE (posY = feet + 1.62F), and
	 * the heightmap gy is the first cell above the top light-blocking block,
	 * i.e. the FEET cell. The old `y = gy` put the eye at ground level and
	 * the feet 1.62 inside the surface block; on seed 12345 (sand at y=84)
	 * the body fell to feet 83 with the eye in sand and the host suffocated
	 * every perf_stress_5m run. Feet = gy, then Beta's preparePlayerToSpawn
	 * push-up (a non-light-blocking full box, e.g. glass, cannot bury it). */
	float stand[3] = {(float)px + 0.5F, gy + PLAYER_EYE_HEIGHT,
					  (float)pz + 0.5F};
	server_local_prepare_player_to_spawn(s, stand);
	s->player.x = (double)px + 0.5;
	s->player.y = (double)stand[1];
	s->player.z = (double)pz + 0.5;
	s->player.rx = -90.0f; // face east, tilted down (preserved across the load hops)
	s->player.ry = -28.0f;
	server_local_refresh_player_membership(s);
	server_local_set_player_health(s, MAX_PLAYER_HEALTH);

	// MIDNIGHT. Keeps the undead from sun-burning so the FULL mob cap persists for a
	// sustained collision storm, and -- on REAL (non-superflat) terrain -- lets the
	// per-tick chained explosions breach into caves/hillsides whose skylight re-floods
	// tall columns, testing whether the edit flood stays expensive at night (the open
	// superflat made it cheap). A/B: flip to 6000 (noon) for the open-surface worst case.
	s->world_time = 18000;
	server_local_send_w(&s->worlds[0], (struct client_rpc) {
		.type = CRPC_TIME_SET, .payload.time_set = s->world_time });

	// Camera: tilted down so the mob ring + craters frame in the screenshot.

	// Mob cap in a TIGHT ring (~3 blocks) -- all inside aggro range so each paths every
	// tick (the per-mob collision + get_block storm). On varied terrain, snap EACH mob
	// to its own column's surface so they spawn on solid ground, not buried/floating.
	const int mob_n = MOB_SPAWN_CAP;
	for(int i = 0; i < mob_n; i++) {
		float ang = (float)i * (2.0F * (float)M_PI / (float)mob_n);
		int mx = px + (int)(3.0F * cosf(ang));
		int mz = pz + (int)(3.0F * sinf(ang));
		uint8_t mh = 0;
		float my = (float)gy;
		if(server_world_get_height(&s->world, mx, mz, &mh))
			my = (float)mh;
		int mid = (i % 3 == 0) ? MONSTER_ZOMBIE
				: (i % 3 == 1) ? MONSTER_SPIDER
							   : MONSTER_SKELETON;
		server_local_spawn_monster((vec3) {(float)mx + 0.5F, my, (float)mz + 0.5F},
								   mid, s);
	}

	// The per-tick half (server_local_perf_stress_tick) sustains the worst case:
	// chained explosions (the flood) + load-center hops (chunk streaming + fresh
	// terrain). No single load-time blast here -- the tick hook drives it continuously.
	printf("[perf_stress] COMBINED real-world stress armed: %d mobs @ midnight, ground "
		   "y=%d; rotating explosion bursts (fixed player) follow\n", mob_n, gy);
	s->perf_guard_armed = s->perf_guard_local_arm && s->player.health > 0;
	server_local_perf_guard_before_damage(s);
}

// Per-tick half of the COMBINED real-world stress (debug.perf_stress). Called every
// tick from server_local_update; sustains the worst realistic load the once-at-load
// arming only sampled. Everything stays within existing legal caps (the per-tick
// explosion cap gates synchronous blasts, the overflow auto-defers) -- flag-gated,
// debug-only, no rule changes.
static void server_local_perf_stress_tick(struct server_local* s) {
	// EXPLOSION BURST every 30 ticks (~1.5s) at a ROTATING ring around the FIXED
	// player: 3 power-4 blasts at radius ~28 + a rotating bearing, so each burst breaks
	// FRESH, un-cratered terrain that is ALREADY LOADED inside the view -- the
	// worst-case set_block lighting flood, repeated, on REAL terrain (breaching caves
	// re-floods tall skylight columns). The player does NOT move: a load-center hop
	// forces perpetual chunk gen whose RPC traffic stalls the server thread on the
	// 16-slot pipe (the client can't mesh real terrain fast enough) -- so the world
	// would never reach a steady state to measure. Spacing the bursts (not per-tick)
	// also avoids the runaway fluid/scheduled-tick cascade that continuous blasting
	// into real terrain near water triggers. Ring r~28 > the 2*power=8 damage radius,
	// so the player + r=3 mobs survive.
	if(s->world_time % 30 == 0) {
		float base = (float)((s->world_time / 30) * 47 % 360) * 0.01745329f;
		for(int i = 0; i < 3; i++) {
			float a = base + (float)(i * 120) * 0.01745329f;
			vec3 c = {(float)s->player.x + 28.0f * cosf(a),
					  (float)s->player.y - (float)(i % 2),
					  (float)s->player.z + 28.0f * sinf(a)};
			server_world_explode(&s->worlds[0], c, 4.0f);
		}
	}

	// Bound item-drop entities. The blasts spawn block drops (Beta's 30% per unit) which
	// never despawn fast enough at this artificial rate and would otherwise blow past
	// the engine's ENTITY_TICK_SNAPSHOT_MAX (512) invariant (an assert on debug, a
	// frozen+leaked tail on release). Mark the OLDEST items for the engine's OWN reaper
	// (delay_destroy=0 -> removed by the entity tick that runs right after this, which
	// sends CRPC_ENTITY_DESTROY + frees them) rather than freeing here -- no manual
	// free/erase of a live entity, no aliasing risk. Real play never approaches this
	// drop rate, so this only ever fires under the stress demo.
	{
		uint32_t items[600];
		size_t in = 0;
		dict_entity_it_t it;
		dict_entity_it(it, s->entities);
		while(!dict_entity_end_p(it) && in < 600) {
			struct entity* e = dict_entity_ref(it)->value;
			if(e && e->type == ENTITY_ITEM)
				items[in++] = dict_entity_ref(it)->key;
			dict_entity_next(it);
		}
		const size_t ITEM_KEEP = 48;
		for(size_t i = 0; i + ITEM_KEEP < in; i++) {
			struct entity** pp = dict_entity_get(s->entities, items[i]);
			if(pp && *pp)
				(*pp)->delay_destroy = 0; // engine reaps it in the entity tick below
		}
	}
}

// P0 perf instrument: the SERVER tick's true compute wall-clock -- the cost of one
// server_local_update, measured in server_local_thread and surfaced to F3 as last +
// session max. On the single Broadway core this is time stolen directly from the
// render budget, so it is the headline number for the tick-side optimization phases.
// Distinct from the client-side "tck" (particles+entities) on the cpu-ms line.
static float s_tick_last_ms = 0;
static float s_tick_max_ms = 0;
void server_local_tick_stats(float* last_ms, float* max_ms) {
	if(last_ms)
		*last_ms = s_tick_last_ms;
	if(max_ms)
		*max_ms = s_tick_max_ms;
}

// Spawner-pass cost, surfaced to the F3 overlay: us spent in the last
// tick_spawners (dominated by the +-SPAWNER_RANGE block scan) + the number of
// spawners currently tracked near the player.
static int s_spawner_us = 0;
static int s_spawner_active = 0;
void server_local_spawner_stats(int* us, int* active) {
	if(us)
		*us = s_spawner_us;
	if(active)
		*active = s_spawner_active;
}

static void server_local_tick_spawners_w(struct server_local* s,
										 struct server_world* w) {
	ptime_t t0 = time_get();
	/* A1b: the near-player tracker is shared by both worlds (MAX 8 rows);
	 * each row is owned by the world it was sighted in. A1c: this pass runs
	 * per EXPLICIT world -- it touches only `w`'s rows and scans `w`'s blocks
	 * around the first eligible actor committed to `w` (the host today; a
	 * guest-centred scan is a recorded follow-up, not a silent change). With
	 * no eligible actor nothing is in range: every row of `w` is evicted and
	 * no delay is rolled -- Beta's spawner idles without a player within 16. */
	for(int i = 0; i < MAX_ACTIVE_SPAWNERS; i++)
		if(spawner_tracker_owned(&s->active_spawners[i], w))
			s->active_spawners[i].seen = false;

	struct server_player* actors[SERVER_LOCAL_MAX_PRESENT_ACTORS];
	size_t actor_count = server_local_eligible_actors_w(
		s, w, actors, SERVER_LOCAL_MAX_PRESENT_ACTORS);
	w_coord_t px = 0, py = 0, pz = 0;
	if(actor_count > 0) {
		px = (w_coord_t)floor(actors[0]->x);
		py = (w_coord_t)floor(actors[0]->y);
		pz = (w_coord_t)floor(actors[0]->z);
	}

	// Match every in-range spawner block to a tracker entry (created on first
	// sight). The cube may reach unloaded chunks; get_block just fails there.
	// TODO(perf): make this +-SPAWNER_RANGE cube scan chunk-local. Deferred -- cheap at
	// the ~1 Hz spawner cadence; premature for a 0.3ms tick.
	for(w_coord_t x = px - SPAWNER_RANGE; actor_count > 0 && x <= px + SPAWNER_RANGE; x++)
		for(w_coord_t z = pz - SPAWNER_RANGE; z <= pz + SPAWNER_RANGE; z++)
			for(w_coord_t y = py - SPAWNER_RANGE; y <= py + SPAWNER_RANGE; y++) {
				if(y < 0 || y >= WORLD_HEIGHT)
					continue;
				struct block_data b;
				if(!server_world_get_block(w, x, y, z, &b)
				   || b.type != BLOCK_MOB_SPAWNER)
					continue;
				int idx = spawner_track(s, w, x, y, z);
				if(idx < 0)
					continue; // tracker full
				// FH-17: mob type comes from the spawner's MobSpawner tile
				// entity now, not the block's metadata nibble -- migration
				// (region_archive_migrate_mob_spawner_tes) guarantees every
				// BLOCK_MOB_SPAWNER has a TE by the time a world is live. A
				// missing TE (corrupt/unmigrated data) or an EntityId this
				// engine's spawner path does not implement resolves to -1;
				// leave `seen` false so this spawner is evicted below,
				// matching Beta's own createEntityInWorld(null) no-op.
				struct spawner_te* te = spawner_te_lookup_w(w, x, y, z);
				int mob = te ? spawner_mob_from_id(te->mob_id) : -1;
				if(mob < 0)
					continue;
				s->active_spawners[idx].mob = mob;
				s->active_spawners[idx].seen = true;
			}

	// Tick tracked spawners; fire the ones whose delay elapsed, evict the rest.
	int active = 0;
	for(int i = 0; i < MAX_ACTIVE_SPAWNERS; i++) {
		struct active_spawner* sp = &s->active_spawners[i];
		if(!spawner_tracker_owned(sp, w))
			continue;
		if(!sp->seen) {
			sp->used = false; // out of range / chunk unloaded
			continue;
		}
		if(server_world_light_halted(w))
			break; /* G9 R3: a light stop ends the loop at once */
		active++;
		if(--sp->delay > 0)
			continue;
		spawner_fire(s, w, sp->x, sp->y, sp->z, sp->mob);
		sp->delay = SPAWNER_MIN_UNITS
			+ rand_gen_int(&s->rand_src, SPAWNER_RAND_UNITS);
	}

	s_spawner_active = active;
	s_spawner_us = (int)(time_diff_s(t0, time_get()) * 1e6F);
}

#ifdef CAVEWII_SERVER_LOCAL_TEST
/* A1b/fix-1 seam: drive one near-player spawner tracker pass directly and
 * report how many rows the tracker holds for the current world. */
int server_local_test_tick_spawners(struct server_local* s) {
	server_local_tick_spawners_w(s, &s->worlds[0]);
	return s_spawner_active;
}
/* I04 test hook: one real dungeon-spawner burst (spawner_fire) at a cell,
 * without the near-player tracker / tile-entity lookup. */
void server_local_test_spawner_fire(struct server_local* s, w_coord_t x,
									w_coord_t y, w_coord_t z, int mob) {
	spawner_fire(s, &s->worlds[0], x, y, z, mob);
}
int server_local_test_tick_spawners_w(struct server_local* s,
									  struct server_world* w) {
	server_local_tick_spawners_w(s, w);
	return s_spawner_active;
}
#endif

// Debug capture aid: re-aim the player camera at s->debug_cam_track_id each tick so a
// test subject stays centered + well-framed in headless screenshots (the camera can't
// be turned with no controller input, so the server authors the rotation). Keeps the
// player POSITION as-is; only overrides the look direction. No-op unless a demo set the
// id; clears itself when the target is gone. Convention (client_interface.c +
// camera.c:128-136, the forward vector (sin rx * sin ry, cos ry, cos rx * sin ry)):
// camera.rx = -rotation[0], so yaw-to-target = atan2(dx,dz). camera.ry = rotation[1]+90,
// and the look's Y = cos(camera.ry): ry>90 looks DOWN (NOT <90 -- the old demo comment
// was backwards). So to look DOWN by theta at a mob below the eye, rotation[1] =
// +atan2(eye_y - target_center_y, horizontal_dist) (POSITIVE).
static void server_local_debug_cam_track(struct server_local* s) {
	if(!s->debug_cam_track_id)
		return;
	struct entity** pp = dict_entity_get(s->entities, s->debug_cam_track_id);
	if(!pp || !*pp) {
		s->debug_cam_track_id = 0; // target despawned/died -> stop tracking
		return;
	}
	struct entity* t = *pp;
	float dx = (float)(t->pos[0] - s->player.x);
	float dz = (float)(t->pos[2] - s->player.z);
	float horiz = sqrtf(dx * dx + dz * dz);
	if(horiz < 1.0e-3f)
		return; // target directly above/below: keep the last aim (avoid a yaw spin)
	// Aim from the player's EYE (the network y here is the feet -- the camera renders
	// the eye PLAYER_EYE_HEIGHT above it) at the mob's mid-body, so a ground mob sits
	// below the eye and the camera tilts DOWN onto it.
	float dy = ((float)s->player.y + PLAYER_EYE_HEIGHT) - (t->pos[1] + 0.5f);
	s->player.rx = -(atan2f(dx, dz) * (180.0f / (float)M_PI));   // yaw toward target
	s->player.ry = (atan2f(dy, horiz) * (180.0f / (float)M_PI)); // +pitch = look DOWN
	server_local_next_player_correction(s);
	clin_rpc_send(&(struct client_rpc) {
		.type = CRPC_PLAYER_POS,
		.payload.player_pos.position = {s->player.x, s->player.y, s->player.z},
		.payload.player_pos.rotation = {s->player.rx, s->player.ry},
		.payload.player_pos.correction_seq = s->player.correction_seq,
	});
}

// Per-phase server-tick breakdown (us), surfaced in the perf dump (perf_stress only):
// ps = perf-stress demo work (explosion bursts), rt = the random-tick floor, wt =
// server_world_tick (scheduled-tick / fluid-cascade processing). This split is what
// located the post-P1 bottleneck (the fluid cascade dominates wt at ~1300 scheduled
// ticks/tick); kept as a standing instrument for the perf campaign. Debug-only.
static int s_dbg_ps_us = 0, s_dbg_rt_us = 0, s_dbg_wt_us = 0;
// LEVER 1 (render-distance measurement enabler, 2026-06-22): mirror the random-tick
// (rt) + scheduled/fluid-tick (wt) CPU cost to non-static globals so the F3 overlay
// can show the server tick split in NORMAL play -- previously these were visible ONLY
// in the perf_stress SD dump. Read with the existing "wait: gpu/vsync" F3 row to name
// the limiter on real hardware (high rt/wt => CPU/tick-bound, the MEM2-dict storm;
// high gpu wait => GPU draw-ceiling-bound) -- the Step-0 gate for any reach increase.
// Memory-only: NO per-frame SD I/O on the tick thread (that would itself spike).
int g_srv_tick_rt_us = 0, g_srv_tick_wt_us = 0;
/* ASTRA-G9-R5 point 9: per-WINDOW maxima of the two component timings. The
 * single-tick samples above overwrite each completed tick, so a heartbeat
 * read misses every spike that is not the last tick before it (g9_1: the
 * 1.1-1.7 s checkpoint tick was caught once in five). The producer does an
 * atomic max per tick (checkpoint ticks included -- they are production
 * work, point 2); the heartbeat reader exchanges each with 0 once per
 * heartbeat, so every tick is graded by exactly one window and the final
 * heartbeat flushes the last window. Microsecond width, unsaturated. */
static uint32_t s_srv_tick_rt_max_us, s_srv_tick_wt_max_us;
static void srv_tick_window_max(uint32_t* slot, uint32_t us) {
	uint32_t cur = __atomic_load_n(slot, __ATOMIC_RELAXED);
	while(us > cur
		  && !__atomic_compare_exchange_n(slot, &cur, us, true,
										  __ATOMIC_RELAXED, __ATOMIC_RELAXED))
		;
}
void server_local_tick_window_max_take(uint32_t* rt_us, uint32_t* wt_us) {
	*rt_us = __atomic_exchange_n(&s_srv_tick_rt_max_us, 0u, __ATOMIC_RELAXED);
	*wt_us = __atomic_exchange_n(&s_srv_tick_wt_max_us, 0u, __ATOMIC_RELAXED);
}
/* One publication per simulation clock increment. Diagnostic only; the
 * simulation never consumes this value. Main reads with matching atomics. */
uint32_t g_srv_sim_ticks;
uint32_t g_srv_tick_backlog;
// Far-ring keep-up probe (2026-09-03 reach-sweep gate 4): far-skin
// generation cost/count/backlog, sampled once per SERVER tick by the
// FAR_SEND_BUDGET loop below -- same single-tick-sample convention as
// g_srv_tick_rt_us/g_srv_tick_wt_us above (NOT cumulative across the run).
// srv_gen_us/srv_gen_cols cover the generate+extract work
// (server_world_extract_far_skin / the ensure_populated+extract_far_column
// pair); srv_gen_backlog is the annulus slot count still neither far_sent
// nor chunk_sent, sampled from the FIRST candidate scan of the tick (reused,
// not re-scanned) -- the server's own view of the queue depth main.c's
// far_missing/far_settle_ms pair measures independently from the client.
int g_srv_far_gen_us = 0, g_srv_far_gen_cols = 0, g_srv_far_gen_backlog = 0;
// Server-loop wedge instrumentation (2026-09-08, lane/carve-observer-boot):
// written by the SERVER thread with relaxed atomics (server_local_thread
// below), read by main with matching relaxed atomics when composing the
// heartbeat -- same convention as g_srv_tick_backlog above. srv_loop_it and
// srv_far_us_max are windowed over the trailing ~1s (the heartbeat's own
// <=1Hz cadence); the other four are the LAST value the loop computed,
// republished every server iteration. See docs on struct
// hw_telemetry_heartbeat's srv_loop_it/srv_elapsed_ms/srv_ticks_pend/
// srv_partial_m/srv_sleep_ms/srv_far_us_max for what each names.
uint32_t g_srv_loop_it;
uint32_t g_srv_lean_it; /* lean (tick-first) iterations in the trailing ~1 s */
/* split_dims_6m evidence (splitdims-profile-0926, Fable F1): the dimension
 * the SERVER simulates each actor in, republished every loop iteration with
 * relaxed atomics (INT32_MIN = no bound guest). The heartbeat pairs it with
 * the dimension each client VIEW shows, so a view bound to one dimension
 * while its body is simulated in another can never certify. Telemetry
 * only -- nothing reads it back into the simulation. */
int32_t g_srv_host_dim;
int32_t g_srv_guest_dim = INT32_MIN;
/* split_dims_6m host-switch evidence (splitdims-hostswitch-0927), same
 * relaxed-atomic telemetry-only convention: host actor transfer COMMITs
 * (server_transfer.c), resident columns of world slot 1 (-1 = the slot is
 * not LIVE), and accepted CRPC_WORLD_RELEASE messages (vacant or retiring). */
uint32_t g_srv_host_commits;
int32_t g_srv_slot1_cols = -1;
uint32_t g_srv_release_sent;
/* Split render reach as the SERVER sees it (set by main.c from the config;
 * 0 = full presentation). While two anchors are active and the reach lies
 * inside the near radius, the render-only far ring (annulus past
 * MAX_VIEW_DISTANCE) cannot be displayed, so its generation/extraction is
 * skipped (Astra debate 2026-09-11, B: ~100 ms/s of invisible work).
 * Simulation support columns (the near ring) are untouched. */
static int s_split_stream_reach;
void server_local_set_split_reach(int chunks) {
	s_split_stream_reach = chunks < 0 ? 0 : chunks;
}
int server_local_split_reach(void) {
	return s_split_stream_reach;
}
/* True while the render-only far ring cannot be displayed: two anchors and
 * the split reach inside the near radius. The far batch skips generation and
 * the residency refresh records no far debt (stg25: 48 unserved far claims
 * pinned srv_gen_backlog at 47 and grew anchor_oldest to 6,973 ticks). */
/* Split policy transitions (Astra round 6, B/C): while two anchors are active
 * the far ring is OFF -- the effective far distance equals the split radius,
 * so no far claims are created, the debt map scans radius r, and the far
 * batch has nothing to do; the configured single-player far distance is
 * restored the moment two-anchor mode ends (leave), and the outer shell
 * streams back through ordinary residency. Called at guest admission commit,
 * guest release, and server start (synthetic anchor_sep). */
static bool server_local_residency_sync(struct server_local* s);
void server_local_split_policy_apply(struct server_local* s) {
	if(!s)
		return;
	/* SPLIT_POLICY_DIAL_ZERO_IS_OFF: dial 0 means the full radius AND the configured
	 * far ring -- no split policy at all (the PC residency fixtures run at 0 and
	 * exercise the far ring under two anchors). Only an active dial turns the
	 * ring off; the restore branch still runs so a dial lowered to 0 at runtime
	 * cannot strand a clamped far distance. */
	if((server_local_two_anchor(s) && s->split_view_radius > 0)
	   || (clin_world_payloads_enabled()
		   && (s->split_enabled || s->guest_gameplay
			   || s->player.world_slot != 0))) {
		if(!s->far_view_configured)
			s->far_view_configured = s->far_view_distance;
		int r = server_local_view_radius(s);
		if(s->far_view_distance > r)
			s->far_view_distance = r;
	} else if(s->far_view_configured) {
		s->far_view_distance = s->far_view_configured;
		s->far_view_configured = 0;
	}
	/* ...and reconcile the scheduler's backing store with what the new state
	 * actually needs. This hook is already called at exactly the three points
	 * where the split state changes (guest admission commit, guest release,
	 * server start), which is precisely where the LIVE switch needs the
	 * residency block released: a guest admitted while the switch was ON, then
	 * switched OFF, keeps its block until THIS call at its normal release.
	 * The accept class follows for the same reason -- the departing guest was
	 * the only remaining reason it was armed.
	 *
	 * This can only ever FREE or no-op, never allocate: at admission the block
	 * already exists (server_local_guest_gameplay refuses without it), at
	 * release the wanted set can only shrink, and at server start the switch
	 * has already been applied by the boot path. The assert pins that. */
	bool synced = server_local_residency_sync(s);
	assert(synced && "split policy reconcile must never need an allocation");
	(void)synced;
	svin_set_split_accept(s->split_enabled || s->guest_gameplay);
}

static bool server_local_far_invisible(const struct server_local* s) {
	return server_local_two_anchor(s) && s_split_stream_reach > 0
		&& s_split_stream_reach <= server_local_view_radius(s);
}
int g_srv_elapsed_ms;
uint32_t g_srv_ticks_pend;
int g_srv_partial_m;
int g_srv_sleep_ms;
int g_srv_far_us_max;
// Running max of a single far-column gen+extract cost (us) within the current
// ~1s loop window (see server_local_thread's window block below). Both
// server_local_update (the far-send batch loop) and server_local_thread (the
// window publish) run on the SAME server thread, sequentially -- plain,
// not atomic, like s_tick_last_ms above.
static int s_far_us_max_window;
#ifdef CAVEWII_SERVER_LOCAL_TEST
static bool s_test_far_gen_one_per_update;
void server_local_test_far_gen_one_per_update(bool enable) {
	s_test_far_gen_one_per_update = enable;
}
#endif
// M1 deep reach instrument: cumulative far chunks streamed + live far_sent count
// (the bounded far ring; should sit near the annulus size, not grow without limit).
static uint32_t s_far_sent_total = 0;
static int s_far_sent_live = 0;

void server_local_far_stats(unsigned* total, int* live) {
	if(total)
		*total = s_far_sent_total;
	if(live)
		*live = s_far_sent_live;
}

// Far-slot pool STARVATION, counted in consecutive far-batch bails. The non-blocking
// clin_far_slot_try_acquire turned an exhausted pool from a visible server-thread park
// into a silent defer, so the pool's deferral counter needs a reader that separates the
// two things an empty pool can mean:
//   PRESSURE -- a few bails while the main thread catches up, then a slot comes back.
//               Normal at a high far_view_distance; one tick can claim the whole pool.
//   LEAK     -- a slot the client consumed and never released. The pool shrinks for
//               good and far streaming stops silently, which is exactly what the old
//               blocking acquire could not hide (it froze the tick instead).
// The client releases every far slot inside the clin_update that consumes its
// CRPC_FAR_CHUNK, so a healthy pool is back within a frame or two; FAR_SLOT_LEAK_BAILS
// straight bails is ~5s at 20 TPS of a pool that never handed one back.
#define FAR_SLOT_LEAK_BAILS 100
static uint32_t s_far_slot_starve = 0;

// One line per starvation EPISODE (== , not >=), so a leak is loud exactly once and
// ordinary backpressure stays silent; a successful acquire resets the run. Reads
// clin_far_slot_busy_count() instead of keeping a second private tally: one owner for
// the number, and the figure reported here is the pool's own.
static void server_local_far_slot_bail(void) {
	if(++s_far_slot_starve == FAR_SLOT_LEAK_BAILS)
		fprintf(stderr,
				"[server] far slot pool starved for %d consecutive far batches "
				"(%u deferrals this session): the client is not releasing far "
				"slots -- far streaming is stalled\n",
				FAR_SLOT_LEAK_BAILS, (unsigned)clin_far_slot_busy_count());
}

// The consecutive-bail RUN, for the readers that exist on the SHIPPING build: the F3
// far-ring row and the watchdog hang report / cell-bar paint. stderr is not one of them --
// main.c calls SYS_STDIO_Report(true) only under !NDEBUG and the Wii Makefile compiles
// -DNDEBUG, so the alarm above produces nothing whatsoever on hardware. A counter whose
// only sink is compiled out is the same write-only-instrument defect that made
// watchdog_phase_worker's permanently-zero cell-bar row misdirect the 2026-07-27 hang.
uint32_t server_local_far_slot_starve(void) {
	return s_far_slot_starve;
}

static int server_entity_key_compare(const void* lhs, const void* rhs) {
	uint32_t a = *(const uint32_t*)lhs;
	uint32_t b = *(const uint32_t*)rhs;
	return (a > b) - (a < b);
}

// W1-c (far-reach program Wave 1, docs/far_reach_program_2026-09-03.md):
// cached nearest-first far-pick frontier. The old far send loop rescanned
// the WHOLE (2*far_view_distance+1)^2 square once per SENT column (up to
// FAR_SEND_BUDGET times/tick) to find the global-nearest not-yet-sent
// annulus column -- 8 x 1089 = 8712 iterations/tick at reach 16
// (docs/far_reach_program_2026-09-03.md S3 "Server-side scan cost"). Annulus
// membership and distance only depend on the OFFSET from the player's
// current chunk and far_view_distance -- never on px/pz itself -- so the
// sorted order is precomputed ONCE per far_view_distance value into
// s->far_pick_template and reused every tick; only the per-tick re-basing
// (px+dx, pz+dz) is position-dependent, so a player chunk crossing needs no
// rebuild, only a reach (far_view_distance) change does.
//
// Sort key matches the old loop's tie-break EXACTLY: squared distance
// ascending, then z ascending, then x ascending -- the old loop's outer z /
// inner x nesting with a strict "<" replace means, among equal-d2
// candidates, the earliest in (z,x) raster order always wins. Insertion
// order below is already (dz asc outer, dx asc inner), i.e. this comparator
// only needs to break d2 ties by dz then dx to reproduce that order exactly
// after qsort (proof: tests/test_far_pick_frontier_golden.c compares the
// exact (cx,cz) send sequence of the old full-rescan loop against this one
// for a scripted walk).
static int far_pick_offset_compare(const void* lhs, const void* rhs) {
	const struct far_pick_offset* a = lhs;
	const struct far_pick_offset* b = rhs;
	int32_t da = (int32_t)a->dx * a->dx + (int32_t)a->dz * a->dz;
	int32_t db = (int32_t)b->dx * b->dx + (int32_t)b->dz * b->dz;
	if(da != db)
		return da < db ? -1 : 1;
	if(a->dz != b->dz)
		return a->dz < b->dz ? -1 : 1;
	if(a->dx != b->dx)
		return a->dx < b->dx ? -1 : 1;
	return 0;
}

// Rebuilds s->far_pick_template for the CURRENT s->far_view_distance. Called
// lazily from the far send loop only when far_view_distance has changed
// since the last build (server_local_init seeds far_pick_template_built_for
// to -1, and far_view_distance is always >= MAX_VIEW_DISTANCE > 0, so the
// first tick always builds). O(n log n) in far_view_distance, but this runs
// at most once per reach change, never once per tick.
static void far_pick_template_build(struct server_local* s) {
	int fvd = s->far_view_distance;
	int n = 0;
	for(int dz = -fvd; dz <= fvd; dz++) {
		for(int dx = -fvd; dx <= fvd; dx++) {
			int ax = dx < 0 ? -dx : dx;
			int az = dz < 0 ? -dz : dz;
			int cheb = ax > az ? ax : az;
			// the annulus only: outside the near ring, inside the far ring --
			// identical predicate to the old loop's per-candidate test.
			if(cheb <= server_local_view_radius(s) || cheb > fvd)
				continue;
			assert(n < FAR_PICK_TEMPLATE_MAX);
			s->far_pick_template[n].dx = (int16_t)dx;
			s->far_pick_template[n].dz = (int16_t)dz;
			n++;
		}
	}
	qsort(s->far_pick_template, (size_t)n, sizeof(s->far_pick_template[0]),
		 far_pick_offset_compare);
	s->far_pick_template_count = n;
	s->far_pick_template_built_for = fvd;
}

// W1-c measurement instrument (docs/far_reach_program_2026-09-03.md
// "Server-side scan cost"): cumulative count of far-pick template entries
// examined by the far send loop, across every tick this process has run.
// Read via server_local_far_pick_iterations(); a test resets its own
// before/after delta rather than this counter (matches s_far_sent_total's
// pattern above -- SOLE writer is the server thread).
static uint64_t s_far_pick_iterations = 0;

uint64_t server_local_far_pick_iterations(void) {
	return s_far_pick_iterations;
}

// The single "advance *cursor to the next eligible far annulus column" step.
// ONE implementation shared by the production far send loop below and (under
// CAVEWII_SERVER_LOCAL_TEST) server_local_test_far_pick_next, so the golden
// order-equivalence proof (tests/test_far_pick_frontier_golden.c) exercises
// the REAL production selection code, not a hand-mirrored copy that could
// silently drift from it. s->far_pick_template must already be built for
// s->far_view_distance (far_pick_template_build) before this is called.
// *cursor is caller-owned: pass 0 to start a fresh walk (e.g. a new tick),
// or a value returned by an earlier call to resume past it. Returns false
// once the template is exhausted with nothing eligible left.
static bool far_pick_next(struct server_local* s, w_coord_t px, w_coord_t pz,
						  int* cursor, w_coord_t* out_x, w_coord_t* out_z) {
	for(; *cursor < s->far_pick_template_count; (*cursor)++) {
		s_far_pick_iterations++;
		w_coord_t x = px + s->far_pick_template[*cursor].dx;
		w_coord_t z = pz + s->far_pick_template[*cursor].dz;
		// far_sent must NOT block a full send -> gate on both independently
		// (promotion picks it via the near scan's !is_chunk_sent regardless
		// of far_sent).
		if(server_world_is_far_sent(&s->world, x, z)
		   || server_world_is_chunk_sent(&s->world, x, z))
			continue;
		*out_x = x;
		*out_z = z;
		(*cursor)++; // consume this slot before the next call resumes
		return true;
	}
	return false;
}

// ---------------------------------------------------------------------------
// T2 far-send share (2026-09-04, lane/far-send-share; docs/platform_perf_notes.md
// "Far-send share while the near frontier moves"). Two PURE decision helpers,
// deliberately state-free so tests/test_far_send_share.c drives the REAL
// production rule instead of a hand-mirrored copy of it (same discipline as
// far_pick_next / test_far_pick_frontier_golden above).
// ---------------------------------------------------------------------------

// What the far send batch is allowed to do this tick.
struct far_send_share {
	bool allowed; // may the far batch run at all
	int budget;   // columns it may send (<= FAR_SEND_BUDGET)
	int lead;     // promotion-debt guard look-ahead, in chunks (0 = guard off)
};

// near_owed: near chunks still unsent-but-loadable this tick (0 == the old
// near_complete). near_sent: how many the near loop actually sent this tick.
// share_limit: s->far_send_near_owed (config "lod.far_send_near_owed"; 0 =
// the strict pre-2026-09-04 gate).
static struct far_send_share far_send_share_decide(int near_owed, int near_sent,
												   int share_limit) {
	struct far_send_share out = {false, 0, 0};
	if(near_owed <= 0) {
		// STRICT path == the pre-2026-09-04 behaviour, unchanged: the near
		// square is fully sent, so far owns the whole budget and the debt guard
		// is off (nothing can be "about to enter" a frontier that isn't moving,
		// and every template column is outside the near radius by construction).
		out.allowed = true;
		out.budget = FAR_SEND_BUDGET;
		return out;
	}
	// share_limit <= 0 reproduces the strict gate EXACTLY: near_owed > 0 is
	// precisely !near_complete, so the far batch stays suspended. 0 is the
	// documented opt-out value (shipping default is 8, lane/far-share-default-8,
	// 2026-09-04); the share below only ever runs at share_limit > 0, per
	// CLAUDE.md's T2 rule.
	if(share_limit <= 0 || near_owed > share_limit)
		return out; // near convergence still owns the pipe
	// SHARE path: spend ONLY the send slots the near loop left unused this tick.
	// If near spent its whole CHUNK_SEND_BATCH, far gets zero -- far can never
	// displace a near send, it only consumes idle capacity, which is what keeps
	// this from re-creating the "slow-SD near frontier deferred with zero
	// progress while far burned another gen budget" failure the strict gate was
	// introduced for. The near_owed <= share_limit test above is the other half:
	// a genuinely stalled frontier (many chunks owed) never reaches here at all.
	int leftover = CHUNK_SEND_BATCH - near_sent;
	if(leftover <= 0)
		return out;
	out.allowed = true;
	out.budget = leftover < FAR_SEND_BUDGET ? leftover : FAR_SEND_BUDGET;
	out.lead = FAR_SEND_SHARE_LEAD_CHUNKS;
	return out;
}

// The promotion-debt guard. (dx,dz) is the candidate far column's offset from
// the player's chunk; (heading_x, heading_z) the sticky per-axis chunk-crossing
// direction (-1/0/+1). Returns true when the column would be INSIDE the near
// square after `lead` more crossings in that heading -- i.e. it is about to be
// claimed by the near loop, and far-sending it now would file a far_sent claim
// that cannot be evicted until the full near send succeeds (the 113-121 live
// debt photographed in World38). lead == 0 (or a zero heading) reduces this to
// "is it inside the near square right now", which is always false for a
// far_pick template entry -- the guard is then a provable no-op.
static bool far_send_enters_near(w_coord_t dx, w_coord_t dz, int heading_x,
								 int heading_z, int lead) {
	int ax = (int)dx - heading_x * lead;
	int az = (int)dz - heading_z * lead;
	if(ax < 0)
		ax = -ax;
	if(az < 0)
		az = -az;
	int cheb = ax > az ? ax : az;
	// MAX_VIEW_DISTANCE on purpose, not server_local_view_radius(): the only
	// caller sits behind !server_local_two_anchor(s) (the share-mode far batch is
	// single-anchor only), and with one anchor the runtime split radius IS the
	// compile-time constant -- see tests/test_split_view_radius_equiv.c.
	return cheb <= MAX_VIEW_DISTANCE;
}

// Sticky per-axis heading, refreshed once a tick from the player's own chunk
// crossings. The server does NOT mirror the client's walk velocity (player.
// vel_x/vel_z carry knockback only -- see the splash comment further down), so
// the crossings themselves are the only heading signal available here. Sticky
// rather than per-tick: a player who stops mid-annulus keeps the last direction,
// which is the conservative choice for the guard (it keeps excluding the columns
// they were walking into).
static void far_send_heading_update(struct server_local* s, w_coord_t px,
									w_coord_t pz) {
	if(!s->far_send_heading_valid) {
		s->far_send_last_cx = px;
		s->far_send_last_cz = pz;
		s->far_send_heading_x = 0;
		s->far_send_heading_z = 0;
		s->far_send_heading_valid = true;
		return;
	}
	if(px != s->far_send_last_cx) {
		s->far_send_heading_x = px > s->far_send_last_cx ? 1 : -1;
		s->far_send_last_cx = px;
	}
	if(pz != s->far_send_last_cz) {
		s->far_send_heading_z = pz > s->far_send_last_cz ? 1 : -1;
		s->far_send_last_cz = pz;
	}
}

