static bool server_local_tick_entities_w_body(struct server_local* s,
											  struct server_world* w);
/* Split dims (entity-driven block changes): the entity pass of `w` runs as a
 * dispatch of `w` -- every block_world(s) read or write an entity makes (a
 * falling-sand landing, a fireball's or TNT's explosion and its onBreak
 * chain, fire from an entity, their sounds; Beta has no endermen) lands in the ticking entity's own world, never slot 0. Single
 * world: block_world is worlds[0] throughout, byte-identical. */
static bool server_local_tick_entities_w(struct server_local* s,
										 struct server_world* w) {
	assert(s && w);
	struct server_world* bw_prev = block_world_enter(s, w);
	bool done = server_local_tick_entities_w_body(s, w);
	block_world_leave(s, bw_prev);
	return done;
}

static bool server_local_tick_entities_w_body(struct server_local* s,
											  struct server_world* w) {
	assert(s && w);
	s->entity_tick_active = false;
	s->entity_tick_count = 0;
	s->entity_tick_reserved = 0;
	/* A1c (entity-world contract): the worklist is exactly the entities
	 * bound to `w` -- Beta's per-World loadedEntityList. A dictionary entry
	 * without a value is carried (and skipped below) exactly as before. */
	size_t initial_count = 0;
	dict_entity_it_t it;
	dict_entity_it(it, s->entities);
	while(!dict_entity_end_p(it)) {
		struct entity* e = dict_entity_ref(it)->value;
		if(!e || server_local_entity_world(s, e) == w)
			initial_count++;
		dict_entity_next(it);
	}
	if(initial_count > 0
	   && !server_local_entity_tick_reserve(s, initial_count)) {
		static bool warned = false;
		if(!warned) {
			warned = true;
			fprintf(stderr,
					"[server] entity tick worklist allocation failed; "
					"entity phase skipped intact and will retry\n");
		}
		return false;
	}

	dict_entity_it(it, s->entities);
	while(!dict_entity_end_p(it)) {
		struct entity* e = dict_entity_ref(it)->value;
		if(!e || server_local_entity_world(s, e) == w)
			s->entity_tick_keys[s->entity_tick_count++]
				= dict_entity_ref(it)->key;
		dict_entity_next(it);
	}
	assert(s->entity_tick_count == initial_count);
	if(s->entity_tick_count > 1)
		qsort(s->entity_tick_keys, s->entity_tick_count,
			  sizeof(*s->entity_tick_keys), server_entity_key_compare);

	/* The initial monotonic-id order models Beta's loadedEntityList. Every
	 * committed entityJoinedWorld during a tick appends to this same worklist,
	 * so the loop observes its growing size and advances the new entity later in
	 * this pass. A dict lookup per id safely skips earlier removals/rollbacks. */
	s->entity_tick_active = true;
	size_t i = 0;
	while(i < s->entity_tick_count || s->pending_arrow_count > 0
		  || s->pending_monster_count > 0) {
		/* Any death ends this old-body live-list pass. A Nether death has shown the
		 * loading barrier and durably owns its close/drop plan; an Overworld death
		 * has already installed a fresh player at spawn. In either case, ticking a
		 * tagged drop across a chunk edge could escape recovery, and a later attack
		 * must never land on the replacement body in this same update. */
		if(s->death_world_evict || s->reject_player_pos_this_update)
			break;
		/* G9 R3: a light stop inside an earlier entity (a nested write whose
		 * reservation failed) ends the pass: no later entity consumes it. */
		if(server_local_light_stopped(s))
			break;
		if(i < s->entity_tick_count) {
			uint32_t key = s->entity_tick_keys[i++];
			struct entity** pp = dict_entity_get(s->entities, key);
			/* A mid-pass join appended to this worklist is ticked here only
			 * if it is bound to `w` (the flushes below construct into the
			 * routed world; A2-E binds them to the spawning world). */
			if(pp && *pp && server_local_entity_world(s, *pp) == w) {
				struct entity* e = *pp;
				bool retained = true;
				bool remove = e->delay_destroy == 0;
				bool area_loaded = false;
				if(!remove) {
					/* Beta freezes a loaded-list entity unless every chunk in its
					 * position +/-32 block box exists. This keeps ordinary motion
					 * from crossing the resident edge and losing its chunk owner.
					 * The membership refresh below still runs when the area becomes
					 * complete, so an addedToChunk=false entity reattaches without
					 * receiving an update until the following tick. Dead entities are
					 * reaped above regardless of chunk availability. [740c583:
					 * World.updateEntityWithOptionalForce:1291-1354] */
					double bx = floor((double)e->pos[0]);
					double bz = floor((double)e->pos[2]);
					if(isfinite(bx) && isfinite(bz)
					   && bx >= INT32_MIN && bx <= INT32_MAX
					   && bz >= INT32_MIN && bz <= INT32_MAX)
						/* Beta supplies fixed Y bounds 0..128 here; Y is not
						 * derived from the entity. Passing zero keeps the shared
						 * predicate's vertical interval overlapping the world and
						 * makes this check depend only on the required X/Z chunks. */
						area_loaded = server_world_area_loaded_radius(
							w, (w_coord_t)bx, 0,
							(w_coord_t)bz, 32);
					if(area_loaded && e->added_to_chunk && e->tick_server) {
						remove = e->tick_server(e, s);
						if(vsp_armed())
							vsp_srv_vehicle_ticked(s, e);
						/* W1F: Peaceful setEntityDead AFTER the update ran
						 * (EntityMob.java:22 follows super.onUpdate; the ghast
						 * check sits in its AI step, alive only --
						 * EntityGhast.java:32), and World.updateEntities
						 * drops an isDead entity in that same pass. No loot:
						 * setEntityDead never calls onDeath. A frozen
						 * (not-updated) entity is not removed -- Beta never
						 * ran its onUpdate either. */
						if(!remove && e->type == ENTITY_MONSTER
						   && difficulty_removes_monster(
							   server_local_difficulty(s),
							   e->data.monster.id, e->health))
							remove = true;
					}
				}
				if(remove) {
					retained = false;
					server_local_send_w(w, (struct client_rpc) {
						.type = CRPC_ENTITY_DESTROY,
						.payload.entity_destroy.entity_id = key,
					});
					free(e);
					dict_entity_erase(s->entities, key);
				}
				if(retained && area_loaded)
					server_local_refresh_entity_membership(s, e);
			}
		}

		/* These constructors were historically deferred only to protect a live
		 * dict iterator. Flush after each logical list entry so their committed
		 * joins append in occurrence order, just like Beta's live list. */
		server_local_flush_arrows(s);
		server_local_flush_fireballs(s);
		server_local_flush_monsters(s);
	}
	s->entity_tick_active = false;
	assert(s->entity_tick_reserved == 0);
	s->entity_tick_count = 0;
	return true;
}


static bool server_minecart_snapshot_due(
	const struct server_local* s, const struct entity* cart, bool priority) {
	assert(s && cart && cart->type == ENTITY_MINECART);
	uint64_t elapsed
		= s->world_time - cart->data.minecart.snapshot_last_tick;
	if(priority)
		return cart->data.minecart.snapshot_urgent
			|| (cart->data.minecart.occupied
				&& elapsed >= MINECART_RIDDEN_SNAPSHOT_INTERVAL);
	return !cart->data.minecart.occupied
		&& !cart->data.minecart.snapshot_urgent
		&& cart->data.minecart.snapshot_dirty
		&& elapsed >= MINECART_BACKGROUND_SNAPSHOT_INTERVAL;
}

/* Select the next due id after cursor, wrapping to the smallest due id. This
 * makes fairness independent of the entity hash table's iteration order. */
static struct entity* server_select_minecart_snapshot(
	struct server_local* s, uint32_t cursor, bool priority) {
	struct entity* after = NULL;
	struct entity* wrapped = NULL;
	dict_entity_it_t it;
	dict_entity_it(it, s->entities);
	while(!dict_entity_end_p(it)) {
		struct entity* e = dict_entity_ref(it)->value;
		if(e && e->type == ENTITY_MINECART
		   && server_minecart_snapshot_due(s, e, priority)) {
			if((!wrapped || e->id < wrapped->id))
				wrapped = e;
			if(e->id > cursor && (!after || e->id < after->id))
				after = e;
		}
		dict_entity_next(it);
	}
	return after ? after : wrapped;
}

static void server_local_publish_minecart_snapshots(struct server_local* s) {
	assert(s);
	unsigned attempts = 0;
	/* Give ownership/epoch corrections first claim on the channel, but consume
	 * only one attempt before checking the background lane. Although the current
	 * game has one local rider, restored/future non-player occupants can make
	 * several carts priority-due; allowing both attempts to stay in this lane
	 * would starve a dirty empty cart indefinitely. */
	struct entity* priority = server_select_minecart_snapshot(
		s, s->minecart_snapshot_priority_cursor, true);
	if(priority) {
		attempts++;
		/* Advance fairness on the attempt, not only on delivery. A perpetually
		 * full client inbox must not let one due id monopolize the next tick. */
		s->minecart_snapshot_priority_cursor = priority->id;
		if(!server_try_publish_minecart_snapshot(s, priority))
			return; /* token pool full; this cart remains due */
	}

	/* Reserve the second opportunity for an eligible background cart. Regular
	 * rail motion and explicit external-impulse hooks keep it eligible until one
	 * successful final snapshot. */
	struct entity* background = server_select_minecart_snapshot(
		s, s->minecart_snapshot_background_cursor, false);
	if(background && attempts < MINECART_SNAPSHOT_ATTEMPT_BUDGET) {
		attempts++;
		s->minecart_snapshot_background_cursor = background->id;
		if(!server_try_publish_minecart_snapshot(s, background))
			return;
	}

	/* No background cart needed its reserved opportunity: spend the remaining
	 * budget on a second urgent/ridden cart. */
	if(!background && attempts < MINECART_SNAPSHOT_ATTEMPT_BUDGET) {
		priority = server_select_minecart_snapshot(
			s, s->minecart_snapshot_priority_cursor, true);
		if(priority) {
			s->minecart_snapshot_priority_cursor = priority->id;
			(void)server_try_publish_minecart_snapshot(s, priority);
		}
	}
}

