	s->nether_roundtrip_tick = 0;
	s->nether_roundtrip_mx = s->nether_roundtrip_my = s->nether_roundtrip_mz = 0;
	s->nether_roundtrip_nx = s->nether_roundtrip_ny = s->nether_roundtrip_nz = 0;
	s->nether_roundtrip_ow_ok = false;
